-- [1] HELPER GIỐNG BONCUTI: tween() và new()
--------------------------------------------------------------------------------
local function tween(obj, duration, props, style, direction)
    local info = TweenInfo.new(duration, style or Enum.EasingStyle.Quint, direction or Enum.EasingDirection.Out)
    local playing = TweenService:Create(obj, info, props)
    playing:Play()
    return playing
end

-- new(): gán props rồi mới gán Parent (đỡ tốn layout, giống Boncuti).
local function new(class, props, children)
    local inst = Instance.new(class)
    local parent
    for key, value in pairs(props or {}) do
        if key == "Parent" then
            parent = value
        else
            inst[key] = value
        end
    end
    for _, child in ipairs(children or {}) do
        child.Parent = inst
    end
    if parent then
        inst.Parent = parent
    end
    return inst
end

--------------------------------------------------------------------------------
-- [2] HÀM EASING
--------------------------------------------------------------------------------
local function clamp(x, lo, hi)
    if x < lo then
        return lo
    elseif x > hi then
        return hi
    end
    return x
end

local function smooth(t)
    t = clamp(t, 0, 1)
    return t * t * (3 - 2 * t)
end

local function easeOutCubic(t)
    t = clamp(t, 0, 1)
    local u = 1 - t
    return 1 - u * u * u
end

local function easeInOutCubic(t)
    t = clamp(t, 0, 1)
    if t < 0.5 then
        return 4 * t * t * t
    end
    local u = -2 * t + 2
    return 1 - u * u * u / 2
end

--------------------------------------------------------------------------------
-- [3] SPRING (cùng thuật toán Boncuti: Euler nửa ẩn + substep 1/120 + ngủ khi lắng)
--     host.active là tập các spring đang chạy; Spring.step(host, dt) gọi mỗi frame.
--------------------------------------------------------------------------------
local Spring = {}
Spring.__index = Spring

function Spring.new(host, initial, stiffness, damping, callback, epsilon)
    local self = setmetatable({}, Spring)
    self.Host = host
    self.Value = initial
    self.Target = initial
    self.Velocity = 0
    self.Stiffness = stiffness
    self.Damping = damping
    self.Callback = callback
    self.Epsilon = epsilon or 0.01
    callback(initial)
    return self
end

function Spring:Set(target)
    self.Target = target
    self.Host.active[self] = true
end

function Spring:Snap(value)
    self.Value = value
    self.Target = value
    self.Velocity = 0
    self.Host.active[self] = nil
    self.Callback(value)
end

function Spring.step(host, dt)
    dt = math.min(dt, 1 / 20)
    local steps = math.max(1, math.ceil(dt / (1 / 120)))
    local h = dt / steps
    local list = {}
    for spring in pairs(host.active) do
        list[#list + 1] = spring
    end
    for _, spring in ipairs(list) do
        local value = spring.Value
        local velocity = spring.Velocity
        for _ = 1, steps do
            local acceleration = spring.Stiffness * (spring.Target - value) - spring.Damping * velocity
            velocity = velocity + acceleration * h
            value = value + velocity * h
        end
        if math.abs(spring.Target - value) < spring.Epsilon and math.abs(velocity) < spring.Epsilon * 8 then
            value = spring.Target
            velocity = 0
            host.active[spring] = nil
        end
        spring.Value = value
        spring.Velocity = velocity
        spring.Callback(value)
    end
end

--------------------------------------------------------------------------------
-- [4] ĐƯỜNG CONG: Catmull-Rom centripetal (kỹ thuật của Hello) + LUT độ dài cung
--     Path:at(s) trả điểm cách điểm đầu đúng s pixel dọc theo đường.
--------------------------------------------------------------------------------
local function knot(a, b, t)
    return t + math.max(math.sqrt((b[1] - a[1]) ^ 2 + (b[2] - a[2]) ^ 2), 1e-6) ^ 0.5
end

local function interpolate(a, b, ta, tb, t)
    if tb == ta then
        return { a[1], a[2] }
    end
    local w = (t - ta) / (tb - ta)
    return { a[1] * (1 - w) + b[1] * w, a[2] * (1 - w) + b[2] * w }
end

-- Lấy mẫu spline đi qua mọi điểm điều khiển, mỗi đoạn chia `per` mẫu.
local function sampleSpline(points, per)
    local count = #points
    local padded = { points[1] }
    for _, point in ipairs(points) do
        padded[#padded + 1] = point
    end
    padded[#padded + 1] = points[count]
    local line = {}
    for index = 2, #padded - 2 do
        local p0, p1, p2, p3 = padded[index - 1], padded[index], padded[index + 1], padded[index + 2]
        local t0 = 0
        local t1 = knot(p0, p1, t0)
        local t2 = knot(p1, p2, t1)
        local t3 = knot(p2, p3, t2)
        for step = 0, per - 1 do
            local t = t1 + (t2 - t1) * step / per
            local a1 = interpolate(p0, p1, t0, t1, t)
            local a2 = interpolate(p1, p2, t1, t2, t)
            local a3 = interpolate(p2, p3, t2, t3, t)
            local b1 = interpolate(a1, a2, t0, t2, t)
            local b2 = interpolate(a2, a3, t1, t3, t)
            line[#line + 1] = interpolate(b1, b2, t1, t2, t)
        end
    end
    line[#line + 1] = { points[count][1], points[count][2] }
    return line
end

local Path = {}
Path.__index = Path

function Path.new(line)
    local self = setmetatable({ line = line, cum = { 0 } }, Path)
    for i = 1, #line - 1 do
        local a, b = line[i], line[i + 1]
        self.cum[i + 1] = self.cum[i] + math.sqrt((b[1] - a[1]) ^ 2 + (b[2] - a[2]) ^ 2)
    end
    self.length = self.cum[#line]
    return self
end

function Path.spline(points, per)
    return Path.new(sampleSpline(points, per or 6))
end

-- Bezier bậc hai (dùng cho cuống đen bắn lên đỉnh màn hình).
function Path.quad(p0, c, p1, n)
    local line = {}
    for i = 0, n do
        local t = i / n
        local u = 1 - t
        line[#line + 1] = {
            u * u * p0[1] + 2 * u * t * c[1] + t * t * p1[1],
            u * u * p0[2] + 2 * u * t * c[2] + t * t * p1[2],
        }
    end
    return Path.new(line)
end

function Path:at(s)
    local line, cum = self.line, self.cum
    if s <= 0 then
        return line[1][1], line[1][2]
    end
    if s >= self.length then
        local last = line[#line]
        return last[1], last[2]
    end
    local lo, hi = 1, #line
    while hi - lo > 1 do
        local mid = math.floor((lo + hi) / 2)
        if cum[mid] <= s then
            lo = mid
        else
            hi = mid
        end
    end
    local seg = cum[hi] - cum[lo]
    local w = seg > 0 and (s - cum[lo]) / seg or 0
    local a, b = line[lo], line[hi]
    return a[1] + (b[1] - a[1]) * w, a[2] + (b[2] - a[2]) * w
end

function Path:pos(s)
    return self:at(s)
end

-- Route của sao đen = đoạn bay vào (spline) nối liền vòng tròn tâm (0,0) bán kính R.
-- Sau điểm cuối spline (s > S1) vị trí tính bằng công thức vòng tròn nên sao có
-- thể quay vô hạn trong lúc chờ Until(). Chiều quay: phi giảm = ngược chiều kim đồng hồ.
local function makeRoute(path, R, phi0)
    local route = { path = path, S1 = path.length, R = R, phi0 = phi0 }
    function route:pos(s)
        if s <= self.S1 then
            return self.path:at(s)
        end
        local phi = self.phi0 - (s - self.S1) / self.R
        return self.R * math.cos(phi), self.R * math.sin(phi)
    end
    return route
end

--------------------------------------------------------------------------------
-- [5] CỤM CHẤM (giống HelloDot của Boncuti): n chấm tròn xếp dọc một đường cong,
--     đầu to, đuôi nhỏ dần => thành "sao chổi" đen. Hai lớp: viền (rim) dưới, ruột trên.
--------------------------------------------------------------------------------
local function makePool(parent, count, cfg, zBase)
    local pool = { n = count, fill = {}, rim = nil, rimPx = cfg.RimPx, last = {}, trailFractions = {}, trailPower = nil }
    if cfg.UseRim then
        pool.rim = {}
        for i = 1, count do
            local dot = new("Frame", {
                Name = "InkRim",
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromOffset(-100, -100),
                Size = UDim2.fromOffset(0, 0),
                BackgroundColor3 = cfg.Rim,
                BackgroundTransparency = cfg.RimTransparency,
                BorderSizePixel = 0,
                ZIndex = zBase,
                Parent = parent,
            })
            new("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = dot })
            pool.rim[i] = dot
        end
    end
    for i = 1, count do
        local dot = new("Frame", {
            Name = "InkDot",
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromOffset(-100, -100),
            Size = UDim2.fromOffset(0, 0),
            BackgroundColor3 = cfg.Ink,
            BorderSizePixel = 0,
            ZIndex = zBase + 1,
            Parent = parent,
        })
        new("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = dot })
        pool.fill[i] = dot
    end
    return pool
end

local function hidePool(pool)
    for i = 1, pool.n do
        local dot = pool.fill[i]
        local rim = pool.rim and pool.rim[i]
        local last = pool.last[i]
        if not last or last.size ~= 0 then
            dot.Size = UDim2.fromOffset(0, 0)
            if rim then rim.Size = UDim2.fromOffset(0, 0) end
        end
        if last then last.size = 0 end
    end
end

-- Vẽ một sao chổi: đầu ở quãng đường sHead, đuôi dài L (px) lùi dọc route.
--   headSize / tipSize : độ dày ở đầu / chóp đuôi
--   p                  : p > 1 dồn chấm về phía chóp đuôi (đuôi mịn liền nét),
--                        p nhỏ hơn thì chấm thưa ra => đứt thành hạt (beads) như khung 69 của video
--   k                  : hệ số nhân kích thước (dùng để co dần khi biến mất)
local function drawTrail(pool, route, sHead, L, headSize, tipSize, p, cx, cy, k)
    local n = pool.n
    L = math.max(0, math.min(L, sHead))
    local rimExtra = pool.rimPx * 2

    -- p thường không đổi trong suốt một phase; cache phân bố hạt thay vì pow() lại mỗi frame.
    if pool.trailPower ~= p then
        pool.trailPower = p
        for i = 1, n do
            local x = (i - 1) / math.max(n - 1, 1)
            pool.trailFractions[i] = 1 - (1 - x) ^ p
        end
    end

    for i = 1, n do
        local f = pool.trailFractions[i]
        local dx, dy = route:pos(sHead - L * f)
        local x, y = cx + dx, cy + dy
        local size = (tipSize + (headSize - tipSize) * (1 - f) ^ 0.9) * k
        if size < 0.4 then size = 0 end

        local dot = pool.fill[i]
        local rim = pool.rim and pool.rim[i]
        local last = pool.last[i]
        if not last then
            last = { x = math.huge, y = math.huge, size = -1 }
            pool.last[i] = last
        end

        -- Chỉ ghi thuộc tính GUI khi thay đổi đủ lớn; giảm churn UDim2 trên frame budget thấp.
        if math.abs(x - last.x) >= 0.15 or math.abs(y - last.y) >= 0.15 then
            local position = UDim2.fromOffset(x, y)
            dot.Position = position
            if rim then rim.Position = position end
            last.x, last.y = x, y
        end
        if math.abs(size - last.size) >= 0.15 then
            dot.Size = UDim2.fromOffset(size, size)
            if rim then
                local rimSize = size > 0 and size + rimExtra or 0
                rim.Size = UDim2.fromOffset(rimSize, rimSize)
            end
            last.size = size
        end
    end
end

-- Chỗ đặt gui an toàn cho executor: gethui, rồi CoreGui, rồi PlayerGui.
local function resolveParent()
    if gethui then
        local ok, holder = pcall(gethui)
        if ok and holder then
            return holder
        end
    end
    local okCore, core = pcall(function()
        return game:GetService("CoreGui")
    end)
    if okCore and core then
        local probe = Instance.new("Folder")
        local writable = pcall(function()
            probe.Parent = core
        end)
        if writable and probe.Parent == core then
            probe:Destroy()
            return core
        end
        pcall(function()
            probe:Destroy()
        end)
    end
    return Players.LocalPlayer:WaitForChild("PlayerGui")
end
-- ====== Maru boot: sao đen + chấm; island và cửa sổ là của Maru thật (không dựng UI demo) ======
local gui, blur, loopConn, connections = nil, nil, nil, {}
local host = { active = {} }
local function islandGui()
    local sg = B.WindUI and B.WindUI.ScreenGui
    local par = sg and sg.Parent
    return par and par:FindFirstChild("WindUI/DynamicIsland")
end
local function setHidden(hidden)
    pcall(function() if B.WindUI and B.WindUI.ScreenGui then B.WindUI.ScreenGui.Enabled = not hidden end end)
    pcall(function() local g = islandGui() if g then g.Enabled = not hidden end end)
end
B.Fixes = {}
local function destroyBoot(restore)
    if B.Done then return end
    B.Done = true
    for _, fx in ipairs(B.Fixes) do pcall(fx) end
    if restore then
        setHidden(false)
        local w = B.Win
        if w and w.Closed == true then
            w.__BubbleOpen = true
            pcall(function() w:Open() end)
            w.__BubbleOpen = nil
        end
    end
    for _, c in ipairs(connections) do pcall(function() c:Disconnect() end) end
    table.clear(connections)
    pcall(function() if gui then gui:Destroy() end end)
    pcall(function() if blur then blur:Destroy() end end)
end
B.Destroy = function() destroyBoot(true) end

function B.Attach(windui, win, lib)
    if B.Done then return end
    B.WindUI, B.Win, B.Lib = windui, win, lib
    B.Attached, B.AttachedAt = true, os.clock()
    setHidden(true)
    task.delay(0.6, function()
        if B.Done or not win then return end
        pcall(function()
            win.__BubbleOpen = true
            if win.Closed ~= true then win:Close() end
            win.__BubbleOpen = nil
        end)
    end)
    local sc = windui and windui.UIScaleObj
    B.WinBase = sc and sc.Scale or 1
end

local function ready()
    if not B.Attached then return false end
    if os.clock() - B.AttachedAt < 1.2 then return false end
    local q = B.Lib and B.Lib.UIBuildStats
    if q and (q.Running or q.Head <= q.Tail) and os.clock() - B.AttachedAt < 6 then return false end
    return true
end

