        { 125 * U, 72 * U }, { 78 * U, 58 * U }, { 58 * U, 38 * U }, onCircle(phiB), onCircle(phiB - rad(20)), onCircle(phiB - rad(40)) }
    local function newComet(points, phiJoin, pool)
        local path = Path.spline(points, 6)
        local route = makeRoute(path, R, phiJoin - rad(40))
        local tIn = route.S1 / (V_SPIN + (V_IN - V_SPIN) / 3)
        return { route = route, pool = pool, tIn = tIn, s = 0, L = 0, size = RING_HEAD, delay = 0 }
