        local bg = main and main:FindFirstChild("Background")
        local ws = win and win.Size
        local scl = (B.WindUI and B.WindUI.UIScaleObj and B.WindUI.UIScaleObj.Scale) or B.WinBase or 1
        local wx = (ws and typeof(ws) == "UDim2" and ws.X.Offset > 0) and ws.X.Offset or cfg.WindowSize.X
        local wy = (ws and typeof(ws) == "UDim2" and ws.Y.Offset > 0) and ws.Y.Offset or cfg.WindowSize.Y
        return { bg = bg, w = wx * scl, h = wy * scl, corner = (win and tonumber(win.UICorner)) or 16 }
    end
    local function buildSampleWindow(spec)
        if not spec.bg then return nil end
        local okc, c = pcall(function() return spec.bg:Clone() end)
        if not okc or not c then return nil end
        local group = new("CanvasGroup", { Name = "SampleWinGroup", AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1,
            Position = UDim2.fromOffset(vw / 2, vh / 2), Size = UDim2.fromOffset(spec.w, spec.h), ZIndex = 20, Parent = gui })
        c.AnchorPoint = Vector2.new(0.5, 0.5)
        c.Position = UDim2.fromScale(0.5, 0.5)
        c.Size = UDim2.fromScale(1, 1)
        c.Visible = true
        pcall(function()
            local tr = (B.Win and B.Win.Transparent) and B.WindUI.TransparencyValue or 0
            c.ImageTransparency = tr
        end)
        c.Parent = group
        return { group = group }
    end

    -- [QM-FARM] P128 Smooth GooSpin | metaball orbit lien tuc, merge vao orb trung tam va bung island/window khong co settle pause.
    -- Moi khoa = {giay, d/D, goc xoay (do), rA, rB, co hep} do TU DONG bang cach khop hinh bong (hop cac vong tron) voi tung khung video (IoU 0.92-0.99); noi suy Hermite moi khung hinh
    local REST = 2.07                      -- d/D luc rieng le (video do 2.07)
    local D0 = 2 * R / REST                -- duong kinh 1 cuc luc rieng le
    local TCYC = 2.75                      -- chu ky: rieng le - lai gan - dinh - tach co cuc - xoay - co lai - bat ra (giay)
    local GOO_KEYS = {
        { 0, 2.07, 0, 0.98, 0.99, 0 }, { 0.3, 2.07, 0, 0.98, 0.99, 0 },
        { 0.4, 1.816, 0, 1.123, 0.887, 0 }, { 0.467, 1.649, 0, 1.115, 0.847, 0 },
        { 0.633, 1.444, 0, 1.17, 0.792, 0.39 }, { 0.7, 0.94, 0, 1.204, 0.772, 0.218 },
        { 0.733, 0.386, 0, 1.264, 0.702, 0.629 }, { 0.867, 0.386, 0, 1.264, 0.702, 0.629 },
        { 0.9, 1.774, -1.6, 0.995, 1.105, 0 }, { 0.967, 1.894, -2.9, 0.988, 1.057, 0 },
        { 1.033, 1.877, -7.8, 1.06, 1.042, 0 }, { 1.067, 1.517, -14.4, 1.109, 0.943, 0.436 },
        { 1.133, 1.517, -14.4, 1.109, 0.943, 0.436 }, { 1.167, 0.761, -20.8, 1.157, 0.897, 0.504 },
        { 1.2, 0.398, -23.8, 1.091, 0.876, 0.518 }, { 1.233, 0.198, -33, 1.003, 1.015, 0.457 },
        { 1.3, 0.187, -38.6, 0.923, 1.051, 0.444 }, { 1.333, 0.421, -54.5, 0.899, 0.925, 0 },
        { 1.433, 0.397, -61.6, 0.929, 0.876, 0.091 }, { 1.5, 0.077, -95.3, 0.966, 0.747, 0.464 },
        { 1.733, 0.05, -140, 0.898, 0.86, 0.525 }, { 1.95, 0.05, -170, 0.9, 0.87, 0.52 },
        { 2.05, 0.722, -180, 1.169, 1.173, 0.555 }, { 2.117, 1.227, -180, 1.183, 1.193, 0.501 },
        { 2.15, 1.285, -180, 1.205, 1.212, 0.523 }, { 2.217, 1.285, -180, 1.205, 1.212, 0.523 },
        { 2.25, 1.77, -180, 1.085, 1.087, 0 }, { 2.3, 2.07, -180, 0.985, 1.005, 0 },
        { 2.75, 2.07, -180, 0.98, 0.99, 0 },
    }
    local function gooTan(ka, kb, kc, j)  -- tiep tuyen don dieu (Fritsch-Butland): noi suy khong vot qua gia tri khoa
        local h0, h1 = kb[1] - ka[1], kc[1] - kb[1]
        local s0 = h0 > 0 and (kb[j] - ka[j]) / h0 or nil
        local s1 = h1 > 0 and (kc[j] - kb[j]) / h1 or nil
        if not s0 then return s1 or 0 end
        if not s1 then return s0 end
        if s0 * s1 <= 0 then return 0 end
        local w1, w2 = 2 * h1 + h0, h1 + 2 * h0
        return (w1 + w2) / (w1 / s0 + w2 / s1)
    end
    local function gooEval(tc, gs)         -- gs = { d/D, goc, rA, rB, co hep }
        local K, n = GOO_KEYS, #GOO_KEYS
        if tc >= K[n][1] then
            for j = 1, 5 do gs[j] = K[n][j + 1] end
            return gs
        end
        local i = 1
        while K[i + 1][1] <= tc do i = i + 1 end
        local ka, k0, k1, kb = K[math.max(i - 1, 1)], K[i], K[i + 1], K[math.min(i + 2, n)]
        local h = k1[1] - k0[1]
        local s = (tc - k0[1]) / h
        local s2, s3 = s * s, s * s * s
        local h00, h10, h01, h11 = 2 * s3 - 3 * s2 + 1, s3 - 2 * s2 + s, -2 * s3 + 3 * s2, s3 - s2
        for j = 2, 6 do
            gs[j - 1] = h00 * k0[j] + h10 * h * gooTan(ka, k0, k1, j) + h01 * k1[j] + h11 * h * gooTan(k0, k1, kb, j)
        end
        return gs
    end
    -- Mot "metaball" = hop cac vong tron: 2 dau + chuoi vong cau noi (ban kinh o giua = co hep), xoay quanh tam theo goc. Tra ve {x, y, r} (px, tam o 0,0).
    local function gooCircles(gs, out, bridgeN)
        out = out or {}
        local d, nk = clamp(gs[1], 0.03, 2.5), clamp(gs[5], 0, 1)
        local rA, rB = 0.5 * D0 * math.max(gs[3], 0.3), 0.5 * D0 * math.max(gs[4], 0.3)
        local am = clamp(nk * 6, 0, 1)
        local dpx = d * D0
        local c, s = cos(rad(gs[2])), sin(rad(gs[2]))
        local nn = 1

        -- Reuse các record x/y/r; không tạo 26-44 table mới ở mỗi RenderStepped.
        local a = out[1]
        if not a then a = {}; out[1] = a end
        a[1], a[2], a[3] = -dpx / 2 * c, -dpx / 2 * s, rA

        nn = 2
        local b = out[2]
        if not b then b = {}; out[2] = b end
        b[1], b[2], b[3] = dpx / 2 * c, dpx / 2 * s, rB

        for j = 1, bridgeN do
            local u = j / (bridgeN + 1)
            local endR = rA + (rB - rA) * u
            local w = math.max(endR * 0.85, 1e-4)
            local xa, xb = u * dpx, (1 - u) * dpx
            local env = math.max(math.exp(-(xa / w) ^ 2), math.exp(-(xb / w) ^ 2))
            local rn = endR * nk
            local x = -dpx / 2 + xa
            nn = nn + 1
            local item = out[nn]
            if not item then item = {}; out[nn] = item end
            item[1], item[2], item[3] = x * c, x * s, am * (rn + (endR - rn) * env)
        end
        for k = nn + 1, #out do out[k] = nil end
        return out
    end

    local clock, speed, phase = 0, 1, "ring"
    local finishRequested = false
    local tLaunch, tPop, tWin, tStage2 = 0, 0, 0, 0
    local launchPath, launchLen
    local islandShown, morphShown, stage2, winRevealed = false, false, false, false
    
    local function staticRoute(x, y)
        return { S1 = 0, R = 1, phi0 = 0, pos = function(_, s) return x, y end }
    end
    -- trạng thái metaball
    local gooT0, gooA, gooB, tUnm = nil, nil, nil, 0
    local gooS, gooU = { REST, 0, 1, 1, 0 }, { REST, 0, 1, 1, 0 }
    local gooPoolsHidden = false
    local gooList = {}
    local function drawSingleOrb(pool, x, y, size)
        local dot = pool.fill[1]
        local rim = pool.rim and pool.rim[1]
        local last = pool.last[1]
        if not last then
            last = { x = math.huge, y = math.huge, size = -1 }
            pool.last[1] = last
        end
        if math.abs(x - last.x) >= 0.15 or math.abs(y - last.y) >= 0.15 then
            local pos = UDim2.fromOffset(x, y)
            dot.Position = pos
            if rim then rim.Position = pos end
            last.x, last.y = x, y
        end
        if math.abs(size - last.size) >= 0.15 then
            dot.Size = UDim2.fromOffset(size, size)
            if rim then
                local rimSize = size > 0 and size + pool.rimPx * 2 or 0
                rim.Size = UDim2.fromOffset(rimSize, rimSize)
            end
            last.size = size
        end
        -- Những hạt còn lại đã được ẩn, chỉ giữ một orb thật ở tâm.
        for i = 2, pool.n do
            local other = pool.last[i]
            if not other then
                other = { x = 0, y = 0, size = -1 }
                pool.last[i] = other
            end
            if other.size ~= 0 then
                pool.fill[i].Size = UDim2.fromOffset(0, 0)
                if pool.rim then pool.rim[i].Size = UDim2.fromOffset(0, 0) end
                other.size = 0
            end
        end
    end

    local function drawCircles(pool, list, cx, cy)
        for i = 1, pool.n do
            local c = list[i]
            local r = c and c[3] or 0
            local dot = pool.fill[i]
            local rim = pool.rim and pool.rim[i]
            local last = pool.last[i]
            if not last then
                last = { x = math.huge, y = math.huge, size = -1 }
                pool.last[i] = last
            end

            if c and r > 0.25 then
                local x, y, sz = cx + c[1], cy + c[2], r * 2
                if math.abs(x - last.x) >= 0.15 or math.abs(y - last.y) >= 0.15 then
                    local pos = UDim2.fromOffset(x, y)
                    dot.Position = pos
                    if rim then rim.Position = pos end
                    last.x, last.y = x, y
                end
                if math.abs(sz - last.size) >= 0.15 then
                    dot.Size = UDim2.fromOffset(sz, sz)
                    if rim then
                        local rs = sz + pool.rimPx * 2
                        rim.Size = UDim2.fromOffset(rs, rs)
                    end
                    last.size = sz
                end
            elseif last.size ~= 0 then
                dot.Size = UDim2.fromOffset(0, 0)
                if rim then rim.Size = UDim2.fromOffset(0, 0) end
                last.size = 0
            end
        end
    end
    local function updateEnterSpin()
        for _, comet in ipairs(comets) do
            local t = clock - comet.delay
            local route = comet.route
            local s
            if t <= 0 then s = 0
            elseif t < comet.tIn then
                local u = t / comet.tIn
                s = V_SPIN * t + (V_IN - V_SPIN) * comet.tIn / 3 * (1 - (1 - u) ^ 3)
            else s = route.S1 end
            comet.s = s
            local u = clamp((s - (route.S1 - 240 * U)) / (240 * U), 0, 1)
            comet.L = L_ENTER + (L_RING - L_ENTER) * smooth(u)
        end
    end

    -- Island + WindUI thật: chỉ bật lại và để chúng tự chạy animation gốc của Maru (không đụng scale/kích cỡ)
    local function revealIsland()
        local g = islandGui()
        if g then g.Enabled = true end
    end
    local function revealWindow()
        local wsg = B.WindUI and B.WindUI.ScreenGui
        if wsg then wsg.Enabled = true end
        local win = B.Win
        if win and win.Closed == true then
            win.__BubbleOpen = true
            pcall(function() win:Open() end)
            win.__BubbleOpen = nil
        end
        tween(morph, 0.5, { BackgroundTransparency = 1 })
    end

    local function finish()
        if B.Done then return end
        if not islandShown then revealIsland() end
        if not winRevealed then revealWindow() end
        tween(blur, 0.5, { Size = cfg.BlurEnd })
        B.Finished = true
        task.delay(0.6, function() destroyBoot(false) end)
        phase = "done"
    end

    local function step(rawDt)
        if B.Done then return end
        -- Giữ giới hạn dt và substep đồng nhất với Spring của Boncuti để tránh overshoot khi frame hitch.
        local dt = math.min(rawDt or 0, 1 / 20) * speed
        clock = clock + dt
        Spring.step(host, dt)
        vw, vh = metrics()
        local cx, cy = vw / 2, vh / 2

        if phase == "ring" then
            updateEnterSpin()
            local waited = clock - spinStart
            local isReady = finishRequested or ready()
            if waited >= cfg.MaxSpin then isReady = true end
            if waited < 0 then
                drawTrail(poolA, A.route, A.s, A.L, RING_HEAD, TIP, 2.2, cx, cy, 1)
                drawTrail(poolB, Bc.route, Bc.s, Bc.L, RING_HEAD, TIP, 2.2, cx, cy, 1)
            else
                if not gooT0 then
                    gooT0 = clock
                    gooA = { A.route:pos(A.s) }
                    gooB = { Bc.route:pos(Bc.s) }
                end
                local tg = clock - gooT0
                local bl = smooth(tg / 0.40)           -- đầu sao chổi chảy dần thành cục metaball
                if isReady and waited >= cfg.MinSpin then
                    -- Không đóng băng 2 cục sau khi dính: chuyển thẳng sang pha orbit-handoff.
                    phase, tUnm = "handoff", clock
                    for j = 1, 5 do gooU[j] = gooS[j] end
                else
                    gooEval(tg % TCYC, gooS)
                    gooCircles(gooS, gooList, poolG.n - 2)
                    if bl < 1 then
                        local la, lb = gooList[1], gooList[2]
                        la[1], la[2], la[3] = gooA[1] + (la[1] - gooA[1]) * bl, gooA[2] + (la[2] - gooA[2]) * bl, RING_HEAD / 2 + (la[3] - RING_HEAD / 2) * bl
                        lb[1], lb[2], lb[3] = gooB[1] + (lb[1] - gooB[1]) * bl, gooB[2] + (lb[2] - gooB[2]) * bl, RING_HEAD / 2 + (lb[3] - RING_HEAD / 2) * bl
                        drawTrail(poolA, A.route, A.s, L_RING * (1 - bl), RING_HEAD, TIP, 2.2, cx, cy, 1 - bl)
                        drawTrail(poolB, Bc.route, Bc.s, L_RING * (1 - bl), RING_HEAD, TIP, 2.2, cx, cy, 1 - bl)
                    elseif not gooPoolsHidden then
                        gooPoolsHidden = true
                        hidePool(poolA)
                        hidePool(poolB)
                    end
                    drawCircles(poolG, gooList, cx, cy)
                end
            end
        elseif phase == "handoff" then
            -- Hai orb tiếp tục quay quanh tâm trong khi khoảng cách thu về 0;
            -- không còn pha đứng yên 0.8s trước khi bung Dynamic Island.
            local tu = clock - tUnm
            local duration = 0.72
            local u = clamp(tu / duration, 0, 1)
            local merge = smooth(u)
            gooS[1] = gooU[1] + (0.10 - gooU[1]) * merge
            gooS[2] = gooU[2] - 300 * tu                    -- quay liên tục 300 độ/giây
            gooS[3] = gooU[3] + (0.72 - gooU[3]) * merge
            gooS[4] = gooU[4] + (0.72 - gooU[4]) * merge
            gooS[5] = gooU[5] + (0.52 - gooU[5]) * merge  -- cổ nối tăng dần, tạo một orb trung tâm
            gooCircles(gooS, gooList, poolG.n - 2)
            drawCircles(poolG, gooList, cx, cy)

            if tu >= duration then
                hidePool(poolG)
                hidePool(poolA)
                -- Orb đã nhập tại tâm; chuyển động thẳng lên pill bằng đường cong, không có khoảng dừng.
                local sc = (vh / 1008) * ((UserInputService.TouchEnabled and 1.25) or 1.08)
                local targetY = -cy + (cfg.IslandTop + cfg.IslandH / 2) * sc
                tgtY, isc = targetY, sc
                A.route, Bc.route = staticRoute(-2000, -2000), staticRoute(0, 0)
                A.s, Bc.s, A.L, Bc.L = 0, 0, 0, 0
                A.size, Bc.size = DOT_LAND, DOT_LAND
                local midY = targetY * 0.5
                launchPath = Path.quad({ 0, 0 }, { 0, midY }, { 0, targetY }, 28)
                launchLen = launchPath.length
                phase, tLaunch = "launch", clock
            end
        elseif phase == "launch" or phase == "pop" then
            local tl = clock - tLaunch
            local T_FLY = 0.18
            if not morphShown then
                drawSingleOrb(poolB, cx, cy, Bc.size)
            end
            if tl < T_FLY then
                local sHead = launchLen * easeOutCubic(tl / T_FLY)
                local sTail = launchLen * easeInOutCubic((tl - 0.025) / T_FLY)
                drawTrail(poolL, launchPath, sHead, sHead - sTail, 22 * U, 3 * U, 1.6, cx, cy, 1)
            elseif phase == "launch" then
                phase, tPop = "pop", clock
                hidePool(poolA)
                hidePool(poolL)
                local okI, made = pcall(buildSampleIsland)
                sIsl = okI and made or nil
                if sIsl then
                    siW:Snap(22 * U / sIsl.base) siH:Snap(22 * U / sIsl.base)
                    siW:Set(cfg.IslandSize.X) siH:Set(cfg.IslandSize.Y)
                else
                    sIsland.Visible = true
                    siW:Snap(22 * U) siH:Snap(22 * U)
                    siW:Set(cfg.IslandSize.X * isc) siH:Set(cfg.IslandSize.Y * isc)
                end
            end
            if sIsl then
                sIsl.clone.Size = UDim2.fromOffset(islW, islH)
                if sIsl.corner then sIsl.corner.CornerRadius = UDim.new(0, math.max(0, math.min(islW, islH) / 2)) end
            elseif sIsland.Visible then
                sIsland.Size = UDim2.fromOffset(islW, islH)
                sIsland.Position = UDim2.fromOffset(cx, cy + tgtY)
                sIslandCorner.CornerRadius = UDim.new(0, math.max(0, math.min(islW, islH) / 2))
            end
            if phase == "pop" then
                local tp = clock - tPop
                if tp >= 0.08 and not morphShown then
                    morphShown, tWin = true, clock
                    local dx = Bc.route:pos(Bc.s)
                    hidePool(poolB)
                    morph.Visible = true
                    pcall(function()
                        local sp = realWindowSpec()
                        if sp.bg then morph.BackgroundColor3 = sp.bg.ImageColor3 end
                    end)
                    ms.W, ms.H, ms.X = Bc.size, Bc.size, dx
                    sW:Snap(Bc.size) sH:Snap(Bc.size) sR:Snap(Bc.size / 2) sX:Snap(dx)
                    sW.Stiffness, sW.Damping, sH.Stiffness, sH.Damping = 900, 40, 900, 40
                    sW:Set(96 * U) sH:Set(76 * U) sR:Set(16 * U)
                end
                if morphShown and not stage2 and clock - tWin >= 0.20 then
                    stage2, tStage2 = true, clock
                    local sp = realWindowSpec()
                    local fw = math.min(sp.w, vw * 0.94)
                    local fh = math.min(sp.h, vh * 0.88)
                    winSpec = sp
                    sW.Stiffness, sW.Damping, sH.Stiffness, sH.Damping = 620, 32, 620, 32
                    sW:Set(fw) sH:Set(fh) sR:Set(sp.corner) sX:Set(0)
                end
                if morphShown then
                    morph.Size = UDim2.fromOffset(ms.W, ms.H)
                    morph.Position = UDim2.fromOffset(cx + ms.X, cy)
                    morphCorner.CornerRadius = UDim.new(0, math.max(0, math.min(ms.R, math.min(ms.W, ms.H) / 2)))
                end
                if stage2 and not sWin and winSpec and clock - tStage2 >= 0.40 then
                    local okW, made = pcall(buildSampleWindow, { bg = winSpec.bg, w = math.min(winSpec.w, vw * 0.94), h = math.min(winSpec.h, vh * 0.88) })
                    sWin = okW and made or false
                    if sWin then morph.Visible = false end
                end
                if stage2 and not winRevealed and clock - tStage2 >= 0.55 then
                    winRevealed, islandShown = true, true
                    pcall(revealIsland)
                    pcall(revealWindow)
                    tween(sIsland, 0.5, { BackgroundTransparency = 1 })
                    if sIsl then tween(sIsl.holder, 0.5, { GroupTransparency = 1 }) end
                    if sWin then tween(sWin.group, 0.5, { GroupTransparency = 1 }) end
                    tween(blur, 0.9, { Size = cfg.BlurEnd })
                end
                if stage2 and clock - tStage2 >= 1.3 then finish() end
            end
        end
    end

    tween(blur, 0.5, { Size = cfg.BlurIdle })
    hidePool(poolA)
    hidePool(poolB)
    hidePool(poolL)
    loopConn = RunService.RenderStepped:Connect(function(dt)
        local okS, e = pcall(step, dt)
        if not okS then
            warn("[MaruBoot] " .. tostring(e))
            destroyBoot(true)
        end
    end)
    connections[#connections + 1] = loopConn
    if cfg.SkipOnInput then
        connections[#connections + 1] = UserInputService.InputBegan:Connect(function(input)
            if clock < 0.9 or B.Done then return end
            local k = input.UserInputType
            if k == Enum.UserInputType.MouseButton1 or k == Enum.UserInputType.Touch or k == Enum.UserInputType.Keyboard then
                finishRequested = true
                speed = 3.2
            end
        end)
    end
end)
if not ok then
    warn("[MaruBoot] start failed: " .. tostring(err))
    destroyBoot(true)
end
-- chốt an toàn: dù lỗi gì cũng phải trả lại island + cửa sổ
task.delay(40, function()
    if not B.Done then destroyBoot(true) end
end)
end

local Library = (function()
    local WindUI = (function()
local a a={cache={}, load=function(b)if not a.cache[b]then a.cache[b]={c=a[b]()}end return a.cache[b].c end}
a.IS=function()
local Players = game:GetService("Players")
local TweenService = game:GetService("TweenService")
local RunService = game:GetService("RunService")
local TextService = game:GetService("TextService")
local Stats = game:GetService("Stats")
local UserInputService = game:GetService("UserInputService")
local V2, U2, UD = Vector2.new, UDim2.new, UDim.new
local QUAD, BACK = Enum.EasingStyle.Quad, Enum.EasingStyle.Back
local EIN, EOUT = Enum.EasingDirection.In, Enum.EasingDirection.Out
local FONT, FONTB = Enum.Font.MontserratMedium, Enum.Font.MontserratBold
local BASE_H = 1008
local SPEC = {
        Idle = { W = 148, H = 38, R = 19 },
        MusicPill = { W = 244 },
        Wide = { W = 428, H = 100, R = 50 },
        Task = { W = 428, H = 150, R = 46 },
