local function new(class, props, kids)
        local o = Instance.new(class)
        local parent
        if class == "TextButton" or class == "ImageButton" then
                o.Selectable = false
        end
        for k, v in pairs(props or {}) do
                if k == "Parent" then
                        parent = v
                else
                        o[k] = v
                end
        end
        for _, c in ipairs(kids or {}) do
                c.Parent = o
        end
        if parent then
                o.Parent = parent
        end
        return o
end
