                        corner(AL.disc)
                        AL.grad = new("UIGradient", { Rotation = 45, Color = ColorSequence.new(Color3.fromRGB(139, 255, 204), Color3.fromRGB(18, 137, 91)), Parent = AL.disc })
                        AL.ds = new("UIScale", { Scale = 1, Parent = AL.disc })
