                local badS = new("UIScale", { Scale = 0, Parent = bad })
                local title = label(f, {
                        Font = FONTB, TextSize = 14, TextColor3 = C.Green, TextXAlignment = Enum.TextXAlignment.Center,
                        TextTruncate = Enum.TextTruncate.AtEnd, AnchorPoint = V2(0.5, 0.5), Position = UDim2.fromOffset(74, 101),
                        Size = UDim2.fromOffset(132, 20), Text = "",
                })
                local sub = label(f, {
                        Font = FONT, TextSize = 10, TextColor3 = C.Sub, TextXAlignment = Enum.TextXAlignment.Center,
                        TextTruncate = Enum.TextTruncate.AtEnd, AnchorPoint = V2(0.5, 0.5), Position = UDim2.fromOffset(74, 122),
                        Size = UDim2.fromOffset(132, 14), Text = "",
                })
                function v.Set(d)
                        local ok = d.Success ~= false
                        local color = d.Color or (ok and C.Green or C.Red)
                        stroke.Color = color
                        good.Visible = ok
                        bad.Visible = not ok
                        recolor(ok and good or bad, color)
                        title.Text = tostring(d.Title or "")
                        title.TextColor3 = color
                        sub.Text = tostring(d.Content or "")
                        ringScale.Scale = 0.6
                        tw(ringScale, 0.5, { Scale = 1 }, BACK, EOUT)
                        goodS.Scale, badS.Scale = 0, 0
                        tw(ok and goodS or badS, 0.5, { Scale = 1 }, BACK, EOUT)
                end
                return v
        end
        local queue = {}
        local lives = {}
        -- Primary live-pill order: Data Quest, route tracking, Music, then Timer/Stopwatch.
        local LIVE_ORDER = { "farm", "track", "media", "timer", "stopwatch" }
        local LIVE_RANK = {}
        for i, kind in ipairs(LIVE_ORDER) do LIVE_RANK[kind] = i end
        local runJob, dismissJob, goIdle, showLive
        local lastTouch = os.clock()
        local function touch()
                lastTouch = os.clock()
                XC.touched = lastTouch
        end
        local function pickLive()
                live = nil
                for _, k in ipairs(LIVE_ORDER) do
                        if lives[k] then
                                live = lives[k]
                                break
                        end
                end
        end
        local function removeQueued(job)
                for i, j in ipairs(queue) do
                        if j == job then
                                table.remove(queue, i)
                                return
                        end
                end
        end
        local function buildActPill(kind)
                local isT = kind == "timer"
                local col = ACT_COL[kind]
                local v = makeView(isT and "TimerPill" or "WatchPill", SPEC.TimerPill.W, SPEC.PillH)
                local f = v.frame
                local bg = frame({ BackgroundColor3 = isT and Color3.fromRGB(53, 40, 20) or Color3.fromRGB(40, 28, 50), Size = UDim2.fromScale(1, 1), Parent = f })
                corner(bg, SPEC.Idle.R)
                new("UIStroke", { Thickness = 3, Color = col, Transparency = 0.15, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = bg })
                local dot = frame({
                        BackgroundColor3 = col, AnchorPoint = V2(0.5, 0.5), Position = U2(0, 21, 0.5, 0),
                        Size = UDim2.fromOffset(10, 10), Parent = f,
                })
                corner(dot)
                local dscale = new("UIScale", { Scale = 1, Parent = dot })
                local ico = new("ImageLabel", {
                        BackgroundTransparency = 1, AnchorPoint = V2(0, 0.5), Position = U2(0, 13, 0.5, 0),
                        Size = UDim2.fromOffset(18, 18), ImageColor3 = col, Visible = false, Parent = f,
                })
                local icoScale = new("UIScale", { Scale = 1, Parent = ico })
                local hasIco = false
                for _, nm in ipairs(isT and { "hourglass", "timer", "alarm-clock" } or { "timer", "alarm-clock", "clock" }) do
                        local okI = false
                        pcall(function() okI = applyIcon(ico, nm, Creator) and true or false end)
                        if okI then
                                hasIco = true
                                break
                        end
                end
                ico.Visible = hasIco
                dot.Visible = not hasIco
                if hasIco then ico.ImageColor3 = col end
                label(f, {
                        Font = FONT, TextSize = 13, TextColor3 = C.Sub, TextXAlignment = Enum.TextXAlignment.Left,
                        AnchorPoint = V2(0, 0.5), Position = U2(0, hasIco and 38 or 34, 0.5, 0), Size = UDim2.fromOffset(84, 18), Text = isT and "Timer" or "Watch",
                })
                local val = label(f, {
                        Font = FONTB, TextSize = 14, TextXAlignment = Enum.TextXAlignment.Right,
                        AnchorPoint = V2(1, 0.5), Position = U2(1, -16, 0.5, 0), Size = UDim2.fromOffset(56, 18), Text = "",
                })
                TweenService:Create(hasIco and icoScale or dscale, TweenInfo.new(0.6, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), { Scale = hasIco and 1.14 or 1.25 }):Play()
                local acc, last = 1, nil
                function v.Set()
                        acc = 1
                end
                function v.Tick(dt)
                        acc = acc + dt
                        if acc < 0.25 then
                                return
                        end
                        acc = 0
                        local okA, acts = pcall(function() return DIM.Acts and DIM.Acts() or {} end)
                        if not okA or type(acts) ~= "table" then
                                return
                        end
                        for _, a in ipairs(acts) do
                                if a.kind == kind and a.text ~= last then
                                        last = a.text
                                        val.Text = a.text or ""
                                end
                        end
                end
                return v
        end
        local CARD_ORDER = { "home", "music", "cross", "timer", "watch" }
        local function buildCard()
                local v = makeView("Card", SPEC.Card.W, SPEC.Card.H)
                local f = v.frame
                v.page, v.pages, v.dots = nil, {}, {}
                local ORANGE, PURPLE, RED = ACT_COL.timer, ACT_COL.stopwatch, C.Red
                local WHITE, SUB = Color3.new(1, 1, 1), C.Sub
                local function pageH(name)
                        return SPEC.Card.H
                end
                local function idxOf(name)
                        for i, n in ipairs(CARD_ORDER) do
                                if n == name then
                                        return i
                                end
                        end
                        return 1
                end
                local function actOf(kind)
                        local ok, acts = pcall(function() return DIM.Acts and DIM.Acts() or {} end)
                        if ok and type(acts) == "table" then
                                for _, a in ipairs(acts) do
                                        if a.kind == kind then
                                                return a
                                        end
                                end
                        end
                        return nil
                end
                local function avail()
                        -- Overview, Music and Longxgen are permanent destinations.
                        -- Each live Timer / Stopwatch owns a separate icon slot on the Liquid Glass axis.
                        local out = { "home", "music", "cross" }
                        local active = { timer = actOf("timer") ~= nil, watch = actOf("stopwatch") ~= nil }
                        if active.timer then out[#out + 1] = "timer" end
                        if active.watch then out[#out + 1] = "watch" end
                        return out
                end
                local function newPage(name, c1, c2, c3)
                        local pg = new("CanvasGroup", {
                                Name = "Page_" .. name, BackgroundTransparency = 1, GroupTransparency = 1, AnchorPoint = V2(0.5, 0.5),
                                Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(SPEC.Card.W, pageH(name)), Visible = false, Parent = f,
                        })
                        local bgf = frame({ BackgroundColor3 = WHITE, Size = UDim2.fromScale(1, 1), Parent = pg })
                        corner(bgf, SPEC.Card.R)
                        new("UIGradient", {
                                Rotation = 90,
                                Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, c1), ColorSequenceKeypoint.new(0.5, c2), ColorSequenceKeypoint.new(1, c3) }),
                                Parent = bgf,
                        })
                        v.pages[name] = { frame = pg, bgf = bgf }
                        return pg
                end
                local function section(parent)
                        return new("CanvasGroup", { BackgroundTransparency = 1, GroupTransparency = 1, Size = UDim2.fromScale(1, 1), Parent = parent })
                end
                local function grabber(parent)
                        corner(frame({
                                BackgroundColor3 = Color3.fromRGB(150, 150, 156), BackgroundTransparency = 0.45,
                                Position = UDim2.fromOffset(152, 6), Size = UDim2.fromOffset(36, 4), Parent = parent,
                        }))
                end
                local function mkBtn(parent, x, y, w, h, color, text, size)
                        local b = new("TextButton", {
                                BackgroundColor3 = color, Text = text, Font = FONTB, TextSize = size or 15, TextColor3 = WHITE,
                                AutoButtonColor = false, Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(w, h), Parent = parent,
                        })
                        corner(b, math.floor(h / 2))
                        local sc = new("UIScale", { Scale = 1, Parent = b })
                        pressFx(b, sc, 0.94)
                        XC.glass(b)
                        return b
                end
                local function addTabs(parent)
                        local NAV_LABELS = {
                                home = "Overview", music = "Music", cross = "Longxgen",
                                timer = "Timer", watch = "Stopwatch",
                        }
                        local NAV_ORDER = { "home", "music", "cross", "timer", "watch" }
                        local SLOT, TAB_W, TAB_H = 58, 56, 22
                        local seg = frame({
                                BackgroundColor3 = Color3.fromRGB(24, 20, 38), BackgroundTransparency = 0.34,
                                Position = UDim2.fromOffset(80, 151), Size = UDim2.fromOffset(180, 28), Parent = parent,
                        })
                        corner(seg, 15)
                        new("UIStroke", { Thickness = 1, Color = Color3.new(1, 1, 1), Transparency = 0.72, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = seg })
                        local sel = frame({
                                BackgroundColor3 = Color3.fromRGB(255, 255, 255), BackgroundTransparency = 0.64,
                                Position = UDim2.fromOffset(3, 3), Size = UDim2.fromOffset(TAB_W, TAB_H), Parent = seg,
                        })
                        sel.Active = false
                        corner(sel, 11)
                        new("UIGradient", {
                                Rotation = 90,
                                Color = ColorSequence.new({
                                        ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
                                        ColorSequenceKeypoint.new(0.48, Color3.fromRGB(224, 218, 244)),
                                        ColorSequenceKeypoint.new(1, Color3.fromRGB(176, 166, 214)),
                                }),
                                Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.04), NumberSequenceKeypoint.new(1, 0.34) }),
                                Parent = sel,
                        })
                        local rim = new("UIStroke", { Thickness = 1.15, Color = Color3.new(1, 1, 1), Transparency = 0.16, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = sel })
                        new("UIGradient", {
                                Rotation = 35,
                                Transparency = NumberSequence.new({
                                        NumberSequenceKeypoint.new(0, 0.05), NumberSequenceKeypoint.new(0.34, 0.72),
                                        NumberSequenceKeypoint.new(0.7, 0.88), NumberSequenceKeypoint.new(1, 0.12),
                                }), Parent = rim,
                        })
                        local sheen = frame({
                                BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.82,
                                AnchorPoint = V2(0.5, 0), Position = U2(0.5, 0, 0, 1),
                                Size = U2(1, -12, 0.42, 0), Parent = sel,
                        })
                        sheen.Active = false
                        corner(sheen)
                        new("UIGradient", { Rotation = 90, Transparency = NumberSequence.new(0, 1), Parent = sheen })
                        local scl = new("UIScale", { Scale = 1, Parent = sel })
                        if XC and XC.glass then
                                pcall(XC.glass, seg)
                                pcall(XC.glass, sel)
                        end

                        local buttons, activityIcons, slotPages = {}, {}, {}
                        for i, name in ipairs(NAV_ORDER) do
                                local b = new("TextButton", {
                                        BackgroundTransparency = 1, Text = NAV_LABELS[name], Font = FONTB,
                                        TextSize = 10, TextColor3 = SUB, TextTruncate = Enum.TextTruncate.AtEnd,
                                        AutoButtonColor = false, Position = UDim2.fromOffset(3 + SLOT * (i - 1), 3),
                                        Size = UDim2.fromOffset(TAB_W, TAB_H), Visible = false,
                                        ZIndex = 5, Parent = seg,
                                })
                                b.TextScaled = true
                                new("UITextSizeConstraint", { MaxTextSize = 11, MinTextSize = 7, Parent = b })
                                local activityIcon = new("ImageLabel", {
                                        Name = "ActivityNavIcon", BackgroundTransparency = 1,
                                        AnchorPoint = V2(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
                                        Size = UDim2.fromOffset(19, 19), ImageTransparency = 1,
                                        ImageColor3 = name == "timer" and ACT_COL.timer or ACT_COL.stopwatch,
                                        Visible = false, ZIndex = 7, Parent = b,
                                })
                                local activityScale = new("UIScale", { Scale = 0.58, Parent = activityIcon })
                                activityIcons[i] = { image = activityIcon, scale = activityScale, kind = nil, token = 0 }
                                buttons[i] = b
                        end

                        -- Soft-liquid tuning: critically damped enough to stay on-axis,
                        -- with a short gel-like rebound rather than a long oscillation.
                        local navSpring = Spring.new(3, { r = 0.29, d = 0.91 })
                        local warpSpring = Spring.new(0, { r = 0.24, d = 0.92 })
                        local tiltSpring = Spring.new(0, { r = 0.30, d = 0.94 })
                        local drag, enabled, layoutKey = nil, true, nil
                        local slotCount = 3

                        local function pagesNow()
                                local a = avail()
                                if type(a) ~= "table" or #a == 0 then
                                        return { "home", "music", "cross" }
                                end
                                return a
                        end
                        local function indexOf(name, pages)
                                for i, item in ipairs(pages or pagesNow()) do
                                        if item == name then return i end
                                end
                                return nil
                        end
                        local function nearest(x, pages)
                                local count = #(pages or pagesNow())
                                return math.clamp(math.floor((x - 3) / SLOT + 0.5) + 1, 1, count)
                        end
                        local function selectedX(name, pages)
                                local idx = indexOf(name, pages) or 1
                                return 3 + SLOT * (idx - 1)
                        end
                        local function disconnectDrag(d)
                                for _, c in ipairs(d and d.conns or {}) do
                                        pcall(function() c:Disconnect() end)
                                end
                        end
                        local function snapToCurrent()
                                local pages = pagesNow()
                                navSpring:to(selectedX(v.page or "home", pages), { r = 0.28, d = 0.76 })
                                warpSpring:to(0)
                                tiltSpring:to(0)
                        end
                        local function setActivityIcon(i, b, name)
                                local state = activityIcons[i]
                                if not state then return end
                                local kind = (name == "timer" or name == "watch") and name or nil
                                local previous = state.kind
                                if previous == kind then
                                        if kind then b.Text = "" end
                                        return
                                end
                                state.token = state.token + 1
                                local token = state.token
                                state.kind = kind
                                local img, scale = state.image, state.scale
                                if kind then
                                        b.Text = ""
                                        b.Visible = true
                                        if previous then
                                                TweenService:Create(img, TweenInfo.new(0.11, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { ImageTransparency = 1 }):Play()
                                                TweenService:Create(scale, TweenInfo.new(0.13, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { Scale = 0.62 }):Play()
                                        end
                                        task.delay(previous and 0.10 or 0, function()
                                                if state.token ~= token or state.kind ~= kind or not b.Parent then return end
                                                local names = kind == "timer" and { "hourglass", "timer", "alarm-clock" } or { "stopwatch", "timer", "alarm-clock", "clock" }
                                                local applied = false
                                                for _, iconName in ipairs(names) do
                                                        local okIcon = false
                                                        pcall(function() okIcon = applyIcon(img, iconName, Creator) and true or false end)
                                                        if okIcon then applied = true break end
                                                end
                                                if not applied then
                                                        img.Visible = false
                                                        b.Text = kind == "timer" and "⌛" or "⏱"
                                                        b.TextSize = 17
                                                        return
                                                end
                                                b.Text = ""
                                                img.ImageColor3 = kind == "timer" and ACT_COL.timer or ACT_COL.stopwatch
                                                img.Visible = true
                                                img.ImageTransparency = 1
                                                scale.Scale = 0.58
                                                TweenService:Create(img, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { ImageTransparency = 0 }):Play()
                                                TweenService:Create(scale, TweenInfo.new(0.34, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 }):Play()
                                        end)
                                else
                                        b.Text = ""
                                        if previous then
                                                b.Visible = true
                                                TweenService:Create(img, TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { ImageTransparency = 1 }):Play()
                                                TweenService:Create(scale, TweenInfo.new(0.16, Enum.EasingStyle.Back, Enum.EasingDirection.In), { Scale = 0.52 }):Play()
                                                task.delay(0.17, function()
                                                        if state.token == token and state.kind == nil then
                                                                img.Visible = false
                                                                if slotPages[i] == nil then b.Visible = false end
                                                        end
                                                end)
                                        else
                                                img.Visible = false
                                                b.Visible = name ~= nil
                                        end
                                end
                        end
                        local function layout()
                                local pages = pagesNow()
                                local key = table.concat(pages, "|")
                                local changed = key ~= layoutKey
                                slotCount = #pages
                                if changed then
                                        layoutKey = key
                                        local width = 6 + SLOT * slotCount
                                        seg.Size = UDim2.fromOffset(width, 28)
                                        seg.Position = UDim2.fromOffset(math.floor((SPEC.Card.W - width) / 2), 151)
                                        for i, b in ipairs(buttons) do
                                                local name = pages[i]
                                                slotPages[i] = name
                                                setActivityIcon(i, b, name)
                                                if name then
                                                        b.Visible = true
                                                        b.Position = UDim2.fromOffset(3 + SLOT * (i - 1), 3)
                                                        b.Size = UDim2.fromOffset(TAB_W, TAB_H)
                                                        if name ~= "timer" and name ~= "watch" then
                                                                b.Text = NAV_LABELS[name] or name
                                                        end
                                                elseif not activityIcons[i] or not activityIcons[i].image.Visible then
                                                        b.Visible = false
                                                end
                                        end
                                        if drag then
                                                local d = drag
                                                drag = nil
                                                v.dragging = false
                                                disconnectDrag(d)
                                                navSpring:snap(selectedX(v.page or "home", pages))
                                                warpSpring:to(0)
                                                tiltSpring:to(0)
                                        else
                                                navSpring:snap(selectedX(v.page or "home", pages))
                                        end
                                end
                                for i, b in ipairs(buttons) do
                                        local name = pages[i]
                                        b.Active = enabled and name ~= nil
                                        b.TextColor3 = name == v.page and WHITE or Color3.fromRGB(205, 198, 226)
                                        local iconState = activityIcons[i]
                                        if iconState and iconState.kind then
                                                iconState.image.ImageColor3 = name == v.page and WHITE or (iconState.kind == "timer" and ACT_COL.timer or ACT_COL.stopwatch)
                                        end
                                end
                        end
                        local function setPage(name)
                                layout()
                                local pages = pagesNow()
                                if indexOf(name, pages) ~= nil then
                                        navSpring:to(selectedX(name, pages), { r = 0.27, d = 0.74 })
                                end
                                for i, b in ipairs(buttons) do
                                        b.TextColor3 = pages[i] == name and WHITE or Color3.fromRGB(205, 198, 226)
                                end
                        end
                        local function setActive(on)
                                enabled = on == true
                                for i, b in ipairs(buttons) do
                                        b.Active = enabled and b.Visible
                                end
                                if not enabled and drag then
                                        local d = drag
                                        drag = nil
                                        v.dragging = false
                                        disconnectDrag(d)
                                        snapToCurrent()
                                end
                        end
                        local function finishDrag(d)
                                if drag ~= d then return end
                                drag = nil
                                v.dragging = false
                                touch()
                                disconnectDrag(d)
                                local pages = pagesNow()
                                local predicted = (d.lastTx or navSpring.x) + math.clamp(d.velocity or 0, -260, 260) * 0.045
                                local targetIndex = d.moved and nearest(predicted, pages) or math.clamp(d.idx, 1, #pages)
                                local name = pages[targetIndex]
                                local targetX = 3 + SLOT * (targetIndex - 1)
                                navSpring.t = targetX
                                navSpring.v = math.clamp((d.velocity or 0) * 0.045, -92, 92)
                                warpSpring:to(0, { r = 0.25, d = 0.94 })
                                tiltSpring:to(0, { r = 0.31, d = 0.95 })
                                tw(sel, 0.20, { BackgroundTransparency = 0.64 })
                                tw(scl, 0.22, { Scale = 1 }, Enum.EasingStyle.Quint, EOUT)
                                tw(sheen, 0.24, { Position = U2(0.5, 0, 0, 1), Size = U2(1, -12, 0.42, 0) }, Enum.EasingStyle.Quint, EOUT)
                                if enabled and name and name ~= v.page and currentView == v then
                                        v.Go(name)
                                elseif name then
                                        setPage(name)
                                else
                                        snapToCurrent()
                                end
                        end
                        local function begin(idx, inp)
                                local ut = inp.UserInputType
                                if not enabled or (ut ~= Enum.UserInputType.MouseButton1 and ut ~= Enum.UserInputType.Touch) or drag then
                                        return
                                end
                                local pages = pagesNow()
                                if not pages[idx] then return end
                                local d = {
                                        x0 = inp.Position.X, l0 = navSpring.x, lastTx = navSpring.x,
                                        lastT = os.clock(), velocity = 0, moved = false,
                                        idx = idx, conns = {},
                                }
                                drag = d
                                v.dragging = true
                                touch()
                                -- Soft gel press: a small inward compression, not a hard pop.
                                warpSpring:to(2.2, { r = 0.22, d = 0.94 })
                                tw(scl, 0.16, { Scale = 1.035 }, Enum.EasingStyle.Quad, EOUT)
                                tw(sel, 0.14, { BackgroundTransparency = 0.50 })
                                local function update(i)
                                        if drag ~= d or not i or not i.Position then return end
                                        local dx = i.Position.X - d.x0
                                        if not d.moved and math.abs(dx) < 5 then return end
                                        d.moved = true
                                        local tx = math.clamp(d.l0 + dx, 3, 3 + SLOT * (#pagesNow() - 1))
                                        local now = os.clock()
                                        local elapsed = math.max(now - d.lastT, 0.001)
                                        d.velocity = (tx - (d.lastTx or tx)) / elapsed
                                        d.lastTx, d.lastT = tx, now
                                        navSpring:snap(tx)
                                        local bulge = math.clamp(2 + math.abs(dx) * 0.022 + math.abs(d.velocity) * 0.0011, 0, 8)
                                        warpSpring:snap(bulge)
                                        tiltSpring:snap(math.clamp(d.velocity * 0.0010, -1.8, 1.8))
                                        sel.Position = UDim2.fromOffset(tx, 3 - bulge * 0.025)
                                        sel.Size = UDim2.fromOffset(math.min(TAB_W + bulge, SLOT + 1), TAB_H - math.min(bulge * 0.075, 0.65))
                                        sel.Rotation = tiltSpring.x
                                        scl.Scale = 1.008 + math.min(bulge * 0.0038, 0.032)
                                        sheen.Position = U2(0.5, math.clamp(dx * 0.035, -5, 5), 0, 1)
                                        sheen.Size = U2(1, -12 + math.min(bulge * 0.45, 4), 0.42, 0)
                                end
                                d.conns[1] = UserInputService.InputChanged:Connect(function(i)
                                        if i ~= inp and not (ut == Enum.UserInputType.MouseButton1 and i.UserInputType == Enum.UserInputType.MouseMovement) then
                                                return
                                        end
                                        update(i)
                                end)
                                d.conns[2] = UserInputService.InputEnded:Connect(function(i)
                                        if i == inp or (ut == Enum.UserInputType.MouseButton1 and i.UserInputType == Enum.UserInputType.MouseButton1) then
                                                finishDrag(d)
                                        end
                                end)
                        end
                        for i, b in ipairs(buttons) do
                                b.InputBegan:Connect(function(inp) begin(i, inp) end)
                        end
                        layout()
                        return {
                                seg = seg, sel = sel, buttons = buttons,
                                SetActive = setActive, Layout = layout, SetPage = setPage,
                                Step = function(dt)
                                        if drag then return end
                                        local h = math.clamp(tonumber(dt) or 0, 0, 0.05)
                                        if h <= 0 then return end
                                        navSpring:step(h)
                                        warpSpring:step(h)
                                        tiltSpring:step(h)
                                        local bulge = math.clamp(warpSpring.x, 0, 8)
                                        sel.Position = UDim2.fromOffset(navSpring.x, 3 - bulge * 0.025)
                                        sel.Size = UDim2.fromOffset(math.min(TAB_W + bulge, SLOT + 1), TAB_H - math.min(bulge * 0.075, 0.65))
                                        sel.Rotation = tiltSpring.x
                                        scl.Scale = 1 + math.min(bulge * 0.0038, 0.032)
