                local enabled = not (f ~= nil and f.Enable ~= nil and f.Enable.BCToast == false)
                return enabled and not destroyed and gui ~= nil and gui.Parent ~= nil
        end
        Island.BCToastQ = {}
        function Island.BCToastBuild()
                if Island.BCToastUI then
                        return Island.BCToastUI
                end
                local T = {}
                T.root = new("TextButton", {
                        Name = "WABCToast", AutoButtonColor = false, Text = "", BackgroundColor3 = Color3.fromRGB(13, 14, 18),
