                        AnchorPoint = V2(0, 0.5), Position = U2(0, 48, 0.5, 9), Size = U2(1, -60, 0, 14), ZIndex = 31, Text = "", Visible = false,
                })
                T.bar = frame({ BackgroundColor3 = C.White, BackgroundTransparency = 0.16, AnchorPoint = V2(0.5, 1), Position = U2(0.5, 0, 1, -2), Size = U2(1, -32, 0, 2), ZIndex = 31, Parent = T.root })
                corner(T.bar)
