        local function toastScreenY()
                local y = 8
                pcall(function()
                        y = island.AbsolutePosition.Y + island.AbsoluteSize.Y + 10
                end)
                return math.max(8, y)
        end
        function Island.BCToastRun()
                if Island.BCToastBusy then
                        return
                end
                Island.BCToastBusy = true
                task.spawn(function()
                        local T = Island.BCToastBuild()
                        while #Island.BCToastQ > 0 and Island.BCToastOn() do
                                local it = table.remove(Island.BCToastQ, 1)
                                local level = it.level
                                if level == "success" or level == "green" then level = "green"
                                elseif level == "error" or level == "red" then level = "red"
                                else level = "yellow" end
                                local palette = BC_TOAST_GRAD[level] or BC_TOAST_GRAD.yellow
                                local c1,c2,glyph = palette[1],palette[2],palette[3]
                                T.disc.BackgroundColor3, T.bar.BackgroundColor3 = c1, c1
                                T.discGrad.Color = ColorSequence.new(c1,c2)
                                T.barGrad.Color = ColorSequence.new(c1,c2)
                                T.glyph.Text = glyph
                                T.glyph.TextColor3 = level == "yellow" and Color3.fromRGB(35,27,8) or Color3.fromRGB(7,13,14)
                                local two = it.desc ~= nil and tostring(it.desc) ~= "" and tostring(it.desc) ~= it.title
                                T.title.Text = it.title
                                T.desc.Text = two and tostring(it.desc) or ""
                                T.desc.Visible = two
                                T.title.Position = U2(0, 48, 0.5, two and -8 or 0)
                                local showY = toastScreenY()
                                T.root.Position = U2(0.5, 0, 0, showY - 62)
                                T.root.Visible = true
                                T.ds.Scale = 0.3
                                tw(T.root, 0.4, { Position = U2(0.5, 0, 0, showY) }, BACK, EOUT)
                                tw(T.ds, 0.5, { Scale = 1 }, BACK, EOUT)
                                local hold = math.clamp(tonumber(it.dur) or 2.6, 1.8, 4)
                                T.bar.Size = U2(1, -32, 0, 2)
                                tw(T.bar, hold, { Size = U2(0, 0, 0, 2) }, Enum.EasingStyle.Linear, EOUT)
                                Island.BCToastSkip = false
                                local t0 = os.clock()
                                while not destroyed and Island.BCToastOn() and not Island.BCToastSkip and os.clock() - t0 < hold do
                                        task.wait(0.05)
                                end
                                tw(T.root, 0.26, { Position = U2(0.5, 0, 0, toastScreenY() - 62) }, Enum.EasingStyle.Quint, EIN)
                                task.wait(0.28)
                                T.root.Visible = false
                        end
                        Island.BCToastBusy = false
                        if not destroyed and #Island.BCToastQ > 0 then
                                local rest = Island.BCToastQ
                                Island.BCToastQ = {}
                                for _, it in ipairs(rest) do
                                        pcall(function()
                                                if it.notify then
                                                        Island:Notify(it.d)
                                                else
                                                        Island:StatusPill(it.level, it.d)
                                                end
                                        end)
                                end
                        end
                end)
        end
