                if #q >= 3 then
                        table.remove(q, 1)
                end
                q[#q + 1] = {
                        level = level, d = d, notify = isNotify, title = tostring(d.Text or d.Title or d.Content or ""),
                        desc = d.Description or ((isNotify and d.Title and d.Content) and d.Content or nil), dur = d.Duration,
                }
                Island.BCToastRun()
        end
