local function vec(v)
local ty=typeof(v)
if ty=="number"then return {v}
elseif ty=="UDim2"then return {v.X.Scale,v.X.Offset,v.Y.Scale,v.Y.Offset}
elseif ty=="Vector2"then return {v.X,v.Y}
elseif ty=="Color3"then return {v.R,v.G,v.B}
elseif ty=="UDim"then return {v.Scale,v.Offset}
end
return nil
end
local function unvec(ty,c)
if ty=="number"then return c[1]
elseif ty=="UDim2"then return UDim2.new(c[1],c[2],c[3],c[4])
elseif ty=="Vector2"then return Vector2.new(c[1],c[2])
elseif ty=="Color3"then return Color3.new(math.clamp(c[1],0,1),math.clamp(c[2],0,1),math.clamp(c[3],0,1))
elseif ty=="UDim"then return UDim.new(c[1],c[2])
end
end
local ents={}
for k,v in pairs(props)do
local okc,cur=pcall(function()return inst[k]end)
local tv=typeof(v)
local a=okc and vec(cur)
local b=vec(v)
if not a or not b or typeof(cur)~=tv then return r._WATweenOld(inst,props,time,style,dir)end
ents[#ents+1]={inst=inst,k=k,ty=tv,cur=a,vel={},tgt=b}
for i=1,#a do ents[#ents].vel[i]=0 end
end
local reg=r._WAReg
if not reg then reg=setmetatable({},{__mode="k"})r._WAReg=reg end
local per=reg[inst]
if not per then per={}reg[inst]=per end
local t=math.max(tonumber(time)or 0.2,0.02)
local bouncy=(style==Enum.EasingStyle.Back and dir==Enum.EasingDirection.Out)
local zeta=bouncy and 0.55 or 0.9
local w=5.8/(zeta*t)
local S=r._BSP
if not S then S={list={},con=nil}r._BSP=S end
for _,e in ipairs(ents)do
local old=per[e.k]
if old then old.dead=true end
e.w=w e.z=zeta
e.clamp=(string.find(e.k,"Transparency")~=nil)
per[e.k]=e
S.list[#S.list+1]=e
end
if not S.con then
S.con=game:GetService("RunService").RenderStepped:Connect(function(dt)
dt=math.min(dt,1/20)
local n=math.max(1,math.ceil(dt/(1/120)))
local h=dt/n
local list=S.list
local i=1
while i<=#list do
local e=list[i]
local rm=e.dead or not e.inst.Parent and not e.inst:IsDescendantOf(game)
if not rm then
local maxd,maxv=0,0
for c=1,#e.cur do
local x,v=e.cur[c],e.vel[c]
local tg=e.tgt[c]
for _=1,n do
local a=-2*e.z*e.w*v-e.w*e.w*(x-tg)
v=v+a*h
x=x+v*h
end
e.cur[c],e.vel[c]=x,v
maxd=math.max(maxd,math.abs(x-tg))
maxv=math.max(maxv,math.abs(v))
end
local done=maxd<0.004 and maxv<0.05
if done then for c=1,#e.cur do e.cur[c]=e.tgt[c] end end
local cv=e.cur
if e.clamp then cv={math.clamp(cv[1],0,1)}end
pcall(r._WASet,e.inst,e.k,unvec(e.ty,cv))
if done then rm=true end
end
if rm then
local p=r._WAReg and r._WAReg[e.inst]
if p and p[e.k]==e then p[e.k]=nil end
table.remove(list,i)
else
i=i+1
end
end
if #list==0 and S.con then S.con:Disconnect()S.con=nil end
end)
end
return {Cancel=function()for _,e in ipairs(ents)do e.dead=true end end,Play=function()end,Pause=function()end,Completed={Connect=function()return{Disconnect=function()end}end}}
end
function r.WAScale(inst)
