function r.WAPress(trigger,target,flag,lockedFn)
if not trigger or not target then return end
local function isIn(i)
return i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch
end
local function up()
local sc=target:FindFirstChild("WAScale")
if sc and sc.Scale~=1 then
r.WATween(sc,{Scale=1},0.24,Enum.EasingStyle.Back,Enum.EasingDirection.Out)
end
end
r.AddSignal(trigger.InputBegan,function(i)
if not isIn(i)or not r.WAOn(flag)then return end
if lockedFn and lockedFn()then return end
r.WATween(r.WAScale(target),{Scale=0.965},0.09,Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
end)
r.AddSignal(trigger.InputEnded,function(i)
if isIn(i)then up()end
end)
r.AddSignal(trigger.MouseLeave,up)
end
function r.WAToggleBind(track,trigger,lockedFn)
if not track or not trigger then return end
local base
local token=0
local function isIn(i)
return i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch
end
local function shifted(sv)
local ap=track.AnchorPoint
