end
r.AddSignal(trigger.InputBegan,function(i)
if not isIn(i)or not r.WAOn("WAToggle")then return end
if lockedFn and lockedFn()then return end
token=token+1
if not base then base=track.Position end
r.WATween(r.WAScale(track),{Scale=0.86},0.09,Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
r.WATween(track,{Position=shifted(0.86)},0.09,Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
end)
local function release()
if not base then return end
local my=token
task.delay(0.06,function()
if my~=token or not track.Parent then return end
local sc=track:FindFirstChild("WAScale")
if sc then r.WATween(sc,{Scale=1},0.22,Enum.EasingStyle.Back,Enum.EasingDirection.Out)end
r.WATween(track,{Position=base},0.22,Enum.EasingStyle.Back,Enum.EasingDirection.Out)
end)
end
r.AddSignal(trigger.InputEnded,function(i)
if isIn(i)then release()end
end)
r.AddSignal(trigger.MouseLeave,release)
end
