function r.WADropOpen(menu,tabs,ty,ap,skipBloom)
if not menu then return end
local revealUntil=tonumber(menu:GetAttribute("WADropRevealUntil"))or 0
local revealWait=math.max(0,revealUntil-os.clock())
-- A second UIScale tween while the circle is morphing makes the frame edge wobble.
if revealWait<=0 then
local sc=r.WAScale(menu)
r.WACancel(sc,{"Scale"})
sc.Scale=0.96
r.WATween(sc,{Scale=1},0.22,Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
end
local tok=r.WATokBump(menu,"drop")
if type(tabs)~="table"then return end
for idx,row in ipairs(r.WARowList(tabs))do
local tf=r.WATitleOf(row)
if tf then
local dl=revealWait+math.min((idx-1)*0.038,0.30)+(r.WAStackHoldT and r.WAStackHoldT(idx)or 0)
for _,d in ipairs(tf:GetChildren())do
if d:IsA("TextLabel")then
r.WACancel(d,{"TextTransparency"})
d.TextTransparency=1
task.delay(dl,function()
if d.Parent and r.WATokOk(menu,"drop",tok)then
r.WATween(d,{TextTransparency=r.WALblRestT(row,d,ty)},0.22,Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
end
end)
end
end
end
end
task.delay(revealWait+1.35,function()
if r.WATokOk(menu,"drop",tok)then r.WALblSnap(tabs,ty)end
end)
end
