local function WADropAnchorCenter(menu,ap)
local parent=menu.Parent
if not parent then return 0,0 end
local pp=parent.AbsolutePosition
local ps=parent.AbsoluteSize
local cx,cy=ps.X*0.5,ps.Y*0.5
local trigger=ap and(ap.UIElements and ap.UIElements.Dropdown or(ap.DropdownFrame and ap.DropdownFrame.UIElements and ap.DropdownFrame.UIElements.Main))
if trigger and trigger.Parent then
local tp,ts=trigger.AbsolutePosition,trigger.AbsoluteSize
cx=tp.X+ts.X*0.5-pp.X
cy=tp.Y+ts.Y*0.5-pp.Y
end
return math.clamp(cx,6,math.max(6,ps.X-6)),math.clamp(cy,6,math.max(6,ps.Y-6))
end
function r.WABloomRunOld(menu,ap,state,kind,m0)
-- P94 bloom: ONE NumberValue tween drives position, size, corner and fade from a single progress m,
-- so nothing can drift apart. open = light back overshoot, content appears after the surface (as in the Night Hub video).
local TS=game:GetService("TweenService")
local parent=menu.Parent
if not parent then return nil end
local cfg=(_G.FARMX and _G.FARMX.Cfg)or{}
local isOpen=kind=="open"
local T=isOpen and(tonumber(cfg.WABloomOpenT)or 0.38)or(tonumber(cfg.WABloomCloseT)or 0.22)
local c1=tonumber(cfg.WABloomOver)or 1.05
local c3=c1+1
local D=10
local R=state.cornerRadius and state.cornerRadius.Offset or 18
if not(R>0)then R=18 end
local imageProp="ImageTransparency"
if not pcall(function()local _=menu.ImageTransparency end)then imageProp="BackgroundTransparency" end
local corner=WADropCorner(menu,state)
local nv=Instance.new("NumberValue")
nv.Value=0
local motion={kind=kind,m=m0,tweens={}}
local conn
local done=false
local shown=m0>=0.5
local function put(m)
local W,H=parent.AbsoluteSize.X,parent.AbsoluteSize.Y
if W<2 or H<2 then return end
local ax,ay=WADropAnchorCenter(menu,ap)
local mp=math.clamp(m,0,1)
local w=math.max(D,D+(W-D)*m)
local h=math.max(D,D+(H-D)*m)
menu.Position=UDim2.fromScale((ax+(W*0.5-ax)*mp)/W,(ay+(H*0.5-ay)*mp)/H)
menu.Size=UDim2.fromScale(w/W,h/H)
local half=math.min(w,h)*0.5
corner.CornerRadius=UDim.new(0,math.min(half,half+(R-half)*mp))
local a
if isOpen then a=0.55*(1-math.clamp(m*4,0,1))else a=1-math.clamp(m*2.5,0,1)end
pcall(function()menu[imageProp]=a end)
if isOpen and not shown and m>=0.5 then
shown=true
r.WADropContent(menu,true)
end
end
local function apply(t)
local m
if isOpen then
local x=t-1
m=m0+(1-m0)*(1+c3*x*x*x+c1*x*x)
else
m=m0*(1-t*t)
end
motion.m=m
put(m)
end
local function finish(completed)
if done then return end
done=true
if conn then conn:Disconnect()conn=nil end
pcall(function()nv:Destroy()end)
if r._WADropMotion[menu]==motion then r._WADropMotion[menu]=nil end
if not completed or not menu.Parent then return end
menu.AnchorPoint=state.anchor
menu.Position=state.position
menu.Size=state.size
menu.ClipsDescendants=state.clip
if state.corner and state.corner.Parent then
if state.cornerCreated then state.corner:Destroy()else state.corner.CornerRadius=state.cornerRadius end
end
if r._WADropBase[menu]==state then r._WADropBase[menu]=nil end
if isOpen then
pcall(function()menu[imageProp]=0 end)
r.WADropContent(menu,true)
menu:SetAttribute("WADropRevealUntil",0)
else
pcall(function()menu[imageProp]=1 end)
end
end
motion.stop=function()finish(false)end
menu.AnchorPoint=Vector2.new(0.5,0.5)
menu.ClipsDescendants=true
if isOpen and not shown then r.WADropContent(menu,false)end
apply(0)
local tween=TS:Create(nv,TweenInfo.new(T,Enum.EasingStyle.Linear),{Value=1})
motion.tweens={tween}
r._WADropMotion[menu]=motion
conn=nv.Changed:Connect(function(t)
if done then return end
if not pcall(apply,t)then finish(true)end
end)
tween.Completed:Connect(function(pb)
if pb==Enum.PlaybackState.Completed then pcall(apply,1)finish(true)else finish(false)end
end)
tween:Play()
return T
end
function r.WABloomRun(menu,ap,state,kind,m0)
-- [QM-FARM] P95-3 WABloomSpring | Boncuti Spring (stiffness/damping, 1 stepper chung, ngu khi xong) + stretch/overshoot Boncuti Drop | gan tai WADropClose
if not r.WAOn("WABloomSpring")then return r.WABloomRunOld(menu,ap,state,kind,m0)end
local parent=menu.Parent
if not parent then return nil end
local cfg=(_G.FARMX and _G.FARMX.Cfg)or{}
local isOpen=kind=="open"
local T=isOpen and(tonumber(cfg.WABloomOpenT)or 0.46)or(tonumber(cfg.WABloomCloseT)or 0.26)
local D=10
local R=state.cornerRadius and state.cornerRadius.Offset or 18
if not(R>0)then R=18 end
local imageProp="ImageTransparency"
if not pcall(function()local _=menu.ImageTransparency end)then imageProp="BackgroundTransparency" end
local corner=WADropCorner(menu,state)
local function soft(x)x=math.clamp(x,0,1)return x*x*(3-2*x)end
local nv=Instance.new("NumberValue")
nv.Name="WABloomM"
nv.Value=m0
nv.Parent=menu
local rim,rc,rs
pcall(function()
rim=Instance.new("Frame")
rim.Name="WABloomRim"
rim.BackgroundTransparency=1
rim.BorderSizePixel=0
rim.Active=false
rim.AnchorPoint=Vector2.new(0.5,0.5)
rim.ZIndex=(menu.ZIndex or 1)+60
rc=Instance.new("UICorner")
rc.Parent=rim
rs=Instance.new("UIStroke")
rs.Thickness=1.5
rs.Color=Color3.new(1,1,1)
rs.Transparency=1
rs.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
rs.Parent=rim
local rg=Instance.new("UIGradient")
