r.STK={H=36,P=31,S=0.04,VIS=4}
function r.STK.layout(i,f,P)
local H=r.STK.H
-- Relative positions are intentionally proportional to card height:
-- row 2 is ~70% visible (30% covered), row 3 is ~20% visible (80% covered).
local firstGap=math.floor(H*0.70+0.5)
local secondGap=math.floor(H*0.20+0.5)
local deepGap=math.floor(H*0.15+0.5)
local first=math.floor(f+0.000001)
local slot=i-first
if slot<0 or slot>4 then return 0,0,0,0 end
local frac=math.clamp(f-first,0,0.9999)
local function offset(n)
if n<=0 then return 0 end
if n==1 then return firstGap end
if n==2 then return firstGap+secondGap end
return firstGap+secondGap+(n-2)*deepGap
end
local y=offset(slot)
if slot>0 then y=y-frac*(offset(slot)-offset(slot-1)) end
local sc,al,z
if slot==0 then
sc,al,z=1,1,190
elseif slot==1 then
sc,al,z=0.985,1,186
elseif slot==2 then
sc,al,z=0.96,0.98,182
else
local deep=slot-2
sc=math.max(0.90,0.96-0.025*deep)
al=math.max(0.72,1-0.08*deep)
z=178-slot*4
end
return y,sc,al,z
end
function r.STK.innerStack(P,count)
local H=r.STK.H
local firstGap=math.floor(H*0.70+0.5)
local secondGap=math.floor(H*0.20+0.5)
local deepGap=math.floor(H*0.15+0.5)
local n=math.clamp(tonumber(count)or 5,1,5)
local last=math.max(0,n-1)
local pos
if last==0 then pos=0 elseif last==1 then pos=firstGap elseif last==2 then pos=firstGap+secondGap else pos=firstGap+secondGap+(last-2)*deepGap end
return H+pos+12
end
function r.STKVel(d,trel)
local first,last,n
for i=#d.buf,1,-1 do
local s=d.buf[i]
if s.t<trel-0.08 then break end
first=s
last=last or s
n=(n or 0)+1
end
if not n or n<2 or last.t-first.t<0.03 then return 0 end
local v=(last.f-first.f)/(last.t-first.t)
if math.abs(v)<0.8 then return 0 end
return math.clamp(v,-4.5,4.5)
end
function r.STKRestore(ap)
local st=ap.STK
if not st then return end
ap.STK=nil
ap.STKOn=false
st.dead=true
pcall(r.WABlurPulse,0)
for _,c in ipairs(st.conns)do pcall(function()c:Disconnect()end)end
st.conns={}
for _,row in ipairs(st.items)do
local ref=st.refs[row]
local it=ref and ref.it
local o=st.orig[row]
if it and it.Parent and o then
it.Size,it.AutomaticSize,it.Position,it.AnchorPoint=o.Size,o.Auto,o.Pos,o.Anc
it.ZIndex,it.Visible,it.ClipsDescendants=o.Z,true,o.Clip
if ref.sco then ref.sco:Destroy()end
if ref.hl and o.Hi then ref.hl.ImageTransparency=o.Hi end
it.ImageTransparency=row.Selected and st.selT or r.WARowT(1)
if ref.lb then ref.lb.TextTransparency=row.Selected and 0 or 0.4 end
if ref.ic then ref.ic.ImageTransparency=row.Selected and 0 or 0.2 end
end
end
local sf=st.sf
if sf and sf.Parent then
sf.AutomaticCanvasSize,sf.CanvasSize,sf.ScrollingEnabled=st.sfo.Auto,st.sfo.Canvas,st.sfo.Scroll
sf.Active=st.sfo.Active
sf.ScrollBarThickness=st.sfo.Bar or sf.ScrollBarThickness
sf.ScrollBarImageTransparency=st.sfo.BarAlpha or sf.ScrollBarImageTransparency
sf.ScrollingDirection=st.sfo.Direction or sf.ScrollingDirection
sf.ElasticBehavior=st.sfo.Elastic or sf.ElasticBehavior
sf.ClipsDescendants=st.sfo.Clip
sf.CanvasPosition=Vector2.new(0,0)
if st.lay then st.lay.Parent=sf end
end
if st.mc and st.mc.Parent then st.mc.Size=st.mco end
for _,g in ipairs({st.rail,st.less})do if g and g.Parent then g:Destroy()end end
end
function r.STKClose(ap)
local st=ap.STK
if not st or st.closing then return end
st.closing=true
st.lock=true
st.drag=nil
local mc=st.mc
local function try(n)
if ap.STK~=st then return end
if mc and mc.Parent and mc.Visible and n<14 then
task.delay(0.05,function()try(n+1)end)
return
end
r.STKRestore(ap)
end
task.delay(0.3,function()try(0)end)
end
function r.STKDump()
local st=r._STKLast
if not st then print("[STK] chua mo dropdown stack nao")return end
local s=st.stats
local secs=math.max(os.clock()-s.t0,1e-3)
print(string.format("[STK] N=%d f=%.3f tgt=%d b=%.2f hPx=%.1f uiS=%.3f y=%.1f applies=%d (%.1f/s) avg=%.3f ms findfirstchild_in_apply=0 conns=%d",
st.N,st.f,st.tgt,st.b,st.hPx or -1,st.uiS or -1,st.lastY or -1,s.n,s.n/secs,s.n>0 and s.ms/s.n or 0,#st.conns))
end
-- [QM-FARM] P95-1 STKPlace | goi o STKOpen apply + UpdatePosition nhung KHONG co dinh nghia => STKOpen no loi, pcall nuot, tut ve dropdown thuong | gan tai r.STKOpen
function r.STKPlace(ap,aq,hPx)
local ui=ap and ap.UIElements
local mc=ui and ui.MenuCanvas
local trig=ui and(ui.Dropdown or(ap.DropdownFrame and ap.DropdownFrame.UIElements and ap.DropdownFrame.UIElements.Main))
if not(mc and trig and trig.Parent)then return 0 end
local cam=workspace.CurrentCamera
local vpY=cam and cam.ViewportSize.Y or 800
local pad=(aq and aq.MenuPadding)or 0
local avail=vpY-(trig.AbsolutePosition.Y+trig.AbsoluteSize.Y)-pad-54
local hh=tonumber(hPx)
if not(hh and hh>0)then hh=mc.AbsoluteSize.Y end
local need=hh+pad
local shift=-54
if avail<need then shift=need-avail-54 end
local y=trig.AbsolutePosition.Y+trig.AbsoluteSize.Y-shift+pad*2
mc.Position=UDim2.new(0,trig.AbsolutePosition.X+trig.AbsoluteSize.X,0,y)
return y
end
function r.STKOpen(ap,ao,aq,as,selT)
if not(r.WAOn("WAStack")and r.WAOn("WAStackPersist")and r.WAOn("WAStackFix"))then return false end
if ap.SearchBarEnabled then return false end
if ap.STK then r.STKRestore(ap)end
local items=r.WARowList(ap.Tabs)
table.sort(items,function(a,b)
local ai=a and a.UIElements and a.UIElements.TabItem
local bi=b and b.UIElements and b.UIElements.TabItem
if not ai then return false end
if not bi then return true end
if ai.LayoutOrder~=bi.LayoutOrder then return ai.LayoutOrder<bi.LayoutOrder end
local ay,by=ai.AbsolutePosition.Y,bi.AbsolutePosition.Y
if math.abs(ay-by)>0.5 then return ay<by end
return tostring(a.Name or "")<tostring(b.Name or "")
end)
local N=#items
if N<2 then return false end
local mc,menu=ap.UIElements.MenuCanvas,ap.UIElements.Menu
local clip=menu and menu:FindFirstChild("Frame")
local sf=clip and clip:FindFirstChild("ScrollingFrame")
local lay=ap.UIElements.UIListLayout
if not(mc and menu and clip and sf and lay)then return false end
local UIS=game:GetService("UserInputService")
local RS=game:GetService("RunService")
local fx=_G.FARMX
if fx then fx.STKDump=r.STKDump end
local cfg=(fx and fx.Cfg)or{}
local P=math.clamp(tonumber(cfg.WAStackPeek)or 31,27,33)
local gap=tonumber(cfg.WAStackGap)or 10
local H=r.STK.H
local pad=aq.MenuPadding
local visibleCount=math.min(5,N)
local innerS=r.STK.innerStack(P,visibleCount)
local totalH=N*H+(N-1)*gap
local cam=workspace.CurrentCamera
local vpY=cam and cam.ViewportSize.Y or 800
local uiS=1
if mc.AbsoluteSize.X>0 and mc.Size.X.Offset>0 then uiS=mc.AbsoluteSize.X/mc.Size.X.Offset else uiS=ao.UIScale or 1 end
uiS=math.clamp(uiS,0.2,5)
local wfoot=menu and menu:FindFirstChild("zzWAFoot")
local footH=wfoot and(wfoot.Size.Y.Offset+pad)or 0
local fiveRowsH=H*visibleCount+math.max(0,visibleCount-1)*gap
local viewportCap=math.max(innerS,math.floor(0.5*vpY/uiS)-2*pad-footH)
local maxInner=math.max(innerS,math.min(fiveRowsH,viewportCap))
local expInner=math.max(innerS,math.min(totalH,maxInner))
local f0=0
for i,row in ipairs(items)do if row.Selected then f0=i-1 break end end
local st={items=items,N=N,f=f0,v=0,tgt=f0,b=0,bv=0,bt=0,bprev=0,tTog=0,rb={},rbv={},acc=0,conns={},orig={},refs={},selT=selT or 0.67,sf=sf,lay=lay,mc=mc,mco=mc.Size,
sfo={Auto=sf.AutomaticCanvasSize,Canvas=sf.CanvasSize,Scroll=sf.ScrollingEnabled,Active=sf.Active,
Bar=sf.ScrollBarThickness,BarAlpha=sf.ScrollBarImageTransparency,Direction=sf.ScrollingDirection,
Elastic=sf.ElasticBehavior,Clip=sf.ClipsDescendants},inner=innerS,lastH=-1,dirty=true,uiS=uiS,noClickUntil=0,
stats={n=0,ms=0,t0=os.clock()}}
r._STKLast=st
ap.STK=st
ap.STKOn=true
lay.Parent=nil
sf.AutomaticCanvasSize=Enum.AutomaticSize.None
sf.Active=true
sf.ScrollingEnabled=false
sf.ScrollingDirection=Enum.ScrollingDirection.Y
sf.ElasticBehavior=Enum.ElasticBehavior.WhenScrollable
sf.ClipsDescendants=true
sf.ScrollBarThickness=2
sf.ScrollBarImageTransparency=0.3
sf.CanvasPosition=Vector2.new(0,0)
for _,row in ipairs(items)do
local it=row.UIElements.TabItem
local hl=it:FindFirstChild("Highlight")
st.orig[row]={Size=it.Size,Auto=it.AutomaticSize,Pos=it.Position,Anc=it.AnchorPoint,Z=it.ZIndex,Clip=it.ClipsDescendants,Hi=hl and hl.ImageTransparency}
it.AutomaticSize=Enum.AutomaticSize.None
it.Size=UDim2.new(1,0,0,H)
it.AnchorPoint=Vector2.new(0.5,0.5)
it.ClipsDescendants=true
local sco=Instance.new("UIScale")
sco.Name="WAStkS"
sco.Parent=it
local fr=it:FindFirstChild("Frame")
local ti=fr and fr:FindFirstChild("Title")
local ic=row.UIElements.TabIcon and row.UIElements.TabIcon:FindFirstChild("ImageLabel")
st.refs[row]={it=it,sco=sco,hl=hl,lb=ti and ti:FindFirstChild("TextLabel"),ic=ic,c={},vis=true}
end
-- [QM-FARM] P98-1 WAEdgeStack | 2 the giua PHANG, the tren/duoi xep chong, het danh sach the cuoi phang, keo 1:1 | gan tai STKOpen apply
local U=H+gap
local edgeOn=r.WAOn("WAEdgeStack")and totalH>expInner+0.5
local EK=math.clamp(math.floor(tonumber(cfg.WAEdgeK)or 4),1,6)
local EPK=H*math.clamp(tonumber(cfg.WAEdgePk)or 0.18,0.1,0.8)
local EDRAG=math.clamp(tonumber(cfg.WAEdgeDrag)or 1,0.4,2)
st.edge=edgeOn
st.pp,st.ppv,st.ppA,st.acc2,st.eY={},{},{},0,0
local function elastic(nf)
if nf<0 then local o=-nf return -(o/(1+o*1.6))*0.8
elseif nf>N-1 then local o=nf-(N-1) return N-1+(o/(1+o*1.6))*0.8 end
return nf
end
local rowB=r.WAOn("WABounce")
local function apply()
local t0=os.clock()
local b=st.b
local inner=innerS+(expInner-innerS)*b
-- [QM-FARM] P99-1 StackFlow | khung dropdown co theo noi dung (chong tren + cap giua + chong duoi); cap giua khong con bi keo tut theo ngon tay
local fe=0
if edgeOn then
fe=math.clamp(st.f,0,N-1)
st.eY=EPK*math.min(fe,EK)
local eh=st.eY+H+U*math.clamp(N-1-fe,0,1)+EPK*math.clamp(N-2-fe,0,EK)+4
inner=innerS+(math.min(expInner,eh)-innerS)*b
end
st.inner=inner
local canvasH=inner+2*pad+footH
if math.abs(canvasH-st.lastH)>0.05 then
st.lastH=canvasH
mc.Size=UDim2.new(st.mco.X.Scale,st.mco.X.Offset,0,canvasH)
st.hPx=canvasH*st.uiS
st.lastY=r.STKPlace(ap,aq,st.hPx)
end
local want=b>0.02
if st.cs~=totalH then st.cs=totalH sf.CanvasSize=UDim2.new(0,0,0,totalH)end
-- [QM-FARM] P97-1 | khi xoe, cuon = ScrollingFrame native cua WindUI goc (keo, quan tinh, wheel); xep chong thi khoa cuon, chi con the bai
-- [QM-FARM] P98-2 | cuon do script (1:1 theo ngon tay) khi edgeOn; danh sach vua khung giu hanh vi cu
local nat=(not edgeOn)and(st.bt or 0)>0.5 and b>0.5
if sf.ScrollingEnabled~=nat then sf.ScrollingEnabled=nat end
if edgeOn and sf.CanvasPosition.Y~=0 then sf.CanvasPosition=Vector2.new(0,0)end
if not want and sf.CanvasPosition.Y~=0 then sf.CanvasPosition=Vector2.new(0,0)end
local cpy=sf.CanvasPosition.Y
local eY0,eF
if edgeOn then
eF=fe
eY0=st.eY-(st.f-fe)*U*0.4
end
local cur=math.floor(st.f+0.5)
for k,row in ipairs(items)do
local ref=st.refs[row]
local bk=(rowB and st.rb[k])or b
local bkc=math.min(math.max(bk,0),1)
local it=ref.it
local i=k-1
local d=i-st.f
local ad=math.abs(d)
local slot=k-1-math.floor(st.f+0.000001)
local inViewport=slot>=0 and slot<visibleCount
if it.Parent and not(edgeOn and b>0.999 and ref.c.vis==false and math.abs(i-eF)>EK+2.5)then
local c=ref.c
local ys,sc,al,z=r.STK.layout(i,st.f,P)
if not inViewport then
al=0
z=1
end
-- [QM-FARM] P96-5 | xoe: vi tri lien tuc theo st.f (cuon muot, khong nhay bac) + hang ra mep nho dan/mo dan nhu video
local ye=i*(H+gap)+H/2
local ea,sce,ze,cv,flat=1,1,50,0,false
if edgeOn then
local dd=i-eF
local depth
if dd<0 then depth=-dd ye=eY0+H/2-math.min(depth,EK)*EPK
elseif dd<=1 then depth=0 ye=eY0+H/2+dd*U
else depth=dd-1 ye=eY0+U+H/2+math.min(depth,EK)*EPK end
local dm=math.min(depth,EK)
cv=math.clamp(depth,0,1)
flat=depth==0
sce=1-0.035*dm
ea=math.clamp(EK+1-depth,0,1)*(1-0.1*dm)
ze=math.max(2,60-math.floor(depth*6))
else
local vy=ye-cpy
ea=math.min(math.clamp((vy+H*0.5)/(H*0.9),0,1),math.clamp((expInner-(vy-H*0.5))/(H*0.9),0,1))
end
local alMix=al+(ea-al)*bkc
if edgeOn and flat~=c.flat then
-- [QM-FARM] P99-2 FlatPop | the vao trang thai khong xep chong -> tung nhe len 1 lan
if flat and c.flat==false and b>0.9 and st.bt>0.5 then st.ppv[k]=(st.ppv[k]or 0)-95 st.pp[k]=st.pp[k]or 0 st.ppA[k]=true end
c.flat=flat
end
local ya=H/2+ys+cpy
local cy=math.floor((ya+(ye-ya)*bkc+(st.pp[k]or 0)*bkc)*4+0.5)/4
if c.y~=cy then it.Position=UDim2.new(0.5,0,0,cy)c.y=cy end
