if ad<=1.5 or want then
if not c.sc or math.abs(c.sc-scl)>0.002 then ref.sco.Scale=scl c.sc=scl end
elseif c.sc~=sc then ref.sco.Scale=sc c.sc=sc end
local vis=alMix>0.001
if c.vis~=vis then it.Visible=vis c.vis=vis end
ref.vis=vis
local zz=b>0.5 and ze or math.max(z,1)
if c.z~=zz then it.ZIndex=zz c.z=zz end
local cc=math.min(ad,3)
local alp=alMix
local bgS=0.04+0.06*cc
local bgL=row.Selected and st.selT or r.WARowT(1)
local bg=1-(1-(bgS+(bgL-bgS)*bkc))*alp
if not c.bg or math.abs(c.bg-bg)>0.01 then it.ImageTransparency=bg c.bg=bg end
local base=row.Selected and 0 or 0.4
-- Keep all five visible labels readable; depth is conveyed by the card stack alpha,
-- not by hiding every unselected label.
local ta=math.clamp(alMix,0,1)
local tt=1-(1-base)*ta
tt=tt+(1-tt)*cv*bkc
if ref.lb and(not c.tt or math.abs(c.tt-tt)>0.02)then ref.lb.TextTransparency=tt c.tt=tt end
if ref.ic then
local it2=1-(1-0.12)*ta
it2=it2+(1-it2)*cv*bkc*0.85
if not c.it or math.abs(c.it-it2)>0.02 then ref.ic.ImageTransparency=it2 c.it=it2 end
end
if ref.hl then
local o=st.orig[row]
local line=(k-1==cur)and(row.Selected and 0.05 or 0.3)or 0.92
local hv=line+((o and o.Hi or line)-line)*bkc
if not c.hl or math.abs(c.hl-hv)>0.01 then ref.hl.ImageTransparency=hv c.hl=hv end
end
end
end
if st.rail then
st.rail.Visible=b<0.5
local D=#st.dots
local idx=N>1 and math.floor(st.f/(N-1)*(D-1)+0.5)+1 or 1
idx=math.clamp(idx,1,D)
if st.idx~=idx then
st.idx=idx
for j,dot in ipairs(st.dots)do
local on=(j==idx)
dot.Size=UDim2.fromOffset(4,on and 10 or 4)
dot.BackgroundTransparency=on and 0.1 or 0.65
end
end
end
if st.less then st.less.Visible=b>0.5 end
local s=st.stats
s.n=s.n+1
s.ms=s.ms+(os.clock()-t0)*1000
end
-- No expand-all control: five visible cards are the fixed viewport.
-- Users reveal additional options by scrolling/dragging the stack itself.
st.rail=nil
st.dots={}
st.less=nil
local function pickRow(row)
ap._STKPicking=true
pcall(row.Pick)
ap._STKPicking=false
st.dirty=true
if not ap.Multi then
task.delay(0.14,function()
if ap.STK==st and ap.Opened then pcall(function()as:Close()end)end
end)
end
end
local function isP(i)return i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch end
local function beginStackDrag(inp)
if st.lock or st.drag or not isP(inp)then return end
st.drag={input=inp,touch=inp.UserInputType==Enum.UserInputType.Touch,mouse=inp.UserInputType==Enum.UserInputType.MouseButton1,
y0=inp.Position.Y,f0=st.f,b0=st.bt or st.b,buf={},moved=false,lastEv=os.clock(),lastApply=os.clock()}
end
local function release()
local d=st.drag
if not d then return end
st.drag=nil
pcall(r.WABlurPulse,0)
if d.moved then st.noClickUntil=os.clock()+0.25 end
if edgeOn and(st.bt or 0)>0.5 and not d.fired then
local v=r.STKVel(d,os.clock())
st.tgt=math.floor(math.clamp(st.f+v*0.22,0,N-1)+0.5)
st.v=v
end
end
for k,row in ipairs(items)do
local it=st.refs[row].it
st.conns[#st.conns+1]=it.InputBegan:Connect(beginStackDrag)
st.conns[#st.conns+1]=it.MouseButton1Click:Connect(function()
if st.lock or os.clock()<st.noClickUntil then return end
-- [QM-FARM] P96-4 | khi da xoe (bt>0.5) cham 1 hang = chon luon (truoc day return -> khong chon duoc)
if st.bt>0.5 then
if not row.Locked and not ap.Locked then pickRow(row)end
return
end
local cur=math.floor(st.f+0.5)
if k-1==cur then
if math.abs(st.f-cur)<0.12 and math.abs(st.v)<0.5 and not row.Locked and not ap.Locked then
pickRow(row)
else
st.tgt=cur
end
else
st.tgt=k-1
end
end)
end
st.conns[#st.conns+1]=sf.InputBegan:Connect(beginStackDrag)
st.conns[#st.conns+1]=UIS.InputChanged:Connect(function(inp)
if st.lock then return end
local d=st.drag
if d then
local ok=false
if d.touch then ok=(inp==d.input)
elseif d.mouse then ok=(inp.UserInputType==Enum.UserInputType.MouseMovement and UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1))end
if ok then
d.lastEv=os.clock()
local dy=inp.Position.Y-d.y0
if math.abs(dy)>6 then d.moved=true st.didDrag=true end
local now=os.clock()
local bt=st.bt or 0
if bt<0.5 then
if dy<-12 and not d.fired then d.fired=true st.bprev=st.bt st.bt=1 st.tTog=now st.dirty=true end
elseif edgeOn then
local dyL=dy/st.uiS
if d.f0<=0.05 and dyL>34 and not d.fired then
d.fired=true st.bprev=st.bt st.bt=0 st.tTog=now st.dirty=true
elseif not d.fired and d.moved then
local nf=elastic(d.f0-dyL/U*EDRAG)
local buf=d.buf
buf[#buf+1]={t=now,f=nf}
while #buf>12 or(#buf>0 and now-buf[1].t>0.2)do table.remove(buf,1)end
st.f,st.v,st.tgt=nf,0,nf
st.dirty=true
pcall(r.WABlurPulse,math.min(math.abs(r.STKVel(d,now))*1.1,4))
end
elseif dy>28 and sf.CanvasPosition.Y<=1 and not d.fired then
d.fired=true st.bprev=st.bt st.bt=0 st.tTog=now st.dirty=true
end
end
elseif inp.UserInputType==Enum.UserInputType.MouseWheel and st.hover then
if (st.bt or 0)<0.5 then st.bprev=st.bt st.bt=1 st.tTog=os.clock() st.dirty=true
elseif edgeOn then st.tgt=math.clamp(st.tgt-(tonumber(inp.Position.Z)or 0),0,N-1)end
end
end)
st.conns[#st.conns+1]=UIS.InputEnded:Connect(function(inp)
local d=st.drag
if not d then return end
if d.touch then
if inp==d.input then release()end
elseif d.mouse and inp.UserInputType==Enum.UserInputType.MouseButton1 then
release()
end
end)
st.conns[#st.conns+1]=mc.MouseEnter:Connect(function()st.hover=true end)
st.conns[#st.conns+1]=mc.MouseLeave:Connect(function()st.hover=false end)
st.conns[#st.conns+1]=sf:GetPropertyChangedSignal("CanvasPosition"):Connect(function()st.dirty=true end)
local zb=0.92
local STEP,w,zt=1/120,2*math.pi/0.28,(tonumber(((_G.FARMX and _G.FARMX.Cfg)or{}).WAStackDamp)or 0.6)
st.conns[#st.conns+1]=RS.RenderStepped:Connect(function(dt)
local d=st.drag
if d then
local lost=false
if d.touch then
local s=d.input.UserInputState
lost=(s==Enum.UserInputState.End or s==Enum.UserInputState.Cancel)
elseif d.mouse then
lost=not UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
end
if lost or os.clock()-d.lastEv>2 then release()end
if os.clock()-d.lastEv>0.12 then pcall(r.WABlurPulse,0)end
end
local moved=false
if not st.drag then
st.acc=st.acc+math.min(dt,0.1)
