st.acc=st.acc-STEP
local x,v,dest=st.f,st.v,st.tgt
local expd=edgeOn and(st.bt or 0)>0.5
local wq=expd and 2*math.pi/0.40 or w
local zq=expd and 0.92 or zt
if math.abs(dest-x)>0.002 or math.abs(v)>0.01 then
v=v+(wq*wq*(dest-x)-2*zq*wq*v)*STEP
x=x+v*STEP
if math.abs(dest-x)<0.002 and math.abs(v)<0.01 then x,v=dest,0 end
st.f,st.v=x,v
moved=true
end
if rowB then
local nowc=os.clock()
local wR=2*math.pi/0.34
local zR=tonumber(cfg.WARowBounceZ)or 0.8
for k=1,N do
local xk=st.rb[k]or st.b
local vk=st.rbv[k]or 0
local tg=((nowc-st.tTog)>=math.min((k-1)*0.025,0.12))and st.bt or st.bprev
if math.abs(tg-xk)>0.002 or math.abs(vk)>0.01 then
vk=vk+(wR*wR*(tg-xk)-2*zR*wR*vk)*STEP
xk=xk+vk*STEP
if math.abs(tg-xk)<0.002 and math.abs(vk)<0.01 then xk,vk=tg,0 end
moved=true
end
st.rb[k],st.rbv[k]=xk,vk
end
end
local bx,bv=st.b,st.bv
if math.abs(st.bt-bx)>0.002 or math.abs(bv)>0.01 then
bv=bv+(w*w*(st.bt-bx)-2*zb*w*bv)*STEP
bx=bx+bv*STEP
if math.abs(st.bt-bx)<0.002 and math.abs(bv)<0.01 then bx,bv=st.bt,0 end
st.b,st.bv=bx,bv
moved=true
end
end
else
st.acc=0
end
if next(st.ppA)then
local wP=2*math.pi/0.30
st.acc2=st.acc2+math.min(dt,0.1)
while st.acc2>=STEP do
st.acc2=st.acc2-STEP
for k in pairs(st.ppA)do
local x,v=st.pp[k],st.ppv[k]
v=v+(wP*wP*(0-x)-2*0.42*wP*v)*STEP
x=x+v*STEP
if math.abs(x)<0.02 and math.abs(v)<0.4 then x,v=0,0 st.ppA[k]=nil end
st.pp[k],st.ppv[k]=x,v
end
end
moved=true
end
if moved or st.dirty then
st.dirty=false
apply()
end
end)
apply()
return true
end
r._WALGScans=r._WALGScans or setmetatable({},{__mode="k"})
function r.WAStackIn(container)
