 local scan=r._WALGScans[container]
 if not scan then
  scan={queue={},head=1,seen=setmetatable({},{__mode="k"}),busy=false,connections={}}
  r._WALGScans[container]=scan
  local function enqueue(inst)
   if not inst or scan.seen[inst] then return end
   scan.seen[inst]=true
   scan.queue[#scan.queue+1]=inst
  end
  local pump
  pump=function()
   if scan.busy or not container.Parent then return end
   scan.busy=true
   task.spawn(function()
    while container.Parent and scan.head<=#scan.queue do
     local started=os.clock()
     local processed=0
     repeat
      local inst=scan.queue[scan.head]
      scan.head=scan.head+1
      if inst and inst.Parent then
       if inst~=container then pcall(r.WALGHandle,inst,r._WALGDrop)end
       local okChildren,children=pcall(function()return inst:GetChildren()end)
       if okChildren and type(children)=="table"then
        for _,child in ipairs(children)do enqueue(child)end
       end
      end
      processed=processed+1
     until scan.head>#scan.queue or processed>=40 or os.clock()-started>=0.002
     if scan.head>#scan.queue then
      scan.queue={}
      scan.head=1
      break
     end
     game:GetService("RunService").Heartbeat:Wait()
    end
    scan.busy=false
    if container.Parent and scan.head<=#scan.queue then pump()end
   end)
  end
  scan.enqueue=enqueue
  scan.pump=pump
  scan.connections[#scan.connections+1]=container.DescendantAdded:Connect(function(inst)
   enqueue(inst)
   pump()
  end)
  scan.connections[#scan.connections+1]=container.AncestryChanged:Connect(function()
   if not container:IsDescendantOf(game)then
    for _,connection in ipairs(scan.connections)do pcall(function()connection:Disconnect()end)end
    r._WALGScans[container]=nil
   end
  end)
  -- Walk the existing tree incrementally instead of allocating one huge GetDescendants array.
  -- DescendantAdded covers controls created while the queue is being drained.
  enqueue(container)
 end
 scan.pump()
end
