r.BCSpring={}
r.BCSpring.__index=r.BCSpring
r.BCActive={}
r.BCHooks={Tasks={},Frame=nil}
r.BCOff={}
function r.BCOffAdd(fn)
for _,f in ipairs(r.BCOff) do
if f==fn then return end
end
r.BCOff[#r.BCOff+1]=fn
end
function r.BCOn()
local fx=_G.FARMX
return fx~=nil and type(fx.Enable)=="table" and fx.Enable.BCCore==true
end
function r.BCSpring.new(initial,stiffness,damping,callback,epsilon)
local self=setmetatable({Value=initial,Target=initial,Velocity=0,Stiffness=stiffness,Damping=damping,Callback=callback,Epsilon=epsilon or 0.01},r.BCSpring)
callback(initial)
return self
end
function r.BCSpring.Set(self,target)
self.Target=target
if not r.BCOn() then
r.BCActive[self]=nil
self.Value=target
self.Velocity=0
self.Callback(target)
return
end
r.BCActive[self]=true
r.BCWake()
end
function r.BCSpring.Snap(self,value)
self.Value=value
self.Target=value
self.Velocity=0
r.BCActive[self]=nil
self.Callback(value)
end
function r.BCStep(dt)
dt=math.min(dt,1/20)
local steps=math.max(1,math.ceil(dt/(1/120)))
local h=dt/steps
local list={}
for spring in pairs(r.BCActive) do list[#list+1]=spring end
for _,spring in ipairs(list) do
local value=spring.Value
local velocity=spring.Velocity
for _=1,steps do
local acceleration=spring.Stiffness*(spring.Target-value)-spring.Damping*velocity
velocity=velocity+acceleration*h
value=value+velocity*h
end
if math.abs(spring.Target-value)<spring.Epsilon and math.abs(velocity)<spring.Epsilon*8 then
value=spring.Target
velocity=0
r.BCActive[spring]=nil
end
spring.Value=value
spring.Velocity=velocity
pcall(spring.Callback,value)
end
end
function r.BCSettle()
for spring in pairs(r.BCActive) do
r.BCActive[spring]=nil
spring.Value=spring.Target
spring.Velocity=0
pcall(spring.Callback,spring.Target)
end
end
function r.BCAddTask(fn)
local tasks=r.BCHooks.Tasks
tasks[#tasks+1]=fn
r.BCWake()
return function()
for i=#tasks,1,-1 do
if tasks[i]==fn then table.remove(tasks,i) end
end
end
end
function r.BCWake()
if r.BCCon or not r.BCOn() then return end
r.BCCon=game:GetService("RunService").RenderStepped:Connect(function(dt)
if not r.BCOn() then
r.BCSettle()
if r.BCCon then r.BCCon:Disconnect() r.BCCon=nil end
local offs=r.BCOff
r.BCOff={}
for _,f in ipairs(offs) do pcall(f) end
return
end
r.BCStep(dt)
local hooks=r.BCHooks
if hooks.Frame then pcall(hooks.Frame,dt) end
for i=#hooks.Tasks,1,-1 do
local fn=hooks.Tasks[i]
if fn then
local okT,errT=pcall(fn,dt)
if not okT and not r.BCErr then
r.BCErr=true
warn("[BC] task error: "..tostring(errT))
end
end
end
if next(r.BCActive)==nil and #hooks.Tasks==0 and not hooks.Frame then
if r.BCCon then r.BCCon:Disconnect() r.BCCon=nil end
end
end)
end
function r.WASz(btn,size,t,bouncy)
if not btn then return end
if r.WAOn("WASearchSpring")then
return r.WATween(btn,{Size=size},t,bouncy and Enum.EasingStyle.Back or Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
end
local TS=game:GetService("TweenService")
local tw=TS:Create(btn,TweenInfo.new(t,bouncy and Enum.EasingStyle.Back or Enum.EasingStyle.Quint,Enum.EasingDirection.Out),{Size=size})
tw:Play()
return tw
end
-- [QM-FARM] P96-1 WASearchGlassBtn | nut search + pill keo dai: ha nen den (kep ImageTransparency>=0.6), gan LGApply (pane/rim flux/touch) bo goc 0.5 scale = pill moi kich thuoc | goi o WASearchInit + WASearchOpen
function r.WASearchGlassBtn(btn)
