local guard=false
local function soften(d)
if guard or not d.Parent then return end
if d.ImageTransparency<0.6 then
guard=true
d.ImageTransparency=0.6
guard=false
end
end
pcall(function()
for _,d in ipairs(btn:GetDescendants())do
