function r.WASearchClose(st)
if not st or st.closed then return end
st.closed=true
for _,c in ipairs(st.conns)do pcall(function()c:Disconnect()end)end
pcall(r.WABlur,st,false)
pcall(function()if st.dimOff then st.dimOff()end end)
pcall(function()st.box:ReleaseFocus()end)
pcall(function()st.box.Text=""end)
pcall(function()if st.pop then st.pop:Close(true)end end)
pcall(function()st.box.Visible=false end)
pcall(function()st.x.Visible=false end)
pcall(function()if st.lab and st.lab.Parent then st.lab.Text=st.labText st.lab.TextTransparency=st.labTr end end)
if r._WASrch==st then r._WASrch=nil end
local fx=_G.FARMX
if fx and fx.TraceAdd then pcall(fx.TraceAdd,"SEARCH_CLOSE",st.why or "")end
if st.btn and st.btn.Parent then r.WASearchCollapse(st.btn)end
local finish=function()
 pcall(function()if st.box then st.box:Destroy()end end)
 pcall(function()if st.fl then st.fl:Destroy()end end)
 pcall(function()if st.dim then st.dim:Destroy()end end)
 pcall(function()if st.x then st.x:Destroy()end end)
 if st.onClosed then pcall(st.onClosed)end
end
if st.animatePanel then
 local ok=pcall(st.animatePanel,false)
 if ok then task.delay(0.40,finish)else finish()end
else
 finish()
end
end
-- [QM-FARM] P97-2 WAFocusDim/WALockScroll | dropdown mo = lop mo toan man hinh (Active, nuot input) duoi menu + khoa cuon moi ScrollingFrame cha cua nut mo; bam cho khac / bam nut mo = dong | co watchdog 0.25s tu tat neu dropdown khong con mo (khong bao gio ket man hinh)
-- [QM-FARM] P99-3 WAMenuBlur | mo nen man hinh khi search / dropdown mo (1 BlurEffect, Boncuti Spring BCSpring), them nhip mo khi keo chong | gan truoc WAFocusDim
r._WABlurKeys=r._WABlurKeys or{}
function r.WABlurEnsure()
local B=r._WABlur
if B and B.fx and B.fx.Parent then return B end
local fx=Instance.new("BlurEffect")
fx.Name="MaruMenuBlur"
fx.Size=0
fx.Parent=game:GetService("Lighting")
B={fx=fx,max=12,b=0,p=0}
r._WABlur=B
local function put()
if not fx.Parent then return end
fx.Size=math.max(0,B.b*B.max+B.p)
if B.sb and B.sp and B.sb.Target==0 and B.sp.Target==0 and B.b<=0.002 and B.p<=0.02 then
fx:Destroy()
if r._WABlur==B then r._WABlur=nil end
end
end
B.sb=r.BCSpring.new(0,170,26,function(v)B.b=v put()end,0.004)
B.sp=r.BCSpring.new(0,260,28,function(v)B.p=v put()end,0.02)
return B
end
function r.WABlur(key,on)
if not r.WAOn("WAMenuBlur")then return end
local ks=r._WABlurKeys
ks[key]=on and true or nil
local any=next(ks)~=nil
if not any and not r._WABlur then return end
local B=r.WABlurEnsure()
B.max=tonumber(((_G.FARMX and _G.FARMX.Cfg)or{}).WAMenuBlurSize)or 12
B.sb:Set(any and 1 or 0)
end
function r.WABlurPulse(x)
