-- [QM-FARM] P96-3 DD5Cap | tong cao 5 hang dau (UIListLayout cha) + khoang cach; nil neu <=5 hang | nguon: AbsoluteSize/UIScale tung hang
function r.DD5Cap(ap,uiScale)
local lay=ap and ap.UIElements and ap.UIElements.UIListLayout
local par=lay and lay.Parent
if not par then return nil end
local rows={}
for _,c in ipairs(par:GetChildren())do
if c:IsA("GuiObject")and c.Visible and c.AbsoluteSize.Y>1 then rows[#rows+1]=c end
end
if #rows<=5 then return nil end
table.sort(rows,function(a,b)
if a.LayoutOrder~=b.LayoutOrder then return a.LayoutOrder<b.LayoutOrder end
return a.AbsolutePosition.Y<b.AbsolutePosition.Y
end)
local us=(tonumber(uiScale)and uiScale>0)and uiScale or 1
local pad=lay.Padding.Offset
local h=0
for i=1,5 do h=h+rows[i].AbsoluteSize.Y/us+(i>1 and pad or 0)end
return h
end
function r.WASearchFind(tm,q)
local out={}
q=string.lower(tostring(q or""))
if q==""or not tm or type(tm.Tabs)~="table"then return out end
local function has(s)
if s==nil or s==""then return false end
return string.find(string.lower(tostring(s)),q,1,true)~=nil
end
local function keysOf(t)
local ks={}
for k in next,t do ks[#ks+1]=k end
table.sort(ks,function(a,b)
if type(a)=="number"and type(b)=="number"then return a<b end
return tostring(a)<tostring(b)
end)
return ks
end
for _,k in ipairs(keysOf(tm.Tabs))do
local t=tm.Tabs[k]
if type(t)=="table"and not t.Locked then
local els={}
if type(t.Elements)=="table"then
for _,ei in ipairs(keysOf(t.Elements))do
local e=t.Elements[ei]
if type(e)=="table"and e.__type~="Section"and(has(e.Title)or has(e.Desc))then
els[#els+1]={title=e.Title,desc=e.Desc,idx=ei}
end
end
end
if has(t.Title)or #els>0 then out[#out+1]={tab=t,key=k,title=t.Title,els=els}end
end
end
return out
end
