local last
local function layout()
if not(btn.Parent and main.Parent)then return end
local W,Hh=main.AbsoluteSize.X,main.AbsoluteSize.Y
if W<=0 or Hh<=0 then return end
local m=5
local x0=math.clamp(btn.AbsolutePosition.X-main.AbsolutePosition.X-m,0,W)
local y0=math.clamp(btn.AbsolutePosition.Y-main.AbsolutePosition.Y-m,0,Hh)
local x1=math.clamp(x0+btn.AbsoluteSize.X+2*m,0,W)
local y1=math.clamp(y0+btn.AbsoluteSize.Y+2*m,0,Hh)
local key=string.format("%.1f|%.1f|%.1f|%.1f|%d|%d",x0,y0,x1,y1,W,Hh)
if key==last then return end
last=key
parts[1].Position=UDim2.fromScale(0,0)
parts[1].Size=UDim2.fromScale(1,y0/Hh)
parts[2].Position=UDim2.fromScale(0,y1/Hh)
parts[2].Size=UDim2.fromScale(1,1-y1/Hh)
parts[3].Position=UDim2.fromScale(0,y0/Hh)
parts[3].Size=UDim2.fromScale(x0/W,(y1-y0)/Hh)
parts[4].Position=UDim2.fromScale(x1/W,y0/Hh)
parts[4].Size=UDim2.fromScale(1-x1/W,(y1-y0)/Hh)
end
layout()
st.conns[#st.conns+1]=game:GetService("RunService").Heartbeat:Connect(layout)
st.dimOff=function()
for _,f in ipairs(parts)do
if f.Parent then TS2:Create(f,TweenInfo.new(0.2,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{BackgroundTransparency=1}):Play()end
end
task.delay(0.26,function()if cont.Parent then cont:Destroy()end end)
end
end)
local flyOriginX=(btn.AbsolutePosition.X-main.AbsolutePosition.X+btn.AbsoluteSize.X*0.5)/us
local flyOriginY=(btn.AbsolutePosition.Y-main.AbsolutePosition.Y+btn.AbsoluteSize.Y*0.5)/us
local tlx,tly,wl=px/us,py/us,wdt/us
local D0=8
local fmv=Instance.new("NumberValue")
fmv.Name="WAFlyM"
fmv.Value=0
fmv.Parent=fl
local fhv=Instance.new("NumberValue")
fhv.Name="WAFlyH"
fhv.Value=48
fhv.Parent=fl
fl.AnchorPoint=Vector2.new(0.5,0.5)
local function soft(x)x=math.clamp(x,0,1)return x*x*(3-2*x)end
local function showContent(v)
flyContent=v
sc.Visible=v
sheen.Visible=v
if glow then glow.Visible=v end
end
local function render()
if not fl.Parent then return end
local m=fmv.Value
local hl=fhv.Value
local mp=math.clamp(m,0,1)
local over=math.max(m-1,0)
local wide=soft((mp-0.10)/0.90)
local tall=soft((mp-0.02)/0.98)
local stretch=math.sin(math.pi*math.clamp(mp/0.5,0,1))
local w=math.max(D0,D0+(wl-D0)*wide-4*stretch+over*wl*0.5)
local h=math.max(D0,D0+(hl-D0)*tall+8*stretch+over*hl*0.5)
fl.Position=UDim2.fromOffset(flyOriginX+(tlx+wl*0.5-flyOriginX)*mp,flyOriginY+(tly+hl*0.5-flyOriginY)*mp)
fl.Size=UDim2.fromOffset(w,h)
fc.CornerRadius=UDim.new(0,math.min(18,math.min(w,h)*0.5))
fl.BackgroundTransparency=0.03+0.97*(1-math.clamp(m*3,0,1))
fs.Transparency=0.05+0.95*(1-math.clamp(m*2.5,0,1))
if flyOpen then
if not flyContent and m>=0.55 then showContent(true)flyMorphing=false end
elseif m<=0.003 then
fl.Visible=false
end
end
fmv.Changed:Connect(render)
fhv.Changed:Connect(render)
local function animateFly(open,height,morph)
if not fl.Parent then return end
if open then
local h=math.max(44,tonumber(height)or 48)
if not flyOpen then
flyOpen=true
flyMorphing=true
showContent(false)
fl.Visible=true
fhv.Value=h
render()
r.WATween(fmv,{Value=1},0.5,Enum.EasingStyle.Back,Enum.EasingDirection.Out)
else
fl.Visible=true
if math.abs(fhv.Value-h)>0.5 then r.WATween(fhv,{Value=h},0.3,Enum.EasingStyle.Quint,Enum.EasingDirection.Out)end
if morph==true then
fmv.Value=math.min(fmv.Value,0.88)
r.WATween(fmv,{Value=1},0.42,Enum.EasingStyle.Back,Enum.EasingDirection.Out)
end
end
else
if not flyOpen then return end
flyOpen=false
flyMorphing=true
showContent(false)
fl.Visible=true
r.WATween(fmv,{Value=0},0.3,Enum.EasingStyle.Quint,Enum.EasingDirection.Out)
end
end
