function r.WAReveal(menu,ap)
if not menu or not menu.Parent then return false end
local previous=r._WADropMotion[menu]
local state=r._WADropBase[menu]
if not state then
local st
local corner=menu:FindFirstChildOfClass("UICorner")
st={anchor=menu.AnchorPoint,position=menu.Position,size=menu.Size,clip=menu.ClipsDescendants,
imageTransparency=(pcall(function()return menu.ImageTransparency end)and menu.ImageTransparency or 1),
corner=corner,cornerRadius=corner and corner.CornerRadius or UDim.new(0,18),cornerCreated=false}
state=st
end
local m0=(previous and tonumber(previous.m))or 0
WADropCancel(menu)
r.WATokBump(menu,"drop")
r._WADropBase[menu]=state
local T=r.WABloomRun(menu,ap,state,"open",m0)
if not T then return false end
-- label fade (WADropOpen) waits for this moment: content comes after the surface has formed
menu:SetAttribute("WADropRevealUntil",os.clock()+T*0.3*(1-m0))
return true
end
