task.defer(function()
if not inst.Parent or inst:FindFirstChild("WALG")then return end
if dropGui and inst:IsDescendantOf(dropGui)then return end
local sz=inst.AbsoluteSize
local u=r.UIScale or 1
local function walgSizeReady(size)
local scale=(r.UIScale or 1)
local ww,hh=size.X/scale,size.Y/scale
return size.X>0 and size.Y>0 and hh>=20 and hh<=170 and ww<=760 and (ww>=36 or (math.abs(ww-hh)<2 and ww>=22))
end
if not walgSizeReady(sz) and inst:GetAttribute("WALGRetry") then return end
local tooBig=(sz.X/(r.UIScale or 1))>760 or (sz.Y/(r.UIScale or 1))>170
if not walgSizeReady(sz) and not tooBig and not inst:GetAttribute("WALGRetry") and (r._WALGRetryN or 0)<3000 then
inst:SetAttribute("WALGRetry",true)
r._WALGRetryN=(r._WALGRetryN or 0)+1
P.glassRetry=(P.glassRetry or 0)+1
local done=false
local cn
local function finishRetry(retryNow)
if done then return end
done=true
r._WALGRetryN=math.max(0,(r._WALGRetryN or 1)-1)
if cn then cn:Disconnect() end
if not inst.Parent then pcall(function()inst:SetAttribute("WALGRetry",nil)end) return end
inst:SetAttribute("WALGRetry",nil)
if retryNow then task.defer(function() if inst.Parent then r.WALGHandle(inst,dropGui) end end) end
end
cn=inst:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
if walgSizeReady(inst.AbsoluteSize) then finishRetry(true) end
end)
task.delay(3,function()
if done then return end
if inst.Parent and walgSizeReady(inst.AbsoluteSize) then
finishRetry(true)
else
finishRetry(false)
end
end)
return
end
local w,h=sz.X/u,sz.Y/u
