end
function r.BCGlassTouch(rim,inst,orad)
if rim:FindFirstChild("WABCTouch") then return end
local glow=Instance.new("Frame")
glow.Name="WABCTouch"
glow.Active=false
glow.BorderSizePixel=0
glow.Size=UDim2.fromScale(1,1)
glow.BackgroundColor3=Color3.new(1,1,1)
glow.BackgroundTransparency=1
glow.ZIndex=rim.ZIndex+1
local c=Instance.new("UICorner")
c.CornerRadius=UDim.new(0,math.max(orad or 12,0))
c.Parent=glow
local g=Instance.new("UIGradient")
g.Rotation=55
g.Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,0.6),NumberSequenceKeypoint.new(0.5,0.86),NumberSequenceKeypoint.new(1,0.7)})
g.Parent=glow
glow.Parent=rim
local TS=game:GetService("TweenService")
local function lit(on)
TS:Create(glow,TweenInfo.new(on and 0.09 or 0.5),{BackgroundTransparency=on and 0 or 1}):Play()
end
inst.InputBegan:Connect(function(i)
if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then lit(true) end
end)
inst.InputEnded:Connect(function(i)
if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then lit(false) end
end)
inst.MouseLeave:Connect(function() lit(false) end)
end
function r.BCGlassReg(rim,g,inst,orad,h,pads)
local G=r.BCG
G.N=G.N+1
G.Reg[rim]={g=g,ph=(G.N*53)%360,vis=true,pads=pads}
rim:SetAttribute("BCRad",orad or 12)
if h and h<=110 and inst.Name~="Main" and inst:IsA("GuiObject") then
pcall(r.BCGlassTouch,rim,inst,orad)
end
r.BCGlassStart()
end
function r.BCGlassStart()
local G=r.BCG
if G.Rm then return end
r.BCOffAdd(r.BCGlassOff)
local last,visT=0,0
G.Rm=r.BCAddTask(function()
if not r.BCGlassOn() then
r.BCGlassOff()
return
end
if G.Pause then return end
local now=os.clock()
if now-visT>1 then
visT=now
for rim,e in pairs(G.Reg) do
if not rim.Parent then
G.Reg[rim]=nil
else
local v=true
local a=rim
while a and a:IsA("GuiObject") do
if not a.Visible then v=false break end
a=a.Parent
end
e.vis=v
end
end
end
if now-last<0.05 then return end
last=now
local base=now*45
local cam=workspace.CurrentCamera
local vs=cam and cam.ViewportSize or Vector2.new(1920,1080)
for rim,e in pairs(G.Reg) do
if e.vis and rim.Parent then
local p=rim.AbsolutePosition
if p.X>-300 and p.Y>-300 and p.X<vs.X and p.Y<vs.Y then
e.g.Rotation=(base+e.ph)%360
end
end
end
end)
end
function r.BCGlassOff()
local G=r.BCG
if G.Rm then
G.Rm()
G.Rm=nil
end
for rim,e in pairs(G.Reg) do
if rim.Parent then
if e.g then e.g.Rotation=45 end
local tf=rim:FindFirstChild("WABCTouch")
if tf then tf:Destroy() end
local p=e.pads
if p and p.fixed then
local ot=p[5] or 0
rim.Size=UDim2.new(1,2*ot,1,2*ot)
rim.Position=UDim2.fromOffset(-ot,-ot)
end
end
end
G.Reg={}
end
function r.BCGlassScan()
if not r._WALGRims then return end
local cfg=(_G.FARMX and _G.FARMX.Cfg)or{}
local ot=tonumber(cfg.WALGOut)or 1.5
local n=0
for rim in pairs(r._WALGRims) do
if rim.Parent and rim.Name=="WALG" and not r.BCG.Reg[rim] then
local g=rim:FindFirstChild("WALGGrad")
local inst=rim.Parent
if g and inst:IsA("GuiObject") then
local pl,pt,pr,pb=0,0,0,0
local up=inst:FindFirstChildOfClass("UIPadding")
if up then pl,pt,pr,pb=up.PaddingLeft.Offset,up.PaddingTop.Offset,up.PaddingRight.Offset,up.PaddingBottom.Offset end
rim.Size=UDim2.new(1,2*ot+pl+pr,1,2*ot+pt+pb)
rim.Position=UDim2.fromOffset(-ot-pl,-ot-pt)
r.BCGlassReg(rim,g,inst,tonumber(rim:GetAttribute("BCRad")) or 12,inst.AbsoluteSize.Y/(r.UIScale or 1),{pl,pt,pr,pb,ot,fixed=true})
end
n=n+1
if n%120==0 then task.wait() end
end
end
end
