function r.LGEdge(parent)
local K=NumberSequenceKeypoint.new
local g=Instance.new("UIGradient")
g.Name="LGEdge"
g.Transparency=NumberSequence.new({K(0,0.12),K(0.15,0.42),K(0.34,0.8),K(0.5,0.92),K(0.66,0.8),K(0.85,0.42),K(1,0.12)})
