g.Parent=parent
return g
end
function r.LGStart()
local G=r.LG
if G.Conn then return end
local acc,visT=0,0
G.Conn=game:GetService("RunService").Heartbeat:Connect(function(dt)
acc=acc+dt
if acc<0.05 then return end
acc=0
local bcg=r.BCG
local paused=bcg and bcg.Pause
local now=os.clock()
local chk=now-visT>0.3
if chk then visT=now end
local base=now*45
local cam=workspace.CurrentCamera
local vs=cam and cam.ViewportSize or Vector2.new(1920,1080)
for rim,e in pairs(G.Reg)do
if not rim.Parent then
G.Reg[rim]=nil
else
if chk then
local v=true
local a=rim
while a and a:IsA("GuiObject")do
if not a.Visible then v=false break end
if a:IsA("ScrollingFrame")and a~=rim then
local p0,s0=a.AbsolutePosition,a.AbsoluteSize
local p1=rim.AbsolutePosition
if p1.Y>p0.Y+s0.Y+8 or p1.Y+rim.AbsoluteSize.Y<p0.Y-8 then v=false break end
end
a=a.Parent
end
local p=rim.AbsolutePosition
if p.X<-300 or p.Y<-300 or p.X>vs.X or p.Y>vs.Y then v=false end
e.vis=v
end
if e.vis and(e.always or not paused)then e.g.Rotation=(base+e.ph)%360 end
end
end
end)
end
function r.LGApply(inst,opt)
