st.Thickness=1
st.Transparency=tab and 0.72 or 0.2
st.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
st.Parent=rim
local eg=r.LGEdge(st)
rim.Parent=inst
if opt.touch~=false then
