glow.BackgroundTransparency=1
local gg=Instance.new("UIGradient")
gg.Rotation=55
gg.Transparency=NumberSequence.new({K(0,0.6),K(0.5,0.86),K(1,0.7)})
gg.Parent=glow
glow.Parent=inst
local TS=game:GetService("TweenService")
