end
inst.InputBegan:Connect(function(i)
if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then lit(true) end
end)
inst.InputEnded:Connect(function(i)
if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then lit(false) end
end)
inst.MouseLeave:Connect(function()lit(false)end)
end
local G=r.LG
G.N=G.N+1
G.Reg[rim]={g=eg,ph=(G.N*53)%360,vis=true,always=opt.always==true}
r.LGStart()
if opt.link then
local src=opt.link
