        end)
    end
    local function startUIQueue()
        if UIQueue.Running then return end
        UIQueue.Running = true
        task.spawn(function()
            local runService = game:GetService("RunService")
            while UIQueue.Head <= UIQueue.Tail do
                local frameStart = os.clock()
                local made = 0
                repeat
                    local item = UIQueue.Items[UIQueue.Head]
                    UIQueue.Items[UIQueue.Head] = nil
