                    return true
                end
            end
        end
        return false
    end
    local function cover(toks, P)
        local n = #toks
        if n == 0 then
            return 0, 0
        end
        local m = 0
        for _, w in ipairs(toks) do
            if hasTok(P, w) then
                m = m + 1
            end
        end
        local s = m / n
        if m == n then
            s = s + 0.25 + 0.12 * math.min(m, 4)
        elseif m > 0 then
            s = s - 0.05
        end
        return s, m
    end
    local function scoreItem(it, phrase, P)
        local s1 = cover(it.toks, P)
        local s2 = cover(it.itoks, P)
        local best = math.max(s1, s2 * 0.9)
        if #it.nt >= 3 and string.find(phrase, it.nt, 1, true) then
            best = best + 0.3
        end
        return best
    end
    local function resolve(phrase, want)
        local P = {}
        for _, w in ipairs(words(phrase)) do
            if not FILL[w] and not tonumber(w) then
                P[w] = true
            end
        end
        local list = {}
        for _, it in ipairs(buildReg()) do
            if not want or want[it.type] then
                local s = scoreItem(it, phrase, P)
                if s >= 0.6 then
                    list[#list + 1] = { it = it, s = s }
                end
            end
        end
        table.sort(list, function(a, b)
            if a.s ~= b.s then
                return a.s > b.s
            end
            return #a.it.nt > #b.it.nt
        end)
        if #list == 0 then
            return nil, list
        end
        local gap = list[2] and (list[1].s - list[2].s) or 1
        if gap >= 0.12 then
            return list[1].it, list
        end
        return nil, list
    end

    ------------------------------------------------------------------ actions (moi action in 1 dong shell len island)
    local function need(perm, name)
        if not LX.Perm[perm] then
            LX.Out("err", "permission denied: " .. (name or perm))
            return false
        end
        return true
    end
    local function short(it)
        return string.lower(asc(it.title))
    end
    local function toBool(v)
        return v == true
    end
    function LX.DoToggle(it, on)
        if not need("Control", "control") then
            return false, "perm"
        end
        LX.Out("cmd", "toggle '" .. short(it) .. "' " .. (on and "on" or "off"))
        if toBool(it.rec.Value) == on then
            LX.Out("dim", "already " .. (on and "on" or "off"))
            return true, "same"
        end
        local ok, err = pcall(it.rec.SetValue, it.rec, on)
        if ok then
            LX.Out("ok", "done")
        else
            LX.Out("err", tostring(err))
        end
        return ok, "set"
    end
    function LX.DoSlider(it, n)
        if not need("Control", "control") then
            return false, "perm"
        end
        local lo, hi = tonumber(it.rec.Min) or 0, tonumber(it.rec.Max) or 100
        local c = math.clamp(n, lo, hi)
        LX.Out("cmd", "set '" .. short(it) .. "' = " .. tostring(c) .. "  [" .. lo .. ".." .. hi .. "]")
        local ok, err = pcall(it.rec.SetValue, it.rec, c)
        if ok then
            LX.Out("ok", "done")
        else
            LX.Out("err", tostring(err))
        end
        return ok, c
    end
    local function valueText(v)
        if type(v) == "table" then
            return tostring(v.Title or v.Name or v.Value or "")
        end
        return tostring(v)
    end
    function LX.DoDropdown(it, text)
        if not need("Control", "control") then
            return false, "perm"
        end
        local want = norm(text)
        local bestV, bestS = nil, 0
        for _, v in ipairs(it.rec.Values or {}) do
            local nv = norm(valueText(v))
            local s = 0
            if nv == want then
                s = 2
            elseif nv ~= "" and (string.find(nv, want, 1, true) or string.find(want, nv, 1, true)) then
                s = 1 + #nv / math.max(#want, 1) * 0.1
            else
                local P = {}
                for _, w in ipairs(words(want)) do
                    P[w] = true
                end
                local tk = words(nv)
                local m = 0
                for _, w in ipairs(tk) do
                    if P[w] then
                        m = m + 1
                    end
                end
                if #tk > 0 then
                    s = m / #tk * 0.9
                end
            end
            if s > bestS then
                bestV, bestS = v, s
            end
        end
        if not bestV or bestS < 0.5 then
            LX.Out("err", "no option matches '" .. asc(text) .. "'")
            return false, "none"
        end
        LX.Out("cmd", "select '" .. short(it) .. "' -> " .. string.lower(asc(valueText(bestV))))
        local ok, err = pcall(it.rec.SetValue, it.rec, bestV)
        if ok then
            LX.Out("ok", "done")
        else
            LX.Out("err", tostring(err))
        end
        return ok, valueText(bestV)
    end
    function LX.DoInput(it, text)
        if not need("Control", "control") then
            return false, "perm"
        end
        LX.Out("cmd", "input '" .. short(it) .. "' <- " .. asc(text))
        local ok, err = pcall(it.rec.SetValue, it.rec, text)
        if ok then
            LX.Out("ok", "done")
        else
            LX.Out("err", tostring(err))
        end
        return ok
    end
    function LX.DoPress(it)
        if not need("Control", "control") then
            return false, "perm"
        end
        LX.Out("cmd", "press '" .. short(it) .. "'")
        local cb = it.rec._cb
        if not cb then
            local e = it.rec.Element
            cb = e and e.Callback
        end
        if type(cb) ~= "function" then
            LX.Out("err", "button has no callback")
            return false
        end
        task.spawn(pcall, cb)
        LX.Out("ok", "pressed")
        return true
    end
    function LX.DoAll(on)
        if not need("Control", "control") then
            return 0
        end
        LX.Out("cmd", "toggle * " .. (on and "on" or "off"))
        local n = 0
        for _, it in ipairs(buildReg()) do
            if it.type == "Toggle" and toBool(it.rec.Value) ~= on then
                if pcall(it.rec.SetValue, it.rec, on) then
                    n = n + 1
                end
            end
        end
        LX.Out("ok", n .. " toggles changed")
        return n
    end

