    function LX.DoTimer(minutes)
        local d = dim()
        if not d or not d.TimerStart then
            LX.Out("err", "timer unavailable")
            return false
        end
        LX.Out("cmd", "timer " .. tostring(minutes) .. "m")
        d.TimerStart(minutes)
        LX.Out("ok", "timer started")
        return true
    end
    function LX.DoWatch(act)
        local d = dim()
        if not d then
            LX.Out("err", "stopwatch unavailable")
            return false
        end
        LX.Out("cmd", "stopwatch " .. act)
        if act == "lap" and d.WatchLap then
            d.WatchLap()
        elseif act == "reset" and d.WatchReset then
            d.WatchReset()
        elseif act == "stoptimer" and d.TimerStop then
            d.TimerStop()
        elseif d.WatchToggle then
            d.WatchToggle()
        end
        LX.Out("ok", "done")
        return true
    end
    function LX.ThemeList()
        local out = {}
        pcall(function()
            for k in pairs(WindUI:GetThemes()) do
                out[#out + 1] = tostring(k)
            end
        end)
        table.sort(out)
        return out
    end
    function LX.DoTheme(name)
        if not need("Interface", "interface") then
            return false
        end
        local want = norm(name)
        if want == "toi" then
            want = "dark"
        elseif want == "sang" then
            want = "light"
        end
        for _, th in ipairs(LX.ThemeList()) do
            if norm(th) == want then
                LX.Out("cmd", "theme " .. string.lower(th))
                local ok = pcall(function()
                    WindUI:SetTheme(th)
                end)
                LX.Out(ok and "ok" or "err", ok and "done" or "theme failed")
                return ok, th
            end
        end
        LX.Out("err", "unknown theme '" .. asc(name) .. "'")
        return false
    end

