    function LX.PermText()
        local parts = {}
        for _, k in ipairs({ "Control", "Shell", "Character", "Interface", "Trigger" }) do
            parts[#parts + 1] = string.lower(k) .. "=" .. (LX.Perm[k] and "on" or "off")
        end
        return table.concat(parts, "  ")
    end
    local function permKey(p)
        for k, names in pairs(PERM_NAMES) do
            for _, n in ipairs(names) do
                if has(p, n) then
                    return k
                end
            end
        end
        return nil
    end

    ------------------------------------------------------------------ shell
    local SHELLW = {
        help = true, ls = true, ps = true, find = true, get = true, perm = true, clear = true, history = true,
        fps = true, ping = true, time = true, echo = true, theme = true, face = true, say = true, timer = true,
        watch = true, jump = true, spin = true, on = true, off = true, set = true, sel = true, press = true,
        open = true, tab = true, music = true, nhac = true,
        all = true, whoami = true, uname = true,
    }
    local function fmtVal(it)
        local v = it.rec.Value
        if it.type == "Toggle" then
            return v == true and "on" or "off"
        elseif it.type == "Dropdown" then
            if type(v) == "table" then
                local o = {}
                for _, x in ipairs(v) do
                    o[#o + 1] = valueText(x)
                end
                return table.concat(o, ",")
            end
            return tostring(v)
        elseif it.type == "Button" then
            return "-"
        end
        return tostring(v)
    end
    local function lookup(arg, want)
        local it, list = resolve(norm(arg), want)
        if it then
            return it
        end
        if #list == 0 then
            LX.Out("err", "not found: " .. asc(arg))
        else
            LX.Out("warn", "ambiguous, try one of:")
            for i = 1, math.min(#list, 4) do
                LX.Out("out", "  " .. short(list[i].it))
            end
        end
        return nil
    end
    local HELP = {
        "help               this list",
        "ls [tab]           list controls (auto registry)",
        "ps                 toggles that are on",
        "find <text>        search controls",
        "get <name>         show a value",
        "on|off <name>      toggle   (on|off all)",
        "set <name> <n>     slider / input",
        "sel <name> <val>   dropdown",
        "press <name>       button",
        "timer <min>  watch [lap|reset]",
        "theme [name]  face [name]  jump  spin",
        "open <tab>  tab <tab>  music [play|pause|next|prev|stop]",
        "perm [name on|off]  fps  ping  time  clear",
    }
    function LX.Exec(line)
        if not need("Shell", "shell") then
            LX.Say("Shell đang bị khóa. Bật lại trong Setting.", "annoyed")
            return
        end
        line = tostring(line or "")
        line = string.gsub(line, "^%s+", "")
        line = string.gsub(line, "%s+$", "")
        LX.Out("cmd", "$ " .. line)
        local w = words(line)
        local cmd = string.lower(asc(w[1] or ""))
        local rest = table.concat(w, " ", 2)
        if line ~= "" and cmd ~= "open" and cmd ~= "tab" then LX.EnsureWindowOpen() end
        if cmd == "help" or cmd == "" then
            for _, l in ipairs(HELP) do
                LX.Out("out", l)
            end
        elseif cmd == "open" or cmd == "tab" then
            LX.DoOpenTab(rest)
        elseif cmd == "music" or cmd == "nhac" then
            local args = words(rest)
            local act = norm(args[1] or "play")
            local query = table.concat(args, " ", 2)
            if act == "next" then act = "next"
            elseif act == "prev" or act == "previous" then act = "prev"
            elseif act == "pause" or act == "stop" or act == "resume" or act == "play" or act == "random" or act == "shuffle" or act == "find" or act == "search" or act == "select" then
            else
                query = rest
                act = "find"
            end
            LX.DoMusic(act, query)
        elseif cmd == "clear" then
            LX.Lines = {}
            LX.Ver = LX.Ver + 1
        elseif cmd == "ls" then
            local want = norm(rest)
            local n = 0
            for _, it in ipairs(buildReg()) do
                if want == "" or string.find(norm(it.tab or ""), want, 1, true) or string.find(it.nt, want, 1, true) then
                    n = n + 1
                    if n <= 14 then
                        LX.Out("out", string.format("%-9s %s = %s", string.sub(string.lower(it.type), 1, 8), string.sub(short(it), 1, 26), string.sub(fmtVal(it), 1, 14)))
                    end
                end
            end
            LX.Out("dim", n .. " controls" .. (n > 14 and " (showing 14, narrow with ls <tab>)" or ""))
        elseif cmd == "ps" then
            local n = 0
            for _, it in ipairs(buildReg()) do
                if it.type == "Toggle" and it.rec.Value == true then
                    n = n + 1
                    if n <= 14 then
                        LX.Out("out", "  on  " .. short(it))
                    end
                end
            end
            LX.Out("dim", n .. " running")
        elseif cmd == "find" then
            local _, list = resolve(norm(rest), nil)
            for i = 1, math.min(#list, 8) do
                LX.Out("out", string.format("%-9s %s", string.lower(list[i].it.type), short(list[i].it)))
            end
            LX.Out("dim", #list .. " match")
        elseif cmd == "get" then
            local it = lookup(rest, nil)
            if it then
                LX.Out("out", short(it) .. " = " .. fmtVal(it))
            end
        elseif cmd == "on" or cmd == "off" then
            local on = cmd == "on"
            if norm(rest) == "all" or norm(rest) == "het" then
                LX.DoAll(on)
            else
                local it = lookup(rest, { Toggle = true })
                if it then
                    LX.DoToggle(it, on)
                end
            end
        elseif cmd == "set" then
            local num = string.match(rest, "(%-?%d+%.?%d*)%s*$")
            local name = num and string.gsub(rest, "%-?%d+%.?%d*%s*$", "") or rest
            name = string.gsub(name, "=", " ")
            local it = lookup(name, { Slider = true, Input = true })
            if it then
                if it.type == "Slider" then
                    if num then
                        LX.DoSlider(it, tonumber(num))
                    else
                        LX.Out("err", "need a number")
                    end
                else
                    LX.DoInput(it, num or string.match(rest, "=%s*(.+)$") or "")
                end
            end
        elseif cmd == "sel" then
            local it, list = resolve(norm(rest), { Dropdown = true })
            if not it then
                lookup(rest, { Dropdown = true })
            else
                local val = rest
                for _, tk in ipairs(it.toks) do
                    val = string.gsub(val, "%f[%w]" .. esc(tk) .. "%f[%W]", "", 1)
                end
                val = norm(val)
                if val == "" then
                    LX.Out("out", short(it) .. " = " .. fmtVal(it))
                    local o = {}
                    for _, v in ipairs(it.rec.Values or {}) do
                        o[#o + 1] = string.lower(asc(valueText(v)))
                    end
                    LX.Out("dim", "options: " .. string.sub(table.concat(o, ", "), 1, 90))
                else
                    LX.DoDropdown(it, val)
                end
            end
        elseif cmd == "press" then
            local it = lookup(rest, { Button = true })
            if it then
                LX.DoPress(it)
            end
        elseif cmd == "timer" then
            local n = tonumber(string.match(rest, "%d+%.?%d*"))
            if n then
                LX.DoTimer(n)
            else
                LX.DoWatch("stoptimer")
            end
        elseif cmd == "watch" then
            LX.DoWatch(norm(rest) ~= "" and norm(rest) or "toggle")
        elseif cmd == "theme" then
            if rest == "" then
                LX.Out("out", string.lower(table.concat(LX.ThemeList(), ", ")))
            else
                LX.DoTheme(rest)
            end
        elseif cmd == "face" then
            local f = norm(rest)
            local map = { cold = "cold", lanh = "cold", bored = "bored", chan = "bored", deadpan = "deadpan" }
            if map[f] then
                LX.Face = map[f]
                LX.SetMood(LX.Face)
                LX.Out("ok", "face = " .. LX.Face)
            else
                LX.Out("out", "face = " .. LX.Face .. "   (cold | bored | deadpan)")
            end
        elseif cmd == "jump" then
            LX.DoJump()
        elseif cmd == "spin" then
            LX.DoSpin()
        elseif cmd == "perm" then
            local k = permKey(norm(rest))
            local on = has(norm(rest), "on")
            local off = has(norm(rest), "off")
            if k and (on or off) then
                LX.SetPerm(k, on)
            else
                LX.Out("out", LX.PermText())
            end
        elseif cmd == "fps" then
            local dt = game:GetService("RunService").RenderStepped:Wait()
            LX.Out("out", string.format("%d fps", math.floor(1 / math.max(dt, 0.001) + 0.5)))
        elseif cmd == "ping" then
            local p = 0
            pcall(function()
                p = math.floor(game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue() + 0.5)
            end)
            LX.Out("out", p .. " ms")
        elseif cmd == "time" then
            LX.Out("out", os.date("%H:%M:%S  %d/%m/%Y"))
        elseif cmd == "history" then
            local n = 0
            for i = math.max(1, #LX.Chat - 6), #LX.Chat do
                local m = LX.Chat[i]
                n = n + 1
                LX.Out("out", (m.role == "user" and "> " or "< ") .. string.sub(asc(m.text), 1, 40))
            end
            LX.Out("dim", n .. " lines")
        elseif cmd == "echo" or cmd == "say" then
            LX.Out("out", rest)
            if cmd == "say" then
                LX.Say(rest)
            end
        elseif cmd == "whoami" then
            LX.Out("out", "longxgen")
        elseif cmd == "uname" then
            LX.Out("out", "longxgen 1.0 deadpan #" .. #buildReg() .. " controls")
        else
            LX.Out("err", "command not found: " .. cmd .. "  (help)")
        end
    end

    ------------------------------------------------------------------ NLU (tieng Viet khong dau/co dau + tieng Anh co ban)
    local V_ON = { "bat", "mo", "kich hoat", "enable", "on", "turn on", "start" }
    local V_OFF = { "tat", "dung", "ngung", "disable", "off", "turn off", "stop", "huy" }
    local V_SET = { "dat", "chinh", "set", "=", "thanh", "len", "xuong" }
    local V_SEL = { "chon", "select", "switch", "pick", "doi sang", "chuyen sang", "chuyen" }
    local V_PRESS = { "bam", "nhan", "click", "press", "tap", "thuc hien", "kich" }
    local COLD = {
        ok = { "Rồi.", "Xong.", "Ừ, làm rồi.", "Đó.", "Xong rồi đấy." },
        same = { "Nó vậy sẵn rồi.", "Đang như thế từ nãy.", "Không có gì để đổi." },
        nf = { "Không thấy cái đó. Nói rõ hơn đi.", "Tên gì cơ? Tôi không tìm ra.", "Không có thứ nào như vậy." },
        perm = { "Quyền đó đang tắt. Vào Setting mà bật.", "Không được phép. Tự đi mà bật quyền." },
        idk = { "Nghe không hiểu. Gõ help đi.", "Hả. Nói lại.", "...Không hiểu. Thử 'bật <tên>' hoặc 'help'.", "Chán thật. Nói lệnh cho đàng hoàng." },
        hi = { "Ừ.", "Gì?", "Có chuyện gì.", "Nói đi." },
        thanks = { "Khỏi.", "Ừ.", "Không cần cảm ơn." },
        who = { "Longxgen. Bấm hộ mấy cái nút trong này. Hỏi ít thôi." },
        bored = { "Ừ... làm gì thì làm.", "Tôi chán rồi đấy.", "Có việc thì giao đi.", "Tôi đang đợi. Vô nghĩa thật." },
    }
    local function say(kind, mood)
        LX.Say(pick(COLD[kind]), mood)
    end
    local function lastNumber(p)
        local n
        for w in string.gmatch(p, "%S+") do
            if tonumber(w) then
                n = tonumber(w)
            end
        end
        return n
    end
    local function ambiguous(list)
        local o = {}
        for i = 1, math.min(#list, 3) do
            o[#o + 1] = list[i].it.title
        end
        return o
    end
    function LX.Ask(text)
        local p = norm(text)
        if p == "" then
            return
        end
        local mood = LX.Face

        -- quyen
        if has(p, "quyen") or has(p, "permission") then
            local k = permKey(p)
            local on, off = hasAny(p, { "bat", "mo", "cho phep", "on" }), hasAny(p, { "tat", "cam", "off" })
            if k and (on or off) then
                LX.Out("cmd", "perm " .. string.lower(k))
                LX.SetPerm(k, on and not off)
                local opened = (on and not off) and true or false
                LX.Say((opened and "Mở quyền " or "Khóa quyền ") .. (PERM_LABEL[k] or k) .. ".", "deadpan")
            else
                LX.Out("cmd", "perm")
                LX.Out("out", LX.PermText())
                LX.Say("Quyền hiện tại: " .. LX.PermText(), "deadpan", 3)
            end
            return
        end
        -- huong dan / danh sach
        if hasAny(p, { "help", "huong dan", "lam duoc gi", "co gi", "giup" }) and not resolve(p, nil) then
            LX.Out("cmd", "help")
            LX.Out("out", #buildReg() .. " controls registered")
            LX.Out("out", "bat|tat <ten>  dat <ten> = n  chon <ten> <gt>  bam <ten>")
            LX.Say("Tôi bật/tắt, đặt số, chọn dropdown, bấm nút mọi thứ trong UI (" .. #buildReg() .. " mục). Gõ 'help' để xem lệnh shell.", "deadpan", 3.5)
            return
        end
        if hasAny(p, { "dang bat", "dang chay", "trang thai chung", "ps" }) then
            LX.Exec("ps")
            LX.Say("Danh sách đang bật nằm ở shell đấy.", mood)
            return
        end
        -- tab navigation and music player
        local openVerb = hasAny(p, { "mo tab", "vao tab", "open tab", "chuyen tab", "goi tab" })
            or (hasAny(p, { "mo", "open", "vao" }) and hasAny(p, { "farm", "farm lv", "farming", "nhac", "am nhac", "music", "quest", "setting", "settings", "sea event", "teleport" }))
        if openVerb then
            local target
            if hasAny(p, { "nhac", "am nhac", "music" }) then target = "music"
            elseif hasAny(p, { "farm lv", "farm level", "farming", "farm" }) then target = "farming"
            elseif hasAny(p, { "quest", "item" }) then target = "quest"
            elseif hasAny(p, { "setting", "settings", "cai dat" }) then target = "setting"
            elseif hasAny(p, { "sea event", "sea" }) then target = "sea event"
            elseif hasAny(p, { "travel", "teleport" }) then target = "teleport"
            elseif hasAny(p, { "race", "mirage" }) then target = "race"
            elseif hasAny(p, { "raid", "dungeon" }) then target = "raid"
            elseif hasAny(p, { "shop", "shopping" }) then target = "shopping"
            elseif hasAny(p, { "prehistoric", "volcano" }) then target = "prehistoric"
            elseif hasAny(p, { "halloween" }) then target = "halloween"
            elseif hasAny(p, { "esp", "stats" }) then target = "esp"
            elseif hasAny(p, { "combat", "local player" }) then target = "combat"
            elseif hasAny(p, { "misc", "miscellaneous" }) then target = "misc"
            elseif hasAny(p, { "info", "status", "overview" }) then target = "info"
            end
            if target then
                local ok = LX.DoOpenTab(target)
                LX.Say(ok and ("Đã mở tab " .. target .. ".") or "Không mở được tab đó.", ok and mood or "annoyed")
            else
                LX.Out("out", "tabs: " .. "Farming, Music Player, Quest And Item, Setting, Sea Event, Teleport")
                LX.Say("Bạn muốn mở tab nào?", "listen", 3)
            end
            return
        end

        if hasAny(p, { "bat nhac", "phat nhac", "play music", "resume music", "tiep tuc nhac" }) then
            local act = hasAny(p, { "tiep tuc", "resume" }) and "resume" or "play"
            local ok = LX.DoMusic(act)
            LX.Say(ok and "Được. Nhạc chạy rồi." or "Không phát được nhạc.", ok and mood or "annoyed")
            return
        end
        if hasAny(p, { "phat bai", "tim bai", "play song", "play track" }) then
            local query = p
            for _, prefixText in ipairs({ "phat bai", "tim bai", "play song", "play track" }) do
                local at = string.find(query, prefixText, 1, true)
                if at then query = string.sub(query, at + #prefixText); break end
            end
            query = string.gsub(query, "^%s+", "")
            local ok = LX.DoMusic("find", query)
            LX.Say(ok and "Đã chọn bài phù hợp." or "Không tìm thấy bài đó.", ok and mood or "annoyed")
            return
        end
        if hasAny(p, { "am luong nhac", "music volume" }) then
            local n = lastNumber(p)
            local ok = n and LX.DoMusic("volume", tostring(n))
            LX.Say(ok and ("Âm lượng nhạc " .. tostring(math.clamp(n, 0, 100)) .. "%.") or "Cần một mức âm lượng từ 0 đến 100.", ok and mood or "annoyed")
            return
        end
        if hasAny(p, { "tam dung nhac", "pause music" }) then
            local ok = LX.DoMusic("pause")
            LX.Say(ok and "Đã tạm dừng nhạc." or "Không có nhạc đang chạy.", ok and mood or "annoyed")
            return
        end
        if hasAny(p, { "dung nhac", "stop music" }) then
            local ok = LX.DoMusic("stop")
            LX.Say(ok and "Đã dừng nhạc." or "Không dừng được nhạc.", ok and mood or "annoyed")
            return
        end
        if hasAny(p, { "bai tiep theo", "next song", "next track", "chuyen bai" }) then
            local ok = LX.DoMusic("next")
            LX.Say(ok and "Chuyển bài." or "Không chuyển được bài.", ok and mood or "annoyed")
            return
        end
        if hasAny(p, { "bai truoc", "previous song", "prev track" }) then
            local ok = LX.DoMusic("prev")
            LX.Say(ok and "Quay lại bài trước." or "Không chuyển được bài.", ok and mood or "annoyed")
            return
        end
        if has(p, "mo nhac") or has(p, "open music") then
            local ok = LX.DoOpenTab("music")
            LX.Say(ok and "Mở Music Player." or "Không mở được Music Player.", ok and mood or "annoyed")
            return
        end

        -- timer / stopwatch
        if has(p, "hen gio") or has(p, "timer") or (has(p, "dem nguoc")) then
            local n = lastNumber(p)
            if hasAny(p, { "tat", "dung", "huy", "stop" }) then
                LX.DoWatch("stoptimer")
                say("ok", mood)
            else
                local min = n or 5
                if has(p, "giay") or has(p, "s") then
                    min = min / 60
                end
                LX.DoTimer(min)
                say("ok", mood)
            end
            return
        end
        if has(p, "bam gio") or has(p, "stopwatch") then
            LX.DoWatch(has(p, "reset") and "reset" or (has(p, "lap") and "lap" or "toggle"))
            say("ok", mood)
            return
        end
        -- theme
        if has(p, "theme") or has(p, "giao dien") or has(p, "che do") then
            local list = LX.ThemeList()
            local hit
            for _, th in ipairs(list) do
                if has(p, norm(th)) then
                    hit = th
                end
            end
            if not hit and (has(p, "toi") or has(p, "dark")) then
                hit = "Dark"
            elseif not hit and (has(p, "sang") or has(p, "light")) then
                hit = "Light"
            end
            if hit then
                local ok = LX.DoTheme(hit)
                if ok then
                    say("ok", mood)
                else
                    say("perm", "annoyed")
                end
                return
            end
        end
        -- nhan vat
        if has(p, "nhay") or has(p, "jump") then
            if LX.DoJump() then
                say("ok", mood)
            else
                say("perm", "annoyed")
            end
            return
        end
        if has(p, "xoay") or has(p, "spin") then
            if LX.DoSpin() then
                say("ok", mood)
            else
                say("perm", "annoyed")
            end
            return
        end
        -- tat het / bat het
        if (has(p, "het") or has(p, "tat ca") or has(p, "all")) and hasAny(p, V_OFF) then
            local n = LX.DoAll(false)
            LX.Say("Tắt " .. n .. " cái. Yên tĩnh rồi.", "deadpan")
            return
        end
        -- pending (cau hoi lam ro)
        if LX.Pending then
            local pend = LX.Pending
            LX.Pending = nil
            if not (hasAny(p, V_PRESS) or hasAny(p, V_SEL) or hasAny(p, V_OFF) or hasAny(p, V_ON) or hasAny(p, V_SET)) then
                local it = resolve(p, nil)
                if it then
                    p = pend.verb .. " " .. it.nt
                end
            end
        end
        -- dieu khien element
        local verb, kinds
        if hasAny(p, V_PRESS) then
            verb, kinds = "press", { Button = true }
        elseif hasAny(p, V_SEL) then
            verb, kinds = "sel", { Dropdown = true }
        elseif hasAny(p, V_OFF) then
            verb, kinds = "off", { Toggle = true }
        elseif hasAny(p, V_ON) then
            verb, kinds = "on", { Toggle = true }
        elseif hasAny(p, V_SET) and lastNumber(p) then
            verb, kinds = "set", { Slider = true, Input = true }
        end
        if verb then
            local it, list = resolve(p, kinds)
            if not it and verb ~= "set" and verb ~= "sel" then
                it, list = resolve(p, nil)
            end
            if not it and #list > 1 then
                local names = ambiguous(list)
                LX.Out("cmd", verb .. " ?")
                LX.Out("warn", "ambiguous: " .. string.lower(asc(table.concat(names, " | "))))
                LX.Pending = { verb = verb }
                LX.Say("Cái nào? " .. table.concat(names, " / "), "annoyed", 3)
                return
            elseif not it then
                LX.Out("cmd", verb .. " ?")
                LX.Out("err", "no control matches")
                say("nf", "annoyed")
                return
            end
            if verb == "on" or verb == "off" then
                if it.type ~= "Toggle" then
                    LX.Say("'" .. it.title .. "' không phải công tắc.", "annoyed")
                    return
                end
                local ok, why = LX.DoToggle(it, verb == "on")
                if why == "perm" then
                    say("perm", "annoyed")
                elseif why == "same" then
                    say("same", "bored")
                else
                    LX.Say((verb == "on" and "Bật " or "Tắt ") .. it.title .. ". " .. pick({ "Xong.", "Rồi đấy.", "Ừ." }), mood)
                end
            elseif verb == "set" then
                local n = lastNumber(p)
                if it.type == "Slider" then
                    local ok, c = LX.DoSlider(it, n)
                    if ok then
                        LX.Say("Đặt " .. it.title .. " = " .. tostring(c) .. ".", mood)
                    else
                        say("perm", "annoyed")
                    end
                else
                    local ok = LX.DoInput(it, tostring(n))
                    LX.Say(ok and ("Điền " .. it.title .. " = " .. tostring(n) .. ".") or "Không điền được.", mood)
                end
            elseif verb == "sel" then
                local val = p
                for _, w in ipairs(it.toks) do
                    val = string.gsub(val, "%f[%w]" .. esc(w) .. "%f[%W]", " ")
                end
                for w in pairs(FILL) do
                    val = string.gsub(val, "%f[%w]" .. esc(w) .. "%f[%W]", " ")
                end
                val = norm(val)
                if val == "" then
                    LX.Say(it.title .. " đang là " .. asc(fmtVal(it)) .. ".", mood)
                else
                    local ok, name = LX.DoDropdown(it, val)
                    LX.Say(ok and ("Chọn " .. asc(tostring(name)) .. " cho " .. it.title .. ".") or "Không có lựa chọn đó.", ok and mood or "annoyed")
                end
            elseif verb == "press" then
                local ok = LX.DoPress(it)
                LX.Say(ok and ("Bấm " .. it.title .. ". " .. pick({ "Xong.", "Rồi." })) or "Bấm không được.", ok and mood or "annoyed")
            end
            return
        end
        -- xa giao
        if hasAny(p, { "xin chao", "chao", "hello", "hi", "alo", "hey", "yo" }) then
            say("hi", "listen")
            return
        end
        if hasAny(p, { "cam on", "thanks", "thank", "thx" }) then
            say("thanks", "deadpan")
            return
        end
        if has(p, "ban la ai") or has(p, "may la ai") or has(p, "who are you") or has(p, "longxgen la gi") then
            say("who", "deadpan")
            return
        end
        if hasAny(p, { "chan", "buon", "met", "bored" }) then
            say("bored", "bored")
            LX.SetMood("eyeroll", 1.4)
            return
        end
        -- ten khong co dong tu: neu khop 1 toggle thi hoi
        local it = resolve(p, nil)
        if it then
            LX.Pending = nil
            if it.type == "Toggle" then
                LX.Say(it.title .. " đang " .. (it.rec.Value == true and "bật" or "tắt") .. ". Bật hay tắt?", "listen", 3)
            else
                LX.Say(it.title .. " = " .. asc(fmtVal(it)) .. ".", "listen", 3)
            end
            return
        end
        say("idk", "bored")
    end

    local function processRequest(text, chatAtStart)
        local c = string.sub(text, 1, 1)
        local ok, err
        local w1 = string.lower(asc(words(text)[1] or ""))
        if c == "/" or c == "$" or c == ">" then
            ok, err = pcall(LX.Exec, string.sub(text, 2))
        elseif SHELLW[w1] and (#words(text) <= 3 or w1 == "help" or w1 == "ls") and not (w1 == "on" or w1 == "off" or w1 == "set") then
            ok, err = pcall(LX.Exec, text)
        elseif (w1 == "on" or w1 == "off" or w1 == "set" or w1 == "sel" or w1 == "press") and #words(text) >= 2 then
            ok, err = pcall(LX.Exec, text)
        else
            ok, err = pcall(LX.Ask, text)
        end
        if not ok then
            LX.Out("err", tostring(err))
            LX.Say("Có lỗi. Chán thật.", "annoyed")
        elseif LX.ChatVer == chatAtStart then
            LX.Say("Đã xử lý lệnh.", LX.Face)
        end
    end

    local function runQueue()
        while #LX.Queue > 0 and LX.Enabled do
            local text = table.remove(LX.Queue, 1)
            LX.Busy = #LX.Queue + 1
            LX.Thinking = true
            LX.SetMood("think", 0)
            if LX.OnThinking then pcall(LX.OnThinking, true) end
            task.wait(3)
            if not LX.Enabled then
                LX.Thinking = false
                break
            end
            LX.Thinking = false
            if LX.OnThinking then pcall(LX.OnThinking, false) end
            local chatAtStart = LX.ChatVer
            local ok, err = pcall(processRequest, text, chatAtStart)
            if not ok then
                LX.Out("err", tostring(err))
                LX.Say("Có lỗi khi xử lý. Thử lại sau.", "annoyed")
            end
            LX.Busy = #LX.Queue
        end
        LX.Thinking = false
        LX.Busy = 0
        if LX.OnThinking then pcall(LX.OnThinking, false) end
    end

    local queueRunning = false
    function LX.Handle(text)
        text = tostring(text or "")
        text = string.gsub(text, "^%s+", "")
        text = string.gsub(text, "%s+$", "")
        if text == "" or not LX.Enabled then
            return false
        end
        if #text > 240 then
            text = string.sub(text, 1, 240)
        end
        if #LX.Queue >= 5 then
            LX.Out("warn", "command queue full; wait for the current request")
            return false, "queue-full"
        end
        LX.EnsureWindowOpen()
        LX.User(text)
        table.insert(LX.Queue, text)
        LX.Busy = #LX.Queue + (queueRunning and 1 or 0)
        if not queueRunning then
            queueRunning = true
            task.spawn(function()
                runQueue()
                queueRunning = false
            end)
        end
        return true
    end

    function LX.Suggestions(query)
        local q = norm(query or "")
        local items = {}
        local function add(title, detail, command, category, base)
            local hay = norm(title .. " " .. detail .. " " .. command .. " " .. category)
            local score = base or 1
            if q ~= "" then
                if string.find(hay, q, 1, true) then
                    score = score + 100
                else
                    local matched, total = 0, 0
                    for token in string.gmatch(q, "%S+") do
                        total = total + 1
                        if string.find(hay, token, 1, true) then matched = matched + 1 end
                    end
                    if total == 0 or matched == 0 then return end
                    score = score + matched / total * 20
                end
            end
            items[#items + 1] = {
                Title = title, Detail = detail, Command = command,
                Category = category, Score = score,
            }
        end

        add("Mở tab Farming", "Mở bảng farm và các chức năng level", "mở tab farming", "TAB", 18)
        add("Mở Music Player", "Mở playlist và điều khiển âm nhạc", "mở tab music", "TAB", 17)
        add("Bật nhạc", "Phát hoặc tiếp tục bài hiện tại", "bật nhạc", "MUSIC", 16)
        add("Tạm dừng nhạc", "Pause track hiện tại", "tạm dừng nhạc", "MUSIC", 15)
        add("Bài tiếp theo", "Chuyển sang track kế tiếp", "bài tiếp theo", "MUSIC", 14)
        add("Bài trước", "Quay lại track trước", "bài trước", "MUSIC", 13)
        add("Dừng nhạc", "Dừng player Maru MusicX", "dừng nhạc", "MUSIC", 12)
        add("Phát ngẫu nhiên", "Chọn track ngẫu nhiên trong playlist", "/music shuffle", "MUSIC", 10)
        add("Mở tab Quest And Item", "Mở các nhiệm vụ và vật phẩm", "mở tab quest", "TAB", 11)
        add("Mở tab Settings", "Mở cài đặt Maru", "mở tab settings", "TAB", 8)
        add("Trạng thái farm", "Liệt kê các toggle đang bật", "ps", "SHELL", 10)
        add("Danh sách lệnh", "Hiển thị hướng dẫn Longxgen", "help", "SHELL", 9)

        local mx = Library.MusicX
        if mx and mx.n and mx.track then
            local okCount, trackCount = pcall(mx.n)
            if okCount then
                for i = 1, math.min(tonumber(trackCount) or 0, 120) do
                    local okTrack, track = pcall(mx.track, i)
                    if okTrack and type(track) == "table" and track.name then
                        add("Phát bài " .. tostring(track.name),
                            tostring(track.artist or "Unknown") .. " · Playlist Maru",
                            "phát bài " .. tostring(track.name), "MUSIC", 5)
                    end
                end
            end
        end

        local win = Library.Window or Window
        local tabModule = win and win.TabModule
        for _, tab in pairs(tabModule and tabModule.Tabs or {}) do
            local title = tostring(tab and tab.Title or "")
            if title ~= "" then
                add("Mở tab " .. title, "Đi tới tab " .. title, "mở tab " .. title, "TAB", 4)
            end
        end

        for _, it in ipairs(buildReg()) do
            if it.type == "Toggle" then
                local on = it.rec.Value == true
                add((on and "Tắt " or "Bật ") .. it.title,
                    tostring(it.tab or "Farm control") .. " · " .. (on and "Đang bật" or "Đang tắt"),
                    (on and "tắt " or "bật ") .. it.title, "TOGGLE", 2)
            elseif it.type == "Button" then
                add("Bấm " .. it.title, tostring(it.tab or "Action") .. " · Button",
                    "bấm " .. it.title, "BUTTON", 1)
            elseif it.type == "Dropdown" then
                local values = it.rec.Values or {}
                for valueIndex, value in ipairs(values) do
                    local valueName = valueText(value)
                    add("Chọn " .. it.title .. " · " .. valueName,
                        tostring(it.tab or "Option") .. " · Dropdown option",
                        "chọn " .. it.title .. " " .. valueName, "DROPDOWN", 1.5 - valueIndex * 0.001)
                end
            end
        end

        table.sort(items, function(a, b)
            if a.Score ~= b.Score then return a.Score > b.Score end
            return a.Title < b.Title
        end)
        local out = {}
        local seen = {}
        for _, item in ipairs(items) do
            local key = norm(item.Command)
            if not seen[key] then
                seen[key] = true
                out[#out + 1] = item
                if #out >= 36 then break end
            end
        end
        return out
    end

    ------------------------------------------------------------------ phim goi: go "longxgen" (khong can o chat)
    do
        local buf = ""
        UIS.InputBegan:Connect(function(i, gp)
            if gp or not LX.Enabled or not LX.Perm.Trigger or UIS:GetFocusedTextBox() then
                return
            end
            local nm = i.KeyCode and i.KeyCode.Name
            if type(nm) == "string" and #nm == 1 then
                buf = string.sub(buf .. string.lower(nm), -8)
                if buf == "longxgen" then
                    buf = ""
                    if LX.OnOpen then
                        pcall(LX.OnOpen)
                    end
                end
            end
        end)
    end

    LX.Out("dim", "longxgen ready - " .. "type help")
    local isl = WindUI.Island
    if isl then
        isl.CrossHook = {
            Enabled = function()
                return LX.Enabled
            end,
            Accent = function()
                return Color3.fromRGB(170, 200, 255)
            end,
            Longxgen = LX,
        }
        if isl.BindLongxgen then
            pcall(isl.BindLongxgen, isl, LX)
        end
    end
end

