function ScanWorldSpawns()
    if _G.QM_WorldSpawnScanBusy then return end
    local spawnsFolder = Workspace:FindFirstChild("_WorldOrigin")
        and Workspace._WorldOrigin:FindFirstChild("EnemySpawns")
    if not spawnsFolder then return end
    _G.QM_WorldSpawnScanBusy = true
    local worldSpawnData = getgenv().WorldSpawnData
    local worldLevelData = getgenv().WorldMobLevelData
    local worldBossData = getgenv().WorldMobBossData
    local pending = { spawnsFolder }
    local processed = 0
    local okScan, scanError = pcall(function()
        while #pending > 0 do
            local node = table.remove(pending)
            if node and node.Parent then
                local children = node:GetChildren()
                for i = 1, #children do pending[#pending + 1] = children[i] end
                if node:IsA("BasePart") then
                    local part = node
                    local rawName = part.Name
                    local name = rawName:match("^(.-)%s*%[") or rawName
                    if name == "" then name = rawName end
                    if name:match("^Part%d*$") or name:match("^Union%d*$")
                        or name:match("^Spawn%d*$") or name == "SpawnLocation" then
                        name = (part.Parent and part.Parent ~= spawnsFolder and part.Parent.Name) or name
                        rawName = name
                    end
                    local lvlStr = rawName:match("%[%s*[Ll][Vv]%.?%s*(%d+)%s*%]")
                    if lvlStr then
                        local lvlNum = tonumber(lvlStr)
                        if lvlNum and (not worldLevelData[name] or lvlNum > worldLevelData[name]) then
                            worldLevelData[name] = lvlNum
                        end
                    end
                    if rawName:match("%[%s*[Bb]oss%s*%]") then worldBossData[name] = true end
                    local pos = part.Position
                    local cf = CFrame.new(pos.X, pos.Y + 25, pos.Z)
                    local list = worldSpawnData[name]
                    if not list then list = {}; worldSpawnData[name] = list end
                    local isDup = false
                    for _, existingCF in ipairs(list) do
                        if (existingCF.Position - cf.Position).Magnitude < 3 then isDup = true; break end
                    end
                    if not isDup then table.insert(list, cf) end
                end
            end
            processed = processed + 1
            if processed % 180 == 0 then task.wait() end
        end
    end)
    _G.QM_WorldSpawnScanBusy = false
    _G.QM_WorldSpawnScanDone = okScan and os.clock() or nil
    if not okScan then warn("[Maru] WorldSpawn scan: " .. tostring(scanError)) end
end
getgenv().ScanWorldSpawns = ScanWorldSpawns
function GetMobDropdownList()
    local items = {}
    for name, posList in pairs(getgenv().WorldSpawnData or {}) do
        if posList and #posList > 0 then
            table.insert(items, {
                name  = name,
                level = getgenv().WorldMobLevelData and getgenv().WorldMobLevelData[name],
                boss  = getgenv().WorldMobBossData and getgenv().WorldMobBossData[name],
            })
        end
    end
    table.sort(items, function(a, b)
        local la = a.level or math.huge
        local lb = b.level or math.huge
        if la ~= lb then return la < lb end
        return a.name < b.name
    end)
    local display, map = {}, {}
    for _, item in ipairs(items) do
        local label
        if item.level then
            label = item.boss and ("%s [Lv. %d] [Boss]"):format(item.name, item.level)
                or ("%s [Lv. %d]"):format(item.name, item.level)
        else
            label = item.name
        end
        table.insert(display, label)
        map[label] = item.name
    end
    return display, map
end
getgenv().GetMobDropdownList = GetMobDropdownList
