          (_G.MobCrew      and CheckFishCrew()          )
      ) and true or false
      _G.PFS_BossActive = (
          _G.FarmEliteHunt or _G.FarmEliteH  or
          _G.FarmBoss      or _G.AutoFarmAllBoss or
          _G.AutoKillCursedCaptain or _G.AutoGetGravityBlade or _G.AutoGetFlail or
          _G.FarmTyrant    or _G.FarmPhaBinh
      ) and true or false
      _G.PFS_FruitActive = (
          _G.TwFruits and
          not _G.FruitPickActive and
          _FindNearestWildFruit() ~= nil
      ) and true or false
      if _G.PFS_SeaActive then
