-- [PHASE115 FPS] Banana-style FPS boost: snapshot -> batch (frame budget) -> restore. Replaces the old QM pass.
do
    local Lighting = game:GetService("Lighting")
    local RunService = game:GetService("RunService")
    local PlayersS = game:GetService("Players")
    local snap = setmetatable({}, { __mode = "k" })
    local lightSnap, terrainSnap, qualitySnap = nil, nil, nil
    local pending, queued = {}, setmetatable({}, { __mode = "k" })
    local workerRunning, workerToken = false, 0
    local stats = { processed = 0, errors = 0, restored = 0 }
    _G.QM_FpsStats = stats
    local function remember(inst, prop)
        local rec = snap[inst]
        if not rec then rec = {} snap[inst] = rec end
        if rec[prop] == nil then
            local ok, v = pcall(function() return inst[prop] end)
            if ok then rec[prop] = { v } end
        end
    end
    local function setp(inst, prop, value)
        remember(inst, prop)
        local ok = pcall(function() inst[prop] = value end)
        if not ok then stats.errors = stats.errors + 1 end
    end
    local function inPlayerCharacter(inst)
        for _, p in ipairs(PlayersS:GetPlayers()) do
            local c = p.Character
            if c and inst:IsDescendantOf(c) then return true end
        end
        return false
    end
    local function inLivingModel(inst)
        local m = inst:FindFirstAncestorWhichIsA("Model")
        if not m then return false end
        if m:FindFirstChildOfClass("Humanoid") then return true end
        local n = m.Name
        return n == "Characters" or n == "Enemies" or n == "NPCs"
    end
    local function applyLighting()
        if _G.QM_StartupAntiLowGfx == false and _G.QM_FpsBoost == false then return end
        if not lightSnap then
            lightSnap = {}
            for _, k in ipairs({ "GlobalShadows", "FogEnd", "FogStart", "Brightness", "EnvironmentDiffuseScale", "EnvironmentSpecularScale" }) do
                local ok, v = pcall(function() return Lighting[k] end)
                if ok then lightSnap[k] = v end
            end
        end
        pcall(function()
            Lighting.GlobalShadows = false
            Lighting.FogEnd = 9000000000
            Lighting.FogStart = 9000000000
            Lighting.Brightness = 1
            Lighting.EnvironmentDiffuseScale = 0
            Lighting.EnvironmentSpecularScale = 0
        end)
        pcall(function() if sethiddenproperty then sethiddenproperty(Lighting, "Technology", 2) end end)
        pcall(function()
            local terrain = workspace:FindFirstChildOfClass("Terrain")
            if terrain then
                if not terrainSnap then
                    terrainSnap = { terrain.WaterWaveSize, terrain.WaterWaveSpeed, terrain.WaterReflectance, terrain.WaterTransparency, terrain.Decoration }
                end
                terrain.WaterWaveSize = 0
                terrain.WaterWaveSpeed = 0
                terrain.WaterReflectance = 0
                terrain.WaterTransparency = 0
                terrain.Decoration = false
            end
        end)
        pcall(function()
            if settings and settings().Rendering and _G.QM_NoGraphics ~= false then
                if qualitySnap == nil then qualitySnap = settings().Rendering.QualityLevel end
                settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
            end
        end)
        if _G.NR then pcall(function() RunService:Set3dRenderingEnabled(false) end) end
    end
    local function reduceOne(obj)
        if not obj or not obj.Parent then return end
        if obj:IsA("Humanoid") or obj:IsA("ProximityPrompt") or obj:IsA("ClickDetector") or obj:IsA("Camera")
            or obj:IsA("SpawnLocation") or obj:IsA("Tool") or obj:IsA("BaseScript") or obj:IsA("RemoteEvent")
            or obj:IsA("RemoteFunction") or obj:IsA("BillboardGui") or obj:IsA("ScreenGui") or obj:IsA("SurfaceGui") then
            return
        end
        if obj.Name == "Rip_Indra" then return end
        if inPlayerCharacter(obj) then return end
        if _G.QM_StartupAntiLowGfx ~= false then
            if obj:IsA("Sky") then
                setp(obj, "StarCount", 0) setp(obj, "MoonSize", 0) setp(obj, "SunAngularSize", 0)
            elseif obj:IsA("Atmosphere") then
                setp(obj, "Density", 0) setp(obj, "Glare", 0) setp(obj, "Haze", 0)
            elseif obj:IsA("Clouds") then
                setp(obj, "Enabled", false)
            elseif obj:IsA("PostEffect") then
                setp(obj, "Enabled", false)
            elseif obj:IsA("ParticleEmitter") then
                setp(obj, "Enabled", false) setp(obj, "Rate", 0)
            elseif obj:IsA("Trail") or obj:IsA("Beam") or obj:IsA("Highlight") or obj:IsA("SelectionBox") then
                setp(obj, "Enabled", false)
            elseif obj:IsA("Fire") or obj:IsA("Smoke") or obj:IsA("Sparkles") or obj:IsA("Light") then
                setp(obj, "Enabled", false)
            elseif obj:IsA("Explosion") then
                setp(obj, "Visible", false)
            end
        end
        if _G.QM_FpsBoost ~= false then
            if obj:IsA("Decal") or obj:IsA("Texture") then
                setp(obj, "Transparency", 1)
            elseif obj:IsA("BasePart") and not inLivingModel(obj) then
                setp(obj, "Material", Enum.Material.SmoothPlastic)
                setp(obj, "CastShadow", false)
                setp(obj, "Reflectance", 0)
            end
        end
    end
    local function enqueue(inst)
        if not inst or queued[inst] then return end
        queued[inst] = true
        pending[#pending + 1] = inst
    end
    local function startWorker()
        if workerRunning then return end
        workerRunning = true
        workerToken = workerToken + 1
        local token = workerToken
        task.spawn(function()
            local processed = 0
            local sliceStart = os.clock()
            while token == workerToken and #pending > 0 do
                local obj = table.remove(pending)
                if obj then
                    if obj ~= workspace and obj ~= Lighting then
                        local ok = pcall(reduceOne, obj)
                        if not ok then stats.errors = stats.errors + 1 end
                    end
                    local okC, ch = pcall(function() return obj:GetChildren() end)
                    if okC and ch then for i = 1, #ch do enqueue(ch[i]) end end
                end
                processed = processed + 1
                if os.clock() - sliceStart > 0.004 then
                    RunService.Heartbeat:Wait()
                    sliceStart = os.clock()
                end
            end
            if token == workerToken then
                workerRunning = false
                stats.processed = stats.processed + processed
                _G.QM_FpsBoostDone = os.clock()
                _G.QM_FpsBoostProcessed = stats.processed
                if #pending > 0 then startWorker() end
            end
        end)
    end
    local function runLowGfx()
        workerToken = workerToken + 1
        workerRunning = false
        pending = {}
        queued = setmetatable({}, { __mode = "k" })
        applyLighting()
        enqueue(workspace)
        enqueue(Lighting)
        startWorker()
    end
    local function restoreAll()
        workerToken = workerToken + 1
        workerRunning = false
        pending = {}
        local n = 0
        for inst, rec in pairs(snap) do
            if inst and inst.Parent then
                for prop, box in pairs(rec) do
                    if pcall(function() inst[prop] = box[1] end) then n = n + 1 end
                end
            end
        end
        snap = setmetatable({}, { __mode = "k" })
        if lightSnap then
            for k, v in pairs(lightSnap) do pcall(function() Lighting[k] = v end) end
            lightSnap = nil
        end
        if terrainSnap then
            pcall(function()
                local t = workspace:FindFirstChildOfClass("Terrain")
                if t then
                    t.WaterWaveSize, t.WaterWaveSpeed, t.WaterReflectance, t.WaterTransparency, t.Decoration =
                        terrainSnap[1], terrainSnap[2], terrainSnap[3], terrainSnap[4], terrainSnap[5]
                end
            end)
            terrainSnap = nil
        end
        if qualitySnap ~= nil then
            pcall(function() settings().Rendering.QualityLevel = qualitySnap end)
            qualitySnap = nil
        end
        stats.restored = stats.restored + n
        return n
    end
    _G.QM_FpsBoostRun = runLowGfx
    _G.QM_FpsBoostRestore = restoreAll
    if _G.QM_FpsConn then pcall(function() _G.QM_FpsConn:Disconnect() end) end
    if _G.QM_LightingConn then pcall(function() _G.QM_LightingConn:Disconnect() end) end
    _G.QM_FpsConn = workspace.DescendantAdded:Connect(function(inst)
        if _G.QM_FpsBoost ~= false or _G.QM_StartupAntiLowGfx ~= false then
            enqueue(inst)
            startWorker()
        end
    end)
    _G.QM_LightingConn = Lighting.DescendantAdded:Connect(function(inst)
        if _G.QM_FpsBoost ~= false or _G.QM_StartupAntiLowGfx ~= false then
            enqueue(inst)
            startWorker()
        end
    end)
    if _G.QM_StartupAntiLowGfx ~= false or _G.QM_FpsBoost ~= false then
        runLowGfx()
    end
end

