EquipWeapon = function(text)
  if not text then return end
  if type(text) ~= "string" or text == "" then return end
  local _c = plr.Character
  if not _c then return end
  local _bp = plr:FindFirstChild("Backpack")
  if not _bp then return end
  local _t = _bp:FindFirstChild(text)
  if not _t then return end
  if not _t:IsA("Tool") then return end
  local _h = _c:FindFirstChildOfClass("Humanoid")
  if not (_h and _h:IsA("Humanoid")) then return end
  _h:EquipTool(_t)
end
weaponSc = function(weapon)
  for __in, v in pairs(plr.Backpack:GetChildren()) do
    if v:IsA("Tool") then
      if v.ToolTip == weapon then EquipWeapon(v.Name) end
    end
  end
end
local Attack = {}
Attack.__index = Attack
Attack.Hum = function(model)
    if not model then return nil end
    local h = model:FindFirstChildOfClass("Humanoid")
    if h and h:IsA("Humanoid") then return h end
    return nil
end
Attack.Alive = function(model)
    if not model then return false end
    local h = Attack.Hum(model)
    return h ~= nil and h.Health > 0
end
Attack.Pos = function(model, dist)
    if not model then return false end
    local root = model:FindFirstChild("HumanoidRootPart")
    if not root then return false end
    if not Root or not Root.Position then return false end
    return (Root.Position - root.Position).Magnitude <= dist
end
Attack.Dist = function(model,dist) return (Root.Position - model:FindFirstChild("HumanoidRootPart").Position).Magnitude <= dist end
Attack.DistH = function(model,dist) return (Root.Position - model:FindFirstChild("HumanoidRootPart").Position).Magnitude > dist end
_G.FarmPositionMode = _G.FarmPositionMode or "None"
_G.OrbitAngle2 = _G.OrbitAngle2 or 0
_G.OrbitLastTick2 = _G.OrbitLastTick2 or tick()
_G.StarAxis = _G.StarAxis or Vector3.new(0, 8, 15)
_G.StarDebounce = _G.StarDebounce or 0
do
local function GetNextStarAxis()
    if tick() - _G.StarDebounce <= 0.4 then
        return _G.StarAxis
    end
    local dist = _G.SpinRadius or 15
    local axis
    if math.random() <= 0.5 then
        axis = Vector3.new((math.random() <= 0.5 and -1 or 1) * dist, 8, 0)
    else
        axis = Vector3.new(0, 8, (math.random() <= 0.5 and -1 or 1) * dist)
    end
    _G.StarAxis = axis
    _G.StarDebounce = tick()
    return axis
end
function GetSpinCFrame(targetPart, offset)
    if _G.FarmPositionMode == "Spin" then
        local now = tick()
        if _G.SpinAngle > 50000 then _G.SpinAngle = 60 end
        local _dtOrbit = now - (_G.OrbitLastChange or now)
        if _G.SmoothFarmMode then _dtOrbit = math.min(_dtOrbit, 0.1) end
        _G.SpinAngle = _G.SpinAngle + (_dtOrbit > 0.005 and (_G.SpinSpeed or 80) or 0)
        if _dtOrbit > 0.005 then _G.OrbitLastChange = now end
        local radius = _G.SpinRadius or 40
        local rad = math.rad(_G.SpinAngle)
        local pos = targetPart.Position + Vector3.new(math.cos(rad)*radius, offset, math.sin(rad)*radius)
        return CFrame.new(pos, targetPart.Position)
    elseif _G.FarmPositionMode == "Orbit" then
        local now = tick()
        local dt = now - _G.OrbitLastTick2
        _G.OrbitLastTick2 = now
        if dt > 0.5 then dt = 0.05 end
        local orbitSpeed = 3.5
        if _G.SmoothFarmMode then
            _G.OrbitAngle2 = _G.OrbitAngle2 + orbitSpeed * math.min(dt, 0.1)
        else
            _G.OrbitAngle2 = _G.OrbitAngle2 + orbitSpeed * dt
        end
        local dist = _G.SpinRadius or 15
        local off = Vector3.new(math.cos(_G.OrbitAngle2) * dist, offset, math.sin(_G.OrbitAngle2) * dist)
        return CFrame.new(targetPart.Position + off, targetPart.Position)
    elseif _G.FarmPositionMode == "Star" then
        return targetPart.CFrame + GetNextStarAxis()
    else
        return targetPart.CFrame * CFrame.new(0, offset, 0) * CFrame.Angles(0, math.rad(180), 0)
    end
end
end
function GetFarmOffset()
    local offset = _G.SpinHeightMelee or 14
    local tool = plr.Character and plr.Character:FindFirstChildOfClass("Tool")
    if tool and tool.ToolTip == "Blox Fruit" then
        offset = _G.SpinHeightFruit or 12
    end
    return offset
end
function DisableOtherFarms(except)
    if except ~= "Level" then _G.Level = false end
    if except ~= "Bone" then _G.AutoFarm_Bone = false end
    if except ~= "Near" then _G.AutoFarmNear = false end
    if except ~= "Island" then _G.AutoFarmIsland = false end
    _G.ActiveFarm = except
end
Attack.Kill = function(model, Succes)
    if not model then return end
    if not model.Parent then return end
    if not model:FindFirstChild("HumanoidRootPart") or not model:FindFirstChildOfClass("Humanoid") then return end
    if not Attack.Alive(model) then return end
    if not model:GetAttribute("Locked") then
        model:SetAttribute("Locked", model.HumanoidRootPart.CFrame)
    end
    local PosMon = model:GetAttribute("Locked").Position
    local targetName = model.Name
    local BoneMobs = {["Reborn Skeleton"]=true,["Living Zombie"]=true,["Demonic Soul"]=true,["Possessed Mummy"]=true,["Posessed Mummy"]=true}
    local isBone = BoneMobs[targetName] == true
    local startFarm = _G.ActiveFarm
    local fx = _G.FARMX
    local ownedTarget = nil
    local _ep = fx and fx.Epoch
    local stopOn = fx and fx.Enable.KillStopOnSwitch
    local startOwner = stopOn and fx.FH and fx.FH.Owner or nil
    while _G.SelectWeapon and model.Parent and Attack.Alive(model) do
        if fx and fx.On and fx.Enable.HookE and _ep ~= fx.Epoch then break end
        if stopOn then
            if startFarm ~= nil and _G.ActiveFarm ~= startFarm then break end
            if startOwner ~= nil and fx.On and fx.Enable.EnableHandler and fx.FH.Owner ~= startOwner then break end
        end
        if targetName == "Cake Prince" and fx and fx.Enable.KatakuriDodge and fx.Enable.KatakuriDodgeV3 and fx.IsKatakuriDangerV3 and fx.IsKatakuriDangerV3() then break end
        if not plr.Character or not plr.Character:FindFirstChild("HumanoidRootPart") or not plr.Character:FindFirstChildOfClass("Humanoid") then
            task.wait(0.3)
            break
        end
        if not Attack.Alive(plr.Character) then
            task.wait(0.5)
            break
        end
        if isBone then
            local otherOwner = fx and fx.Enable.BoneOther and Succes == true and not _G.AutoFarm_Bone
                and (_G.AutoKillMob == true or _G.AutoMaterial == true or (getgenv and getgenv().AutoMaterial == true))
            if not _G.AutoFarm_Bone and not otherOwner then break end
            if _G.ActiveFarm and _G.ActiveFarm ~= "Bone" and not otherOwner then break end
        else
            if _G.ActiveFarm == "Bone" and not isBone then break end
            if _G.ActiveFarm and _G.ActiveFarm ~= "Bone" then
                if _G.ActiveFarm == "Level" and not _G.Level then break end
                if _G.ActiveFarm == "Near" and not _G.AutoFarmNear then break end
                if _G.ActiveFarm == "Island" and not _G.AutoFarmIsland then break end
            end
            if type(Succes) == "function" then
            local guardOk, guardAllowed = pcall(Succes)
            if not guardOk or guardAllowed ~= true then break end
        elseif type(Succes) == "boolean" and not Succes then
            break
        end
        end
        local current = nil
        local minDist = math.huge
        for _, e in ipairs(workspace.Enemies:GetChildren()) do
            if e.Name == targetName and Attack.Alive(e) and e:FindFirstChild("HumanoidRootPart") then
                local d = (e.HumanoidRootPart.Position - PosMon).Magnitude
                if d <= 450 and d < minDist then
                    minDist = d
                    current = e
                end
            end
        end
        if not current then break end
        if fx then
            fx.AttackingMob = current
            ownedTarget = current
        end
        pcall(function() BringEnemy(current) end)
        EquipWeapon(_G.SelectWeapon)
        local offset = GetFarmOffset()
        pcall(function() _tp(GetSpinCFrame(current.HumanoidRootPart, offset)) end)
        task.wait(_G.Seriality and 0.01 or (_G.QF_AttackDelay or 0.01))
    end
    -- Clear only the target this invocation last owned; never erase another loop's target.
    if fx and ownedTarget and fx.AttackingMob == ownedTarget then
        fx.AttackingMob = nil
    end
end
