BringEnemy = function(Mon)
    if not _B then return end
    if not Mon then
        local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local closestDist = math.huge
        for _, enemy in ipairs(workspace.Enemies:GetChildren()) do
            local hum = enemy:FindFirstChildOfClass("Humanoid")
            local root = enemy:FindFirstChild("HumanoidRootPart")
            if hum and root and hum.Health > 0 then
                local dist = (root.Position - hrp.Position).Magnitude
                if dist < closestDist then
                    closestDist = dist
                    Mon = enemy
                end
            end
        end
        if not Mon then return end
    end
    local AreaMob = false
    local function Mobs(enemy)
        local hum = enemy:FindFirstChildOfClass("Humanoid")
        local root = enemy:FindFirstChild("HumanoidRootPart")
        return hum and root and hum.Health > 0, root, hum
    end
    local function Network(part)
        if isnetworkowner then
            return isnetworkowner(part)
        end
        return part.ReceiveAge == 0 and not part.Anchored and part.Velocity.Magnitude > 0
    end
    pcall(function()
        if sethiddenproperty then
            sethiddenproperty(plr, "SimulationRadius", math.huge)
        end
        local targetPos = Mon.HumanoidRootPart.Position
        for _, v in ipairs(workspace.Enemies:GetChildren()) do
            if v ~= Mon then
                local alive, root, hum = Mobs(v)
                if alive and v.Name == Mon.Name then
                    local distance = (root.Position - targetPos).Magnitude
                    if distance <= (_G.QF_BringRadius or ((_G.FARMX and _G.FARMX.Enable.BringV2) and (_G.FARMX.Cfg.BringRadius or 350)) or 3000) then
                        local _fxBM = _G.FARMX
                        if not (_fxBM and _fxBM.Enable and _fxBM.Enable.BringBodyMover == false) then
                            local bv = root:FindFirstChild("BodyVelocity")
                            if not bv then
                                bv = Instance.new("BodyVelocity")
                                bv.Name = "BodyVelocity"
                                bv.MaxForce = Vector3.new(1e9, 1e9, 1e9)
                                bv.Velocity = Vector3.zero
                                bv.Parent = root
                            end
                        end
                        if distance <= 10 then
                            AreaMob = true
                        end
                        if (not AreaMob or (_G.FARMX and _G.FARMX.Enable.BringV2 and distance > 10)) and Network(root) then
                            root.CFrame = CFrame.new(targetPos)
                        end
                        root.CanCollide = false
                        hum.WalkSpeed = 0
                        hum.JumpPower = 0
                    end
                end
            end
        end
        if Mon and Mon:FindFirstChild("HumanoidRootPart") then
            Mon.HumanoidRootPart.CanCollide = false
            do local _h = Attack.Hum(Mon); if _h then _h.WalkSpeed = 0 end end
            do local _h = Attack.Hum(Mon); if _h then _h.JumpPower = 0 end end
        end
    end)
end
