_G.MaruLv.Pick = function(lvl)
    local team = tostring(game:GetService("Players").LocalPlayer.Team or "")
    local best
    for _, r in ipairs(_G.MaruLv.Rows) do
        if CheckSea(r[1]) and lvl >= r[2] and lvl <= r[3] and (r[10] == nil or r[10] == team or (team ~= "Marines" and team ~= "Pirates" and r[10] == "Pirates")) then
            best = r
        end
    end
    return best
end
_G.MaruLv.ByMob = function(name)
    for _, r in ipairs(_G.MaruLv.Rows) do
        if r[4] == name then return r end
    end
    return nil
end
GetQuests = function()
    local lvl = plr.Data.Level.Value
    local LevelReq = 0
    local mmb = {}
    local mlRow = _G.MaruLv.Pick(lvl)
    if mlRow then
        mmb["Mob"] = mlRow[4]
        mmb["NameQuest"] = mlRow[6]
        mmb["ID"] = mlRow[7]
        mmb["LevelReq"] = mlRow[2]
    elseif lvl >= 700 and CheckSea(1) then
        mmb["Mob"] = "Galley Captain"
        mmb["NameQuest"] = "FountainQuest"
        mmb["ID"] = 2
        mmb["LevelReq"] = 700
    elseif lvl >= 1500 and CheckSea(2) then
        mmb["Mob"] = "Water Fighter"
        mmb["NameQuest"] = "ForgottenQuest"
        mmb["ID"] = 2
        mmb["LevelReq"] = 1450
    else
        for r, v in pairs(Quests) do
            for id, v1 in pairs(v) do
                local LvReq = v1.LevelReq
                for nguoi, tinh in pairs(v1.Task) do
                    if lvl >= LvReq and LevelReq <= LvReq and v1.Task[nguoi] > 1 and not table.find(blacklistquest, r) then
                        LevelReq = LvReq
                        mmb["Mob"] = nguoi
                        mmb["NameQuest"] = r
                        mmb["ID"] = id
                        mmb["LevelReq"] = LvReq
                    end
                end
            end
        end
    end
    return mmb
end
GetQuestPoint = function()
    if GuideModule and GuideModule.Data and GuideModule.Data.LastClosestNPC then
        return GetQuestPointFromNPC(GuideModule.Data.LastClosestNPC)
    end
    return nil
end
