    }
    _G.FARMX = FX
    FX.Log = function(key, msg)
        if not FX.Cfg.Debug then return end
        local now = os.clock()
        local last = FX.Logs[key]
        if last and now - last < FX.Cfg.LogMinGap then return end
        FX.Logs[key] = now
        warn("[QM-FARM] " .. tostring(key) .. ": " .. tostring(msg))
    end
    FX.Cached = function(key, ttl, fn)
        local now = os.clock()
        local c = FX.Cache[key]
        if c and now - c.t < ttl then return c.v end
        local ok, v = pcall(fn)
        if not ok then FX.Log("cache-" .. tostring(key), v) v = false end
        FX.Cache[key] = { t = now, v = v }
        return v
    end
    FX.IsPlayerModel = function(m)
        return game:GetService("Players"):GetPlayerFromCharacter(m) ~= nil
    end
    FX.AliveMob = function(m)
        local h = m and m:FindFirstChildOfClass("Humanoid")
        return h ~= nil and h.Health > 0 and m:FindFirstChild("HumanoidRootPart") ~= nil and not FX.IsPlayerModel(m)
    end
    do
        local traceBuf = {}
        local traceIdx = 1
        local traceMax = 200
        FX.Trace = { Buf = traceBuf }
        FX.TraceAdd = function(code, ...)
            if not FX.Enable or not FX.Enable.FarmTrace then return end
            local entry = { t = os.clock(), mode = tostring(_G.ActiveFarm or "?"), code = tostring(code or "?") }
            local args = { ... }
            if args[1] then entry.mob = tostring(args[1]) end
            if args[2] then entry.dist = tostring(args[2]) end
            if args[3] then entry.alive = tostring(args[3]) end
            if args[4] then entry.owner = tostring(args[4]) end
            traceBuf[traceIdx] = entry
            traceIdx = traceIdx + 1
            if traceIdx > traceMax then traceIdx = 1 end
        end
        FX.TraceDump = function()
            pcall(function()
                local n = 0
                for _ in pairs(traceBuf) do n = n + 1 end
                warn("[QM-FARM] === Farm Trace (ring " .. n .. "/" .. traceMax .. ") ===")
                local start = traceIdx
                for i = 0, traceMax - 1 do
                    local pos = ((start - 1 + i) % traceMax) + 1
                    local e = traceBuf[pos]
                    if e then
                        warn(string.format("[QM-FARM] %.2f | %s | %s | mob=%s dist=%s alive=%s owner=%s",
                            e.t or 0, e.mode or "?", e.code or "?", e.mob or "-", e.dist or "-", e.alive or "-", e.owner or "-"))
                    end
                end
                warn("[QM-FARM] === End Farm Trace ===")
            end)
        end
    end
    FX.Katakuri = {
        Danger = {
            names = { "ring", "fist", "mochiswirl" },
            colors = { "Toothpaste", "Institutional white" },
        },
        seen = {},
        seenN = 0,
        _lastCheck = 0,
        _lastV = false,
    }
    FX.SpeedCap = function()
        return (FX.Cfg and FX.Cfg.FlyCap) or 210
    end
    FX.Katakuri.Danger.seaNames    = { "lightbullet" }
    FX.Katakuri.Danger.seaColors   = { "Toothpaste", "Institutional white" }
    FX.Katakuri.Danger.terrorNames = { "sharkslam", "spin", "chargemodel" }
    FX.IsKatakuriDangerV3 = function()
        local K = FX.Katakuri
        local now = os.clock()
        local gap = (FX.Cfg and FX.Cfg.KatakuriDodgeGap) or 0.1
        if gap < 0.05 then gap = 0.05 end
        if now - (K._v3Check or -1e9) < gap then return K._v3V or false end
        K._v3Check = now
        local ok, v = pcall(function()
            local wo = workspace:FindFirstChild("_WorldOrigin")
            if not wo then return false end
            local E, D = FX.Enable, K.Danger
            for _, child in ipairs(wo:GetChildren()) do
                local cname = (child.Name or ""):lower()
                if E.KatGroupNames then
                    for _, m in ipairs(D.names) do if cname:find(m, 1, true) then return true end end
                end
                if E.KatGroupTerror then
                    for _, m in ipairs(D.terrorNames) do if cname:find(m, 1, true) then return true end end
                end
                if E.KatGroupSea then
                    for _, m in ipairs(D.seaNames) do if cname:find(m, 1, true) then return true end end
                    if child:IsA("BasePart") then
                        local bc = child.BrickColor
                        if bc then
                            for _, c in ipairs(D.seaColors) do if bc.Name == c then return true end end
                        end
                    end
                end
            end
            return false
        end)
        K._v3V = (ok and v) and true or false
        return K._v3V
    end
