    FX.DIM.Timer = { state = "idle", total = 0, endAt = 0, left = 0 }
    FX.DIM.Watch = { state = "idle", startAt = 0, accum = 0, laps = {} }
    FX.DIM.Fmt = function(sec)
        sec = math.max(0, math.floor((tonumber(sec) or 0) + 0.0001))
        return string.format("%d:%02d", math.floor(sec / 60), sec % 60)
    end
    FX.DIM.TimerLeft = function()
        local t = FX.DIM.Timer
        if t.state == "run" then return math.max(0, t.endAt - os.clock()) end
        if t.state == "pause" then return t.left end
        return 0
    end
    FX.DIM.TimerStart = function(minutes)
        local t = FX.DIM.Timer
        t.total = math.clamp(math.floor((tonumber(minutes) or 5) * 60 + 0.5), 1, 3600)
        t.endAt = os.clock() + t.total
        t.left = t.total
        t.state = "run"
        if FX.TraceAdd then pcall(FX.TraceAdd, "DIM_TIMER", "start", tostring(t.total)) end
    end
    FX.DIM.TimerPause = function()
        local t = FX.DIM.Timer
        if t.state == "run" then t.left = math.max(0, t.endAt - os.clock()) t.state = "pause" end
    end
    FX.DIM.TimerResume = function()
        local t = FX.DIM.Timer
        if t.state == "pause" then t.endAt = os.clock() + t.left t.state = "run" end
    end
    FX.DIM.TimerAdd = function(sec)
        local t = FX.DIM.Timer
        if t.state == "run" then t.endAt = t.endAt + sec t.total = t.total + sec
        elseif t.state == "pause" then t.left = t.left + sec t.total = t.total + sec end
    end
    FX.DIM.TimerStop = function()
        FX.DIM.Timer.state = "idle"
    end
    FX.DIM.WatchElapsed = function()
        local w = FX.DIM.Watch
        return w.accum + ((w.state == "run") and (os.clock() - w.startAt) or 0)
    end
    FX.DIM.WatchToggle = function()
        local w = FX.DIM.Watch
        if w.state == "run" then
            w.accum = w.accum + (os.clock() - w.startAt)
            w.state = "pause"
        else
            w.startAt = os.clock()
            w.state = "run"
        end
    end
    FX.DIM.WatchLap = function()
        local w = FX.DIM.Watch
        if w.state ~= "idle" then
            table.insert(w.laps, 1, FX.DIM.WatchElapsed())
            if #w.laps > 3 then table.remove(w.laps) end
            local isl = FX.DIM.Island()
            if isl then pcall(function() isl:Notify({ Title = "Lap " .. #w.laps, Value = FX.DIM.Fmt(w.laps[1]), Duration = 1.5 }) end) end
        end
    end
    FX.DIM.WatchReset = function()
        local w = FX.DIM.Watch
        w.state, w.accum, w.startAt, w.laps = "idle", 0, 0, {}
    end
    FX.DIM.Island = function()
        local ok, isl = pcall(function() return Library.WindUI.Island end)
        return ok and isl or nil
    end
    FX.DIM.Acts = function()
        local out = {}
        local t, w = FX.DIM.Timer, FX.DIM.Watch
        if t.state ~= "idle" then
            out[#out + 1] = { kind = "timer", icon = "hourglass", text = FX.DIM.Fmt(FX.DIM.TimerLeft()), ring = FX.DIM.TimerLeft() / math.max(t.total, 1) }
        end
        if w.state ~= "idle" then
            out[#out + 1] = { kind = "stopwatch", icon = "timer", text = FX.DIM.Fmt(FX.DIM.WatchElapsed()), ring = (FX.DIM.WatchElapsed() % 60) / 60 }
        end
        if Library.MusicIsland ~= nil then
            out[#out + 1] = { kind = "media", icon = "music" }
        end
        return out
    end
    FX.DIM.Promote = function(sk)
        local isl = FX.DIM.Island()
        if not (isl and sk) then return end
        if sk.kind == "timer" then
            pcall(function() isl:Notify({ Title = "Timer", Value = sk.text, Unit = "left", Duration = 3 }) end)
        elseif sk.kind == "stopwatch" then
            pcall(function() isl:Notify({ Title = "Stopwatch", Value = sk.text, Duration = 3 }) end)
        end
        if FX.TraceAdd then pcall(FX.TraceAdd, "DIM_PROMOTE", tostring(sk.kind)) end
    end
    FX.DIM.State = function()
        local isl = FX.DIM.Island()
        local d = isl and isl.Dim
        local acts = {}
        for _, a in ipairs(FX.DIM.Acts()) do acts[#acts + 1] = a.kind .. (a.text and ("=" .. a.text) or "") end
        return string.format("On=%s Glow=%s skin=%s acts=[%s] timer=%s watch=%s", tostring(d and d.On), tostring(d and d.Glow),
            tostring(d and d.skin and d.skin.key), table.concat(acts, ","), FX.DIM.Timer.state, FX.DIM.Watch.state)
    end
    task.spawn(function()
        while task.wait(0.25) do
            pcall(function()
                local t = FX.DIM.Timer
                if t.state == "run" and os.clock() >= t.endAt then
                    t.state = "idle"
                    do local islF = FX.DIM.Island() if islF and islF.Dim and islF.Dim.Flash then pcall(islF.Dim.Flash) end end
                    if FX.FH and FX.FH.NotifyDot then pcall(FX.FH.NotifyDot, "y", "Hẹn giờ đã kết thúc", 3) end
                    if FX.TraceAdd then pcall(FX.TraceAdd, "DIM_TIMER", "end") end
                end
                local isl = FX.DIM.Island()
                local d = isl and isl.Dim
                if d then
                    d.On = FX.Enable.DimMux == true
                    d.Glow = (FX.Enable.IslandGlow == true) and (tonumber(FX.Cfg.GlowQuality) or 0) > 0
                    d.CycleSec = tonumber(FX.Cfg.DimBubbleCycleSec) or 0
                    d.MinShow = tonumber(FX.Cfg.DimMinShow) or 0.35
                    d.Acts = FX.DIM.Acts
                    d.Promote = FX.DIM.Promote
                    d.Ctl = FX.DIM
                    d.Cards = FX.Enable.DimCards == true
                    d.Overview = FX.Enable.DimOverview == true
                end
            end)
        end
    end)
    FX.Stage = function(killed, bossAlive)
        if bossAlive then return 5 end
        local k = tonumber(killed) or 0
        if k < 100 then return 0 end
        if k < 200 then return 1 end
        if k < 300 then return 2 end
        if k < 400 then return 3 end
        if k < 500 then return 4 end
        return 5
    end
    FX.Names = {
        TyrantBoss = "Tyrant of the Skies",
        CakeBoss   = "Cake Prince",
        CakeMobs   = { "Cookie Crafter", "Cake Guard", "Baking Staff", "Head Baker" },
        BoneMobs   = { "Reborn Skeleton", "Living Zombie", "Demonic Soul", "Posessed Mummy", "Possessed Mummy" },
        TikiMobs   = { "Isle Outlaw", "Island Boy", "Sun-kissed Warrior", "Isle Champion", "Serpent Hunter", "Skull Slayer" },
    }
    FX.Area = {}
    FX.Area.Mobs = function(mode)
        if mode == "CakePrince" then return FX.Names.CakeMobs end
        if mode == "Bone" then return FX.Names.BoneMobs end
        if mode == "Tyrant" then return FX.Names.TikiMobs end
        return {}
    end
    FX.Area.Near = function(mode, radius)
        local res = {}
        pcall(function()
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            local enemies = workspace:FindFirstChild("Enemies")
            if not (hrp and enemies) then return end
            local names = FX.Area.Mobs(mode)
            local rad = radius or (FX.Cfg and FX.Cfg.FootSweepRadius) or 120
            for _, mob in ipairs(enemies:GetChildren()) do
                if table.find(names, mob.Name) and FX.AliveMob(mob) then
                    local mh = mob:FindFirstChild("HumanoidRootPart")
                    local d = (mh.Position - hrp.Position).Magnitude
                    if d <= rad then res[#res + 1] = { mob = mob, dist = d, hrp = mh } end
                end
            end
            table.sort(res, function(a, b) return a.dist < b.dist end)
        end)
        return res
    end
    FX.Dwell = { T = {} }
    FX.Dwell.Reset = function(mode) FX.Dwell.T[mode] = nil end
    FX.Dwell.Tick = function(mode, aliveCount)
        local now = os.clock()
        local need = (FX.Cfg and FX.Cfg.MobDwellSec) or 5.25
        local st = FX.Dwell.T[mode]
        if st and now - st.last > 2 then st = nil end
        if not st then st = { t0 = nil, last = now, left = false }; FX.Dwell.T[mode] = st end
        st.last = now
        local bossName = (mode == "CakePrince" and FX.Names.CakeBoss) or (mode == "Tyrant" and FX.Names.TyrantBoss) or nil
        local bossAlive = false
        if bossName then
            pcall(function()
                local en = workspace:FindFirstChild("Enemies")
                local b = en and en:FindFirstChild(bossName)
                bossAlive = b ~= nil and FX.AliveMob(b)
            end)
        end
        if (aliveCount or 0) > 0 or bossAlive then
            st.t0 = nil
            st.left = false
            return false, need
        end
        if not st.t0 then
            st.t0 = now
            if FX.TraceAdd then FX.TraceAdd("DWELL_START", mode, need) end
        end
        local el = now - st.t0
        if el >= need then
            if not st.left then
                st.left = true
                if FX.TraceAdd then FX.TraceAdd("DWELL_LEAVE", mode, el) end
            end
            return true, 0
        end
        return false, need - el
    end
    -- R05/R06: Centralized Tyrant eye reader — dùng cho IH.Probe, tyEyes, tySpam, FH.Tick handoff
    -- Trả { count, ok, list } — ok=false khi hierarchy lỗi (UNKNOWN state)
    FX.ReadTyrantEyes = function()
        local info = { count = 0, ok = false, list = {} }
        local okRead = pcall(function()
            local model = workspace:FindFirstChild("Map")
                and workspace.Map:FindFirstChild("TikiOutpost")
                and workspace.Map.TikiOutpost:FindFirstChild("IslandModel")
            if not model then return end
            local eye1 = model:FindFirstChild("Eye1")
            local eye2 = model:FindFirstChild("Eye2")
            local chunks = model:FindFirstChild("IslandChunks")
            local chunkE = chunks and chunks:FindFirstChild("E")
            local eye3 = chunkE and chunkE:FindFirstChild("Eye3")
            local eye4 = chunkE and chunkE:FindFirstChild("Eye4")
            local eyes = { eye1, eye2, eye3, eye4 }
            for i = 1, #eyes do
                local eye = eyes[i]
                if eye and eye:IsA("BasePart") and eye.Transparency ~= 1 then
                    info.count = info.count + 1
                    info.list[i] = true
                end
            end
            info.ok = true
        end)
        if not okRead then info.ok = false end
        return info
    end
    FX.KillWatch = function(mob, since, dt)
        if (dt or 0) >= 0.05 then return os.clock() end
        if os.clock() - since < 2.5 then return since end
        pcall(function()
            mob:SetAttribute("Locked", nil)
            local mh = mob:FindFirstChild("HumanoidRootPart")
            local hr = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            local dd = (mh and hr) and (hr.Position - mh.Position).Magnitude or -1
            if FX.TraceAdd then FX.TraceAdd("KILL_STALL", mob.Name, dd) end
            if mh and dd > 60 then _tp(mh.CFrame * CFrame.new(0, 20, 0)) end
        end)
        return os.clock()
    end
    FX._SH = {}
    FX.SpawnHold = function(mode, fallbackCF, rotate)
        local arrived = false
        pcall(function()
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            if not hrp then return end
            local now = os.clock()
            local st = FX._SH[mode]
            if not st or now - st.t > 15 then
                local list = {}
                local names = FX.Area.Mobs(mode)
                local wo = workspace:FindFirstChild("_WorldOrigin")
                local sps = wo and wo:FindFirstChild("EnemySpawns")
                if sps then
                    for _, sp in ipairs(sps:GetChildren()) do
                        if sp:IsA("BasePart") then
                            for _, n in ipairs(names) do
                                if string.find(sp.Name, n, 1, true) then list[#list + 1] = sp.CFrame break end
                            end
                        end
                    end
                end
                table.sort(list, function(a, b) return (a.Position - hrp.Position).Magnitude < (b.Position - hrp.Position).Magnitude end)
                st = { list = list, t = now, idx = 1 }
                FX._SH[mode] = st
            end
            if rotate and #st.list > 1 then st.idx = (st.idx % #st.list) + 1 end
            local dest = (#st.list > 0) and (st.list[st.idx] * CFrame.new(0, 25, 0)) or fallbackCF
            if not dest then return end
            if (hrp.Position - dest.Position).Magnitude > 40 then
                _tp(dest)
            else
                arrived = true
            end
        end)
        return arrived
    end
    FX.IslandState = function(mode)
        local bossName
        if mode == "CakePrince" then bossName = "Cake Prince"
        elseif mode == "Tyrant" then bossName = "Tyrant of the Skies"
        end
        if bossName then
            local enemies = workspace:FindFirstChild("Enemies")
            if enemies then
                local b = enemies:FindFirstChild(bossName)
                if b and FX.AliveMob(b) then return "BOSS_ALIVE" end
            end
        end
        if FX.Nav and FX.Nav.IsActive then
            local ok, active = pcall(FX.Nav.IsActive)
            if ok and active then return "TRAVEL_NPC" end
        end
        -- R15: Tyrant dùng eye count + _TyrantKillLast thay vì _CakeKillLast
        if mode == "Tyrant" then
            local eyeInfo = FX.ReadTyrantEyes and FX.ReadTyrantEyes() or { count = 0, ok = false }
            if eyeInfo.ok and eyeInfo.count >= 4 then return "BOSS_PENDING" end
            local tyKill = (FX._TyrantKillLast and FX._TyrantKillLast > 0)
            if tyKill then return "FARMING" end
            return "IDLE"
        end
        -- CakePrince branch: dùng _CakeKillLast
        local hasKill = (FX._CakeKillLast and FX._CakeKillLast > 0)
        if hasKill then return "FARMING" end
        return "IDLE"
    end
