    local FH = { Reg = {}, Order = {}, Seq = 0, Owner = nil, Disabled = false, Warned = {}, ReleasedAt = -1e9 }
    FX.FH = FH
    FH.Warn = function(key, msg)
        if FH.Warned[key] then return end
        FH.Warned[key] = true
        warn("[QM-FARM] " .. tostring(msg))
    end
    FH.GetFlag = function(f)
        local k = string.match(f, "^_G%.(.+)$")
        if k then return _G[k] and true or false end
        k = string.match(f, "^getgenv%(%)%.(.+)$")
        if k then
            local ok, v = pcall(function() return getgenv()[k] end)
            return (ok and v) and true or false
        end
        return false
    end
    FH.SetFlag = function(f, v)
        local k = string.match(f, "^_G%.(.+)$")
        if k then _G[k] = v return end
        k = string.match(f, "^getgenv%(%)%.(.+)$")
        if k then pcall(function() getgenv()[k] = v end) end
    end
    FX.Snap = { t = -1e9, en = {}, rep = {}, bossName = nil }
    FX.Scan = function()
        local sn = FX.Snap
        local now = os.clock()
        if now - sn.t < FX.Cfg.ScanInterval then return sn end
        sn.t = now
        local en, rp = {}, {}
        local function take(folder, into)
            if not folder then return end
            local kids = folder:GetChildren()
            for i = 1, #kids do
                local m = kids[i]
                if into[m.Name] == nil and m:IsA("Model") and FX.AliveMob(m) then into[m.Name] = m end
            end
        end
        take(workspace:FindFirstChild("Enemies"), en)
        take(replicated, rp)
        sn.en, sn.rep = en, rp
        local okq, q = pcall(QuestBeta)
        sn.bossName = (okq and type(q) == "table") and q[1] or nil
        return sn
    end
    FH.Want = {}
    FH.Want.Boss = function()
        local e = FH.Reg.Boss
        local sn = FX.Scan()
        if (_G.FarmBoss or e.masked["_G.FarmBoss"]) and sn.bossName and (sn.en[sn.bossName] or sn.rep[sn.bossName]) then return true end
        if (_G.AutoFarmAllBoss or e.masked["_G.AutoFarmAllBoss"]) and BossList then
            for i = 1, #BossList do
                if sn.en[BossList[i]] then return true end
            end
        end
        return false
    end
    FH.Want.Factory = function()
        local sn = FX.Scan()
        return (sn.en["Core"] or sn.rep["Core"]) ~= nil
    end
    FH.Want.SeaEvent = function()
        if _G.PFS_SeaActive then return true end
        local e = FH.Reg.SeaEvent
        for _, f in ipairs({ "_G.SailBoats", "_G.SailBoat_Hydra", "_G.FrozenTP", "_G.AutofindKitIs", "_G.tweenShrine", "_G.Collect_Ember", "_G.Trade_Ember", "getgenv().AutoCraftVolcanic" }) do
            if FH.GetFlag(f) or e.masked[f] then return true end
        end
