    local function inDimension(name)
        local ok, r = pcall(function()
            local map = workspace:FindFirstChild("Map")
            local d = map and map:FindFirstChild(name)
            local sp = d and d:FindFirstChild("Spawn")
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            return sp ~= nil and hrp ~= nil and (hrp.Position - sp.Position).Magnitude <= 1000
        end)
        return ok and r == true
    end
