    FH.Register = function(def)
        local n = def.name
        if FH.Reg[n] then FH.Warn("dup-" .. n, "[Handler] đăng ký trùng: " .. n) return end
        FH.Seq = FH.Seq + 1
        def.seq = FH.Seq
        def.masked = {}
        def.want = def.wantName and FH.Want[def.wantName] or nil
        def.atomic = def.atomicName and FH.Atomic[def.atomicName] or nil
        FH.Reg[n] = def
    end
