            _G.ActiveFarm       = "CakePrince"
        elseif Value == "Farm Tyrant of Skies" then
            _G.FarmTyrant = true
            _G.ActiveFarm = "Tyrant"
        elseif Value == "Farm Bone" then
            _G.AutoFarm_Bone = true
            _G.ActiveFarm    = "Bone"
        end
        local fxA = _G.FARMX
        if fxA and fxA.Enable.AcceptAutoOn and fxA.Enable.AcceptUiMove and not fxA.AcceptTouched and not _G.AcceptQuest
            and (Value == "Farm Cake Prince" or Value == "Farm Bone" or Value == "Farm Tyrant of Skies") then
