        end
    end)
end
;(function()
    -- [PHASE115] Lifecycle / ownership / verification modules. FH stays the only scheduler; these are passive helpers.
    local FX = _G.FARMX
    if not FX then return end
    local Players = game:GetService("Players")
    local lp = Players.LocalPlayer
    local function flog(tag, msg) pcall(function() if FX.Log then FX.Log(tag, msg) end end) end

    -- Session lifecycle ---------------------------------------------------------
    local old = getgenv().__MaruSession
    if old and type(old.Cleanup) == "function" then pcall(old.Cleanup, "reinject") end
    local Sess = { Id = tostring(os.time()) .. "-" .. tostring(math.random(1000, 9999)), Cleanups = {}, Conns = {}, Closed = false, Started = os.clock() }
    getgenv().__MaruSession = Sess
    FX.Session = Sess
    Sess.IsActive = function(id) return not Sess.Closed and (id == nil or id == Sess.Id) end
    Sess.Track = function(conn) Sess.Conns[#Sess.Conns + 1] = conn return conn end
    Sess.Register = function(name, fn) Sess.Cleanups[name] = fn end
    Sess.Cleanup = function(why)
        if Sess.Closed then return end
        Sess.Closed = true
        for name, fn in pairs(Sess.Cleanups) do
            local ok, err = pcall(fn, why)
            if not ok then flog("session-cleanup", tostring(name) .. ": " .. tostring(err)) end
        end
        for _, c in ipairs(Sess.Conns) do pcall(function() c:Disconnect() end) end
        Sess.Cleanups, Sess.Conns = {}, {}
        flog("session", "cleanup " .. tostring(why))
    end
    pcall(function()
        Sess.Track(lp.OnTeleport:Connect(function(st)
            if st == Enum.TeleportState.Started then Sess.Cleanup("teleport") end
        end))
    end)
    Sess.Register("fps-conns", function()
        if _G.QM_FpsConn then pcall(function() _G.QM_FpsConn:Disconnect() end) end
        if _G.QM_LightingConn then pcall(function() _G.QM_LightingConn:Disconnect() end) end
    end)

    -- Flag ownership (Raid / Dungeon / Trial flags): each flag is true while ANY owner holds it ---------------
    local FC = { owners = {} }
    FX.FlagCoord = FC
    FC.Set = function(flag, owner, value)
        local o = FC.owners[flag]
        if not o then o = {} FC.owners[flag] = o end
        o[owner] = value and true or nil
        _G[flag] = next(o) ~= nil
    end
    FC.Holders = function(flag)
        local t = {}
        for k in pairs(FC.owners[flag] or {}) do t[#t + 1] = k end
        table.sort(t)
        return table.concat(t, ",")
    end
    FC.ReleaseAll = function(owner)
        for flag, o in pairs(FC.owners) do
            if o[owner] then o[owner] = nil _G[flag] = next(o) ~= nil end
        end
    end
    local RC = { }
    FX.RaidCoord = RC
    RC.Claim = function(owner) FC.Set("Raiding", owner, true) end
    RC.Release = function(owner) FC.Set("Raiding", owner, false) end
    RC.Owner = function() return FC.Holders("Raiding") end
    Sess.Register("flag-owners", function() for flag in pairs(FC.owners) do FC.owners[flag] = {} _G[flag] = false end end)

    -- Fishing task controller (one runner per worker, session-bound, busy/throttle guarded) -----------------
    local FishC = { Session = (getgenv().__MaruFishSession or 0) + 1, Stats = {}, Busy = {}, Last = {} }
    getgenv().__MaruFishSession = FishC.Session
    FX.FishCtl = FishC
    FishC.Alive = function(sess) return sess == getgenv().__MaruFishSession and not Sess.Closed end
    FishC.Call = function(key, gap, fn)
        local st = FishC.Stats[key]
        if not st then st = { calls = 0, errors = 0, lastErr = nil, lastWarn = -1e9 } FishC.Stats[key] = st end
        local now = os.clock()
        if FishC.Busy[key] then return false, "busy" end
        if now - (FishC.Last[key] or -1e9) < (gap or 0) then return false, "throttled" end
        FishC.Busy[key] = true
        FishC.Last[key] = now
        st.calls = st.calls + 1
        local ok, err = pcall(fn)
        FishC.Busy[key] = nil
        if not ok then
            st.errors, st.lastErr = st.errors + 1, tostring(err)
            if now - st.lastWarn > 15 then st.lastWarn = now warn("[Maru Fish] " .. key .. ": " .. tostring(err)) end
        end
        return ok, err
    end
    Sess.Register("fishing", function() getgenv().__MaruFishSession = (getgenv().__MaruFishSession or 0) + 1 end)

    -- Purchase verification --------------------------------------------------------------------------------------
    local P = { pending = {} }
    FX.Purchase = P
    P.Run = function(id, owned, send, opts)
        opts = opts or {}
        local timeout, cool, maxTries = opts.timeout or 10, opts.cool or 5, opts.tries or 3
        local r = P.pending[id]
        if not r then r = { state = "IDLE", tries = 0, nextAt = 0, failUntil = 0 } P.pending[id] = r end
        local now = os.clock()
        local okO, have = pcall(owned)
        if okO and have then r.state, r.tries = "SUCCESS", 0 return "SUCCESS" end
        if r.state == "SUCCESS" then r.state = "IDLE" end
        if r.state == "PURCHASE_SENT" then
            if now - r.sentAt < timeout then return "WAIT_CONFIRMATION" end
            r.state, r.nextAt = "RETRY", now + cool
        end
        if r.state == "FAILED" then
            if now < r.failUntil then return "FAILED" end
            r.state, r.tries = "IDLE", 0
        end
        if now < r.nextAt then return "RETRY" end
        if r.tries >= maxTries then r.state, r.failUntil = "FAILED", now + 60 return "FAILED" end
        r.tries = r.tries + 1
        r.state, r.sentAt = "PURCHASE_SENT", now
        local okS, err = pcall(send)
        if not okS then r.lastErr = tostring(err) r.state, r.nextAt = "RETRY", now + cool end
        return r.state
    end
    P.Summary = function()
        local t = {}
        for id, r in pairs(P.pending) do if r.state ~= "IDLE" and r.state ~= "SUCCESS" then t[#t + 1] = id .. "=" .. r.state end end
        return #t > 0 and table.concat(t, " ") or "none"
    end

    -- Progression planner (read-only: recommends the next missing step; FH still decides what runs) ------------------
    local PL = { Tasks = {}, Order = {} }
    FX.Planner = PL
    local function seaNow()
        local pid = game.PlaceId
        if pid == 2753915549 or pid == 85211729168715 then return 1 end
        if pid == 4442272183 or pid == 79091703265657 then return 2 end
        if pid == 7449423635 or pid == 100117331123089 then return 3 end
        return nil
    end
    local function level()
        local ok, v = pcall(function() return lp.Data.Level.Value end)
        return ok and type(v) == "number" and v or nil
    end
    local function owns(name)
        local ok, v = pcall(function() return GetBP and GetBP(name) end)
        return ok and v ~= nil and v ~= false
    end
    local function mastery(name)
        local ok, v = pcall(function() local t = GetBP(name) return t and t:FindFirstChild("Level") and t.Level.Value end)
        return ok and v or nil
    end
    local function task_(id, def) def.Id = id PL.Tasks[id] = def PL.Order[#PL.Order + 1] = id end
    task_("Sea2", { Needs = {}, Done = function() local s = seaNow() return s ~= nil and s >= 2 end, Block = function() local l = level() if l == nil then return "level UNKNOWN" end if l < 700 then return "level " .. l .. "/700" end end })
    task_("Sea3", { Needs = { "Sea2" }, Done = function() return seaNow() == 3 end, Block = function() local l = level() if l == nil then return "level UNKNOWN" end if l < 1500 then return "level " .. l .. "/1500" end end })
    local function beli() local ok, v = pcall(function() return lp.Data.Beli.Value end) return ok and v or nil end
    local function frags() local ok, v = pcall(function() return lp.Data.Fragments.Value end) return ok and v or nil end
    local function mat(n) local ok, v = pcall(function() return GetM(n) end) return ok and type(v) == "number" and v or 0 end
    local function cost(b, f)
        return function()
            local bb, ff = beli(), frags()
            if b and (bb == nil or bb < b) then return "Beli " .. tostring(bb) .. "/" .. b end
            if f and (ff == nil or ff < f) then return "Fragments " .. tostring(ff) .. "/" .. f end
        end
    end
    local function mast(name, need)
        return function() local m = mastery(name) if m and m < need then return name .. " mastery " .. m .. "/" .. need end end
    end
    local function first(...)
        local fs = { ... }
        return function() for i = 1, #fs do local r = fs[i]() if r then return r end end end
    end
    -- Requirements below come from the Kaitun MeleesController Refresh/MeleePrices tables (prices, mastery 400, sea, materials).
    task_("Black Leg", { Needs = {}, Done = function() return owns("Black Leg") end, Block = cost(150000) })
    task_("Electro", { Needs = { "Black Leg" }, Done = function() return owns("Electro") end, Block = first(mast("Black Leg", 400), cost(500000)) })
    task_("Fishman Karate", { Needs = { "Electro" }, Done = function() return owns("Fishman Karate") end, Block = first(mast("Electro", 400), cost(750000)) })
    task_("Dragon Claw", { Needs = {}, Done = function() return owns("Dragon Claw") end, Block = cost(nil, 1500) })
    task_("Superhuman", { Needs = { "Sea2" }, Done = function() return owns("Superhuman") end, Block = cost(3000000), Note = "other Superhuman requirements UNKNOWN (not in sources)" })
    task_("Death Step", { Needs = { "Black Leg", "Sea2" }, Done = function() return owns("Death Step") end, Block = first(mast("Black Leg", 400), cost(2500000, 5000)) })
    task_("Sharkman Karate", { Needs = { "Fishman Karate", "Sea2" }, Done = function() return owns("Sharkman Karate") end, Block = first(mast("Fishman Karate", 400), cost(2500000, 5000)) })
    task_("Electric Claw", { Needs = { "Electro", "Sea3" }, Done = function() return owns("Electric Claw") end, Block = first(mast("Electro", 400), cost(3000000, 5000)) })
    task_("Dragon Talon", { Needs = { "Dragon Claw", "Sea3" }, Done = function() return owns("Dragon Talon") end, Block = first(mast("Dragon Claw", 400), cost(3000000, 5000), function() if mat("Fire Essence") < 1 then return "Fire Essence 0/1" end end) })
    task_("Godhuman", {
        Needs = { "Superhuman", "Death Step", "Sharkman Karate", "Electric Claw", "Dragon Talon" },
        Done = function() return owns("Godhuman") end,
        Block = first(
            mast("Superhuman", 400), mast("Death Step", 400), mast("Sharkman Karate", 400), mast("Electric Claw", 400), mast("Dragon Talon", 400),
            cost(5000000, 5000),
            function()
                local need = { { "Fish Tail", 20 }, { "Dragon Scale", 10 }, { "Magma Ore", 20 }, { "Mystic Droplet", 10 } }
                for _, n in ipairs(need) do if mat(n[1]) < n[2] then return n[1] .. " " .. mat(n[1]) .. "/" .. n[2] end end
            end
        )
    })
    PL.Next = function(goal)
        local seen = {}
        local function walk(id)
            if seen[id] then return nil end
            seen[id] = true
            local t = PL.Tasks[id]
            if not t then return nil, "unknown task " .. tostring(id) end
            local okD, done = pcall(t.Done)
            if okD and done then return nil end
            for _, dep in ipairs(t.Needs) do
                local step, why = walk(dep)
                if step or why then return step, why end
            end
            local blk = t.Block and select(2, pcall(t.Block)) or nil
            return id, blk
        end
        return walk(goal or "Godhuman")
    end

    -- Server recovery (observation + bounded retry; never auto-enables farms) -------------------------------------
    local R = { state = "CONNECTED", since = os.clock(), tries = 0, windowStart = os.clock(), lastErr = nil, ping = nil }
    FX.Recovery = R
    local function rset(s) if R.state ~= s then R.state, R.since = s, os.clock() flog("recovery", s) end end
    pcall(function()
        Sess.Track(game:GetService("GuiService").ErrorMessageChanged:Connect(function()
            local ok, msg = pcall(function() return game:GetService("GuiService"):GetErrorMessage() end)
