                        rset("TELEPORTING")
                        local ok = pcall(function() local h = _G.MaruHop or MaruHop if h then h() else game:GetService("TeleportService"):Teleport(game.PlaceId) end end)
                        if not ok then rset("ERROR_DETECTED") end
                    end
                end
            elseif R.state == "FAILED" and os.clock() - R.since > 300 then
                rset("CONNECTED")
            end
        end
    end)

    -- Health monitor (read-only) --------------------------------------------------------------------------------------
    local H = {}
    FX.Health = H
    H.Snapshot = function()
        local L = {}
        local fh = FX.FH
        local ow = fh and fh.Owner
