    local APPROACH = CFrame.new(-16269.4082, 23.9799957, 1371.66235, -0.999388933, 0, -0.0349550731, 0, 1, 0, 0.0349550731, 0, -0.999388933)
    local SEA3 = { [7449423635] = true, [100117331123089] = true }
    local S = { state = "IDLE", sent = false, tries = 0, seq = 0, cool = 0, failUntil = 0, inner = false, char = nil, last = nil }
    FX.SubRoute = S
    local function setState(st)
        if S.state ~= st then
            S.state = st
            if FX.Trace then FX.Trace("SUB", "state", st) end
        end
    end
    S.Reset = function(why)
        S.seq = S.seq + 1
        S.sent, S.tries, S.cool, S.inner = false, 0, 0, false
        setState("IDLE")
    end
    local function rootOf()
        local c = game:GetService("Players").LocalPlayer.Character
        return c and c:FindFirstChild("HumanoidRootPart"), c
    end
    local function inRegion(pos) return (pos - REGION).Magnitude <= 3000 end
    S.Handle = function(target)
        if S.inner or FX.Enable.SubRoute == false or not SEA3[game.PlaceId] then return false end
        local root, char = rootOf()
        if not root then return false end
        if S.char ~= char then S.Reset("respawn") S.char = char end
        if not inRegion(target.Position) then return false end
        if inRegion(root.Position) then
            if S.state ~= "IDLE" then setState("ARRIVED") end
            return false
        end
        local now = os.clock()
        if S.failUntil > now then return false end
        if S.sent then return true end
        if now < S.cool then return true end
        if (root.Position - APPROACH.Position).Magnitude > 8 then
            setState("MOVE_TO_APPROACH")
            S.inner = true
            pcall(_tp, APPROACH)
            S.inner = false
            return true
        end
        S.sent = true
        S.tries = S.tries + 1
        S.seq = S.seq + 1
        local seq = S.seq
        setState("REQUEST_SUBMERGED_TRAVEL")
        pcall(function()
            local t = getgenv().__MaruActiveTargetTween
            if t then t:Cancel() end
        end)
        task.spawn(function()
            local function stale() return S.seq ~= seq or S.char ~= game:GetService("Players").LocalPlayer.Character end
            local okR, errR = pcall(function()
                local rf = RS.Modules.Net:FindFirstChild("RF/SubmarineWorkerSpeak")
                if not rf then error("RF/SubmarineWorkerSpeak missing", 0) end
                return rf:InvokeServer("TravelToSubmergedIsland")
            end)
            if stale() then return end
            if not okR then
                warn("[SubRoute] travel remote failed: " .. tostring(errR))
                S.sent = false
                S.cool = os.clock() + 8
                if S.tries >= 3 then S.failUntil, S.tries = os.clock() + 60, 0 setState("FAILED") end
                return
            end
            setState("WAIT_SERVER_TRANSITION")
            local t0, arrived = os.clock(), false
            while os.clock() - t0 < 15 and not stale() do
                local r = rootOf()
                if r and inRegion(r.Position) then arrived = true break end
                task.wait(0.25)
            end
            if stale() then return end
            if arrived then
                setState("SET_LAST_SPAWN_POINT")
                local okS, errS = pcall(function()
                    return RS.Remotes.CommF_:InvokeServer("SetLastSpawnPoint", "SubmergedIsland")
                end)
                if not okS then warn("[SubRoute] SetLastSpawnPoint failed: " .. tostring(errS)) end
                S.sent, S.tries = false, 0
                setState("ARRIVED")
            else
                S.sent = false
                S.cool = os.clock() + 8
                if S.tries >= 3 then S.failUntil, S.tries = os.clock() + 60, 0 setState("FAILED") else setState("RETRY_WAIT") end
            end
        end)
        return true
    end
end)()
do
    local function InSubmergedIsland()
        local char = plr.Character
        if not char then return false end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if not hrp then return false end
        local islandXZ = Vector3.new(11520.8017578125, 0, 9829.513671875)
        local playerXZ = Vector3.new(hrp.Position.X, 0, hrp.Position.Z)
        return (playerXZ - islandXZ).Magnitude < 2000
    end
    local function On(key)
        local f = _G.FARMX
        return not (f and f.Enable and f.Enable[key] == false)
    end
    local function Cfg(key, default)
        local f = _G.FARMX
        local v = f and f.Cfg and f.Cfg[key]
        if v == nil then return default end
        return v
    end
    local tFin = -1e9
    local function H(fn, ...)
        if not On("LevelIsland") then return end
        if fn == "Finish" then
            local nowF = os.clock()
            if nowF - tFin < 1.5 then return end
            tFin = nowF
        end
        local FXh = _G.FARMX
        local f = FXh and FXh.FH and FXh.FH[fn]
        if f then
            local ok, err = pcall(f, ...)
            if not ok and FXh.Log then FXh.Log("level-island", err) end
        end
    end
    local function IsPlayerModel(m)
