    end
    local LV = { lastLevel = nil, lastState = nil, lastNeed = nil, mode = nil, tDetect = 0, tFarm = 0, apDeadline = nil, tpAim = 0, tStart = -1e9, spawn = nil }
    -- [QM-FARM] P113 AltSpots | diem spawn phu cho tour (nguon: Tab__2.txt, TestStatusMaru_1.txt, PosMsList cua Material farm); bi loai neu EnemySpawns that co diem khac | gan tai LV
    LV.AltSpots = {
        ["Dragon Crew Warrior"] = { CFrame.new(6709.76367, 52.3442993, -1139.02966), CFrame.new(7021.50439453125, 55.76270294189453, -730.1290893554688) },
        ["Dragon Crew Archer"]  = { CFrame.new(6668.76172, 481.376923, 329.12207), CFrame.new(6625, 378, 244) },
        ["Pirate Millionaire"]  = { CFrame.new(-245.9963836669922, 47.30615234375, 5584.1005859375) },
        ["Pistol Billionaire"]  = { CFrame.new(-187.3301544189453, 86.23987579345703, 6013.513671875) },
        ["Hydra Enforcer"]      = { CFrame.new(4584.69287109375, 1002.6435546875, 705.7958984375), CFrame.new(4547.11523, 1003.10217, 334.194824) },
        ["Venomous Assailant"]  = { CFrame.new(4638.78564453125, 1078.94091796875, 881.8002319335938), CFrame.new(4674.92676, 1134.82654, 996.308838) },
        ["Skull Slayer"]        = { CFrame.new(-16887.7305, 113.074638, 1629.97778) },
        ["Snowman"]             = { CFrame.new(1201.6412353515625, 144.57958984375, -1550), CFrame.new(1200, 144, -1550) },
