    -- [QM-FARM] P113 LevelForceMove | _tp toi cf; neu 3 s khong tien gan them 3 stud (con xa > LevelChaseNear) thi doi bay velocity <-> tween block | gan tai LV
    LV.ForceMove = function(cf, tag)
        local fx = _G.FARMX
        if not (fx and fx.Enable and fx.Enable.LevelForceMove) or typeof(cf) ~= "CFrame" then
            _tp(cf)
            return
        end
        local ch = plr.Character
        local r = ch and ch:FindFirstChild("HumanoidRootPart")
        if r then
            local now = os.clock()
            local dist = (r.Position - cf.Position).Magnitude
            local P = LV.chase
            if not P or P.tag ~= tag then
                P = { tag = tag, best = dist, t = now, n = 0 }
                LV.chase = P
            end
            if dist < P.best - 3 or dist <= (fx.Cfg.LevelChaseNear or 60) then
                P.best, P.t = math.min(P.best, dist), now
            elseif now - P.t >= (fx.Cfg.LevelChaseStall or 3) then
                P.n, P.t, P.best = P.n + 1, now, dist
                local mode
                if fx.FlyOn or not (fx.NoFlyUntil and now < fx.NoFlyUntil) then
                    fx.NoFlyUntil = now + 20
                    if fx.FlyOn and fx.FlyStop then pcall(fx.FlyStop) end
                    mode = "tween"
                else
                    fx.NoFlyUntil = nil
                    mode = "velocity"
                end
                if fx.Log then fx.Log("level-chase", string.format("%s ket d=%.0f lan %d -> %s", tostring(tag), dist, P.n, mode)) end
            end
        end
        _tp(cf)
    end
    local function LevelCleanSpawnName(rawName)
        local clean = tostring(rawName or ""):gsub("%[Lv%.%s*%d+%]%s*", "")
        clean = clean:gsub("^%s+", ""):gsub("%s+$", "")
        return clean
    end
    local function LevelSpawnKey(cf)
        local p = cf.Position
        return math.floor(p.X / 8 + 0.5) .. ":" .. math.floor(p.Y / 8 + 0.5) .. ":" .. math.floor(p.Z / 8 + 0.5)
    end
    local function LevelSpawnCandidates(enemyName, origin, fallbackCF)
        local out = {}
        local fx = _G.FARMX
        local searchRadius = tonumber(fx and fx.Cfg and (fx.Cfg.LevelSpawnSearchRadius or fx.Cfg.LevelStayRadius)) or 5000
        local maxPoints = math.clamp(tonumber(fx and fx.Cfg and fx.Cfg.LevelSpawnMaxPoints) or 6, 1, 6)
        local wanted = string.lower(tostring(enemyName or ""))
        local mlrC = _G.MaruLv and _G.MaruLv.ByMob(enemyName)
        local alias = mlrC and mlrC[5] ~= mlrC[4] and string.lower(mlrC[5]) or nil
        local canonicalEntry = nil
        local function addPoint(cf, source, forceFallback)
            if typeof(cf) ~= "CFrame" then return nil end
            local distance = (cf.Position - origin).Magnitude
            if not forceFallback and distance > searchRadius then return nil end
            for _, existing in ipairs(out) do
                if (existing.cf.Position - cf.Position).Magnitude < 30 then
                    if source == "PosM" then canonicalEntry = existing end
                    return existing
                end
            end
            local entry = { cf = cf, source = source or "spawn", distance = distance, key = LevelSpawnKey(cf) }
            out[#out + 1] = entry
            if source == "PosM" then canonicalEntry = entry end
            return entry
        end
        -- PosM is canonical for this quest mob; keep it as a fallback even when far away.
        if typeof(fallbackCF) == "CFrame" then addPoint(fallbackCF, "PosM", true) end
        do
            local alts = LV.AltSpots and LV.AltSpots[enemyName]
            if alts then for _, c in ipairs(alts) do addPoint(c, "Alt", true) end end
        end
        local worldOrigin = workspace:FindFirstChild("_WorldOrigin")
        local spawnFolder = worldOrigin and worldOrigin:FindFirstChild("EnemySpawns")
        if spawnFolder and wanted ~= "" then
            local parts = spawnFolder:GetChildren()
            -- Pass 1: exact (cleaned) name only. "Pirate" must not pull "Galley Pirate" spawns.
            local found = 0
            for _, spawnPart in ipairs(parts) do
                if spawnPart:IsA("BasePart") then
                    local clean = string.lower(LevelCleanSpawnName(spawnPart.Name))
                    if clean == wanted or (alias and clean == alias) then
                        addPoint(spawnPart.CFrame, spawnPart.Name, false)
                        found = found + 1
                    end
                end
            end
            -- Pass 2: only when the game names spawns differently from the quest mob.
            if found == 0 then
                for _, spawnPart in ipairs(parts) do
                    if spawnPart:IsA("BasePart") then
                        local clean = string.lower(LevelCleanSpawnName(spawnPart.Name))
                        if string.find(clean, wanted, 1, true) or (alias and string.find(clean, alias, 1, true)) then
                            addPoint(spawnPart.CFrame, spawnPart.Name, false)
                        end
                    end
                end
            end
        end
        -- [QM-FARM] P113 LiveSpawnFirst | co diem EnemySpawns that => bo PosM/Alt khong nam trong 150 stud cua diem that (bang du lieu co the cu) | gan tai LevelSpawnCandidates
        do
            local realN = 0
            for _, e in ipairs(out) do if e.source ~= "PosM" and e.source ~= "Alt" then realN = realN + 1 end end
            if realN > 0 then
                local kept = {}
                for _, e in ipairs(out) do
                    local keep = true
                    if e.source == "PosM" or e.source == "Alt" then
                        keep = false
                        for _, o in ipairs(out) do
                            if o.source ~= "PosM" and o.source ~= "Alt" and (o.cf.Position - e.cf.Position).Magnitude <= 150 then keep = true break end
                        end
                    end
                    if keep then kept[#kept + 1] = e end
                end
                if canonicalEntry then
                    local still = false
                    for _, e in ipairs(kept) do if e == canonicalEntry then still = true break end end
                    if not still then canonicalEntry = nil end
                end
                out = kept
            end
        end
        table.sort(out, function(a, b) return a.distance < b.distance end)
        if #out > maxPoints then
            local limited = {}
            for i = 1, maxPoints do limited[#limited + 1] = out[i] end
            -- Keep canonical PosM in the bounded set without duplicating it if already selected.
            if canonicalEntry then
                local hasCanonical = false
                for _, entry in ipairs(limited) do
                    if entry == canonicalEntry then hasCanonical = true break end
                end
                if not hasCanonical then limited[#limited] = canonicalEntry end
            end
            table.sort(limited, function(a, b) return a.distance < b.distance end)
            out = limited
        end
        return out
    end
    local function LevelGetSpawnState(enemyName, level, origin, fallbackCF)
        local now = os.clock()
        local state = LV.spawn
        if not state or state.enemy ~= enemyName or state.level ~= level then
            local list = LevelSpawnCandidates(enemyName, origin, fallbackCF)
            state = { enemy = enemyName, level = level, list = list, idx = 1, scanAt = now, waitSince = nil, lastTp = 0, rounds = 0,
                      visited = {}, curKey = list[1] and list[1].key or nil }
            LV.spawn = state
        elseif now - (state.scanAt or 0) >= 15 then
            -- Rescan, then re-find the point we are working on by its stable key (order changes with player position).
            local fresh = LevelSpawnCandidates(enemyName, origin, fallbackCF)
            state.scanAt = now
            state.list = fresh
            local newIdx = 1
            for i, e in ipairs(fresh) do
                if e.key == state.curKey then newIdx = i break end
            end
            state.idx = newIdx
            state.curKey = fresh[newIdx] and fresh[newIdx].key or nil
            local present = {}
            for _, e in ipairs(fresh) do present[e.key] = true end
            for k in pairs(state.visited) do
                if not present[k] then state.visited[k] = nil end
            end
        end
        return state
    end
    -- Nearest-neighbour tour over spawn points: never revisit a point before the whole round is done.
    local function LevelAdvanceSpawn(state)
        local list = state.list
        if not list or #list <= 1 then return false end
        local cur = list[state.idx]
        if cur then state.visited[cur.key] = true end
        local function nearestUnvisited()
            local best, bestD
            for i, e in ipairs(list) do
                if i ~= state.idx and not state.visited[e.key] then
                    local d = cur and (e.cf.Position - cur.cf.Position).Magnitude or e.distance
                    if not bestD or d < bestD then best, bestD = i, d end
                end
            end
            return best
        end
        local best = nearestUnvisited()
        if not best then
            state.visited = {}
            state.rounds = (state.rounds or 0) + 1
            if cur then state.visited[cur.key] = true end
            best = nearestUnvisited()
        end
        if not best then return false end
        state.idx = best
        state.curKey = list[best].key
        return true
    end
    local GuiC = { t = -1e9, enemy = nil, labels = nil, kills = 0, lows = nil, lastSt = nil }
    local function QuestMobLows()
        if GuiC.lows then return GuiC.lows end
        local lows = {}
        pcall(function()
            for _, qset in pairs(Quests) do
                if type(qset) == "table" then
                    for _, qd in pairs(qset) do
                        if type(qd) == "table" and type(qd.Task) == "table" then
                            for nm in pairs(qd.Task) do
                                if type(nm) == "string" then lows[string.lower(nm)] = true end
                            end
                        end
                    end
                end
            end
        end)
        GuiC.lows = lows
        return lows
    end
    local function QuestGuiRead(enemyName, questData)
        local fxg = _G.FARMX
        local okV, vis = pcall(function() return plr.PlayerGui.Main.Quest.Visible end)
        if not okV then
            if fxg and fxg.Log then fxg.Log("quest-gui", "khong doc duoc plr.PlayerGui.Main.Quest") end
            return "none", nil, nil
        end
        if not vis then
            GuiC.labels = nil
            GuiC.lastSt = "none"
            return "none", nil, nil
        end
        if not On("QuestGuiScan") then return "active", nil, nil end
        local now = os.clock()
        if not GuiC.labels or GuiC.enemy ~= enemyName or now - GuiC.t >= Cfg("QuestGuiTTL", 0.5) then
            GuiC.t = now
            GuiC.enemy = enemyName
            local labels = {}
            local okS, errS = pcall(function()
                for _, d in ipairs(plr.PlayerGui.Main.Quest:GetDescendants()) do
                    if d:IsA("TextLabel") or d:IsA("TextButton") then labels[#labels + 1] = d end
                end
            end)
            if not okS and fxg and fxg.Log then fxg.Log("quest-gui", errS) end
            GuiC.labels = labels
        end
        local texts = {}
        pcall(function()
            for _, lb in ipairs(GuiC.labels) do
                local tx = lb.Text
                if type(tx) == "string" and tx ~= "" then texts[#texts + 1] = tx end
            end
        end)
        local cur, need
        for _, tx in ipairs(texts) do
            local a, b = string.match(tx, "^%s*(%d+)%s*/%s*(%d+)%s*$")
            if a then cur, need = tonumber(a), tonumber(b) break end
        end
        if not cur then
            for _, tx in ipairs(texts) do
                local a, b = string.match(tx, "%((%d+)%s*/%s*(%d+)%)")
                if a then cur, need = tonumber(a), tonumber(b) break end
            end
        end
        if not cur then
            for _, tx in ipairs(texts) do
                local a, b = string.match(tx, "(%d+)%s*/%s*(%d+)")
                if a then cur, need = tonumber(a), tonumber(b) break end
            end
        end
        if not need then
            for _, tx in ipairs(texts) do
                local n = string.match(tx, "[Dd]efeat%s+(%d+)%s")
                if n then need = tonumber(n) break end
            end
        end
        if not need and questData then
            pcall(function() need = Quests[questData[3]][questData[2]].Task[enemyName] end)
            if type(need) ~= "number" then need = nil end
        end
        local lowEnemy = string.lower(enemyName)
        local hasMob, otherMob = false, false
        for _, tx in ipairs(texts) do
            if string.find(string.lower(tx), lowEnemy, 1, true) then hasMob = true break end
        end
        if not hasMob then
            local lows = QuestMobLows()
            for _, tx in ipairs(texts) do
                local lt = string.lower(tx)
                for nm in pairs(lows) do
                    if nm ~= lowEnemy and string.find(lt, nm, 1, true) then otherMob = true break end
                end
                if otherMob then break end
            end
        end
        local state = "active"
        if otherMob then
            state = "wrong"
        elseif cur and need and need > 0 and cur >= need then
            state = "done"
        elseif not cur and need and need > 0 and GuiC.kills >= need then
            state = "done"
        end
        if state == "done" or state == "wrong" then
            if GuiC.cand == state then
                GuiC.candN = (GuiC.candN or 0) + 1
            else
                GuiC.cand, GuiC.candN = state, 1
            end
            if GuiC.candN < (Cfg("QuestStateConfirm", 2)) then state = "active" end
        else
            GuiC.cand, GuiC.candN = nil, 0
        end
        if GuiC.lastSt ~= state and fxg and fxg.Cfg and fxg.Cfg.Debug and fxg.Log then
            local parts = {}
            for _, lb in ipairs(GuiC.labels) do
                local okD, line = pcall(function() return lb:GetFullName() .. " [" .. lb.ClassName .. "] " .. string.sub(lb.Text, 1, 120) end)
                if okD then parts[#parts + 1] = line end
            end
            fxg.Log("quest-gui", "state=" .. state .. " cur=" .. tostring(cur) .. " need=" .. tostring(need) .. "\n" .. table.concat(parts, "\n"))
        end
        GuiC.lastSt = state
        return state, cur, need
    end
    if _G.FARMX then
        _G.FARMX.QuestLog = _G.FARMX.QuestLog or {}
        _G.FARMX.QLogAdd = function(reason, vis, hasQ, cur, need, since)
