            local cr = Instance.new("UICorner") cr.CornerRadius = UDim.new(0.5, 0) cr.Parent = card
            local st = Instance.new("UIStroke") st.Color = Color3.new(1, 1, 1) st.Transparency = 0.85 st.Thickness = 1 st.Parent = card
            local body = Instance.new("CanvasGroup")
            body.AnchorPoint = Vector2.new(0.5, 0.5)
            body.Position = UDim2.fromScale(0.5, 0.5)
            body.Size = UDim2.fromOffset(320, 0)
            body.AutomaticSize = Enum.AutomaticSize.Y
            body.BackgroundTransparency = 1
            body.GroupTransparency = 1
            body.Parent = card
            local pad = Instance.new("UIPadding")
            pad.PaddingTop, pad.PaddingBottom = UDim.new(0, 18), UDim.new(0, 16)
            pad.PaddingLeft, pad.PaddingRight = UDim.new(0, 18), UDim.new(0, 18)
            pad.Parent = body
            local lay = Instance.new("UIListLayout")
            lay.Padding = UDim.new(0, 10)
            lay.SortOrder = Enum.SortOrder.LayoutOrder
            lay.Parent = body
            local function label(txt, size, weight, color, order)
                local l = Instance.new("TextLabel")
                l.BackgroundTransparency = 1
                l.Size = UDim2.new(1, 0, 0, 0)
                l.AutomaticSize = Enum.AutomaticSize.Y
                l.TextWrapped = true
                l.RichText = true
                l.TextXAlignment = Enum.TextXAlignment.Left
                l.FontFace = Font.new("rbxasset://fonts/families/GothamSSm.json", weight)
                l.TextSize = size
                l.TextColor3 = color
                l.Text = txt
                l.LayoutOrder = order
                l.Parent = body
                return l
            end
            label("Lỗi Farm", 20, Enum.FontWeight.SemiBold, Color3.new(1, 1, 1), 1)
            label("Farm bị lỗi" .. (reason and reason ~= "" and (": " .. tostring(reason)) or "") .. ". Bạn có muốn chạy lại farm không?", 14, Enum.FontWeight.Regular, Color3.fromRGB(190, 190, 198), 2)
            local row = Instance.new("Frame")
            row.BackgroundTransparency = 1
            row.Size = UDim2.new(1, 0, 0, 40)
            row.LayoutOrder = 3
            row.Parent = body
            local rl = Instance.new("UIListLayout")
            rl.FillDirection = Enum.FillDirection.Horizontal
            rl.HorizontalAlignment = Enum.HorizontalAlignment.Right
            rl.VerticalAlignment = Enum.VerticalAlignment.Center
            rl.Padding = UDim.new(0, 10)
            rl.SortOrder = Enum.SortOrder.LayoutOrder
            rl.Parent = row
            local closed = false
            local function close(after)
                if closed then return end
                closed = true
                pcall(function()
                    TS:Create(body, TweenInfo.new(0.12, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { GroupTransparency = 1 }):Play()
                    TS:Create(card, TweenInfo.new(0.26, Enum.EasingStyle.Quint, Enum.EasingDirection.In), { Size = UDim2.fromOffset(46, 46) }):Play()
                    TS:Create(cr, TweenInfo.new(0.26, Enum.EasingStyle.Quint, Enum.EasingDirection.In), { CornerRadius = UDim.new(0.5, 0) }):Play()
                end)
                task.delay(0.28, function()
                    pcall(function() gui:Destroy() end)
                    _G.__MaruFarmErrOpen = false
                    if after then task.spawn(after) end
                end)
            end
            local function btn(txt, primary, order, cb)
                local b = Instance.new("TextButton")
                b.AutoButtonColor = false
                b.Size = UDim2.fromOffset(86, 38)
                b.LayoutOrder = order
                b.Text = txt
                b.FontFace = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.SemiBold)
                b.TextSize = 15
                b.TextColor3 = primary and Color3.fromRGB(16, 16, 18) or Color3.new(1, 1, 1)
                b.BackgroundColor3 = primary and Color3.fromRGB(245, 245, 247) or Color3.fromRGB(58, 58, 64)
                b.Parent = row
                local c = Instance.new("UICorner") c.CornerRadius = UDim.new(0, 12) c.Parent = b
                b.Activated:Connect(cb)
            end
            btn("No", false, 1, function() close() end)
            btn("Yes", true, 2, function() close(onYes) end)
            -- bung tròn ra ở giữa (cùng kiểu Back 0.42s của search/dropdown)
            task.spawn(function()
                local n = 0
                while body.Parent and body.AbsoluteSize.Y < 8 and n < 20 do
                    game:GetService("RunService").RenderStepped:Wait()
                    n = n + 1
                end
                if not body.Parent or closed then return end
                local H = math.max(body.AbsoluteSize.Y, 120)
                body.AutomaticSize = Enum.AutomaticSize.None
                body.Size = UDim2.fromOffset(320, H)
                TS:Create(card, TweenInfo.new(0.42, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Size = UDim2.fromOffset(320, H) }):Play()
                TS:Create(cr, TweenInfo.new(0.42, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { CornerRadius = UDim.new(0, 20) }):Play()
                task.delay(0.12, function()
                    if body.Parent then TS:Create(body, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { GroupTransparency = 0 }):Play() end
                end)
            end)
            task.delay(60, function() close() end)
        end)
        if not okP then
            _G.__MaruFarmErrOpen = false
            warn("[Maru Level] panel loi: " .. tostring(errP))
        end
    end
    local function LvRestartFarm()
        LV.fx, LV.qlock, LV.apDeadline, LV.lastState, LV.errN = nil, nil, nil, nil, 0
        teleporting = false
        alreadyTeleported = false
        pcall(function() replicated.Remotes.CommF_:InvokeServer("AbandonQuest") end)
        _G.Level = false
        task.wait(0.5)
        _G.Level = true
    end
    local function LvErrPanel(reason)
        local now = os.clock()
        if now - (LV.tPanel or -1e9) < 60 then return end
        LV.tPanel = now
        _G.MaruFarmErrPanel(reason, LvRestartFarm)
    end
    task.spawn(function()
        while task.wait(Sec) do
            if _G.Level then
                local okLv, errLv = pcall(function()
                    local char = plr.Character or plr.CharacterAdded:Wait()
                    local Root = char:WaitForChild("HumanoidRootPart")
                    if not Root then return end
                    local level = plr.Data.Level.Value
                    if LV.lastLevel and level > LV.lastLevel then
                    end
                    LV.lastLevel = level
                    local inSub = InSubmergedIsland()
                    if level >= 2600 and not inSub and not teleporting and not alreadyTeleported then
                        teleporting = true
                        local npcPos = CFrame.new(-16269.7041, 25.2288494, 1373.65955)
                        local attempts = 0
                        repeat
                            task.wait(Sec)
                            _tp(npcPos)
                            attempts = attempts + 1
                            LvDetect("Submerged Island", (Root.Position - npcPos.Position).Magnitude, "Submarine worker")
                        until not _G.Level or (Root.Position - npcPos.Position).Magnitude <= 8 or attempts > 20
                        if not _G.Level then
                            teleporting = false
                            return
                        end
                        task.wait(1)
                        pcall(function()
                            local args = { "TravelToSubmergedIsland" }
                            game:GetService("ReplicatedStorage").Modules.Net:FindFirstChild("RF/SubmarineWorkerSpeak"):InvokeServer(unpack(args))
                        end)
                        local timeout = tick()
                        repeat
                            task.wait(0.5)
                            local currentInSub = InSubmergedIsland()
                            local farFromNPC = (Root.Position - npcPos.Position).Magnitude > 50
                            if currentInSub or farFromNPC then break end
                        until not _G.Level or tick() - timeout > 15
                        task.wait(2)
                        alreadyTeleported = true
                        teleporting = false
                    elseif inSub or level < 2600 then
                        alreadyTeleported = true
                        teleporting = false
                        local questData = QuestNeta()
                        local fxq5 = _G.FARMX
                        if fxq5 and fxq5.Enable.QuestLock then
                            if GetQuestData() then
                                if LV.qlock then
                                    questData = LV.qlock
                                end
                            else
                                LV.qlock = nil
                            end
                        end
                        if not questData or not questData[1] then
                            task.wait(1)
                            return
                        end
                        local enemyName = questData[1]
                        local st, cur, need = QuestGuiRead(enemyName, questData)
                        local hasQ = GetQuestData()
                        do
                            -- Chỉ check có đang tween/di chuyển không (GUI không đọc được tiến độ/số): đứng yên không tween = kẹt.
                            local mlr = _G.MaruLv.ByMob(enemyName)
                            local nowW = os.clock()
                            local W = LV.fx
                            if not W or W.enemy ~= enemyName or W.level ~= level then
                                W = { enemy = enemyName, level = level, t = nowW, pos = Root.Position, fixN = 0, tFix = -1e9 }
                                LV.fx = W
                            end
                            -- A live Tween object is not proof of movement; only measured root progress resets this watchdog.
                            -- Waiting inside a valid spawn radius is intentional and must not be mistaken for a stalled route.
                            local activeSpawn = LV.spawn and LV.spawn.enemy == enemyName and LV.spawn.level == level
                                and LV.spawn.list and LV.spawn.list[LV.spawn.idx]
                            local intentionalSpawnWait = false
                            if activeSpawn and LV.spawn.waitSince then
                                local spawnWaitPos = activeSpawn.cf.Position + Vector3.new(0, 25, 0)
                                local spawnWaitRadius = tonumber(_G.FARMX and _G.FARMX.Cfg and _G.FARMX.Cfg.LevelSpawnArriveRadius) or 35
                                intentionalSpawnWait = (Root.Position - spawnWaitPos).Magnitude <= spawnWaitRadius + 5
                            end
                            if intentionalSpawnWait then
                                W.t, W.pos, W.fixN = nowW, Root.Position, 0
                            elseif (Root.Position - W.pos).Magnitude > 3 then
                                W.t, W.pos, W.fixN = nowW, Root.Position, 0
                            end
                            local stuckSec = (_G.FARMX and _G.FARMX.Cfg and _G.FARMX.Cfg.LevelStuckSec) or 10
                            if not intentionalSpawnWait and nowW - W.t >= stuckSec and nowW - W.tFix >= 3 then
                                W.tFix = nowW
                                W.fixN = W.fixN + 1
                                local pq = questData[6] or (mlr and mlr[8])
                                local spawnState = LV.spawn
                                local currentSpawn = spawnState and spawnState.enemy == enemyName and spawnState.list and spawnState.list[spawnState.idx]
                                local pm = (currentSpawn and currentSpawn.cf) or questData[7] or (mlr and mlr[9]) or (GetMobFarmPosition and GetMobFarmPosition(enemyName))
                                if W.fixN >= 3 then LvErrPanel("đứng yên, không tween") end
                                do
                                    local fxd = _G.FARMX
                                    local atw = getgenv().__MaruActiveTargetTween
                                    local sp = LV.spawn and LV.spawn.list and LV.spawn.list[LV.spawn.idx]
                                    warn(string.format("[Maru Level] dung yen %.0fs lv=%d mob=%s hasQ=%s fix#%d | shouldTween=%s OnFarm=%s tween=%s FlyOn=%s bodyActive=%s safe=%s spawn=%s/%s distSpawn=%s", nowW - W.t, level, tostring(enemyName), tostring(hasQ), W.fixN, tostring(shouldTween), tostring(getgenv().OnFarm), tostring(atw and atw.PlaybackState), tostring(fxd and fxd.FlyOn), tostring(fxd and fxd.MobDodge and fxd.MobDodge.bodyActive), tostring(fxd and fxd.SafeMode and fxd.SafeMode.state), tostring(LV.spawn and LV.spawn.idx), tostring(LV.spawn and LV.spawn.list and #LV.spawn.list), tostring(sp and math.floor((Root.Position - sp.cf.Position).Magnitude))))
                                end
                                if not hasQ and pq and W.fixN % 2 == 1 then
                                    LvDetect("Quest NPC (fix)", (Root.Position - pq.Position).Magnitude, "Lv " .. tostring(level) .. "  ·  " .. tostring(enemyName))
                                    _tp(pq)
                                    task.wait(0.8)
                                    pcall(function() replicated.Remotes.CommF_:InvokeServer("StartQuest", questData[3], questData[2]) end)
                                    return
                                elseif pm then
                                    LvDetect(enemyName .. " (fix)", (Root.Position - pm.Position).Magnitude, "Lv " .. tostring(level) .. "  ·  " .. tostring(enemyName))
                                    _tp(pm * CFrame.new(0, 25, 0))
                                    task.wait(0.5)
                                    return
                                end
                            end
                        end
                        if LV.lastState == "active" and (st == "done" or st == "none") then
                            H("Finish", "Level", { Title = "Quest complete", Content = tostring(enemyName) .. "  x" .. tostring(LV.lastNeed or "") })
                        end
                        LV.lastState = st
                        if st == "active" then
                            LV.apDeadline = nil
                            if need and need > 0 then LV.lastNeed = need end
                        end
                        if st ~= "active" and not hasQ then
                            local aimCF = questData[6] or (GetMobFarmPosition and GetMobFarmPosition(enemyName)) or nil
                            local nowA = os.clock()
                            local distA = aimCF and (Root.Position - aimCF.Position).Magnitude or 0
                            if not LV.apDeadline then
                                local spd = (type(Settings) == "table" and Settings["Tween Speed"]) or 180
                                LV.apDeadline = nowA + distA / spd + Cfg("QuestApproachPad", 15)
                            end
                            if aimCF and distA > Cfg("QuestArriveRadius", 12) and nowA < LV.apDeadline then
                                if nowA - LV.tpAim >= 0.3 then
                                    LV.tpAim = nowA
                                    _tp(aimCF)
                                end
                                LvDetect("Quest NPC", distA, "Lv " .. tostring(level) .. "  ·  " .. tostring(enemyName))
                                return
                            end
                            task.wait(0.6)
                            local fxm = _G.FARMX
                            local lockOn = fxm and fxm.Enable.QuestLock
                            local okVis, visQ = pcall(function() return plr.PlayerGui.Main.Quest.Visible end)
                            local sinceStart = os.clock() - LV.tStart
                            if lockOn and okVis and visQ == true and sinceStart < Cfg("QuestMinHold", 20) and not GetQuestData() then
                                if fxm.QLogAdd then fxm.QLogAdd("lock", visQ, false, cur, need, sinceStart) end
                            elseif not GetQuestData() and os.clock() - LV.tStart >= Cfg("StartQuestGap", 1.5) then
                                if lockOn and fxm.QLogAdd then fxm.QLogAdd("accept", okVis and visQ or nil, false, cur, need, sinceStart) end
                                LV.tStart = os.clock()
                                if lockOn then LV.qlock = questData end
                                pcall(function()
                                    replicated.Remotes.CommF_:InvokeServer("StartQuest", questData[3], questData[2])
                                end)
                                GuiC.kills = 0
                            end
                            if lockOn then
                                local tw0 = os.clock()
                                repeat
                                    task.wait(0.2)
                                    local okV2, vis2 = pcall(function() return plr.PlayerGui.Main.Quest.Visible end)
                                until GetQuestData() or (okV2 and vis2 == true) or os.clock() - tw0 >= Cfg("QuestAcceptWait", 3)
                            else
                                task.wait(0.6)
                            end
                            LV.apDeadline = nil
                            st, cur, need = QuestGuiRead(enemyName, questData)
                            LV.lastState = st
                        end
                        local target = nil
                        local best = math.huge
                        local mlrT = _G.MaruLv.ByMob(enemyName)
                        for _, v in pairs(workspace.Enemies:GetChildren()) do
                            if (v.Name == enemyName or (mlrT and mlrT[5] ~= mlrT[4] and string.find(v.Name, mlrT[5], 1, true))) and v:FindFirstChild("Humanoid") and v:FindFirstChild("HumanoidRootPart") and Attack.Alive(v) and not IsPlayerModel(v) then
                                local d = (v.HumanoidRootPart.Position - Root.Position).Magnitude
                                if d < best then best = d target = v end
                            end
                        end
                        if target then
                            LV.spawn = nil
                            repeat
                                task.wait(Sec)
                                local hrp = target:FindFirstChild("HumanoidRootPart")
                                local myRoot = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                                if hrp then
                                    if LV.fx then LV.fx.t = os.clock() end
                                    LV.ForceMove(GetSpinCFrame(hrp, GetFarmOffset()), "mob:" .. tostring(enemyName))
                                    if myRoot then
                                        local fxq = _G.FARMX
                                        if fxq and fxq.Enable.QuestCardLive then
                                            if os.clock() - (LV.tGuiRef or -1e9) >= 0.5 then
                                                LV.tGuiRef = os.clock()
                                                local _, cR, nR = QuestGuiRead(enemyName, questData)
                                                if cR ~= nil then
                                                    cur, need = cR, nR
                                                elseif nR then
                                                    need = nR
                                                    cur = cur or GuiC.kills
                                                end
                                            end
                                            LvFarm(enemyName, level, cur, need, "Killing")
                                        elseif (myRoot.Position - hrp.Position).Magnitude < 70 then
                                            LvFarm(enemyName, level, cur, need, "Killing")
                                        end
                                    end
                                end
                                Attack.Kill(target, _G.Level)
                            until not _G.Level or not target.Parent or not Attack.Alive(target)
                            local hum = target:FindFirstChildOfClass("Humanoid")
                            if _G.Level and st == "active" and (not target.Parent or not hum or hum.Health <= 0) then
                                GuiC.kills = GuiC.kills + 1
                            end
                            local s2, c2, n2 = QuestGuiRead(enemyName, questData)
                            LV.lastState = s2
                            if s2 == "active" and n2 and n2 > 0 then LV.lastNeed = n2 end
                            if c2 ~= nil and n2 and _G.FARMX and _G.FARMX.Enable.QuestCardLive then LvFarm(enemyName, level, c2, n2, "Killing") end
                        else
                            local FXl = _G.FARMX
                            local canonicalMobCF = questData[7] or (GetMobFarmPosition and GetMobFarmPosition(enemyName)) or (mlrT and mlrT[9])
                            local spawnState = LevelGetSpawnState(enemyName, level, Root.Position, canonicalMobCF)
                            local spawnPoint = spawnState.list and spawnState.list[spawnState.idx]
                            if spawnPoint and typeof(spawnPoint.cf) == "CFrame" then
                                local goCF = spawnPoint.cf * CFrame.new(0, 25, 0)
                                local dist = (Root.Position - goCF.Position).Magnitude
                                local stayEnabled = FXl and FXl.Enable and FXl.Enable.LevelStay == true
                                local arriveRadius = tonumber(FXl and FXl.Cfg and FXl.Cfg.LevelSpawnArriveRadius) or 35
                                local rotateWait = tonumber(FXl and FXl.Cfg and FXl.Cfg.LevelSpawnWaitSec) or 6
                                if not stayEnabled then
                                    spawnState.waitSince = nil
                                    if dist > 5 and os.clock() - (spawnState.lastTp or 0) >= 0.8 then
                                        spawnState.lastTp = os.clock()
                                        LV.ForceMove(goCF, "spawn:" .. tostring(spawnPoint.key))
                                    end
                                    LvDetect(enemyName .. " spawn", dist, "Lv " .. tostring(level))
                                elseif dist > arriveRadius then
                                    -- Never start the spawn timer until the character reaches the spawn area.
                                    spawnState.waitSince = nil
                                    if os.clock() - (spawnState.lastTp or 0) >= 0.8 then
                                        spawnState.lastTp = os.clock()
                                        LV.ForceMove(goCF, "spawn:" .. tostring(spawnPoint.key))
                                    end
                                    if FXl and FXl.Enable.QuestCardLive then LvFarm(enemyName, level, cur, need, "Killing") else LvDetect(enemyName .. " spawn", dist, "Lv " .. tostring(level)) end
                                else
                                    spawnState.waitSince = spawnState.waitSince or os.clock()
                                    LvFarm(enemyName, level, cur, need, (FXl and FXl.Enable.QuestCardLive) and "Killing" or "Waiting spawn")
                                    if os.clock() - spawnState.waitSince >= rotateWait then
                                        if LevelAdvanceSpawn(spawnState) then
                                            spawnState.waitSince = nil
                                            spawnState.lastTp = 0
                                            if FXl and FXl.Log then
                                                FXl.Log("level-spawn-rotate", string.format("%s: diem %d/%d, het %.0fs khong co mob", enemyName, spawnState.idx, #spawnState.list, rotateWait))
                                            end
                                        else
                                            -- One known point only: rescan the spawn folder, then retry it.
                                            spawnState.waitSince = os.clock()
                                            spawnState.scanAt = 0
                                            if FXl and FXl.Log then FXl.Log("level-spawn-rescan", enemyName .. ": chi co 1 diem, quet lai EnemySpawns") end
                                        end
                                    end
                                end
                            else
                                if FXl and FXl.Log then FXl.Log("level-spawn-missing", "khong co PosM/EnemySpawns hop le cho " .. tostring(enemyName)) end
                                LvDetect(enemyName .. " spawn missing", 0, "Lv " .. tostring(level))
                            end
                            task.wait(0.3)
                        end
                    end
                end)
                if not okLv and _G.FARMX and _G.FARMX.Log then _G.FARMX.Log("level", errLv) end
                if not okLv and tostring(errLv) ~= LV.lastErrTx then
                    LV.lastErrTx = tostring(errLv)
                    warn("[Maru Level] " .. tostring(errLv))
                end
                if okLv then
                    LV.errN = 0
                else
                    LV.errN = (LV.errN or 0) + 1
                    if LV.errN >= 3 and os.clock() - (LV.tErr or -1e9) >= 10 and On("StatusPill") then
                        LV.tErr = os.clock()
                        local fhE = _G.FARMX and _G.FARMX.FH
                        if fhE and fhE.NotifyRed then fhE.NotifyRed({ Text = "Level farm error" }) end
                        LvErrPanel(string.sub(tostring(errLv), 1, 90))
                    end
                end
            else
                teleporting = false
                alreadyTeleported = false
                LV.lastState = nil
                LV.apDeadline = nil
                if LV.mode then
                    LV.mode = nil
                    H("IslandStop", "Level")
                end
            end
        end
    end)
end
