task.spawn(function()
  while task.wait() do
    if not _G.AutoFarmNear then continue end
    pcall(function()
      local char = plr.Character
      if not char then return end
      local root = char:FindFirstChild("HumanoidRootPart")
      if not root then return end
      local closestMob = nil
      local shortestDistance = math.huge
      for _, v in ipairs(workspace.Enemies:GetChildren()) do
        if v:FindFirstChild("Humanoid") and v:FindFirstChild("HumanoidRootPart") and Attack.Alive(v) then
          if Attack and Attack.Alive and not Attack.Alive(v) then continue end
          local distance = (v.HumanoidRootPart.Position - root.Position).Magnitude
          if distance < shortestDistance then
            shortestDistance = distance
            closestMob = v
          end
        end
      end
      if closestMob then
        repeat
          task.wait()
          if _G.AutoFarmNear and closestMob:FindFirstChild("HumanoidRootPart") and closestMob:FindFirstChildOfClass("Humanoid") then
            if _tp then _tp(closestMob.HumanoidRootPart.CFrame * CFrame.new(0, 20, 0)) end
            if Attack and Attack.Kill then Attack.Kill(closestMob, _G.AutoFarmNear) end
          end
        until not _G.AutoFarmNear or not closestMob.Parent or not Attack.Alive(closestMob)
      end
    end)
  end
end)
