spawn(function()
    while wait(Sec) do
        if _G.AutoRaidCastle and _G.FARMX.Own("PirateRaid") then
            pcall(function()
                local CastlePos = CFrame.new(
                    -5496.17432,
                    313.768921,
                    -2841.53027,
                    0.924894512,
                    7.37058015e-09,
                    0.380223751,
                    3.5881019e-08,
                    1,
                    -1.06665446e-07,
                    -0.380223751,
                    1.12297109e-07,
                    0.924894512
                )
                if not Root or not Root.Parent then
                    return
                end
                local NearCastle = (Root.Position - CastlePos.Position).Magnitude <= 800
                if not NearCastle then
                    _tp(CastlePos)
                    return
                end
                local Target = nil
                local Distance = math.huge
                for _, v in pairs(workspace.Enemies:GetChildren()) do
                    if v:FindFirstChildOfClass("Humanoid")
                    and v:FindFirstChild("HumanoidRootPart")
                    and Attack.Alive(v) then
                        local Magnitude = (v.HumanoidRootPart.Position - Root.Position).Magnitude
                        if Magnitude < Distance and Magnitude <= 2500 then
                            Distance = Magnitude
                            Target = v
                        end
                    end
                end
                if Target then
                    repeat
                        task.wait()
                        if not _G.AutoRaidCastle then
                            break
                        end
                        if not Target.Parent
                        or not Target:FindFirstChildOfClass("Humanoid")
                        or not Target:FindFirstChild("HumanoidRootPart")
                        or not Attack.Alive(Target) then
                            break
                        end
                        local DistMob = (Target.HumanoidRootPart.Position - Root.Position).Magnitude
                        if DistMob > 300 then
                            _tp(Target.HumanoidRootPart.CFrame * CFrame.new(0, 30, 0))
                        end
                        Attack.Kill(Target, true)
                    until not _G.AutoRaidCastle
                        or not Target.Parent
                        or not Attack.Alive(Target)
                        or not _G.FARMX.Own("PirateRaid")
                else
                    _tp(CastlePos)
                end
            end)
        end
    end
end)
