        if type(loadstring) ~= "function" then return fail("executor khong co loadstring") end
        if type(setfenv) ~= "function" then return fail("executor khong co setfenv: khong nap engine rieng duoc, giu BLOCKED (khong ghi de global)") end
        local host = (type(getfenv) == "function" and getfenv(1)) or _G
        local realGenv = (type(getgenv) == "function" and getgenv()) or _G
        local own = {}
        local nativeTask = task
        local taskProxy = setmetatable({}, { __index = nativeTask })
        taskProxy.wait = function(...)
            local a, b, c = nativeTask.wait(...)
            if not SQ.BX.TokenValid() then error(bx.CancelTag, 0) end
            return a, b, c
        end
        local function guardedTaskCallback(fn, ...)
            local args = table.pack(...)
            return nativeTask.spawn(function()
                if not SQ.BX.TokenValid() then return end
                local okTask, errTask = pcall(fn, table.unpack(args, 1, args.n))
                if not okTask and not string.find(tostring(errTask), bx.CancelTag, 1, true) then
                    SQ.Log("bx-task", tostring(errTask))
                end
            end)
        end
        taskProxy.spawn = guardedTaskCallback
        taskProxy.defer = function(fn, ...)
            local args = table.pack(...)
            return nativeTask.defer(function()
                if not SQ.BX.TokenValid() then return end
                local okTask, errTask = pcall(fn, table.unpack(args, 1, args.n))
                if not okTask and not string.find(tostring(errTask), bx.CancelTag, 1, true) then SQ.Log("bx-defer", tostring(errTask)) end
            end)
        end
        taskProxy.delay = function(delay, fn, ...)
            local args = table.pack(...)
            return nativeTask.delay(delay, function()
                if not SQ.BX.TokenValid() then return end
                local okTask, errTask = pcall(fn, table.unpack(args, 1, args.n))
                if not okTask and not string.find(tostring(errTask), bx.CancelTag, 1, true) then SQ.Log("bx-delay", tostring(errTask)) end
            end)
        end
        own.task = taskProxy
        local env = setmetatable(own, { __index = function(_, k) local v = host[k] if v == nil then v = rawget(_G, k) end return v end, __newindex = rawset })
        local gpriv = setmetatable({}, { __index = realGenv })
        local lastClick = 0
        gpriv.ClickM1 = function(target)
            local now = os.clock()
            if now - lastClick < 0.06 then return end
            lastClick = now
            pcall(function()
                local vu = game:GetService("VirtualUser")
                vu:CaptureController()
                local point
                if typeof(target) == "Instance" then
                    local part = target:IsA("BasePart") and target or target:FindFirstChild("HumanoidRootPart")
                    if part and part:IsA("BasePart") and workspace.CurrentCamera then
                        local screen, visible = workspace.CurrentCamera:WorldToViewportPoint(part.Position)
                        if visible and screen.Z > 0 then point = Vector2.new(screen.X, screen.Y) end
