        own.VirtualInputManager = game:GetService("VirtualInputManager")
        own.Settings = setmetatable({}, { __index = function(_, k)
            if k == "Auto Secret Quest" then return SQ.BX.Valid() end
            if k == "Select Weapon" then return _G.SelectWeapon end
            if k == "Hidden Hop Dead Hour" then return false end
            return nil
        end })
        local donorMoveState = { target = nil, at = -1e9 }
        own.ToTarget = function(cf)
            if not SQ.BX.Valid() then return false end
            local targetCF = nil
            if typeof(cf) == "CFrame" then
                targetCF = cf
            elseif typeof(cf) == "Vector3" then
                targetCF = CFrame.new(cf)
            elseif typeof(cf) == "Instance" then
                if cf:IsA("BasePart") then targetCF = cf.CFrame
                elseif cf:IsA("Model") then targetCF = cf:GetPivot() end
            end
            if targetCF then
                local now = os.clock()
                local activeTween = getgenv().__MaruActiveTargetTween
                local activeGoal = getgenv().__MaruActiveTargetTweenGoal
                if activeTween and activeGoal and activeTween.PlaybackState == Enum.PlaybackState.Playing
                    and (activeGoal.Position - targetCF.Position).Magnitude < 4 then
                    return true
                end
                if donorMoveState.target and (donorMoveState.target.Position - targetCF.Position).Magnitude < 4
                    and now - donorMoveState.at < 0.6 then
                    return true
                end
                donorMoveState.target, donorMoveState.at = targetCF, now
                local okMove = pcall(_tp, targetCF)
                return okMove
            end
            return pcall(_tp, cf)
        end
        own.SizePart = function() end
