        -- Ported from main_vexze RunFishingCycle (donor evidence C); modules loaded lazily, remotes go through the Remote lease.
        local function fishInit()
            local bx = SQ.BX
            if bx.Fish then return bx.Fish end
            local okF, F = pcall(function()
                local FR = RS:WaitForChild("FishReplicated", 5)
                local cfg = require(FR:WaitForChild("FishingClient"):WaitForChild("Config"))
                pcall(require, FR.FishingClient.Components)
                pcall(require, FR.FishingClient.Components.CatchingMinigame)
                return {
                    Req = FR:WaitForChild("FishingRequest"),
                    Net = require(RS.Modules.Net):RemoteEvent("FishingRemote", true),
                    Water = require(RS.Util.GetWaterHeightAtLocation),
                    Cfg = cfg,
                }
            end)
            if not okF then bx.FishErr = tostring(F) return nil end
            bx.Fish, bx.FishErr = F, nil
            return F
        end
        local function castTarget(F, root, rodTool, power)
            local CS = game:GetService("CollectionService")
            local waterY = F.Water(root.Position)
            local ignore = { root.Parent, workspace:FindFirstChild("Characters"), workspace:FindFirstChild("Enemies") }
            local _, hit = workspace:FindPartOnRayWithIgnoreList(Ray.new(root.Parent.Head.Position, root.CFrame.LookVector * (rodTool:GetAttribute("MaxLaunchDistance") or F.Cfg.Rod.MaxLaunchDistance) * (0.5 + power / 201)), ignore)
            local part, ground = workspace:FindPartOnRayWithIgnoreList(Ray.new(hit + Vector3.new(0, 3, 0), Vector3.new(0, -500, 0)), ignore)
            if not ground then return nil end
            local target = Vector3.new(hit.X, math.max(ground.Y, waterY), hit.Z)
            return target, (part and CS:HasTag(part, F.Cfg.WATER_BODY_TAG)) or target.Y <= waterY
        end
        own.RunFishingCycle = function()
            local bx = SQ.BX
            local F = fishInit()
            if not F then error("UNSUPPORTED: fishing modules unavailable: " .. tostring(bx.FishErr), 0) end
            local root = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            local rodTool = own.DetectRod()
            if not root or not rodTool then return end
            local req = bx.WrapRemote(F.Req)
            local tk = own.task
            if rodTool.Parent == plr:FindFirstChild("Backpack") then own.EquipTool(rodTool.Name) tk.wait(0.5) return end
            local state = rodTool:GetAttribute("ServerState")
            if state then own.StatusFishingLabel.SetText("Status Fishing : " .. tostring(state)) end
            if (rodTool:GetAttribute("SkillChargeAlpha") or 0) >= 1 then
                pcall(function() bx.WrapRemote(RS.Modules.Net:FindFirstChild("RF/JobToolAbilities")):InvokeServer("Z", true) end)
            end
            if not state or state == "ReeledIn" then
                bx.BiteAt = nil
                req:InvokeServer("StartCasting")
                tk.wait(0.7)
                local target, inWater = castTarget(F, root, rodTool, 98)
                if not target then return end
                if not req:InvokeServer("CastLineAtLocation", target, 98, inWater) then
                    own.EquipTool(own.NameWeapon("Melee"))
                    return
                end
                if not bx.FishConn then
                    bx.FishConn = F.Net.OnClientEvent:Connect(function(who, what)
                        if who ~= plr or not SQ.BX.Valid() then return end
                        if what == "SpawnFishOnBob" then
                            task.wait(0.2)
                            pcall(function()
                                local r = SQ.BX.WrapRemote(F.Req)
                                r:InvokeServer("Catching", true, { fastBite = true })
                                task.wait(2)
                                r:InvokeServer("Catch", 1, 1, 1)
                                r:InvokeServer("Catch", 1, 0, 1)
                            end)
                        end
                    end)
                end
            elseif state == "Biting" then
                bx.BiteAt = bx.BiteAt or tick()
                if tick() - bx.BiteAt >= 5 then own.EquipTool(own.NameWeapon("Melee")) tk.wait(1) end
            else
                bx.BiteAt = nil
            end
        end
        own.FormatMagnetTime = function(s) s = math.max(0, tonumber(s) or 0) return string.format("%d:%02d", s // 60, s % 60) end
