                if not SQ.BX.TokenValid() then return false end
                local tok, why = FX.Res.Acquire("Combat", "SecretQuest.BX.Combat")
                if not tok then return false, "combat-lock:" .. tostring(why) end
                bx.CombatToken = tok
                local okKill, resultKill = pcall(rawKill, ...)
                if bx.CombatToken == tok then bx.CombatToken = nil end
                pcall(FX.Res.Release, tok, okKill and "combat-step-complete" or "combat-step-error")
                if not okKill then
                    if string.find(tostring(resultKill), bx.CancelTag, 1, true) then return false end
                    error(resultKill, 0)
                end
                return resultKill
            end
        end
        local rawEquip = own.EquipHiddenWeapon
        if type(rawEquip) == "function" then
            own.EquipHiddenWeapon = function(...)
                if not SQ.BX.TokenValid() then return false end
                local tok, why = FX.Res.Acquire("Equip", "SecretQuest.BX.Equip")
                if not tok then return false, "equip-lock:" .. tostring(why) end
                bx.EquipToken = tok
                local okEquip, resultEquip = pcall(rawEquip, ...)
                if bx.EquipToken == tok then bx.EquipToken = nil end
                pcall(FX.Res.Release, tok, okEquip and "equip-step-complete" or "equip-step-error")
                if not okEquip then
                    if string.find(tostring(resultEquip), bx.CancelTag, 1, true) then return false end
                    error(resultEquip, 0)
                end
                return resultEquip
            end
        end
        bx.Ready, bx.Err = true, nil
        if not bx.CharacterConn and plr.CharacterAdded then
            bx.CharacterConn = plr.CharacterAdded:Connect(function()
                task.defer(function() SQ.BX.CancelMovement("character-respawn") end)
            end)
        end
        return true
    end
    -- One engine step for exactly one quest (the nearest chosen by SQ.Pick). Returns step text, waiting flag.
    SQ.BX.StepInner = function(e)
        local bx = SQ.BX
        bx.Gen = SQ.Gen
        if not bx.Valid() then return "yield: SecretQuest is not FH owner (On=" .. tostring(SQ.On) .. " Flag=" .. tostring(_G.AutoSecretQuest) .. " Own=" .. tostring(FX.Own("SecretQuest")) .. ")", true end
        local ok, why = bx.Load()
        if not ok then return "engine BLOCKED: " .. tostring(why), true end
        if bx.Unsupported[e.name] then return "UNSUPPORTED: " .. bx.Unsupported[e.name], true end
        if not bx.Q[e.name] then return "engine registry missing quest", true end
        if bx.ActiveQuest and bx.ActiveQuest ~= e.name then bx.CancelMovement("quest-switch") end
        if not bx.DialogueRun and type(bx.Env.HiddenDialogueLoop) == "function" then
            bx.DialogueRun = true
            task.spawn(function()
                pcall(bx.Env.HiddenDialogueLoop)
                bx.DialogueRun = false
            end)
        end
        local token, lockWhy = bx.AcquireMovement()
        if not token then return "WAITING Movement lock: " .. tostring(lockWhy), true end
        if not bx.TokenValid() then bx.CancelMovement("invalid-token-before-step") return "yield: Movement token invalid", true end

        local env = bx.Env
        bx.Only, bx.Gen, bx.ActiveQuest = e.name, SQ.Gen, e.name
        local HE = env.HiddenEvent
        if getmetatable(HE.skipped) ~= bx.SkipMT then
            local copy = {}
            for k, v in pairs(HE.skipped) do copy[k] = v end
            copy[e.name] = nil
            HE.skipped = setmetatable(copy, bx.SkipMT)
        end
        bx.Calls = bx.Calls + 1
        local okc, err = pcall(env.AutoHiddenEvent)
        if not okc then
            local message = tostring(err)
            if string.find(message, bx.CancelTag, 1, true) then
                bx.CancelMovement("preempted-during-yield")
                return "YIELDED to higher-priority farm; cleanup complete", true
            end
            if string.find(message, bx.InventoryTag, 1, true) then
                bx.ReleaseMovement("inventory-unavailable", true)
                bx.ActiveQuest = nil
                return "WAITING inventory read failed: " .. message, true
            end
            if string.find(message, bx.RemoteTag, 1, true) then
                bx.ReleaseMovement("remote-lock-wait", true)
                bx.ActiveQuest = nil
                return "WAITING Remote lease: " .. message, true
            end
            bx.CancelMovement("engine-error")
            error("BX " .. message, 0)
        end
        if not bx.TokenValid() then
            bx.CancelMovement("preempted-after-step")
            return "YIELDED to higher-priority farm; cleanup complete", true
        end
        pcall(function() if env.CheckHiddenStall then env.CheckHiddenStall() end end)
        if bx.StopRequested then
            bx.StopRequested = false
            SQ.ProgNext = 0
            SQ.Progress(true)
            if SQ.Status == "OK" and SQ.Done >= #SQ.List then
                bx.ReleaseMovement("server-confirmed-all-done", true)
                bx.ActiveQuest = nil
                return "Server progress confirms all 39 complete", true
            end
            bx.ReleaseMovement("await-server-progress", true)
            bx.ActiveQuest = nil
            return "Engine requested stop; waiting for server progress confirmation", true
        end
        if HE.current == e.name then
            return tostring(HE.step or "Working"), false
        end
        local sk = rawget(HE.skipped, e.name)
        local wait = (type(sk) == "number" and sk > tick()) and (sk - tick()) or 30
        SQ.Skipped[e.name] = os.clock() + math.min(math.max(wait, 15), e.retry or 420)
        bx.ReleaseMovement("engine-waiting", true)
        bx.ActiveQuest = nil
        return tostring((HE.waiting and HE.waiting[e.name]) or HE.step or "waiting"), true
    end
    SQ.BX.Step = function(e)
        local bx = SQ.BX
        if bx.StepBusy and os.clock() - (bx.StepBusyAt or 0) < 180 then return "BUSY: previous engine step still running", true end
        bx.StepBusy, bx.StepBusyAt = true, os.clock()
        local r = table.pack(pcall(bx.StepInner, e))
        bx.StepBusy = false
        if not r[1] then error(r[2], 0) end
        return table.unpack(r, 2, r.n)
    end
    for name, rawNative in pairs(SQ.NativeRun or {}) do
        SQ.Run[name] = function(moment, ...)
            local token, why = SQ.BX.AcquireMovement()
            if not token then return "WAITING Movement lease: " .. tostring(why), true end
            local wrappedMoment = SQ.BX.WrapRemote(moment)
            local okNative, step, waiting = pcall(rawNative, wrappedMoment, ...)
            if not SQ.BX.TokenValid() then
                SQ.BX.CancelMovement("native-handler-preempted:" .. tostring(name))
                return "YIELDED to higher-priority farm; cleanup complete", true
            end
            if not okNative then
                local message = tostring(step)
                if string.find(message, SQ.BX.CancelTag, 1, true) then
                    SQ.BX.CancelMovement("native-handler-cancelled")
                    return "YIELDED to higher-priority farm; cleanup complete", true
                end
                if string.find(message, SQ.BX.RemoteTag, 1, true) then
                    SQ.BX.ReleaseMovement("native-remote-lock-wait", true)
                    return "WAITING Remote lease: " .. message, true
                end
                error("native SQ " .. tostring(name) .. ": " .. message, 0)
            end
            return step, waiting
        end
    end
    for i = 1, #SQ.List do
        local e = SQ.List[i]
        if not SQ.Run[e.name] then
            SQ.BX.Handled[e.name] = true -- wrapper registered; not proof that the donor handler ran
            SQ.Run[e.name] = function() return SQ.BX.Step(e) end
        end
    end
    SQ.HandlerStatus = function(e)
        if SQ.NativeRun and type(SQ.NativeRun[e.name]) == "function" then return "MARU" end
        if SQ.BX.Unsupported[e.name] then return "UNSUPPORTED" end
        if not SQ.BX.Handled[e.name] then return "BLOCKED" end
        local ok, why = SQ.BX.Load()
        if not ok then return "BLOCKED", why end
        if not SQ.BX.Q[e.name] then return "BLOCKED", "not present in Banana HiddenQuests registry" end
        return "BX_READY" -- engine loaded + quest registry entry; still requires in-game verification
    end
    SQ.IslDist = function(island)
        local char = plr.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local pos = SQ.IslandPos(island)
        if not hrp or not pos then return nil end
        return (hrp.Position - pos).Magnitude
    end
    SQ.Locate = function()
        local best, bd
        local seen = {}
        for i = 1, #SQ.List do
            local isl = SQ.List[i].island
            if not seen[isl] then
                seen[isl] = true
                local d = SQ.IslDist(isl)
                if d ~= nil and (not bd or d < bd) then best, bd = isl, d end
            end
        end
        SQ.Here, SQ.HereDist = best or "UNKNOWN", bd
        return SQ.Here, bd
    end
    SQ.Audit = function()
        local progressIsFresh = SQ.Status == "OK" and SQ.ProgFreshAt > 0
            and os.clock() - SQ.ProgFreshAt <= FX.Cfg.SQProgressTTL
        local p = progressIsFresh and type(SQ.Prog) == "table" and SQ.Prog or nil
        local here, hd = SQ.Locate()
        local rows, done, ready, blocked, unsupported = {}, 0, 0, 0, 0
        for i = 1, #SQ.List do
            local e = SQ.List[i]
            local isDone = p and SQ.IsDone(p, SQ.Key(e)) or nil
            if isDone then done = done + 1 end
            local h, why = SQ.HandlerStatus(e)
            if h == "MARU" or h == "BX_READY" then ready = ready + 1
            elseif h == "UNSUPPORTED" then unsupported = unsupported + 1
            else blocked = blocked + 1 end
            local momentLoaded = SQ.Moment(e.name) ~= nil
            rows[#rows + 1] = { e = e, done = isDone, h = h, why = why, loaded = momentLoaded, d = SQ.IslDist(e.island) }
        end
        table.sort(rows, function(a, b)
            if (a.done == true) ~= (b.done == true) then return a.done ~= true end
            return (a.d or math.huge) < (b.d or math.huge)
        end)
        local lines = {}
        for _, r in ipairs(rows) do
            local status = r.done and "DONE" or (p and "TODO" or "PROGRESS_UNKNOWN")
            local distance = r.d and (tostring(math.floor(r.d)) .. "st") or "N/A"
            local availability = r.loaded and "LOADED" or "NOT_LOADED/UNKNOWN"
            lines[#lines + 1] = string.format("%s | %s | %s | %s | %s | %s | %s | %s", status, r.e.name, r.e.island, r.e.kind, r.h, availability, distance, tostring(r.why or ""))
        end
        local age = SQ.ProgFreshAt > 0 and tostring(math.floor(os.clock() - SQ.ProgFreshAt)) .. "s" or "never"
        local head = string.format("39 entries | near: %s (%s) | DONE %s | engine-ready %d | BLOCKED %d | UNSUPPORTED %d | progress age %s | BX %s%s",
            tostring(here), hd and (math.floor(hd) .. "st") or "N/A", p and (tostring(done) .. "/" .. #SQ.List) or "UNKNOWN",
            ready, blocked, unsupported, age, SQ.BX.Ready and "loaded" or "not-loaded", SQ.BX.Err and (" | " .. SQ.BX.Err) or "")
        return head, lines
    end
    SQ.Report = function()
        local head, lines = SQ.Audit()
        return head, lines
    end
    SQ.Runnable = function()
        local n = 0
        for i = 1, #SQ.List do
            local e = SQ.List[i]
            local status = SQ.HandlerStatus(e)
            if status == "MARU" or status == "BX_READY" then n = n + 1 end
        end
        return n
    end
    -- [PHASE115] Single active-quest lock: once a quest is picked it stays selected until server-DONE / drop / toggle-off / generation change.
    SQ.Lock = SQ.Lock or { Name = nil, Gen = nil, Since = nil, Reason = nil }
    FX.SQRef = SQ
    if FX.Session then
        FX.Session.Register("secretquest", function()
            SQ.On, _G.AutoSecretQuest = false, false
            SQ.Gen = SQ.Gen + 1
            SQ.Lock.Name = nil
            pcall(SQ.BX.CancelMovement, "session-cleanup")
            pcall(function() if SQ.CharConn then SQ.CharConn:Disconnect() end end)
        end)
    end
    FX.TraceBuf = FX.TraceBuf or {}
    FX.Trace = function(src, evt, info)
        local b = FX.TraceBuf
        b[#b + 1] = string.format("%.1f %s %s %s", os.clock(), tostring(src), tostring(evt), tostring(info or ""))
        if #b > 60 then table.remove(b, 1) end
    end
    SQ.LockEntry = function()
        local L = SQ.Lock
        if not L.Name then return nil end
        for i = 1, #SQ.List do
            if SQ.List[i].name == L.Name then return SQ.List[i] end
        end
        return nil
    end
    SQ.LockedEntry = function()
        local L = SQ.Lock
        if not L.Name or L.Gen ~= SQ.Gen then return nil end
        local e = SQ.LockEntry()
        if not e then return nil end
        if os.clock() < (SQ.Skipped[e.name] or 0) or os.clock() < (SQ.Explore[e.name] or 0) then return nil end
        local fresh = SQ.Status == "OK" and type(SQ.Prog) == "table" and SQ.ProgFreshAt > 0
            and os.clock() - SQ.ProgFreshAt <= FX.Cfg.SQProgressTTL
        if fresh and SQ.IsDone(SQ.Prog, SQ.Key(e)) then return nil end
        local h = SQ.HandlerStatus(e)
        if h ~= "MARU" and h ~= "BX_READY" then return nil end
        return e
    end
    -- Returns true when it released the lock this call (caller must end the tick so cleanup finishes before the next pick).
    SQ.LockValidate = function()
        local L = SQ.Lock
        if not L.Name then return false end
        local why
        if L.Gen ~= SQ.Gen then why = "generation-changed"
        elseif not SQ.LockEntry() then why = "entry-missing"
        elseif os.clock() < (SQ.Skipped[L.Name] or 0) or os.clock() < (SQ.Explore[L.Name] or 0) then why = "skip-cooldown"
        else
            local e = SQ.LockEntry()
            local fresh = SQ.Status == "OK" and type(SQ.Prog) == "table" and SQ.ProgFreshAt > 0
                and os.clock() - SQ.ProgFreshAt <= FX.Cfg.SQProgressTTL
            if fresh and SQ.IsDone(SQ.Prog, SQ.Key(e)) then why = "server-confirmed-done" end
        end
        if not why then return false end
        FX.Trace("SQ", "lock-release", tostring(L.Name) .. " " .. why)
        if SQ.BX.MoveToken then SQ.BX.CancelMovement("lock-release:" .. why) end
        SQ.EndCard()
        L.Name, L.Gen, L.Since, L.Reason = nil, nil, nil, why
        SQ.Cur, SQ.WaitSince, SQ.IslArr, SQ.Arrived, SQ.EA = nil, nil, nil, nil, nil
        SQ.WorkSince, SQ.WorkTravelAt, SQ.WorkDeadline = nil, nil, nil
        SQ.ProgSig, SQ.ProgSigAt = nil, nil
        SQ.Dist = nil
        return true
    end
    -- Idempotent disable/respawn cleanup: stop donor + Maru tween/fly, restore physics, rebase block, controlled landing.
    SQ.SafeStopRun = function(why)
        local plr_ = game:GetService("Players").LocalPlayer
        local char0 = plr_.Character
        pcall(function()
            local t = getgenv().__MaruActiveTargetTween
            if t then t:Cancel() end
            getgenv().__MaruActiveTargetTween, getgenv().__MaruActiveTargetTweenGoal, getgenv().__MaruActiveTargetTweenSpeed = nil, nil, nil
        end)
        local root = char0 and char0:FindFirstChild("HumanoidRootPart")
        local hum = char0 and char0:FindFirstChildOfClass("Humanoid")
        if not root then return end
        local function otherOwner()
            local fh = FX.FH
            local ow = fh and fh.Owner
            if ow == nil then return false end
            local nm = type(ow) == "table" and ow.name or ow
            return nm ~= "SecretQuest"
        end
        pcall(function()
            if hum then hum.PlatformStand = false hum.AutoRotate = true end
            root.Anchored = false
            local blk = workspace:FindFirstChild("Rip_Indra")
            if blk then blk.CFrame = root.CFrame end
        end)
        if otherOwner() then FX.Trace("SQ", "safestop", "other-owner-active " .. tostring(why)) return end
        local ground
        pcall(function()
            local rp = RaycastParams.new()
            rp.FilterType = Enum.RaycastFilterType.Exclude
            rp.FilterDescendantsInstances = { char0, workspace:FindFirstChild("Rip_Indra") }
            local hit = workspace:Raycast(root.Position, Vector3.new(0, -3000, 0), rp)
            if hit then ground = hit.Position end
        end)
        if ground and root.Position.Y - ground.Y > 30 then
            local target = CFrame.new(ground + Vector3.new(0, 4, 0))
            getgenv().__MaruLanding = true
            FX.Trace("SQ", "landing-start", string.format("%.0f studs", root.Position.Y - ground.Y))
            local t0 = os.clock()
            while os.clock() - t0 < 14 do
                if plr_.Character ~= char0 or not root.Parent or otherOwner() then break end
                if (root.Position - target.Position).Magnitude <= 6 then break end
                pcall(_tp, target)
                task.wait(0.3)
            end
            getgenv().__MaruLanding = false
        else
            FX.Trace("SQ", "safestop", "no-landing-needed-or-ground-unknown " .. tostring(why))
        end
        if not otherOwner() then
            pcall(function() if FX.FlyOn then FX.FlyStop() end end)
            pcall(function()
                local t = getgenv().__MaruActiveTargetTween
                if t then t:Cancel() end
                getgenv().__MaruActiveTargetTween, getgenv().__MaruActiveTargetTweenGoal, getgenv().__MaruActiveTargetTweenSpeed = nil, nil, nil
                local blk = workspace:FindFirstChild("Rip_Indra")
                if blk and root.Parent then blk.CFrame = root.CFrame end
            end)
        end
    end
    SQ.SafeStop = function(why)
        pcall(function() SQ.BX.CancelMovement(why or "safe-stop") end)
        if SQ.StopBusy and os.clock() - (SQ.StopBusyAt or 0) < 30 then return end
        SQ.StopBusy, SQ.StopBusyAt = true, os.clock()
        task.spawn(function()
            local ok, err = pcall(SQ.SafeStopRun, why)
            if not ok then FX.Trace("SQ", "safestop-error", err) end
            SQ.StopBusy = false
        end)
    end
    pcall(function()
        if SQ.CharConn then SQ.CharConn:Disconnect() end
        SQ.CharConn = game:GetService("Players").LocalPlayer.CharacterAdded:Connect(function()
            if SQ.BX.MoveToken then pcall(SQ.BX.CancelMovement, "respawn") end
            getgenv().__MaruLanding = false
            SQ.StopBusy = false
            FX.Trace("SQ", "respawn", "tokens-cancelled")
        end)
    end)
    SQ.Pick = function()
        if not (FX.Enable.SecretQuest and SQ.On) or not SQ.Sea1() then return nil end
        do local lockedE = SQ.LockedEntry() if lockedE then return lockedE end end
        local p = SQ.Prog
        if SQ.Status ~= "OK" or type(p) ~= "table" or SQ.ProgFreshAt <= 0
            or os.clock() - SQ.ProgFreshAt > FX.Cfg.SQProgressTTL then return nil end
        local char = plr.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return nil end
        local now = os.clock()
        local candidates = {}
        for i = 1, #SQ.List do
            local e = SQ.List[i]
            local done = SQ.IsDone(p, SQ.Key(e))
            local prerequisiteOk = not e.requires or SQ.IsDone(p, e.requires)
            local cooldownOk = now >= (SQ.Skipped[e.name] or 0) and now >= (SQ.Explore[e.name] or 0)
            if not done and prerequisiteOk and cooldownOk then
                local handler, reason = SQ.HandlerStatus(e)
                local dist = SQ.IslDist(e.island)
                if (handler == "MARU" or handler == "BX_READY") and dist ~= nil then
                    candidates[#candidates + 1] = { entry = e, distance = dist, handler = handler }
                else
                    SQ.BlockedReason = SQ.BlockedReason or {}
                    SQ.BlockedReason[e.name] = reason or handler
                end
            end
        end
        table.sort(candidates, function(a, b)
            if a.distance ~= b.distance then return a.distance < b.distance end
            return a.entry.name < b.entry.name
        end)
        local best = candidates[1]
        if best and SQ.Cur then
            -- Small hysteresis only: retain the current valid quest when distances are effectively tied.
            for _, candidate in ipairs(candidates) do
                if candidate.entry.name == SQ.Cur then
                    local margin = math.max(8, math.min(25, best.distance * 0.002))
                    if candidate.distance <= best.distance + margin then best = candidate end
                    break
                end
            end
        end
        return best and best.entry or nil
    end
    SQ.Want = function()
        local now = os.clock()
        if now - SQ.EvalT >= 0.5 then
            SQ.EvalT = now
            SQ.Act = SQ.Pick()
        end
        return SQ.Act ~= nil
    end
    SQ.Card = function(e)
        local fh = FX.FH
        if not fh or not fh.FarmData then return end
        local now = os.clock()
        if now - (SQ.tCard or -1e9) < 0.5 then return end
        SQ.tCard = now
        local ok = SQ.Status == "OK"
        pcall(fh.FarmData, "SecretQuest", {
            Title = e.name, Content = (e.island .. "  ·  " .. tostring(SQ.Step)),
            Value = ok and (tostring(SQ.Done) .. "/" .. tostring(#SQ.List)) or nil, Unit = "secret",
            Left = e.island, Right = ok and (tostring(#SQ.List - SQ.Done) .. " left") or "",
            Progress = ok and (SQ.Done / #SQ.List) or nil,
        })
    end
    SQ.EndCard = function()
        SQ.tCard = -1e9
        pcall(function() if FX.FH and FX.FH.IslandStop then FX.FH.IslandStop("SecretQuest") end end)
    end
    -- bỏ quest hiện tại, đổi quest khác (cooldown retry)
    SQ.Drop = function(e, why, cool)
        local now = os.clock()
        SQ.Skipped[e.name] = now + (cool or e.retry or 300)
        if SQ.BX.MoveToken then SQ.BX.CancelMovement("drop:" .. tostring(why)) end
        SQ.Cur, SQ.WaitSince, SQ.ProgSig = nil, nil, nil
        SQ.WorkSince, SQ.WorkTravelAt, SQ.WorkDeadline = nil, nil, nil
        SQ.EndCard()
        SQ.Note("drop" .. e.name, e.name .. ": " .. tostring(why) .. ", chuyen quest khac", "yellow")
    end
    SQ.TickInner = function()
        if SQ.LockValidate() then return end
        local e = SQ.Pick()
        if not e then
            if SQ.BX.MoveToken then SQ.BX.CancelMovement("no-eligible-quest") end
            if SQ.State ~= "IDLE" then SQ.EndCard() end
            SQ.State = "IDLE"
            SQ.Cur = nil
            SQ.WorkSince, SQ.WorkTravelAt, SQ.WorkDeadline = nil, nil, nil
            return
        end
        local now = os.clock()
        if SQ.Cur ~= e.name then
            -- Do not carry a Banana engine Movement lease into a different quest/Maru-native handler.
            if SQ.BX.MoveToken then SQ.BX.CancelMovement("quest-target-changed:" .. tostring(e.name)) end
            SQ.Cur, SQ.CurSince, SQ.WaitSince, SQ.IslArr, SQ.Arrived, SQ.EA = e.name, now, nil, nil, nil, nil
            SQ.WorkSince, SQ.WorkTravelAt, SQ.WorkDeadline = nil, nil, nil
            SQ.ProgSig, SQ.ProgSigAt = nil, nil
            SQ.Lock.Name, SQ.Lock.Gen, SQ.Lock.Since = e.name, SQ.Gen, now
            FX.Trace("SQ", "lock", e.name)
            SQ.Note("start" .. e.name, "Secret Quest: " .. e.name .. " (" .. e.island .. ")", "green")
        end
        local m = SQ.Moment(e.name)
        if not m and not SQ.BX.Handled[e.name] then
            local pos = SQ.IslandPos(e.island)
            if not pos then
                SQ.State = "BLOCKED"
                SQ.Step = "khong doc duoc vi tri dao (Definitions.Map)"
                SQ.Skipped[e.name] = now + (e.retry or 420)
                SQ.Cur = nil
                return
            end
            SQ.State = "TRAVEL"
            SQ.Step = "Travel to " .. e.island
            SQ.Card(e)
            if SQ.Go(pos, 150) then
                SQ.IslArr = SQ.IslArr or now
                if now - SQ.IslArr > FX.Cfg.SQIslandWait then
                    SQ.IslArr = nil
                    SQ.Explore[e.name] = now + (e.retry or 420)
                    SQ.Cur = nil
                    SQ.Step = e.name .. " is not happening on " .. e.island
                    SQ.Note("nothappen" .. e.name, SQ.Step, "yellow")
                end
            else
                SQ.IslArr = nil
            end
            return
        end
        SQ.IslArr = nil
        SQ.State = "STEP"
        SQ.Dist = nil -- distance is per-tick; do not carry a stale travel distance into the work timer
        local ok, step, waiting = pcall(SQ.Run[e.name], m)
        if not ok then
            SQ.Log("run", e.name .. ": " .. tostring(step))
            SQ.Skipped[e.name] = now + 60
            SQ.Cur = nil
            SQ.State = "ERROR"
            SQ.Step = "loi: " .. tostring(step)
            SQ.LastErr = e.name .. ": " .. tostring(step)
            SQ.Note("err" .. e.name, "Secret Quest loi: " .. e.name, "red")
            return
        end
        SQ.Step = tostring(step or "Working")
        SQ.Card(e)
        local travelStep = false
        do
            -- Travel to the outer island (or a long in-island route) is excluded from the 150s work budget.
            travelStep = string.match(SQ.Step, "^Travel to%s") ~= nil
            local travelDist = tonumber(SQ.Dist)
            if travelDist and travelDist > (FX.Cfg.SQWorkTravelRadius or 60) then travelStep = true end
            do
                -- Donor handlers can walk/teleport without reporting SQ.Dist; measured root speed is handler-agnostic.
                local rootM = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                if rootM then
                    local lp, lt = SQ.MovePos, SQ.MoveT
                    SQ.MovePos, SQ.MoveT = rootM.Position, now
                    local p = rootM.Position
                    SQ.PosBucket = math.floor(p.X / 30) .. "," .. math.floor(p.Y / 30) .. "," .. math.floor(p.Z / 30)
                    if lp and lt and now - lt > 0 and now - lt < 5
                        and (rootM.Position - lp).Magnitude / (now - lt) > (FX.Cfg.SQTravelSpeed or 12) then
                        travelStep = true
                    end
                end
            end
            if travelStep then
                SQ.WorkTravelAt = SQ.WorkTravelAt or now
                if now - SQ.WorkTravelAt > (FX.Cfg.SQTravelMaxSec or 300) then
                    SQ.Log("travel-timeout", e.name .. ": di chuyen > " .. tostring(FX.Cfg.SQTravelMaxSec or 300) .. "s")
                    SQ.Drop(e, "di chuyen qua " .. tostring(FX.Cfg.SQTravelMaxSec or 300) .. "s van chua xong", e.retry or 300)
                    return
                end
            else
                if SQ.WorkTravelAt then
                    local paused = math.max(0, now - SQ.WorkTravelAt)
                    if SQ.WorkSince then SQ.WorkSince = SQ.WorkSince + paused end
                    if SQ.WorkDeadline then SQ.WorkDeadline = SQ.WorkDeadline + paused end
                    if SQ.ProgSigAt then SQ.ProgSigAt = SQ.ProgSigAt + paused end
                    SQ.WorkTravelAt = nil
                end
                SQ.WorkSince = SQ.WorkSince or now
                SQ.WorkDeadline = SQ.WorkDeadline or (SQ.WorkSince + (FX.Cfg.SQStallSec or 150))
                if now >= SQ.WorkDeadline then
                    SQ.Log("timeout", e.name .. ": 150s quest work budget exceeded")
                    SQ.Drop(e, "het 150s thuc hien quest (khong tinh di duong)", e.retry or 300)
                    return
                end
            end
            local sig = e.name .. "|" .. SQ.Step .. "|" .. tostring(SQ.Done) .. "|" .. tostring(SQ.PosBucket)
            if SQ.ProgSig ~= sig then SQ.ProgSig, SQ.ProgSigAt = sig, now end
            if not travelStep and now - (SQ.ProgSigAt or now) >= (FX.Cfg.SQNoProgressSec or 150) then
                SQ.Log("noprogress", e.name .. ": " .. SQ.Step)
                SQ.Drop(e, "khong tien trien trong 150s (" .. SQ.Step .. ")", e.retry or 300)
                return
            end
        end
        if waiting and not travelStep then
            SQ.WaitSince = SQ.WaitSince or now
            if now - SQ.WaitSince >= (FX.Cfg.SQWaitTimeout or 150) then
                SQ.Drop(e, "cho trang thai qua 150s (" .. SQ.Step .. ")", e.retry or 300)
                return
            end
        else
            SQ.WaitSince = nil
        end
    end
    SQ.Tick = function()
        if SQ.TickBusy and os.clock() - (SQ.TickBusyAt or 0) < 180 then return end
        SQ.TickBusy, SQ.TickBusyAt = true, os.clock()
        local okT, errT = pcall(SQ.TickInner)
        SQ.TickBusy = false
        if SQ.Cur == nil then SQ.Lock.Name = nil end
        if not okT then error(errT, 0) end
    end
    SQ.Label = nil
    SQ.Refresh = function()
        if not SQ.Label then return end
        local txt
        if not SQ.On then
            txt = "OFF"
        elseif not SQ.Sea1() then
            txt = "GATED (chi Sea 1)"
        else
            local cnt = SQ.Status == "OK" and (tostring(SQ.Done) .. "/" .. tostring(#SQ.List)) or "?/" .. tostring(#SQ.List)
            local hereI, hereD = SQ.Locate()
            txt = cnt .. "  |  o gan: " .. tostring(hereI) .. " (" .. (hereD and tostring(math.floor(hereD)) or "N/A") .. "st)  |  tien do: " .. SQ.Status .. "  |  " .. SQ.State
            if SQ.Cur then txt = txt .. "  |  " .. SQ.Cur .. ": " .. tostring(SQ.Step) end
            local readyCount = SQ.Runnable()
            txt = txt .. "  |  native/engine-ready " .. tostring(readyCount) .. "/" .. tostring(#SQ.List) .. " (khong phai xac nhan in-game)"
            if SQ.Cur then
                for i = 1, #SQ.List do if SQ.List[i].name == SQ.Cur then txt = txt .. "  |  dao: " .. tostring(SQ.List[i].island) break end end
            end
            txt = txt .. "  |  loi cuoi: " .. tostring(SQ.LastErr or "khong") .. "  |  xong cuoi: " .. tostring(SQ.LastDone or "chua co")
        end
        if txt ~= SQ.LastTxt then
            SQ.LastTxt = txt
            pcall(function() SQ.Label:SetContent("Status: " .. txt) end)
        end
    end
    SQ.Success = function(e)
        SQ.LastDone = e.name .. " " .. os.date("%H:%M:%S")
        local fh = FX.FH
        if fh and fh.Finish then
            pcall(fh.Finish, "SecretQuest", { Title = e.name .. " done", Content = tostring(SQ.Done) .. "/" .. tostring(#SQ.List) .. " secret quests", Success = true })
        end
        SQ.Note("done" .. e.name, e.name .. " completed (" .. tostring(SQ.Done) .. "/" .. tostring(#SQ.List) .. ")", "green")
    end
    UIX.Paragraph(Tabs.Main, "Para_SQ", { Title = "Secret Quest [ 39 Island ]", Content = "" })
    SQ.Label = UIX.Paragraph(Tabs.Main, "Para_SQ_Status", { Title = "Secret Quest", Content = "Status: OFF" })
    do
        local repRec
        UIX.Button(Tabs.Main, nil, { Title = "Secret Quest Report (39)", Description = "Trang thai tung entry: MARU/BX_READY/BLOCKED/UNSUPPORTED + server progress. BX_READY khong dong nghia da farm thanh cong.",
            Callback = function()
                local ok, head, lines = pcall(SQ.Report)
                if ok and repRec and repRec.SetContent then pcall(repRec.SetContent, repRec, head .. "\n" .. table.concat(lines, "\n")) end
            end })
        repRec = UIX.Paragraph(Tabs.Main, "Para_SQ_Report", { Title = "Secret Quest Report", Content = "Bam nut Report de doc" })
        local chkRec
        UIX.Button(Tabs.Main, nil, { Title = "Check 39 Secret Quest + Vi tri", Description = "DONE/TODO, handler readiness, LOADED state va khoang cach; sap xep theo vi tri that. LOADED khong dong nghia LIVE.",
            Callback = function()
                pcall(SQ.Progress, true)
                local ok, head, lines = pcall(SQ.Audit)
                if ok and chkRec and chkRec.SetContent then pcall(chkRec.SetContent, chkRec, head .. "\n" .. table.concat(lines, "\n")) end
            end })
        chkRec = UIX.Paragraph(Tabs.Main, "Para_SQ_Check", { Title = "Secret Quest Check", Content = "Bam nut Check de doc" })
    end
    UIX.Toggle(Tabs.Main, "Main_AutoSecretQuest", {
        Title = "Auto Secret Quest",
        Description = "Chon quest du dieu kien gan nhat (Sea 1). BX_READY chi xac nhan engine/registry da nap; DONE chi tinh theo server progress. Chef's Kiss dang UNSUPPORTED vi thieu fishing cycle.",
        Default = false,
        Callback = function(Value)
            if not Value then SQ.BX.CancelMovement("toggle-off-generation") end
            SQ.Gen = SQ.Gen + 1
            local myGen = SQ.Gen
            SQ.On = Value and true or false
            if Value and not SQ.Sea1() then
                SQ.On = false
                _G.AutoSecretQuest = false
                SQ.State = "GATED"
                pcall(function() Library.Options["Main_AutoSecretQuest"]:SetValue(false) end)
                SQ.Note("gate", "Secret Quest chi chay o Sea 1", "yellow")
                SQ.Refresh()
                return
            end
            _G.AutoSecretQuest = SQ.On
            if not SQ.On then
                SQ.BX.CancelMovement("toggle-off")
                SQ.State, SQ.Cur, SQ.Step = "OFF", nil, ""
                SQ.Lock.Name = nil
                SQ.SafeStop("toggle-off")
                SQ.EndCard()
                SQ.AtomicUntil = 0
                SQ.Refresh()
                return
            end
            if not FX.Enable.SecretQuest then SQ.On = false _G.AutoSecretQuest = false return end
            SQ.State = "UNKNOWN"
            task.spawn(function()
                while SQ.Gen == myGen and SQ.On do
                    pcall(function()
                        SQ.Progress()
                        if SQ.Status == "OK" then
                            if SQ.Fresh then local f = SQ.Fresh SQ.Fresh = nil SQ.Success(f) end
                            if SQ.Done >= #SQ.List then
                                SQ.State = "ALL_DONE"
                                SQ.Lock.Name = nil
                                SQ.SafeStop("all-done")
                                SQ.Note("alldone", "Secret Quest: xong " .. tostring(#SQ.List) .. "/" .. tostring(#SQ.List) .. ", tat", "green")
                                SQ.On = false
                                _G.AutoSecretQuest = false
                                pcall(function() Library.Options["Main_AutoSecretQuest"]:SetValue(false) end)
                                return
                            end
                        elseif SQ.State == "UNKNOWN" or SQ.Status ~= "OK" then
                            SQ.State = "UNKNOWN"
                        end
                        if _G.AutoSecretQuest and FX.Own("SecretQuest") then
                            SQ.BX.Gen = myGen
                            SQ.Tick()
                        elseif SQ.State ~= "ALL_DONE" then
                            SQ.State = "ARMED"
                        end
                        SQ.Refresh()
                    end)
                    task.wait(0.3)
                end
            end)
        end,
    })
end
