task.spawn(function()
    while task.wait(0.3) do
        if PFS_ShouldYieldBoss and PFS_ShouldYieldBoss() then continue end
        if _G.FARMX.Enable.Boss and not _G.FARMX.IsTop("Boss") then continue end
        if _G.AutoFarmAllBoss and not _G.AutoKillCursedCaptain then
            pcall(function()
                local player = game.Players.LocalPlayer
                if not player.Character or not player.Character:FindFirstChild("HumanoidRootPart") then return end
                local hrp = player.Character.HumanoidRootPart
                local nearestBoss, nearestDist = nil, math.huge
                for _, boss in pairs(workspace.Enemies:GetChildren()) do
                    if boss:FindFirstChild("HumanoidRootPart") and Attack.Alive(boss) then
                        if table.find(BossList, boss.Name) then
                            local dist = (hrp.Position - boss.HumanoidRootPart.Position).Magnitude
                            if dist < nearestDist then
                                nearestBoss = boss
                                nearestDist = dist
                            end
                        end
                    end
                end
                if nearestBoss and nearestBoss:FindFirstChild("HumanoidRootPart") then
                    local bossHRP = nearestBoss.HumanoidRootPart
                    local humanoid = nearestBoss.Humanoid
                    repeat
                        task.wait(0.1)
                        if not _G.AutoFarmAllBoss then break end
                        local targetCFrame = bossHRP.CFrame * CFrame.new(0, 5, 0)
                        if (hrp.Position - targetCFrame.Position).Magnitude > 100 then
                            player.Character:PivotTo(targetCFrame)
                        else
                            _tp(targetCFrame)
                        end
                        if Attack and typeof(Attack.Kill) == "function" then
                            Attack.Kill(nearestBoss, true)
                        end
                    until not nearestBoss.Parent or humanoid.Health <= 0 or not _G.AutoFarmAllBoss or not _G.FARMX.Own("Boss")
                end
            end)
        end
    end
end)
task.spawn(function()
    local entranceAt, travelAt = 0, 0
    local entrancePos = Vector3.new(923.21252441406, 126.9760055542, 32852.83203125)
    local bossPos = CFrame.new(916.928589, 181.092773, 33422)
    while task.wait(0.35) do
        if not _G.AutoKillCursedCaptain or not World2 then
            continue
        end
        local FXC = _G.FARMX
        if FXC and FXC.Own and not FXC.Own("CursedCaptain") then
            continue
        end
        pcall(function()
            local char = plr.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum or hum.Health <= 0 or not _G.SelectWeapon then return end

            local enemies = workspace:FindFirstChild("Enemies")
            local target = enemies and enemies:FindFirstChild("Cursed Captain") or nil
            if not (target and target.Parent and Attack.Alive(target)
                and target:FindFirstChild("HumanoidRootPart")) then
                target = nil
            end

            if target and target.Parent and Attack.Alive(target)
                and target:FindFirstChild("HumanoidRootPart") then
                repeat
                    if not _G.AutoKillCursedCaptain then break end
                    if FXC and FXC.Own and not FXC.Own("CursedCaptain") then break end
                    task.wait(0.12)
                    Attack.Kill(target, function()
                        return _G.AutoKillCursedCaptain
                            and (not FXC or not FXC.Own or FXC.Own("CursedCaptain"))
                    end)
                until not target.Parent or not Attack.Alive(target)
                    or not _G.AutoKillCursedCaptain
                    or (FXC and FXC.Own and not FXC.Own("CursedCaptain"))
            else
                local now = os.clock()
                if (hrp.Position - entrancePos).Magnitude > 1800 then
                    if now >= entranceAt then
                        entranceAt = now + 15
                        travelAt = now + 2
                        pcall(function()
                            replicated.Remotes.CommF_:InvokeServer("requestEntrance", entrancePos)
                        end)
                    end
                    return
                end
                if (hrp.Position - bossPos.Position).Magnitude > 85 and now >= travelAt then
                    travelAt = now + 4
                    _tp(bossPos)
                end
            end
        end)
    end
end)

