do
    local FX = _G.FARMX
    FX.SwordMasteryStep = function()
        local list, home
        if SelectIsland == "Cake" then
            list, home = mastery1, CFrame.new(-1943.676513671875, 251.5095672607422, -12337.880859375)
        elseif SelectIsland == "Bone" then
            list, home = mastery2, CFrame.new(-9495.6806640625, 453.58624267578125, 5977.3486328125)
        else
            return
        end
        local inv = FX.CachedInvoke("getInventory", FX.Cfg.MasteryInvTTL, "getInventory")
        if type(inv) ~= "table" then FX.Log("mastery-sword", "getInventory không trả về bảng") return end
        local sword
        for _, it in next, inv do
            if type(it) == "table" and it.Type == "Sword" and (tonumber(it.Mastery) or 0) < 600 then
                sword = it.Name
                break
            end
        end
        if not sword then FX.Log("mastery-sword", "không có thanh kiếm nào dưới 600 mastery") return end
        SwordName = sword
        if not GetBP(sword) then
            FX.Log("mastery-sword", "thiếu " .. tostring(sword) .. " trong Backpack/Character, LoadItem")
            if FX.Gate("masterySwordLoad", FX.Cfg.RemoteGap) then
                replicated.Remotes.CommF_:InvokeServer("LoadItem", sword)
            end
            return
        end
        local v = GetConnectionEnemies(list)
        if v and FX.IsPlayerModel(v) then v = nil end
        if not v then
            if FX.Gate("masteryHome", FX.Cfg.MasteryHomeGap) then _tp(home) end
            return
        end
        local t0 = os.clock()
        repeat
            task.wait()
            if not FX.AliveMob(v) then break end
            Attack.Sword(v, _G.FarmMastery_S)
        until not _G.FarmMastery_S
            or not Attack.Alive(v)
            or not v.Parent
            or not FX.Own("Mastery")
            or os.clock() - t0 > FX.Cfg.MasteryKillTimeout
    end
end
