do
    local autoEnv = (type(getgenv) == "function" and getgenv()) or _G
    if autoEnv.AutoExecute == nil then
        autoEnv.AutoExecute = autoEnv.AutoExcuted == true
    end
    autoEnv.AutoExecute = autoEnv.AutoExecute == true
    autoEnv.AutoExcuted = autoEnv.AutoExecute

    UIX.Toggle(Tabs.Settings, "Settings_AutoExecute", {
        Title = "Auto Execute",
        Description = "Tự chạy Longxgen sau khi teleport. Chỉ sử dụng URL Longxgen đã cố định.",
        Default = autoEnv.AutoExecute,
        Callback = function(value)
            local enabled = value == true
            autoEnv.AutoExecute = enabled
            autoEnv.AutoExcuted = enabled
        end
    })

    local teleportPlayer = game:GetService("Players").LocalPlayer
    local oldConnection = autoEnv.__MaruAutoExecuteTeleportConn
    if oldConnection then
        pcall(function() oldConnection:Disconnect() end)
        autoEnv.__MaruAutoExecuteTeleportConn = nil
    end

    local autoExecuteQueued = false
    local queuePayload = [=[
repeat task.wait() until game:IsLoaded() and game:GetService("Players").LocalPlayer
local env = (type(getgenv) == "function" and getgenv()) or _G
if env.AutoExecute ~= true then
    return
end
local targetUrl = "https://raw.githubusercontent.com/nguyenhuuthanhnhan2k11-ai/Redskidhub/refs/heads/main/longxgen.lua"
local ok, source = pcall(function()
    return game:HttpGet(targetUrl)
end)
if not ok or type(source) ~= "string" or source == "" then
    warn("[Maru Auto Execute] Could not download the approved Longxgen script: " .. tostring(source))
    return
end
if type(loadstring) ~= "function" then
    warn("[Maru Auto Execute] loadstring is unavailable in this executor.")
    return
end
local compileOk, chunk = pcall(loadstring, source)
if not compileOk or type(chunk) ~= "function" then
    warn("[Maru Auto Execute] Longxgen compile failed: " .. tostring(chunk))
    return
end
local runOk, runError = pcall(chunk)
if not runOk then
    warn("[Maru Auto Execute] Longxgen execution failed: " .. tostring(runError))
end
]=]

    local function resolveQueueFunction()
        local synApi = autoEnv.syn
        if type(synApi) ~= "table" then
            pcall(function() synApi = syn end)
        end
        local queue = type(synApi) == "table" and synApi.queue_on_teleport or nil
        if type(queue) ~= "function" then queue = autoEnv.queue_on_teleport end
        if type(queue) ~= "function" then queue = autoEnv.queueteleport end
        if type(queue) ~= "function" then
            pcall(function() queue = queue_on_teleport end)
        end
        if type(queue) ~= "function" then
            pcall(function() queue = queueteleport end)
        end
        return queue
    end

    local startedState
    pcall(function() startedState = Enum.TeleportState.Started end)

    local connection = teleportPlayer.OnTeleport:Connect(function(state)
        if autoEnv.AutoExecute ~= true or autoExecuteQueued then
            return
        end

        local isStarted = state == nil or (startedState ~= nil and state == startedState)
        if not isStarted then
            local stateName = tostring(state)
            isStarted = stateName == "Started" or string.find(stateName, "Started", 1, true) ~= nil
        end
        if not isStarted then
            return
        end

        local queue = resolveQueueFunction()
        if type(queue) ~= "function" then
            warn("[Maru Auto Execute] This executor does not expose queue_on_teleport.")
            return
        end

        local ok, err = pcall(queue, queuePayload)
        if ok then
            autoExecuteQueued = true
            warn("[Maru Auto Execute] Approved Longxgen URL queued for teleport.")
        else
            warn("[Maru Auto Execute] Queue failed: " .. tostring(err))
        end
    end)

    autoEnv.__MaruAutoExecuteTeleportConn = connection
end

