-- [PHASE103] World gate + Bartilo shared helpers (PlaceId trước, level sau; thông báo tự biến mất)
do
    local noteGap = {}
    _G.MaruWorldNote = function(title, msg, dur)
        local key = tostring(title) .. "|" .. tostring(msg)
        local now = os.clock()
        if now - (noteGap[key] or -1e9) < 8 then return end
        noteGap[key] = now
        pcall(function() Library:Notify({ Title = title, Content = msg, Duration = dur or 5 }) end)
    end
    local function optOff(optId, flag)
        _G[flag] = false
        pcall(function() Library.Options[optId]:SetValue(false) end)
    end
    _G.MaruWorldOff = optOff
    -- return true = được chạy tiếp; false = đã báo + tự tắt toggle
    _G.MaruWorldGate = function(optId, flag, sea, minLv)
        local pid = game.PlaceId
        local isS2 = pid == 4442272183 or pid == 79091703265657
        local isS3 = pid == 7449423635 or pid == 100117331123089
        local title = "Auto Sea " .. tostring(sea)
        if (sea == 2 and (isS2 or isS3)) or (sea == 3 and isS3) then
            _G.MaruWorldNote(title, "Đã qua Sea " .. tostring(sea) .. " rồi" .. ((sea == 2 and isS3) and " (đang ở Sea 3)" or "") .. ", tự tắt toggle.")
            optOff(optId, flag)
            return false
        end
        if sea == 3 and not isS2 then
            _G.MaruWorldNote(title, "Cần ở Sea 2 trước khi qua Sea 3, tự tắt toggle.")
            optOff(optId, flag)
            return false
        end
        local okLv, lv = pcall(function() return plr.Data.Level.Value end)
        if not okLv or type(lv) ~= "number" then
            _G.MaruWorldNote(title, "Chưa đọc được level (UNKNOWN), chưa chạy.")
            return false
        end
        if lv < minLv then
            _G.MaruWorldNote(title, "Chưa đủ level qua Sea " .. tostring(sea) .. " (cần " .. tostring(minLv) .. ", hiện " .. tostring(lv) .. "), tự tắt toggle.")
            optOff(optId, flag)
            return false
        end
        return true
    end
    -- Một bước Bartilo (Sea 2/Dressrosa). Trả "done" khi tiến độ = 3. Nguồn: logic Maru cũ + file crack (StartQuest BartiloQuest 1).
    _G.MaruBartiloStep = function(isOn)
        local CommF = replicated.Remotes.CommF_
        local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local prog = _G.FARMX.QRead("BartiloQuestProgress", "Bartilo")
        local qv = plr.PlayerGui.Main.Quest
        if prog == 0 then
            local title = qv.Visible and tostring(qv.Container.QuestTitle.Title.Text) or ""
            if string.find(title, "Swan Pirate") then
                _G.MaruWorldNote("Bartilo", "Đang đánh Swan Pirate")
                local v = GetConnectionEnemies("Swan Pirate")
                if v then
                    repeat task.wait() Attack.Kill(v, isOn()) until not isOn() or not v.Parent or not Attack.Alive(v) or not qv.Visible
                else
                    _tp(CFrame.new(1057.92761, 137.614319, 1242.08069))
                end
            else
                if qv.Visible then pcall(function() CommF:InvokeServer("AbandonQuest") end) end
                _G.MaruWorldNote("Bartilo", "Đang nhận quest Bartilo")
                local npc = CFrame.new(-456.28952, 73.0200958, 299.895966)
                _tp(npc)
                if (hrp.Position - npc.Position).Magnitude <= 25 then
                    task.wait(0.5)
                    CommF:InvokeServer("StartQuest", "BartiloQuest", 1)
                    task.wait(0.5)
                end
            end
        elseif prog == 1 then
            _G.MaruWorldNote("Bartilo", "Đang đánh Jeremy")
            local je = GetConnectionEnemies("Jeremy")
            if je then
                repeat task.wait() Attack.Kill(je, isOn()) until not isOn() or not je.Parent or not Attack.Alive(je)
            else
                _tp(CFrame.new(2099.88159, 448.931, 648.997375))
            end
        elseif prog == 2 then
            _G.MaruWorldNote("Bartilo", "Đang chạy puzzle Bartilo")
            local stand = CFrame.new(-1836, 11, 1714)
            local t0 = os.clock()
            repeat task.wait() _tp(stand) until not isOn() or (hrp.Position - stand.Position).Magnitude < 8 or os.clock() - t0 > 25
            if not isOn() then return end
            local plates = {
                CFrame.new(-1850.49329, 13.1789551, 1750.89685), CFrame.new(-1858.87305, 19.3777466, 1712.01807),
                CFrame.new(-1803.94324, 16.5789185, 1750.89685), CFrame.new(-1858.55835, 16.8604317, 1724.79541),
                CFrame.new(-1869.54224, 15.987854, 1681.00659), CFrame.new(-1800.0979, 16.4978027, 1684.52368),
                CFrame.new(-1819.26343, 14.795166, 1717.90625), CFrame.new(-1813.51843, 14.8604736, 1724.79541),
            }
            for _, cf in ipairs(plates) do
                if not isOn() then break end
                if type(notween) == "function" then notween(cf) else hrp.CFrame = cf end
                task.wait(0.15)
            end
            task.wait(1)
        elseif prog == 3 then
            return "done"
        else
            _G.MaruWorldNote("Bartilo", "Không đọc được tiến độ Bartilo (UNKNOWN)")
        end
    end
end
