local function QM_DropFarmCanRun(ownerName, featureName)
    local fx = _G.FARMX
    if fx and fx.FH and type(fx.FH.On) == "function" and fx.FH.On() then
        return fx.Own(ownerName)
    end
    -- Safe fallback when the ordinary farm coordinator is disabled.
    if _G.FruitPickActive then return false end
    if _G.FarmBoss or _G.AutoFarmAllBoss or _G.AutoKillCursedCaptain or _G.AutoEcBoss then
        return false
    end
    if featureName == "Flail" and _G.AutoGetGravityBlade then
        return false
    end
    return true
end

local function QM_StartBossDropFarm(cfg)
    task.spawn(function()
        local inventoryAt, hasSword = 0, false
        local travelAt = 0
        while task.wait(0.4) do
            if not _G[cfg.flag] then
                continue
            end
            if not World2 then
                continue
            end
            if _G.FruitPickActive then
                continue
            end
            if not QM_DropFarmCanRun(cfg.owner, cfg.name) then
                continue
            end
            local now = os.clock()
            if now >= inventoryAt then
                inventoryAt = now + 10
                local ok, result = pcall(GetWP, cfg.item)
                hasSword = ok and result == true
                if hasSword then
                    _G[cfg.flag] = false
                    local option = Library and Library.Options and Library.Options[cfg.ui]
                    if option and option.SetValue then
                        pcall(function() option:SetValue(false) end)
                    end
                    break
                end
            end
            pcall(function()
                local char = plr.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                if not hrp or not hum or hum.Health <= 0 or not _G.SelectWeapon then return end

                local enemies = workspace:FindFirstChild("Enemies")
                local target = enemies and enemies:FindFirstChild(cfg.boss) or nil
                if not (target and target.Parent and Attack.Alive(target)
                    and target:FindFirstChild("HumanoidRootPart")) then
                    target = nil
                end

                if target and target.Parent and Attack.Alive(target)
                    and target:FindFirstChild("HumanoidRootPart") then
                    repeat
                        if not _G[cfg.flag] or not QM_DropFarmCanRun(cfg.owner, cfg.name) then break end
                        task.wait(0.12)
                        Attack.Kill(target, function()
                            return _G[cfg.flag] and QM_DropFarmCanRun(cfg.owner, cfg.name)
                        end)
                    until not target.Parent or not Attack.Alive(target)
                        or not _G[cfg.flag]
                        or not QM_DropFarmCanRun(cfg.owner, cfg.name)
                elseif now >= travelAt and (hrp.Position - cfg.spawn.Position).Magnitude > 90 then
                    travelAt = now + 4
                    _tp(cfg.spawn)
                end
            end)
        end
    end)
end

