-- [PHASE118] Race V3 engine (all races) + shared PvP helper. Logic translated from 6V3 / AutoBounty; movement via Maru _tp, FH RaceV3 stays the only scheduler.
do
local VIM = game:GetService("VirtualInputManager")
local CF = replicated.Remotes.CommF_
_G.MaruPvP = _G.MaruPvP or {}
local PVP = _G.MaruPvP
PVP.Order = { {"Melee","Z"}, {"Sword","Z"}, {"Blox Fruit","Z"}, {"Melee","X"}, {"Sword","X"}, {"Blox Fruit","X"}, {"Melee","C"}, {"Blox Fruit","C"}, {"Blox Fruit","F"} }
PVP.Idx = 0
PVP.Black = PVP.Black or {}
PVP.NextM1 = 0
PVP.NextAbility = 0

function PVP.FindTool(tip)
  for _, c in ipairs({ plr.Character, plr:FindFirstChild("Backpack") }) do
    if c then
      for _, t in ipairs(c:GetChildren()) do
        if t:IsA("Tool") and t.ToolTip == tip then return t end
      end
    end
  end
end

-- skill ready test: GUI cooldown bar collapsed + mastery level reached (6V3 v853)
function PVP.Ready(tool, key)
  local gui = plr:FindFirstChild("PlayerGui")
  local m = gui and gui:FindFirstChild("Main")
  local sk = m and m:FindFirstChild("Skills")
  local tf = sk and sk:FindFirstChild(tool.Name)
  local kf = tf and tf:FindFirstChild(key)
  local cd = kf and kf:FindFirstChild("Cooldown")
  if not cd or not cd:IsA("GuiObject") then return false end
  if cd.Size.X.Scale > 0.001 or cd.Size.X.Offset > 1 then return false end
  local lv = kf:FindFirstChild("Level")
  local need = lv and tonumber(string.match(lv.Text or "", "%d+"))
  local lvl = tool:FindFirstChild("Level")
  local have = lvl and tonumber(lvl.Value) or tonumber(tool:GetAttribute("Mastery"))
  return (not need) or (have ~= nil and have >= need)
end

function PVP.Press(key, hold)
  local kc = Enum.KeyCode[key]
  if not kc then return false end
  pcall(function() VIM:SendKeyEvent(true, kc, false, game) end)
  task.wait(math.clamp(hold or 0.1, 0.08, 0.5))
  pcall(function() VIM:SendKeyEvent(false, kc, false, game) end)
  return true
end

function PVP.AimPos(p)
  local ch = p and p.Character
  local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
  if not hrp then return nil end
  local off = hrp.AssemblyLinearVelocity * 0.12
  if off.Magnitude ~= off.Magnitude then return hrp.Position end
  if off.Magnitude > 35 then off = off.Unit * 35 end
  return hrp.Position + off
end

function PVP.M1()
  local now = os.clock()
  if now < PVP.NextM1 then return end
  PVP.NextM1 = now + 0.3
  local t = plr.Character and plr.Character:FindFirstChildOfClass("Tool")
  if not t or (t.ToolTip ~= "Melee" and t.ToolTip ~= "Sword") then return end
  pcall(function()
    local vu = game:GetService("VirtualUser")
    vu:CaptureController()
    vu:ClickButton1(Vector2.new(851, 158), workspace.CurrentCamera.CFrame)
  end)
end

-- one skill per call, rotating through the order list
function PVP.Cast(target)
  local ch = plr.Character
  local hum = ch and ch:FindFirstChildOfClass("Humanoid")
  if not hum or hum.Health <= 0 then return false end
  local n = #PVP.Order
  for i = 1, n do
    local idx = (PVP.Idx + i - 1) % n + 1
    local slot = PVP.Order[idx]
    local tool = PVP.FindTool(slot[1])
    if tool and PVP.Ready(tool, slot[2]) then
      if tool.Parent ~= ch then hum:EquipTool(tool) task.wait(0.15) end
      local ap = PVP.AimPos(target)
      if ap then MousePos = ap end
      PVP.Idx = idx
      PVP.Press(slot[2], 0.1)
      return true
    end
  end
  return false
end

-- race ability, same per-race HP rules as AutoBounty SmartAbilityUse
function PVP.Ability()
  local now = os.clock()
  if now < PVP.NextAbility then return end
  local ch = plr.Character
  local hum = ch and ch:FindFirstChildOfClass("Humanoid")
  if not hum or hum.Health <= 0 then return end
  local pct = hum.Health / math.max(1, hum.MaxHealth)
  local race = ""
  pcall(function() race = plr.Data.Race.Value end)
  local ok = false
  if race == "Mink" or race == "Ghoul" or race == "Cyborg" then ok = true
  elseif race == "Skypiea" or race == "Fishman" then ok = pct <= 0.8
  elseif race == "Human" then ok = pct <= 0.7 end
  if ok then
    PVP.NextAbility = now + 5
    pcall(function() replicated.Remotes.CommE:FireServer("ActivateAbility") end)
  end
end

local function flag(c, names)
  for _, n in ipairs(names) do
    local v = c:FindFirstChild(n)
    if v and (not v:IsA("BoolValue") or v.Value) then return true end
  end
  return false
end

-- target not hittable: safe zone / pvp disabled / forcefield (6V3 v876/v889)
function PVP.Protected(p)
  local ch = p.Character
  if not ch then return true end
  if flag(ch, { "NoPvP", "SafeZone" }) then return true end
  for _, holder in ipairs({ p, ch }) do
    for _, a in ipairs({ "PvpDisabled", "PvPDisabled", "PVPDisabled", "NoPvP" }) do
      if holder:GetAttribute(a) == true then return true end
      local bv = holder:FindFirstChild(a)
      if bv and bv:IsA("BoolValue") and bv.Value then return true end
    end
  end
  if ch:FindFirstChildOfClass("ForceField") then return true end
  local hrp = ch:FindFirstChild("HumanoidRootPart")
  local wo = workspace:FindFirstChild("_WorldOrigin")
  local sz = wo and wo:FindFirstChild("SafeZones")
  if hrp and sz then
    for _, z in ipairs(sz:GetChildren()) do
      if z:IsA("BasePart") then
        local lp = z.CFrame:PointToObjectSpace(hrp.Position)
        local h = z.Size * 0.5
        if (hrp.Position - z.Position).Magnitude <= 350 or (math.abs(lp.X) <= h.X and math.abs(lp.Y) <= h.Y and math.abs(lp.Z) <= h.Z) then return true end
      end
    end
  end
  return false
end

function PVP.Alive(p)
  local ch = p and p.Character
  local h = ch and ch:FindFirstChildOfClass("Humanoid")
  return h ~= nil and h.Health > 0 and ch:FindFirstChild("HumanoidRootPart") ~= nil
end

function PVP.LevelOf(p)
  local ok, v = pcall(function() return p.Data.Level.Value end)
  return ok and tonumber(v) or 0
end

function PVP.RaceOf(p)
  local ok, v = pcall(function() return p.Data.Race.Value end)
  return ok and v or nil
end

---------------------------------------------------------------- Race V3 engine
local RV3 = { Ready = true, Killed = {}, KilledPlayers = {}, Status = "Idle", NextHop = 0 }
_G.MaruRV3 = RV3
local FLAG = { Mink = "Auto_Mink", Human = "Auto_Human", Skypiea = "Auto_Skypiea", Fishman = "Auto_Fish", Ghoul = "Auto_Ghoul", Cyborg = "Auto_Cyborg" }
local UINAME = { Mink = "Race_AutoUpgradeMink", Human = "Race_AutoUpgradeHuman", Skypiea = "Race_AutoUpgradeAngel", Fishman = "Race_AutoUpgradeFishMan", Ghoul = "Race_AutoUpgradeGhoul", Cyborg = "Race_AutoUpgradeCyborg" }
local statusPara = UIX.Paragraph(Tabs.Race, "Para_RV3_Status", { Title = "Race V3 Status", Content = "Idle" })

local function say(s)
  RV3.Status = s
  pcall(function() statusPara:SetContent(s) end)
end

local function inv(...)
  local a = { ... }
  local ok, r = pcall(function() return CF:InvokeServer(unpack(a)) end)
  if ok then return r end
  return nil
end

local function myRace()
  local ok, v = pcall(function() return plr.Data.Race.Value end)
  return ok and v or nil
end

local function raceLevel()
  return tonumber(inv("getRaceLevel")) or 0
end

local function v3Done(race)
  if race ~= myRace() then return false end
  if raceLevel() >= 3 then return true end
  return inv("Wenlocktoad", "1") == -2
end
RV3.HasV3 = v3Done

local function hopSoon()
  if os.clock() < RV3.NextHop then return end
  RV3.NextHop = os.clock() + 25
  if type(MaruHop) == "function" then
    say("Race V3: khong co muc tieu -> hop server")
    pcall(MaruHop)
  end
end

local function setHelper(name, on)
  pcall(function() _G.FARMX.FlagCoord.Set(name, "RaceV3", on) end)
end

local function stillOn(fl)
  return _G[fl] or _G.Auto_V3Current
end

local function inSea2()
  return game.PlaceId == 4442272183 or game.PlaceId == 79091703265657
end

---- V2 (Alchemist) -- 6V3 v720 flow
local function doV2(fl)
  local bq = inv("BartiloQuestProgress", "Bartilo")
  if type(bq) == "number" and bq < 3 and not GetBP("Warrior Helmet") and type(_G.MaruBartiloStep) == "function" then
    say("Race V2: lam Bartilo truoc")
    pcall(_G.MaruBartiloStep)
    return
  end
  local st = inv("Alchemist", "1")
  if st == 0 then
    say("Race V2: nhan quest Alchemist")
    inv("Alchemist", "2")
  elseif st == 1 then
    local has1 = GetBP("Flower 1") ~= nil
    local has2 = GetBP("Flower 2") ~= nil
    local has3 = GetBP("Flower 3") ~= nil
    local f1 = workspace:FindFirstChild("Flower1") or workspace:FindFirstChild("Flower 1")
    local f2 = workspace:FindFirstChild("Flower2") or workspace:FindFirstChild("Flower 2")
    if not has1 and f1 and (f1.Transparency or 0) < 0.9 then
      say("Race V2: nhat Flower 1")
      _tp(f1.CFrame * CFrame.new(0, 1, 0))
    elseif not has2 and f2 and (f2.Transparency or 0) < 0.9 then
      say("Race V2: nhat Flower 2")
      _tp(f2.CFrame * CFrame.new(0, 1, 0))
    elseif not has3 then
      say("Race V2: kill Swan Pirate (Flower 3)")
      local v = GetConnectionEnemies("Swan Pirate")
      if v then
        repeat task.wait() Attack.Kill(v, stillOn(fl)) until GetBP("Flower 3") or not v.Parent or not Attack.Alive(v) or not stillOn(fl)
      else
        _tp(CFrame.new(980.0985107421875, 121.331298828125, 1287.2093505859375))
      end
    elseif not has1 or not has2 then
      local ct = game:GetService("Lighting").ClockTime
      local night = ct >= 18 or ct < 5
      if (not has1 and not night) or (not has2 and night) then
        say("Race V2: cho hoa spawn")
      else
        hopSoon()
      end
    else
      say("Race V2: nop Alchemist")
      _tp(CFrame.new(556.9, 38.3, 8.7))
      if plr.Character and (plr.Character.HumanoidRootPart.Position - Vector3.new(556.9, 38.3, 8.7)).Magnitude < 25 then
        inv("Alchemist", "3")
      end
    end
  elseif st == 2 then
    say("Race V2: nop quest")
    _tp(CFrame.new(556.9, 38.3, 8.7))
    inv("Alchemist", "3")
  end
end

---- player kill used by Skypiea / Ghoul V3
local function pickTarget(raceFilter, levelFilter)
  local my = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
  local best, bd = nil, math.huge
  for _, p in ipairs(game.Players:GetPlayers()) do
    if p ~= plr and PVP.Alive(p) and not RV3.KilledPlayers[p.UserId] then
      local bl = PVP.Black[p.UserId]
      if not (bl and os.clock() < bl) and not PVP.Protected(p) and not p:GetAttribute("IslandRaiding") then
        if (not raceFilter or PVP.RaceOf(p) == raceFilter) and (not levelFilter or math.abs(PVP.LevelOf(plr) - PVP.LevelOf(p)) <= 200) then
          local d = my and (p.Character.HumanoidRootPart.Position - my.Position).Magnitude or 0
          if d < bd then best, bd = p, d end
        end
      end
    end
  end
  return best
end

local function killPlayer(p, label, fl)
  local ch = p.Character
  local hum = ch and ch:FindFirstChildOfClass("Humanoid")
  if not hum then return false end
  local lastHp, lastDmg, t0, nextPvp = hum.Health, os.clock(), os.clock(), 0
  while stillOn(fl) and p.Parent and p.Character == ch and hum.Health > 0 and os.clock() - t0 < 120 do
    task.wait(0.1)
    local me = plr.Character
    local mh = me and me:FindFirstChild("HumanoidRootPart")
    local mhum = me and me:FindFirstChildOfClass("Humanoid")
    local th = ch:FindFirstChild("HumanoidRootPart")
    if not mh or not mhum or mhum.Health <= 0 or not th then break end
    if PVP.Protected(p) then PVP.Black[p.UserId] = os.clock() + 180 break end
    if os.clock() > nextPvp then nextPvp = os.clock() + 7 inv("EnablePvp") end
    say(label .. " | " .. p.Name .. " | HP " .. math.floor(hum.Health))
    _tp(CFrame.lookAt((th.CFrame * CFrame.new(0, 7, 2)).Position, th.Position))
    local d = (mh.Position - th.Position).Magnitude
    PVP.Ability()
    if d <= 60 then
      if d <= 12 then PVP.M1() end
      PVP.Cast(p)
    end
    if d > 60 or hum.Health < lastHp then
      lastDmg = os.clock()
      lastHp = hum.Health
    elseif os.clock() - lastDmg > 15 then
      PVP.Black[p.UserId] = os.clock() + 180
      say(label .. ": " .. p.Name .. " khong mat mau -> doi muc tieu")
      break
    end
  end
  MousePos = nil
  if hum.Health <= 0 then RV3.KilledPlayers[p.UserId] = true return true end
  return false
end

---- V3 per race
local BOSSES = {
  { name = "Orbitus", pos = CFrame.new(-2172.74, 103.32, -4015.03) },
  { name = "Jeremy", pos = CFrame.new(2006.93, 448.96, 853.98) },
  { name = "Diamond", pos = CFrame.new(-1576.72, 198.59, 13.72) },
}
local function v3Human(fl)
  local found = false
  for _, b in ipairs(BOSSES) do
    if not RV3.Killed[b.name] then
      local v = GetConnectionEnemies(b.name)
      if v then
        found = true
        say("Human V3 | Boss " .. b.name)
        repeat task.wait() Attack.Kill(v, stillOn(fl)) until not v.Parent or not Attack.Alive(v) or not stillOn(fl)
        if not v.Parent or not Attack.Alive(v) then RV3.Killed[b.name] = true end
        break
      end
    end
  end
  if not found then
    for _, b in ipairs(BOSSES) do
      if not RV3.Killed[b.name] then
        say("Human V3 | cho " .. b.name)
        _tp(b.pos)
        RV3.WaitBoss = RV3.WaitBoss or os.clock()
        if os.clock() - RV3.WaitBoss > 45 then RV3.WaitBoss = nil hopSoon() end
        break
      end
    end
  else
    RV3.WaitBoss = nil
  end
end

local function v3Mink(fl)
  say("Mink V3 | farm chest")
  setHelper("AutoFarmChest", true)
  inv("Wenlocktoad", "3")
  task.wait(2)
end

local function v3Skypiea(fl)
  local t = pickTarget("Skypiea", true)
  if t then
    if killPlayer(t, "Skypiea V3", fl) then say("Skypiea V3 | da ha " .. t.Name) task.wait(2) end
  else
    say("Skypiea V3 | khong co Angel hop le (+/-200 Lv)")
    RV3.NoTarget = RV3.NoTarget or os.clock()
    if os.clock() - RV3.NoTarget > 60 then RV3.NoTarget = nil hopSoon() end
  end
end

local function v3Ghoul(fl)
  local n = 0
  for _ in pairs(RV3.KilledPlayers) do n = n + 1 end
  say("Ghoul V3 | kill player " .. n .. "/5")
  if n >= 5 then
    inv("Wenlocktoad", "3")
    task.wait(1)
    if not v3Done("Ghoul") then RV3.KilledPlayers = {} end
    return
  end
  local t = pickTarget(nil, false)
  if t then
    killPlayer(t, "Ghoul V3", fl)
  else
    RV3.NoTarget = RV3.NoTarget or os.clock()
    if os.clock() - RV3.NoTarget > 60 then RV3.NoTarget = nil hopSoon() end
    task.wait(1)
  end
end

local function myBoat()
  local boats = workspace:FindFirstChild("Boats")
  if not boats then return nil end
  for _, b in ipairs(boats:GetChildren()) do
    local o = b:FindFirstChild("Owner")
    if o and tostring(o.Value) == plr.Name then return b end
  end
end
local function seaBeast()
  local f = workspace:FindFirstChild("SeaBeasts")
  if not f then return nil end
  for _, b in ipairs(f:GetChildren()) do
    local h = b:FindFirstChild("Health")
    if b:FindFirstChild("HumanoidRootPart") and h and h.Value > 0 then return b end
  end
end
local function v3Fishman(fl)
  local beast = seaBeast()
  if beast then
    say("Fishman V3 | danh Sea Beast")
    setHelper("SeaBeast1", true)
    local hp = beast:FindFirstChild("HumanoidRootPart")
    local plane = workspace.Map:FindFirstChild("WaterBase-Plane")
    local y = plane and plane.Position.Y + 200 or 200
    if hp then _tp(CFrame.new(hp.Position.X, y, hp.Position.Z)) end
    if hp and plr:DistanceFromCharacter(hp.Position) <= 500 then
      for _, tip in ipairs({ "Blox Fruit", "Melee", "Sword", "Gun" }) do
        local tool = PVP.FindTool(tip)
        if tool then
          if tool.Parent ~= plr.Character then plr.Character.Humanoid:EquipTool(tool) task.wait(0.1) end
          MousePos = hp.Position
          for _, k in ipairs({ "Z", "X", "C" }) do PVP.Press(k, 0.1) end
        end
      end
    end
    return
  end
  setHelper("SeaBeast1", false)
  local boat = myBoat()
  if not boat then
    say("Fishman V3 | mua thuyen")
    _tp(CFrame.new(-110.271713, 9.76438141, 2956.36841))
    if plr.Character and (plr.Character.HumanoidRootPart.Position - Vector3.new(-110.27, 9.76, 2956.37)).Magnitude <= 15 then
      inv("BuyBoat", "MarineBrigade")
      task.wait(2)
    end
    return
  end
  if not plr.Character.Humanoid.Sit then
    say("Fishman V3 | len thuyen")
    _tp(boat.VehicleSeat.CFrame * CFrame.new(0, 1, 0))
    task.wait(2)
    return
  end
  say("Fishman V3 | lai thuyen tim Sea Beast")
  _tp(CFrame.new(-10000000, 31, 37016.25) * CFrame.new(0, 50, 0))
end

-- cheap (non top-tier) fruit for the Cyborg turn-in, read from ItemReplicationService like 6V3 v648
local EXPENSIVE = { ["Quake-Quake"]=1, ["Buddha-Buddha"]=1, ["Love-Love"]=1, ["Spider-Spider"]=1, ["Sound-Sound"]=1, ["Phoenix-Phoenix"]=1, ["Portal-Portal"]=1, ["Rumble-Rumble"]=1, ["Pain-Pain"]=1, ["Blizzard-Blizzard"]=1, ["Gravity-Gravity"]=1, ["Mammoth-Mammoth"]=1, ["T-Rex-T-Rex"]=1, ["Gas-Gas"]=1, ["Yeti-Yeti"]=1, ["Tiger-Tiger"]=1, ["Dough-Dough"]=1, ["Shadow-Shadow"]=1, ["Venom-Venom"]=1, ["Control-Control"]=1, ["Spirit-Spirit"]=1, ["Dragon-Dragon"]=1, ["Leopard-Leopard"]=1, ["Kitsune-Kitsune"]=1, ["Creation-Creation"]=1 }
local function cheapFruit()
  local res
  pcall(function()
    local IRS = require(replicated:WaitForChild("ItemReplicationService"))
    local IC = require(replicated:WaitForChild("ItemConfig"))
    for _, it in pairs(IRS:GetItems(IRS.KEYS.QUANTITY)) do
      if it.Value and it.Value > 0 then
        local ok, cfg = pcall(function() return IC.match(it.ItemId):unwrap() end)
        if ok and cfg and cfg.Display and cfg.Display.Category == "Blox Fruit" then
          local nm = (cfg.Index and cfg.Index.StorageKey) or cfg.Display.Name
          if nm and not EXPENSIVE[nm] then res = nm return end
        end
      end
    end
  end)
  return res
end
local function fruitInHand()
  for _, c in ipairs({ plr.Character, plr.Backpack }) do
    if c then
      for _, t in ipairs(c:GetChildren()) do
        if t:IsA("Tool") and string.find(t.Name, "Fruit") then return t end
      end
    end
  end
end
local function storeFruits()
  for _, c in ipairs({ plr.Backpack, plr.Character }) do
    if c then
      for _, t in ipairs(c:GetChildren()) do
        if t:IsA("Tool") and t:FindFirstChild("EatRemote", true) then
          pcall(function() CF:InvokeServer("StoreFruit", t:GetAttribute("OriginalName") or t.Name, t) end)
        end
      end
    end
  end
end
local function v3Cyborg(fl)
  local tool = fruitInHand()
  if not tool then
    local nm = cheapFruit()
    if nm then
      say("Cyborg V3 | lay trai " .. nm .. " tu kho")
      inv("LoadFruit", nm)
      task.wait(0.5)
    else
      say("Cyborg V3 | khong co trai re -> mua Random")
      _tp(CFrame.new(-422.202271, 72.4190063, 386.306335))
      task.wait(2)
      inv("Cousin", "Buy")
      task.wait(2)
    end
    return
  end
  say("Cyborg V3 | nop trai " .. tool.Name)
  pcall(function() plr.Character.Humanoid:EquipTool(tool) end)
  task.wait(0.5)
  inv("Wenlocktoad", "3")
  task.wait(1.5)
  storeFruits()
end

local V3 = { Human = v3Human, Mink = v3Mink, Skypiea = v3Skypiea, Fishman = v3Fishman, Ghoul = v3Ghoul, Cyborg = v3Cyborg }

local function finish(race, fl)
  say(race .. " V3 DONE")
  setHelper("AutoFarmChest", false)
  setHelper("SeaBeast1", false)
  RV3.Killed, RV3.KilledPlayers = {}, {}
  _G[fl] = false
  _G.Auto_V3Current = false
  pcall(function()
    if Library and Library.Options then
      if Library.Options[UINAME[race]] then Library.Options[UINAME[race]]:SetValue(false) end
      if Library.Options["Race_AutoV3Current"] then Library.Options["Race_AutoV3Current"]:SetValue(false) end
    end
  end)
  pcall(function() if _G.FARMX.FH.NotifyDot then _G.FARMX.FH.NotifyDot("g", race .. " V3 hoan thanh", 4) end end)
end

task.spawn(function()
  while task.wait(1) do
    pcall(function()
      local race = myRace()
      local fl = race and FLAG[race]
      if not fl or not (_G[fl] or _G.Auto_V3Current) then
        if RV3.WasActive then
          RV3.WasActive = false
          setHelper("AutoFarmChest", false)
          setHelper("SeaBeast1", false)
          MousePos = nil
        end
        return
      end
      RV3.WasActive = true
      if v3Done(race) then finish(race, fl) return end
      if not inSea2() and race ~= "Cyborg" then
        say("Race V3: ve Sea 2")
        inv("TravelDressrosa")
        task.wait(8)
        return
      end
      local lvl = raceLevel()
      if lvl <= 1 then
        doV2(fl)
        return
      end
      local st = inv("Wenlocktoad", "1")
      if st == 0 then
        say(race .. " V3 | nhan quest")
        inv("Wenlocktoad", "2")
        RV3.Killed, RV3.KilledPlayers = {}, {}
      elseif st == 2 then
        say(race .. " V3 | nop quest")
        inv("Wenlocktoad", "3")
        RV3.Killed, RV3.KilledPlayers = {}, {}
        task.wait(1)
      elseif st == 1 then
        local h = V3[race]
        if h then h(fl) end
      end
    end)
  end
end)

