do
-- [PHASE118] Race V4 engine (ported from Kaitun6v4 UpgradeRace status machine). Keeps Maru's multi-tab flags.
local R4 = {Cache = {t = 0}, Last = {}}
_G.MaruRV4 = R4
local TEMPLE = Vector3.new(28310.0234, 14895.1123, 109.456741)
local ISL = {
  ["Haunted Castle"] = {CFrame.new(-9530.61, 200.86, 5763.13), {"Reborn Skeleton","Living Zombie","Demonic Soul","Possessed Mummy"}},
  ["Tiki Outpost"]   = {CFrame.new(-16490.97, 98.11, 1245.59), {"Isle Outlaw","Island Boy","Sun-kissed Warrior","Isle Champion"}},
  ["Ice Cream Island"] = {CFrame.new(-851.75, 65.82, -10932.15), {"Peanut Scout","Peanut President","Ice Cream Chef","Ice Cream Commander"}},
  ["Peanut Island"]  = {CFrame.new(-2087.06, 11.72, -10002.08), {"Peanut Scout","Peanut President"}},
  ["Great Tree"]    = {CFrame.new(2527.22, 88.01, -7554.48), {"Marine Commodore","Marine Rear Admiral"}},
  ["Port Town"]     = {CFrame.new(-172.03, 52.89, 5851.13), {"Pirate Millionaire","Pistol Billionaire"}},
}
R4.Order = {"Haunted Castle","Tiki Outpost","Ice Cream Island","Peanut Island","Great Tree","Port Town"}
local function remote(...) 
  local a = {...}
  local ok, r1, r2, r3 = pcall(function() return replicated.Remotes.CommF_:InvokeServer(unpack(a)) end)
  if ok then return r1, r2, r3 end
  return nil
end
function R4.Status(force)
  local C = R4.Cache
  if not force and C.data and tick() - C.t < 2 then return C.data end
  local s = {key = "checking", label = "CHECKING", detail = "", canTrial = false, needsTraining = false, needsPurchase = false, complete = false, cost = 0}
  local ch = plr.Character
  local en = ch and ch:FindFirstChild("RaceEnergy")
  local tr = ch and ch:FindFirstChild("RaceTransformed")
  s.energy = en and tonumber(en.Value) or 0
  s.transformed = tr and tr.Value == true or false
  if not ch then s.label = "WAITING CHARACTER"
  elseif not tr then
    local p = tonumber(remote("RaceV4Progress", "Check"))
    s.progress = p
    if p == nil then s.label = "V4 CHECK FAILED"
    elseif p >= 4 then s.label, s.canTrial = "FIRST TRIAL READY", true
    elseif p == 0 then s.label = "V4 QUEST NOT STARTED (kill rip_indra)"
    elseif p == 1 then s.label = "BEGIN V4 QUEST (Sealed King)"
    elseif p == 2 then s.label = "GO TO GREAT TREE"
    elseif p == 3 then s.label = "CONTINUE V4 QUEST"
    else s.label = "STARTING V4" end
  else
    local code, prog, cost = remote("UpgradeRace", "Check")
    code = tonumber(code)
    s.code, s.progress, s.cost = code, tonumber(prog), tonumber(cost) or 0
    if code == nil then s.label = "V4 CHECK FAILED"
    elseif code == 0 then s.label, s.canTrial = "READY FOR TRIAL", true
    elseif code == 1 or code == 3 then s.label, s.needsTraining = "TRAINING REQUIRED", true
    elseif code == 2 or code == 4 or code == 7 then s.label, s.needsPurchase = "BUY UPGRADE", true
    elseif code == 5 then s.label, s.complete = "RACE V4 COMPLETED", true
    elseif code == 6 then
      local done = math.clamp((tonumber(prog) or 2) - 2, 0, 3)
      s.label, s.needsTraining = "TRAINING " .. done .. "/3", done < 3
    elseif code == 8 then
      local left = math.max(0, 10 - (tonumber(prog) or 0))
      s.label, s.needsTraining, s.complete = "MASTERY " .. (10 - left) .. "/10", left > 0, left <= 0
    elseif code == 9 then s.label = "SPECIAL RACE PATH"
    else s.label = "STATE " .. tostring(code) end
    local tier = 0
    pcall(function() tier = tonumber(plr.Data.Race.C.Value) or 0 end)
    local want = tonumber(_G.MaruRV4TierLock) or 0
    if want > 0 and tier >= want and not s.needsPurchase then s.label, s.complete, s.needsTraining, s.canTrial = "TIER " .. tier .. " LOCKED", true, false, false end
  end
  C.t, C.data = tick(), s
  return s
end
function R4.Buy(s)
  s = s or R4.Status()
  if not s.needsPurchase then return false end
  if tick() - (R4.BuyAt or 0) < 6 then return false end
  local frag = 0
  pcall(function() frag = tonumber(plr.Data.Fragments.Value) or 0 end)
  if (s.cost or 0) > 0 and frag < s.cost then return false end
  R4.BuyAt = tick()
  local r = remote("UpgradeRace", "Buy")
  R4.Cache.t = 0
  pcall(function() _G.FARMX.Log("RaceV4", "buy upgrade -> " .. tostring(r)) end)
  return r ~= nil
end
function R4.InTemple()
  local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
  return hrp and hrp.Position.Y >= 14000 and (hrp.Position - TEMPLE).Magnitude < 3000
end
function R4.Enter()
  local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
  if not hrp then return false end
  if R4.InTemple() then return true end
  pcall(function() replicated.Remotes.CommF_:InvokeServer("RaceV4Progress", "Teleport") end)
  task.wait(1.2)
  if not R4.InTemple() then
    pcall(function()
      for _, d in ipairs(workspace.Map:GetDescendants()) do
        if d:IsA("ProximityPrompt") and d.Parent and d.Parent.Name:find("Temple") and fireproximityprompt then fireproximityprompt(d, math.huge) end
      end
    end)
    task.wait(0.8)
  end
  if not R4.InTemple() then hrp.CFrame = CFrame.new(28286.35546875, 14895.3017578125, 102.62469482421875) end
  return true
end
function R4.Crowd(cf)
  local n = 0
  for _, p in ipairs(game.Players:GetPlayers()) do
    if p ~= plr and p.Character and p.Character:FindFirstChild("HumanoidRootPart") and (p.Character.HumanoidRootPart.Position - cf.Position).Magnitude <= 1000 then n = n + 1 end
  end
  return n
end
function R4.PickIsland()
  local best, bn
  for _, name in ipairs(R4.Order) do
    local I = ISL[name]
    if I and not (R4.Bad and R4.Bad[name] and tick() - R4.Bad[name] < 120) then
      local n = R4.Crowd(I[1])
      if n <= 2 then return name end
      if not bn or n < bn then best, bn = name, n end
    end
  end
  return best or R4.Order[1]
end
function R4.Train()
  local st = R4.Status()
  if st.complete or st.canTrial or st.needsPurchase then return end
  local ch = plr.Character
  local en, tr = ch and ch:FindFirstChild("RaceEnergy"), ch and ch:FindFirstChild("RaceTransformed")
  if not en or not tr then return end
  if not tr.Value then
    if en.Value >= 1 and tick() - (R4.YAt or 0) > 2 then
      R4.YAt = tick()
      vim1:SendKeyEvent(true, "Y", false, game) task.wait(0.1) vim1:SendKeyEvent(false, "Y", false, game)
    end
  end
  R4.Isle = (R4.Isle and tick() - (R4.IsleAt or 0) < 90) and R4.Isle or R4.PickIsland()
  if R4.Isle ~= R4.IsleLast then R4.IsleAt, R4.IsleLast = tick(), R4.Isle end
  local I = ISL[R4.Isle]
  local v = GetConnectionEnemies(I[2])
  if v and Attack.Alive(v) then
    R4.HitAt = tick()
    repeat task.wait() Attack.Kill(v, _G.AcientOne) until not _G.AcientOne or not Attack.Alive(v) or not v.Parent or (R4.Status().needsPurchase)
  else
    _tp(I[1])
  end
  if tick() - (R4.HitAt or tick()) > 60 then
    R4.Bad = R4.Bad or {}
    R4.Bad[R4.Isle] = tick(); R4.Isle = nil; R4.HitAt = tick()
  end
end
