-- [T-05] Weather at Sea: Dodge Lightning / No Lightning / Remove Lighting Effect (+ restore)
-- Chèn TRƯỚC dòng:  UIX.Paragraph(Tabs.SeaEvent, "Para_73", {Title = "Crafting Items", Content = ""})
-- Cần trong scope: Tabs.SeaEvent, UIX, Library, _G.FARMX (FX, có FX.Res), game.
-- Nguồn tham chiếu TsuoHub: 62636-62667 (RaioPerto), 62668-62767 (Dodge), 62770-62802 (No Lightning), 62624-62634 (Remove).
-- Chỉ 1 worker (session token _G.__MaruWeatherLoop), nhịp 0.25s khi có toggle bật, 1s khi tắt hết. Không RenderStepped.
do
    local Lighting = game:GetService("Lighting")
    local Players = game:GetService("Players")
    local W = {
        Dodge = false, NoLightning = false, EffectRemoved = false,
        Dodges = 0, Skipped = 0, LastReason = "idle", LastDodgeAt = -1e9,
        Radius = 250, Step = 300, DodgeCooldown = 1, Poll = 0.25,
        SavedClock = nil, WroteClock = false, Atmo = nil, Token = nil, WarnedRes = false,
    }
    _G.MaruWeather = W
    local function notify(msg, dur)
        pcall(function() Library:Notify({Title = "Weather at Sea", Content = msg, Duration = dur or 4}) end)
    end
    local function resAdapter()
        local fx = _G.FARMX
        return fx and fx.Res or nil
    end
    -- Tsuo 62636: _WorldOrigin.LightningCache > child.BoltPart (Position.Y < 1e8, Transparency < 1) trong bán kính 250 stud
    W.NearestBolt = function(hrp, radius)
        local ok, res = pcall(function()
            local wo = workspace:FindFirstChild("_WorldOrigin")
            local cache = wo and wo:FindFirstChild("LightningCache")
            if not hrp or not cache then return nil end
            local kids = cache:GetChildren()
            for i = 1, #kids do
                local bolt = kids[i]:FindFirstChild("BoltPart")
                if bolt and bolt.Position.Y < 100000000 and bolt.Transparency < 1
                    and (bolt.Position - hrp.Position).Magnitude <= (radius or W.Radius) then
                    return bolt.Position
                end
            end
            return nil
        end)
        if ok then return res end
        return nil
    end
    W.DodgeOnce = function()
        local now = os.clock()
        if now - W.LastDodgeAt < W.DodgeCooldown then return false end
        local char = Players.LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return false end
        local boltPos = W.NearestBolt(hrp, W.Radius)
        if not boltPos then W.LastReason = "no-bolt" return false end
        local res = resAdapter()
        if not res then
            if not W.WarnedRes then W.WarnedRes = true warn("[Weather] FX.Res chưa có, tắt né sét để không tranh Movement") end
            W.LastReason = "no-adapter"
            return false
        end
        -- Movement chỉ lấy được khi FH.Owner == nil; farm đang giữ quyền thì bỏ qua (không tranh SeaEvent/Race/Leviathan)
        local tok, why = res.Acquire("Movement", "WeatherDodge")
        if not tok then W.Skipped = W.Skipped + 1 W.LastReason = "skip:" .. tostring(why) return false end
        W.Token = tok
        local done = false
        local ok, err = pcall(function()
            if not res.Valid(tok) then return end
            local d = hrp.Position - boltPos
            local flat = Vector3.new(d.X, 0, d.Z)
            if flat.Magnitude < 1 then flat = Vector3.new(1, 0, 0) end
            local target = hrp.Position + flat.Unit * W.Step
            local hum = char:FindFirstChildOfClass("Humanoid")
            local seat = hum and hum.SeatPart
            if seat and seat:IsA("VehicleSeat") then
                seat.CFrame = CFrame.new(target.X, seat.Position.Y, target.Z)
            else
                hrp.CFrame = CFrame.new(target)
            end
            done = true
        end)
        res.Release(tok, ok and "dodged" or "error")
        W.Token = nil
        if not ok then W.LastReason = "error:" .. tostring(err) return false end
        if done then
            W.Dodges = W.Dodges + 1
            W.LastDodgeAt = now
            W.LastReason = "dodged"
        else
            W.LastReason = "token-lost"
        end
        return done
    end
    -- No Lightning: chỉ chỉnh Lighting.ClockTime phía client (hiệu ứng local, server vẫn có thể tự đặt lại).
    W.ApplyClock = function()
        if _G.daylightN then return end -- vòng "Turn on Time" ở tab Misc đang sở hữu ClockTime
        local ok = pcall(function()
            if W.SavedClock == nil then W.SavedClock = Lighting.ClockTime end
            if math.abs(Lighting.ClockTime - 12) > 0.01 then Lighting.ClockTime = 12 end
            W.WroteClock = true
        end)
        return ok
    end
    W.RestoreClock = function()
        if W.WroteClock and W.SavedClock ~= nil and not _G.daylightN then
            pcall(function() Lighting.ClockTime = W.SavedClock end)
        end
        W.WroteClock = false
        W.SavedClock = nil
    end
    -- Remove Lighting Effect: gỡ BaseAtmosphere khỏi Lighting (không Destroy), nhớ để trả lại. Chỉ đụng đúng instance tên BaseAtmosphere.
    W.RemoveEffect = function()
        if W.EffectRemoved then return false, "already" end
        local a = Lighting:FindFirstChild("BaseAtmosphere")
        if not a then return false, "no-BaseAtmosphere" end
        local ok = pcall(function() a.Parent = nil end)
        if not ok then return false, "parent-failed" end
        W.Atmo = a
        W.EffectRemoved = true
        return true
    end
    W.RestoreEffect = function()
        if not W.EffectRemoved then return false, "not-removed" end
        local a = W.Atmo
        W.Atmo = nil
        W.EffectRemoved = false
        if not a then return false, "lost" end
        if Lighting:FindFirstChild("BaseAtmosphere") then
            pcall(function() a:Destroy() end) -- game đã tạo lại bản mới, không nhân đôi
            return true, "game-recreated"
        end
        local ok = pcall(function() a.Parent = Lighting end)
        return ok, ok and "restored" or "restore-failed"
    end
    W.ToggleEffect = function()
        if W.EffectRemoved then
            local ok, why = W.RestoreEffect()
            notify(ok and "Đã trả lại hiệu ứng ánh sáng (BaseAtmosphere)." or ("Không trả lại được: " .. tostring(why)))
        else
            local ok, why = W.RemoveEffect()
            notify(ok and "Đã gỡ hiệu ứng ánh sáng (chỉ phía client). Bấm lại để trả lại." or ("Không gỡ được: " .. tostring(why)))
        end
    end
    W.Cleanup = function()
        _G.__MaruWeatherLoop = (tonumber(_G.__MaruWeatherLoop) or 0) + 1
        W.Dodge, W.NoLightning = false, false
        W.RestoreClock()
        W.RestoreEffect()
        local res = resAdapter()
        if W.Token and res then res.Release(W.Token, "cleanup") end
        W.Token = nil
    end
    W.Status = function()
        return string.format("dodge=%s (%d lần, bỏ qua %d, %s) | noLightning=%s | effectRemoved=%s",
            tostring(W.Dodge), W.Dodges, W.Skipped, tostring(W.LastReason), tostring(W.NoLightning), tostring(W.EffectRemoved))
    end
    local myId = (tonumber(_G.__MaruWeatherLoop) or 0) + 1
    _G.__MaruWeatherLoop = myId
    task.spawn(function()
        while _G.__MaruWeatherLoop == myId do
            task.wait((W.Dodge or W.NoLightning) and W.Poll or 1)
            if _G.__MaruWeatherLoop ~= myId then break end
            if W.NoLightning then pcall(W.ApplyClock) end
            if W.Dodge then pcall(W.DodgeOnce) end
        end
    end)
    UIX.Toggle(Tabs.SeaEvent, "SeaEvent_DodgeLightning", {
        Title = "Dodge Lightning (sea storms)",
        Description = "Né tia sét trong bán kính 250 stud (Tsuo: LightningCache/BoltPart). Chỉ chạy khi không có farm nào đang giữ Movement.",
        Default = false,
        Callback = function(Value) W.Dodge = Value and true or false end
    })
    UIX.Toggle(Tabs.SeaEvent, "SeaEvent_NoLightning", {
        Title = "No Lightning (forces midday)",
        Description = "Ép ClockTime = 12 phía client (hiệu ứng local, không đảm bảo đổi thời tiết server). Tắt sẽ trả giờ cũ.",
        Default = false,
        Callback = function(Value)
            W.NoLightning = Value and true or false
            if not W.NoLightning then W.RestoreClock() end
        end
    })
end
