      local char = plr.Character
      local hrp = char and char:FindFirstChild("HumanoidRootPart")
      if not hrp then return end
      local now = os.clock()
      if now - (fx7._SeaDodgeLast or -1e9) < 0.3 then return end
      local dodge = false
      if _G.SeaBeast1 and fx7.Enable.SeabeastDodge and _G.SeabeastDodge then
        if fx7.IsSeabeastDanger and fx7.IsSeabeastDanger() then dodge = true end
      end
      if (not dodge) and _G.TerrorShark and fx7.Enable.TerrorDodge and _G.TerrorDodge then
        if fx7.IsTerrorDanger and fx7.IsTerrorDanger() then dodge = true end
      end
      if dodge then
        local h = (fx7.Cfg and fx7.Cfg.SeaDodgeHeight) or 600
        local lat = (fx7.Cfg and fx7.Cfg.SeaDodgeLateral) or 80
        _tp(CFrame.new(hrp.Position.X + lat, hrp.Position.Y + h, hrp.Position.Z + lat))
        fx7._SeaDodgeLast = now
      end
    end)
  end
