-- [T-02] Fruit Spawn Radar (chỉ quan sát + tween thủ công). Không thay Auto Collect Fruit (collectFruits dòng ~25636).
-- Nguồn tham chiếu TsuoHub: __TSUO_FrutasNoMapa 57661-57733 (quét con trực tiếp của workspace + container "*Spawner"/"Fruits",
-- Handle = child.Handle hoặc BasePart; hợp lệ = Tool ToolTip "Blox Fruit" / WeaponType "Demon Fruit" / mesh Fruit.Fruit.MeshId
-- hoặc Model có Handle + Fruit.Fruit BasePart / attr OriginalName|ItemId), camera 71754-71879 (Scriptable + CFrame.lookAt,
-- RequestStreamAroundAsync mỗi 3s, khôi phục Custom + Humanoid), thông báo 1 lần/instance (__TSUO_FrutaAvisada).
-- Quyết định Q2: camera chỉ bám trái người dùng chọn. Không tuyên bố đã nhặt trái.
do
    if type(_G.__MaruRadarCleanup) == "function" then pcall(_G.__MaruRadarCleanup) end
    local Players = game:GetService("Players")
    local TweenService = game:GetService("TweenService")
    local LP = Players.LocalPlayer
    local myId = (tonumber(_G.__MaruRadarLoop) or 0) + 1
    _G.__MaruRadarLoop = myId
    local R = {
        Radar = false, Observer = false, ShowName = true, ShowDist = true, Radius = 500,
        Sel = nil, List = {}, LabelObj = {}, Sig = "", Notified = setmetatable({}, { __mode = "k" }),
        Ids = setmetatable({}, { __mode = "k" }), NextId = 0, LastScan = -1e9, LastStream = -1e9,
        CamSaved = nil, Tok = nil, Tween = nil, Last = "off", GoneTTL = 5, ScanEvery = 1,
        ObsRec = nil, RadarRec = nil, SelRec = nil, StatusRec = nil, Conn = nil,
    }
    _G.MaruFruitRadar = R
    local function note(msg, dur)
        R.Last = msg
        pcall(function() Library:Notify({ Title = "Fruit Radar", Content = msg, Duration = dur or 4 }) end)
    end
    local function hrp()
        local c = LP.Character
        return c and c:FindFirstChild("HumanoidRootPart")
    end
    local function isFruitLike(o)
        if o:IsA("Tool") and tostring(o.ToolTip) == "Blox Fruit" then return true end
        if tostring(o:GetAttribute("WeaponType")) == "Demon Fruit" then return true end
        local ok, mesh = pcall(function()
            local f = o:FindFirstChild("Fruit")
            local f2 = f and f:FindFirstChild("Fruit")
            return f2 and f2.MeshId
        end)
        if ok and type(mesh) == "string" and #mesh > 0 then return true end
        if o:IsA("Model") and o:FindFirstChild("Handle") then
            if o:GetAttribute("OriginalName") or o:GetAttribute("ItemId") then return true end
        end
        return false
    end
    local function handleOf(o)
        return o:FindFirstChild("Handle") or (o:IsA("BasePart") and o) or o:FindFirstChildWhichIsA("BasePart", true)
    end
    local function displayName(o, part)
        return tostring(o:GetAttribute("OriginalName") or (part and part:GetAttribute("OriginalName")) or o.Name)
    end
    local function candidates()
        local roots = { workspace }
        for _, ch in ipairs(workspace:GetChildren()) do
            local n = tostring(ch.Name)
            if n:sub(-7) == "Spawner" or n == "Fruits" then roots[#roots + 1] = ch end
        end
        local out = {}
        for _, root in ipairs(roots) do
            for _, ch in ipairs(root:GetChildren()) do
                if ch ~= LP.Character and not Players:GetPlayerFromCharacter(ch) then
                    local lname = tostring(ch.Name):lower()
                    if lname:find("fruit", 1, true) and isFruitLike(ch) then
                        local part = handleOf(ch)
                        if part and part.Parent then out[#out + 1] = { obj = ch, part = part } end
                    end
                end
            end
        end
        return out
    end
    local function labelOf(e)
        local id = R.Ids[e.obj]
        if not id then R.NextId = R.NextId + 1; id = R.NextId; R.Ids[e.obj] = id end
        return e.name .. " #" .. id
    end
    R.Scan = function(force)
        local now = os.clock()
        if not force and now - R.LastScan < R.ScanEvery then return end
        R.LastScan = now
        local root = hrp()
        local seen = {}
        local byObj = {}
        for _, e in ipairs(R.List) do byObj[e.obj] = e end
        for _, c in ipairs(candidates()) do
            seen[c.obj] = true
            local e = byObj[c.obj]
            if not e then
                e = { obj = c.obj, part = c.part, first = now }
                R.List[#R.List + 1] = e
                byObj[c.obj] = e
            end
            e.part = c.part
            e.name = displayName(c.obj, c.part)
            e.lastSeen = now
            e.gone = false
            e.dist = root and math.floor((c.part.Position - root.Position).Magnitude) or nil
            e.inRange = e.dist ~= nil and e.dist <= R.Radius
            if R.Radar and e.inRange and not R.Notified[e.obj] then
                R.Notified[e.obj] = true
                note(e.name .. " xuất hiện cách " .. tostring(e.dist) .. " studs", 5)
            end
        end
        local keep = {}
        for _, e in ipairs(R.List) do
            if not seen[e.obj] then
                e.gone = true
                e.inRange = false
                if now - (e.lastSeen or now) <= R.GoneTTL then keep[#keep + 1] = e else R.Notified[e.obj] = nil end
            else
                keep[#keep + 1] = e
            end
        end
        table.sort(keep, function(a, b)
            if a.gone ~= b.gone then return not a.gone end
            return (a.dist or 1e9) < (b.dist or 1e9)
        end)
        R.List = keep
        local labels, map = {}, {}
        for _, e in ipairs(keep) do
            if not e.gone then local l = labelOf(e); labels[#labels + 1] = l; map[l] = e.obj end
        end
        R.LabelObj = map
        local sig = table.concat(labels, "|")
        if sig ~= R.Sig then
            R.Sig = sig
            if R.SelRec and R.SelRec.SetValues then pcall(R.SelRec.SetValues, R.SelRec, labels) end
        end
        if R.Sel and not seen[R.Sel] then R.Sel = nil end
    end
    R.StatusText = function()
        if #R.List == 0 then return "Không thấy trái nào trên map." end
        local lines = {}
        for i = 1, math.min(6, #R.List) do
            local e = R.List[i]
            local p = {}
            if R.ShowName then p[#p + 1] = e.name else p[#p + 1] = "Trái #" .. i end
            if R.ShowDist then p[#p + 1] = e.dist and (tostring(e.dist) .. " studs") or "?" end
            p[#p + 1] = e.gone and "ĐÃ MẤT khỏi client (không có nghĩa đã nhặt)" or (e.inRange and "trong bán kính" or "ngoài bán kính")
            lines[#lines + 1] = table.concat(p, " · ")
        end
        return table.concat(lines, "\n")
    end
    local function pushStatus()
        if R.StatusRec and R.StatusRec.SetContent then pcall(R.StatusRec.SetContent, R.StatusRec, R.StatusText()) end
    end
    -- Camera ---------------------------------------------------------------
    local function humanoid()
        local c = LP.Character
        return c and c:FindFirstChildOfClass("Humanoid")
    end
    R.CamRestore = function(why)
        local s = R.CamSaved
        R.CamSaved = nil
        if not s then return end
        pcall(function()
            local cam = workspace.CurrentCamera
            if not cam then return end
            cam.CameraType = s.Type
            local subj = s.Subject
            local hum = humanoid()
            if not subj or not subj.Parent or (subj:IsA("Humanoid") and hum and subj ~= hum) then subj = hum or subj end
            if subj then cam.CameraSubject = subj end
            if s.FOV then cam.FieldOfView = s.FOV end
        end)
    end
    local function observerOff(why, msg)
        R.CamRestore(why)
        if R.Observer then
            R.Observer = false
            if R.ObsRec and R.ObsRec.SetValue then pcall(R.ObsRec.SetValue, R.ObsRec, false) end
        end
        if msg then note(msg, 4) end
    end
    local function selEntry()
        if not R.Sel then return nil end
        for _, e in ipairs(R.List) do if e.obj == R.Sel and not e.gone then return e end end
        return nil
    end
    R.CamTick = function()
        if not (R.Radar and R.Observer) then return end
        local e = selEntry()
        if not e or not e.obj.Parent or not e.part or not e.part.Parent then
            observerOff("target-lost", "Trái đang quan sát đã biến mất, trả camera về bình thường.")
            return
        end
        local cam = workspace.CurrentCamera
        if not cam then return end
        if not R.CamSaved then R.CamSaved = { Type = cam.CameraType, Subject = cam.CameraSubject, FOV = cam.FieldOfView } end
        local now = os.clock()
        if now - R.LastStream > 3 then
            R.LastStream = now
            task.spawn(function() pcall(function() LP:RequestStreamAroundAsync(e.part.Position) end) end)
        end
        cam.CameraType = Enum.CameraType.Scriptable
        local look = e.part.CFrame.LookVector
        if look.Magnitude < 0.1 then look = Vector3.new(0, 0, 1) end
        cam.CFrame = CFrame.lookAt(e.part.Position + look * 7 + Vector3.new(0, 2, 0), e.part.Position)
    end
    -- Manual tween (Movement qua FX.Res, chỉ khi FH.Owner == nil) -------------
    R.CancelTween = function(why)
        local tok, tw = R.Tok, R.Tween
        R.Tween = nil
        if tw then pcall(function() tw:Cancel() end) end
        if tok then
            R.Tok = nil
            local fx = _G.FARMX
            if fx and fx.Res then fx.Res.Release(tok, why or "cancel") end
        end
    end
    R.ManualTween = function()
        local fx = _G.FARMX
        if not (fx and fx.Res) then note("Chưa có lớp khoá tài nguyên FH, không tween.") return end
        local e = selEntry()
        if not e then note("Chưa chọn trái hợp lệ.") return end
        local root = hrp()
        if not root or not e.obj.Parent or not e.part.Parent then note("Nhân vật hoặc trái không còn hợp lệ.") return end
        if R.Tok then note("Đang tween, bấm Cancel trước.") return end
        local tok, why = fx.Res.Acquire("Movement", "FruitRadar")
        if not tok then note("Không lấy được Movement: " .. tostring(why)) return end
        R.Tok = tok
        local goal = CFrame.new(e.part.Position + Vector3.new(0, 3, 0))
        local dist = (goal.Position - root.Position).Magnitude
        local dur = math.max(0.1, dist / 200)
        local ok, tw = pcall(function()
            return TweenService:Create(root, TweenInfo.new(dur, Enum.EasingStyle.Linear), { CFrame = goal })
        end)
        if not ok or not tw then R.CancelTween("create-fail") note("Không tạo được tween.") return end
        R.Tween = tw
        local finished = false
        tw.Completed:Connect(function() finished = true end)
        tw:Play()
        task.spawn(function()
            local name = e.name
            while R.Tok == tok and not finished do
                task.wait(0.1)
                local c = LP.Character
                if not fx.Res.Valid(tok) or not R.Radar or not e.obj.Parent or not e.part.Parent or not c or c ~= tok.char then
                    local why2 = (not fx.Res.Valid(tok)) and "bị preempt/respawn" or "mục tiêu/radar đổi"
                    R.CancelTween("watch:" .. why2)
                    note("Tween bị hủy (" .. why2 .. ").")
                    return
                end
                pcall(function() root.AssemblyLinearVelocity = Vector3.new(0, 0, 0) end)
            end
            if R.Tok == tok then
                R.CancelTween("done")
                note("Đã tới gần " .. tostring(name) .. ". Radar không nhặt trái, tự nhặt hoặc dùng Auto Collect.", 5)
            end
        end)
    end
    -- Main loop (1 vòng duy nhất, token phiên) --------------------------------
    task.spawn(function()
        while _G.__MaruRadarLoop == myId do
            if R.Radar then
                pcall(R.Scan)
                pcall(pushStatus)
                if R.Observer then pcall(R.CamTick) end
            end
            task.wait((R.Radar and R.Observer) and 0.2 or 1)
        end
    end)
    R.Conn = LP.CharacterAdded:Connect(function()
        R.CancelTween("respawn")
        observerOff("respawn", R.CamSaved and "Respawn: đã trả camera về bình thường." or nil)
    end)
    _G.__MaruRadarCleanup = function()
        _G.__MaruRadarLoop = (tonumber(_G.__MaruRadarLoop) or 0) + 1
        pcall(R.CancelTween, "cleanup")
        pcall(R.CamRestore, "cleanup")
        if R.Conn then pcall(function() R.Conn:Disconnect() end) R.Conn = nil end
    end
    -- UI (tab Raids, ngay sau Auto Collect Fruit; không thêm tab, không nhân đôi toggle Auto Collect) ----
    R.RadarRec = UIX.Toggle(Tabs.Raids, "Raids_FruitRadar", {
        Title = "Fruit Radar", Description = "Quét trái trên map, báo khi vào bán kính (chỉ quan sát)",
        Default = false,
        Callback = function(v)
            R.Radar = v == true
            if not R.Radar then
                R.CancelTween("radar-off")
                observerOff("radar-off")
                R.Last = "off"
                pushStatus()
            else
                R.Scan(true)
            end
        end
    })
    R.ObsRec = UIX.Toggle(Tabs.Raids, "Raids_FruitCamObserver", {
        Title = "Camera Observer", Description = "Camera chỉ bám trái đã chọn trong danh sách",
        Default = false,
        Callback = function(v)
            R.Observer = v == true
            if not R.Observer then R.CamRestore("observer-off") end
        end
    })
    R.SelRec = UIX.Dropdown(Tabs.Raids, "Raids_FruitRadarSelect", {
        Title = "Fruit Radar: chọn trái", Description = "Danh sách trái đang thấy (bấm Refresh để cập nhật)",
        Values = {}, Multi = false,
        Callback = function(v) R.Sel = R.LabelObj[v] end
    })
    UIX.Button(Tabs.Raids, nil, {
        Title = "Refresh Nearby Fruits", Description = "Quét lại 1 lần ngay",
        Callback = function() pcall(R.Scan, true) pcall(pushStatus) end
    })
    UIX.Toggle(Tabs.Raids, "Raids_FruitRadarShowName", {
        Title = "Show Fruit Name", Default = true,
        Callback = function(v) R.ShowName = v == true pcall(pushStatus) end
    })
    UIX.Toggle(Tabs.Raids, "Raids_FruitRadarShowDist", {
        Title = "Show Distance", Default = true,
        Callback = function(v) R.ShowDist = v == true pcall(pushStatus) end
    })
    UIX.Slider(Tabs.Raids, "Raids_FruitRadarRadius", {
        Title = "Notification Radius (studs)", Default = 500, Min = 50, Max = 5000, Rounding = 0,
        Callback = function(v) R.Radius = tonumber(v) or 500 end
    })
    UIX.Button(Tabs.Raids, nil, {
        Title = "Manual Tween to Selected Fruit", Description = "Chỉ bay tới gần trái đã chọn, không tự nhặt; nhường khi farm FH đang chạy",
        Callback = function() task.spawn(R.ManualTween) end
    })
    UIX.Button(Tabs.Raids, nil, {
        Title = "Cancel Manual Tween",
        Callback = function() R.CancelTween("user-cancel") note("Đã hủy tween.", 2) end
    })
    UIX.Button(Tabs.Raids, nil, {
        Title = "Return Camera to Normal",
        Callback = function() observerOff("user-return", "Đã trả camera về bình thường.") end
    })
    R.StatusRec = UIX.Paragraph(Tabs.Raids, "Para_FruitRadar", { Title = "Radar Status", Content = "off" })
end
do
    UIX.Dropdown(Tabs.Raids, "Raids_SelectFruitShop", {
    Title =  "Select Fruit Shop",
    Description =  "Chọn trái trong shop",
    Values =  {
        "Rocket-Rocket", "Spin-Spin", "Blade-Blade", "Spring-Spring",
        "Bomb-Bomb", "Smoke-Smoke", "Spike-Spike", "Flame-Flame",
        "Ice-Ice", "Sand-Sand", "Dark-Dark", "Eagle-Eagle",
        "Diamond-Diamond", "Light-Light", "Rubber-Rubber", "Ghost-Ghost",
        "Magma-Magma", "Quake-Quake", "Buddha-Buddha", "Love-Love",
        "Creation-Creation", "Spider-Spider", "Sound-Sound", "Phoenix-Phoenix",
        "Portal-Portal", "Lightning-Lightning", "Pain-Pain", "Blizzard-Blizzard",
        "Gravity-Gravity", "T-Rex-T-Rex", "Mammoth-Mammoth", "Dough-Dough",
        "Shadow-Shadow", "Venom-Venom", "Gas-Gas", "Control-Control",
        "Spirit-Spirit", "Leopard-Leopard", "Yeti-Yeti", "Kitsune-Kitsune",
        "Dragon-Dragon"
    },
    Callback =  function(Value)
        getgenv().SelectFruit = Value
    end
,
    Multi = false
})
