do
    UIX.Toggle(Tabs.Raids, "Raids_AutoBuyFruitShop", {
    Title =  "Auto Buy Fruit Shop",
    Description =  "Tự động mua trái trong shop (có nguy cơ thay trái đang cầm thì chỉ cảnh báo, phải bấm nút Buy 2 lần)",
    Default =  false,
    Callback =  function(Value)
        getgenv().AutoBuyFruitSniper = Value
        if not Value and _G.MaruFruitShop then
            local FSx = _G.MaruFruitShop
            FSx.AutoGen = (FSx.AutoGen or 0) + 1
            if FSx.Armed and FSx.Armed.auto then FSx.Armed = nil end
            if not FSx.Busy then FSx.State = "IDLE" end
            local fxx = _G.FARMX
            if fxx and fxx.Res and fxx.Res.Cancel then pcall(fxx.Res.Cancel, "Remote", "auto-buy-off") end
        end
    end
})
end
-- [T-06] Fruit Shop double-confirm: IDLE>VALIDATION>WARNING>ARMED>PURCHASE>VERIFY>IDLE
-- Nguồn tham chiếu: TsuoHub 72111-72236 (Buy 2 lần/8s, đọc Data.DevilFruit + Data.Beli) và 57995-58025 (poll GetFruits 5s).
-- Không gọi lặp từng khung; mỗi giao dịch xác nhận chỉ gửi PurchaseRawFruit đúng 1 lần.
do
    local RS = game:GetService("ReplicatedStorage")
    local LP = game:GetService("Players").LocalPlayer
    local FS = {
        State = "IDLE", Armed = nil, Busy = false, Last = "IDLE",
        ArmWindow = 8, Cooldown = 5, AutoPoll = 5, AutoPause = 30, AutoPauseUnknown = 120,
        NextAllowed = 0, AutoPausedUntil = 0, Buys = 0, AutoGen = 0,
    }
    _G.MaruFruitShop = FS
    local function note(msg, dur)
        FS.Last = msg
        pcall(function() Library:Notify({Title = "Fruit Shop", Content = msg, Duration = dur or 5}) end)
    end
    local function curFruit()
        local ok, r = pcall(function()
            local d = LP:FindFirstChild("Data")
            local f = d and d:FindFirstChild("DevilFruit")
            if not f then return nil end
            return tostring(f.Value)
        end)
        if not ok or r == nil then return nil end
        if r == "" then return "none" end
        return r
    end
    local function beli()
        local ok, r = pcall(function()
            local d = LP:FindFirstChild("Data")
            local b = d and d:FindFirstChild("Beli")
            return b and tonumber(b.Value) or nil
        end)
        if ok then return r end
        return nil
    end
    local function readShop(name)
        local ok, res = pcall(function() return RS.Remotes.CommF_:InvokeServer("GetFruits") end)
        if not ok or type(res) ~= "table" then return nil end
        for _, v in pairs(res) do
            if type(v) == "table" and tostring(v.Name) == tostring(name) then
                return { onSale = v.OnSale == true, price = tonumber(v.Price) }
            end
        end
        return { onSale = false, price = nil }
    end
    local function purchase(name, genAtStart)
        local fxr = _G.FARMX and _G.FARMX.Res
        local tok, lockWhy
        if fxr then
            tok, lockWhy = fxr.Acquire("Remote", "FruitShop.Purchase")
            if not tok then
                FS.State = "IDLE"; FS.Armed = nil
                FS.NextAllowed = os.clock() + 2
                note("Remote đang bận (" .. tostring(lockWhy) .. "), CHƯA gửi lệnh mua. Thử lại sau.")
                return "DEFERRED"
            end
        end
        if genAtStart ~= nil and (genAtStart ~= FS.AutoGen or not getgenv().AutoBuyFruitSniper) then
            if fxr then fxr.Release(tok, "auto-buy-cancelled-before-send") end
            FS.State = "IDLE"; FS.Armed = nil
            note("Auto Buy đã tắt trước khi gửi lệnh mua, huỷ giao dịch.")
            return "CANCELLED"
        end
        FS.State = "PURCHASE"
        local b0 = beli()
        if fxr then fxr.Atomic(tok, 1) end
        local ok = pcall(function() RS.Remotes.CommF_:InvokeServer("PurchaseRawFruit", name) end)
        if fxr then fxr.Atomic(tok, -1); fxr.Release(tok, ok and "purchase-sent" or "purchase-error") end
        FS.Buys = FS.Buys + 1
        FS.State = "VERIFY"
        task.wait(1.5)
        local b1 = beli()
        local verdict
        if b0 and b1 and b0 - b1 > 0 then
            verdict = "OK"
            note(tostring(name) .. " đã mua, trừ $" .. tostring(b0 - b1) .. " (kiểm tra kho/trái đang cầm)")
        elseif not ok then
            verdict = "FAILED"
            note("Yêu cầu mua lỗi, chưa trừ tiền. Không gửi lại.")
        else
            verdict = "UNKNOWN"
            note("UNKNOWN / CHECK INVENTORY: không thấy trừ tiền (đã có, hết hàng hoặc chưa đồng bộ).")
        end
        FS.Armed = nil
        FS.State = "IDLE"
        FS.NextAllowed = os.clock() + FS.Cooldown
        return verdict
    end
    local function locked(fn)
        if FS.Busy then return false end
        FS.Busy = true
        local ok, err = pcall(fn)
        FS.Busy = false
        if not ok then FS.State = "IDLE"; FS.Armed = nil; warn("[FruitShop] " .. tostring(err)) end
        return true
    end
    FS.Press = function()
        if os.clock() < FS.NextAllowed then note("Chờ cooldown giao dịch trước.", 3) return end
        local ran = locked(function()
            local name = getgenv().SelectFruit
            if not name then note("Chưa chọn trái trong Select Fruit Shop.") return end
            local now = os.clock()
            local a = FS.Armed
            FS.State = "VALIDATION"
            local st = readShop(name)
            local cur = curFruit()
            if a and now <= a.expires then
                if a.name ~= name or a.cur ~= cur or not st or not st.onSale or st.price ~= a.price then
                    FS.Armed = nil; FS.State = "IDLE"
                    note("Xác nhận bị hủy: trái chọn / trái đang cầm / stock đã đổi. Bấm lại để xác nhận mới.")
                    return
                end
                purchase(name)
                return
            end
            FS.Armed = nil
            if not st then FS.State = "IDLE" note("Không đọc được stock shop (UNKNOWN). Không mua.") return end
            if not st.onSale then FS.State = "IDLE" note(tostring(name) .. " không có trong shop lúc này.") return end
            FS.State = "WARNING"
            FS.Armed = { name = name, cur = cur, price = st.price, expires = os.clock() + FS.ArmWindow }
            FS.State = "ARMED"
            note("Mua " .. tostring(name) .. (st.price and (" ($" .. tostring(st.price) .. ")") or "") .. " có thể THAY trái đang cầm (" .. tostring(cur or "UNKNOWN") .. "). Bấm Buy lần nữa trong " .. FS.ArmWindow .. "s để xác nhận.", FS.ArmWindow)
        end)
        if not ran then note("Đang xử lý giao dịch, bỏ qua lần bấm này.", 2) end
    end
    FS.AutoStep = function()
        locked(function()
            local name = getgenv().SelectFruit
            if not name then return end
            local gen = FS.AutoGen
            local st = readShop(name)
            if not st or not st.onSale then FS.State = "IDLE" return end
            local cur = curFruit()
            if gen ~= FS.AutoGen or not getgenv().AutoBuyFruitSniper or getgenv().SelectFruit ~= name then FS.State = "IDLE" return end
            if cur == "none" then
                local v = purchase(name, gen)
                FS.AutoPausedUntil = os.clock() + (v == "UNKNOWN" and FS.AutoPauseUnknown or FS.AutoPause)
            else
                FS.AutoPausedUntil = os.clock() + FS.AutoPause
                FS.State = "IDLE"
                note(tostring(name) .. " đang có trong shop nhưng sẽ thay trái đang cầm (" .. tostring(cur or "UNKNOWN") .. "). Auto Buy tạm dừng: bấm nút Buy 2 lần để xác nhận.", 8)
            end
        end)
    end
    local myId = (tonumber(_G.__MaruFSLoop) or 0) + 1
    _G.__MaruFSLoop = myId
    task.spawn(function()
        while _G.__MaruFSLoop == myId do
            task.wait(FS.AutoPoll)
            if getgenv().AutoBuyFruitSniper and getgenv().SelectFruit and not FS.Busy
                and os.clock() >= FS.NextAllowed and os.clock() >= FS.AutoPausedUntil then
                pcall(FS.AutoStep)
            end
        end
    end)
    UIX.Button(Tabs.Raids, nil, {
        Title = "Buy selected fruit (bấm 2 lần để xác nhận)",
        Description = "Mua có thể THAY trái đang cầm. Lần 1: cảnh báo + kiểm tra lại stock; lần 2 trong 8s: mua đúng 1 lần.",
        Callback = function() task.spawn(FS.Press) end
    })
end
