-- [T-03] Blacksmith Upgrade Readiness Analyzer (CHỈ ĐỌC). Không worker, không craft/upgrade, không teleport, không equip.
-- Nguồn: TsuoHub 50438-50505 (ItemStats[item][1][1] = {Vật liệu = số lượng}), vật liệu 79157-79206 (RF/GetCraftPlayerData -> EtcItems, evidence C),
-- dự phòng Maru GetM (getInventory: Type=="Material", Name, Count; evidence A). Sở hữu item: getInventory theo Name (kiểu Maru GetIn).
-- Trường nào không đọc được thì UNKNOWN, không coi là 0 hay đã sở hữu.
do
    local RS = game:GetService("ReplicatedStorage")
    local BS = { Items = {}, Index = {}, At = 0, Source = "chưa đọc", Filter = "All", Sort = "Readiness", Sel = nil, Last = "chưa làm mới", Busy = false, Summary = "", Detail = "" }
    _G.MaruBlacksmith = BS
    local function note(msg, dur) BS.Last = msg pcall(function() Library:Notify({Title = "Blacksmith", Content = msg, Duration = dur or 5}) end) end
    local function readStats()
        local ok, res = pcall(function()
            local m = RS:FindFirstChild("Modules")
            local a = m and m:FindFirstChild("Asset")
            local d = a and a:FindFirstChild("ItemData")
            local s = d and d:FindFirstChild("ItemStats")
            if not s then return nil end
            return require(s)
        end)
        if ok and type(res) == "table" then return res end
        return nil
    end
    local function findCraftRemote()
        local ok, r = pcall(function()
            local m = RS:FindFirstChild("Modules")
            local net = m and m:FindFirstChild("Net")
            return net and net:FindFirstChild("RF/GetCraftPlayerData")
        end)
        if ok then return r end
        return nil
    end
    local function readMaterials()
        local rf = findCraftRemote()
        if rf then
            local ok, res = pcall(function() return rf:InvokeServer() end)
            if ok and type(res) == "table" and type(res.EtcItems) == "table" then return res.EtcItems, "RF/GetCraftPlayerData.EtcItems" end
        end
        local ok, inv = pcall(function() return RS.Remotes.CommF_:InvokeServer("getInventory") end)
        if ok and type(inv) == "table" then
            local out = {}
            for _, t in pairs(inv) do
                if type(t) == "table" and t.Type == "Material" and t.Name ~= nil then out[tostring(t.Name)] = (out[tostring(t.Name)] or 0) + (tonumber(t.Count) or 0) end
            end
            return out, "getInventory(Material)"
        end
        return nil, "không đọc được vật liệu"
    end
    local function readOwned()
        local ok, inv = pcall(function() return RS.Remotes.CommF_:InvokeServer("getInventory") end)
        if not ok or type(inv) ~= "table" then return nil end
        local set = {}
        for _, t in pairs(inv) do if type(t) == "table" and t.Name ~= nil then set[tostring(t.Name)] = true end end
        return set
    end
    -- Phân tích thuần túy, tách riêng để dễ kiểm thử.
    BS.Analyze = function(stats, mats, owned)
        local items = {}
        if type(stats) ~= "table" then return items end
        for name, v in pairs(stats) do
            local rec = type(v) == "table" and type(v[1]) == "table" and v[1][1]
            if type(rec) == "table" and next(rec) ~= nil then
                local need, have, miss, bad = 0, 0, {}, false
                local list = {}
                for mat, qty in pairs(rec) do
                    local q = tonumber(qty)
                    if not q or q < 0 then bad = true
                    else
                        local h = mats and (tonumber(mats[mat]) or 0) or nil -- bảng vật liệu đọc được: vắng mặt = 0 (Tsuo 50482); không đọc được bảng: nil = UNKNOWN
                        list[#list + 1] = { name = tostring(mat), need = q, have = h }
                        if h == nil then bad = true else
                            need = need + q
                            have = have + math.min(h, q)
                            if h < q then miss[#miss + 1] = { name = tostring(mat), need = q, have = h, missing = q - h } end
                        end
                    end
                end
                table.sort(list, function(a, b) return a.name < b.name end)
                table.sort(miss, function(a, b) return a.name < b.name end)
                local it = { name = tostring(name), mats = list, missing = miss, owned = owned and (owned[tostring(name)] and "owned" or "not owned") or "UNKNOWN" }
                if bad or mats == nil then
                    it.status, it.pct = "Unknown", nil
                else
                    it.pct = need > 0 and math.floor(have / need * 100 + 0.5) or 100
                    if #miss == 0 then it.status = "Ready"
                    elseif it.pct >= 80 then it.status = "Almost Ready"
                    else it.status = "Missing Materials" end
                end
                items[#items + 1] = it
            end
        end
        return items
    end
    BS.Sorted = function(items, filter, sort)
        local out = {}
        for _, it in ipairs(items) do
            if filter == "All" or (filter == "Ready" and it.status == "Ready") or (filter == "Almost" and it.status == "Almost Ready")
                or (filter == "Missing" and it.status == "Missing Materials") or (filter == "Unknown" and it.status == "Unknown") then out[#out + 1] = it end
        end
        table.sort(out, function(a, b)
            if sort == "Name" then return a.name < b.name end
            local pa, pb = a.pct or -1, b.pct or -1
            if pa ~= pb then return pa > pb end
            return a.name < b.name
        end)
        return out
    end
    BS.Summarize = function(items)
        local c = { Ready = 0, ["Almost Ready"] = 0, ["Missing Materials"] = 0, Unknown = 0 }
        local best
        for _, it in ipairs(items) do
            c[it.status] = (c[it.status] or 0) + 1
            if it.status ~= "Ready" and it.pct and (not best or it.pct > best.pct or (it.pct == best.pct and #it.missing < #best.missing)) then best = it end
        end
        local tot = {}
        for _, it in ipairs(items) do
            if it.status == "Almost Ready" or it.status == "Missing Materials" then
                for _, m in ipairs(it.missing) do tot[m.name] = (tot[m.name] or 0) + m.missing end
            end
        end
        local arr = {}
        for k, v in pairs(tot) do arr[#arr + 1] = { k, v } end
        table.sort(arr, function(a, b) if a[2] ~= b[2] then return a[2] > b[2] end return a[1] < b[1] end)
        local top = {}
        for i = 1, math.min(5, #arr) do top[#top + 1] = arr[i][1] .. " x" .. arr[i][2] end
        local s = string.format("Sẵn sàng: %d | Gần đủ (>=80%%): %d | Thiếu vật liệu: %d | Không rõ công thức/số liệu: %d | Tổng công thức: %d",
            c.Ready, c["Almost Ready"], c["Missing Materials"], c.Unknown, #items)
        if best then s = s .. "\nNâng cấp gần nhất: " .. best.name .. " (" .. tostring(best.pct) .. "%, thiếu " .. #best.missing .. " loại)" end
        if #top > 0 then s = s .. "\nThiếu nhiều nhất: " .. table.concat(top, ", ") end
        return s
    end
    BS.DetailText = function(it)
        if not it then return "Chưa chọn item." end
        local lines = { it.name .. " · " .. it.status .. (it.pct and (" · " .. it.pct .. "%") or "") .. " · sở hữu: " .. it.owned }
        for _, m in ipairs(it.mats) do
            lines[#lines + 1] = string.format("- %s: %s/%d", m.name, m.have ~= nil and tostring(m.have) or "UNKNOWN", m.need)
        end
        return table.concat(lines, "\n")
    end
    local SumRec, DetRec, SelRec
    local function render()
        local list = BS.Sorted(BS.Items, BS.Filter, BS.Sort)
        local labels = {}
        BS.Index = {}
        for i = 1, math.min(#list, 60) do
            local it = list[i]
            local l = it.name .. " [" .. it.status .. (it.pct and (" " .. it.pct .. "%") or "") .. "]"
            labels[#labels + 1] = l
            BS.Index[l] = it
        end
        if SelRec and SelRec.SetValues then pcall(SelRec.SetValues, SelRec, labels) end
        local txt = BS.Summary .. "\nNguồn vật liệu: " .. tostring(BS.Source) .. " (chỉ đọc)"
        if #list > 60 then txt = txt .. "\nDanh sách chọn chỉ hiện 60 mục đầu theo bộ lọc." end
        if SumRec and SumRec.SetContent then pcall(SumRec.SetContent, SumRec, txt) end
        if DetRec and DetRec.SetContent then pcall(DetRec.SetContent, DetRec, BS.DetailText(BS.Sel)) end
    end
    BS.Refresh = function()
        if BS.Busy then return end
        BS.Busy = true
        local ok, err = pcall(function()
            local stats = readStats()
            if not stats then BS.Items, BS.Summary = {}, "Không đọc được ItemStats (UNKNOWN)." BS.Source = "ItemStats không có" render() note("Không đọc được công thức nâng cấp.") return end
            local mats, src = readMaterials()
            local owned = readOwned()
            BS.Source = src
            BS.Items = BS.Analyze(stats, mats, owned)
            BS.Summary = BS.Summarize(BS.Items)
            BS.At = os.clock()
            BS.Sel = nil
            render()
            note("Đã làm mới: " .. #BS.Items .. " công thức.", 3)
        end)
        BS.Busy = false
        if not ok then warn("[Blacksmith] " .. tostring(err)) note("Lỗi khi phân tích, không đổi dữ liệu.") end
    end
    UIX.Paragraph(Tabs.Raids, "Para_BSHeader", { Title = "🔨 Blacksmith Upgrade Readiness (chỉ đọc)", Content = "Không craft, không nâng cấp, không đổi vũ khí. Bấm Refresh để đọc." })
    UIX.Button(Tabs.Raids, nil, { Title = "Refresh Blacksmith Analyzer", Description = "Đọc công thức + vật liệu hiện có (1 lần, có cache)", Callback = function() task.spawn(BS.Refresh) end })
    UIX.Dropdown(Tabs.Raids, "Raids_BSFilter", { Title = "Blacksmith: lọc", Values = {"All", "Ready", "Almost", "Missing", "Unknown"}, Default = "All", Multi = false,
        Callback = function(v) BS.Filter = tostring(v or "All") render() end })
    UIX.Dropdown(Tabs.Raids, "Raids_BSSort", { Title = "Blacksmith: sắp xếp", Values = {"Readiness", "Name"}, Default = "Readiness", Multi = false,
        Callback = function(v) BS.Sort = tostring(v or "Readiness") render() end })
    SelRec = UIX.Dropdown(Tabs.Raids, "Raids_BSItem", { Title = "Blacksmith: chi tiết item", Description = "Chọn sau khi Refresh", Values = {}, Multi = false,
        Callback = function(v) BS.Sel = BS.Index[v] if DetRec and DetRec.SetContent then pcall(DetRec.SetContent, DetRec, BS.DetailText(BS.Sel)) end end })
    SumRec = UIX.Paragraph(Tabs.Raids, "Para_BSSummary", { Title = "Blacksmith Summary", Content = "chưa làm mới" })
    DetRec = UIX.Paragraph(Tabs.Raids, "Para_BSDetail", { Title = "Blacksmith Detail", Content = "Chưa chọn item." })
end
-- [T-04] Trinket catalogue + Dungeon Hub status (CHỈ ĐỌC). Không đụng Buy/Fuse/Refine/Scrap, không teleport, không worker.
-- Nguồn TsuoHub 54748-55130: ReplicatedStorage.AccessoriesShared (GetAllTrinketNames, GetLevelRequirementFromGrade, GetGradeSuffix,
-- GetReforgeCost, GetTrinketData(name).Stats[grade]); Data.Level, Data["Simulation Data"]; DungeonShared.DataRemote:InvokeServer("GetData")
-- (CurrentEnergy, DataForDungeonTypes[loại].UnlockedDifficulties[độ khó].MaxFloorReached); dự phòng RF/DungeonNPCNetworkFunction "GetDungeonEnergy".
-- Trường không đọc được hiển thị UNKNOWN (Q4), không coi là 0/khóa. Đang đeo/sở hữu trinket: chưa có nguồn đọc nên UNKNOWN.
do
    local RS = game:GetService("ReplicatedStorage")
    local LP = game:GetService("Players").LocalPlayer
    local TI = { Names = {}, Sel = nil, Summary = "chưa đọc", Detail = "Chưa chọn trinket.", Dungeon = "chưa đọc" }
    _G.MaruTrinketInfo = TI
    local DUNGEON_PLACE = 73902483975735 -- Maru DUNGEON_PLACE_ID
    local function note(msg, dur) pcall(function() Library:Notify({Title = "Trinket / Dungeon", Content = msg, Duration = dur or 4}) end) end
    local function shared()
        local ok, r = pcall(function() return require(RS:WaitForChild("AccessoriesShared", 5)) end)
        if ok and type(r) == "table" then return r end
        return nil
    end
    local function call(mod, fn, ...)
        local f = mod and mod[fn]
        if type(f) ~= "function" then return nil end
        local ok, r = pcall(f, ...)
        if ok then return r end
        return nil
    end
    -- Hàm thuần: nhận module giả/thật + level + simulation data.
    TI.Catalogue = function(mod, level, sim)
        if not mod then return nil, "UNKNOWN: không đọc được AccessoriesShared" end
        local names = call(mod, "GetAllTrinketNames")
        if type(names) ~= "table" then return nil, "UNKNOWN: không đọc được danh sách trinket" end
        local list = {}
        for _, v in ipairs(names) do list[#list + 1] = tostring(v) end
        table.sort(list)
        local maxG = 0
        for i = 1, 12 do
            if tonumber(call(mod, "GetLevelRequirementFromGrade", i)) then maxG = i else break end
        end
        local grades, open = {}, 0
        for i = 1, maxG do
            local req = tonumber(call(mod, "GetLevelRequirementFromGrade", i))
            local suf = call(mod, "GetGradeSuffix", i)
            local unlocked = level and req and req <= level or nil
            if unlocked then open = open + 1 end
            grades[#grades + 1] = string.format("%s=lv%s%s", suf and tostring(suf) or tostring(i), tostring(req), level == nil and "" or (unlocked and " ✓" or " ✗"))
        end
        local costs, same = {}, true
        for i = 1, maxG do
            costs[i] = tonumber(call(mod, "GetReforgeCost", i))
            if costs[i] ~= costs[1] then same = false end
        end
        local reforge
        if maxG == 0 then reforge = "UNKNOWN"
        elseif same and costs[1] then reforge = string.format("%d (cùng giá mọi grade)", costs[1])
        else
            local t = {}
            for i = 1, maxG do t[i] = costs[i] and tostring(costs[i]) or "UNKNOWN" end
            reforge = table.concat(t, "/") .. " theo grade"
        end
        local fuse = maxG > 0 and string.format("ghép 3 trinket cùng loại+grade; cần %d grade I để lên grade %d (theo chữ trong TsuoHub, chưa kiểm chứng trong game)", 3 ^ (maxG - 1), maxG) or "UNKNOWN"
        local s = string.format("%d trinket | grade: %s | level của bạn: %s, mở %s/%d grade | reforge: %s Simulation Data (bạn có %s) | fusion: %s | đang đeo/sở hữu: UNKNOWN",
            #list, #grades > 0 and table.concat(grades, " ") or "UNKNOWN", level and tostring(level) or "UNKNOWN",
            level and tostring(open) or "UNKNOWN", maxG, reforge, sim and tostring(sim) or "UNKNOWN", fuse)
        return list, s
    end
    TI.Detail = function(mod, name)
        if not mod then return name .. ": UNKNOWN (không đọc được AccessoriesShared)" end
        local d = call(mod, "GetTrinketData", name)
        if type(d) ~= "table" or type(d.Stats) ~= "table" then return name .. ": UNKNOWN (không có dữ liệu stat)" end
        local out = {}
        for i = 1, #d.Stats do
            local st = d.Stats[i]
            if type(st) == "table" then
                local t = {}
                for k, v in pairs(st) do t[#t + 1] = tostring(k) .. " +" .. tostring(v) end
                table.sort(t)
                local suf = call(mod, "GetGradeSuffix", i)
                out[#out + 1] = (suf and tostring(suf) or tostring(i)) .. ": " .. table.concat(t, ", ")
            end
        end
        if #out == 0 then return name .. ": UNKNOWN (stat rỗng)" end
        return name .. " | " .. table.concat(out, "   ")
    end
    -- Dungeon Hub: nhận response của DataRemote "GetData" hoặc nil.
    TI.DungeonText = function(resp, inPlace, npcText)
        local where = inPlace and "đang ở map Dungeon" or "không ở map Dungeon"
        if type(resp) ~= "table" or not tonumber(resp.CurrentEnergy) then
            if type(npcText) == "string" then
                local e = tonumber(npcText:match("has%s+(%d+)%s+energy"))
                return string.format("%s | energy %s | độ khó/floor: UNKNOWN | trạng thái dungeon hiện tại: UNKNOWN", where, e and tostring(e) or "UNKNOWN (" .. npcText:sub(1, 80) .. ")")
            end
            return where .. " | energy UNKNOWN | độ khó/floor UNKNOWN | trạng thái UNKNOWN (không đọc được DataRemote/NPC)"
        end
        local parts = {}
        local types = type(resp.DataForDungeonTypes) == "table" and resp.DataForDungeonTypes or {}
        for k, d in pairs(types) do
            local diffs, top = {}, nil
            local ud = type(d) == "table" and type(d.UnlockedDifficulties) == "table" and d.UnlockedDifficulties or {}
            for dk, info in pairs(ud) do
                diffs[#diffs + 1] = tostring(dk)
                local f = tonumber(type(info) == "table" and info.MaxFloorReached)
                if f and (not top or f > top) then top = f end
            end
            table.sort(diffs)
            parts[#parts + 1] = string.format("%s (%s, floor cao nhất %s)", tostring(k), #diffs > 0 and table.concat(diffs, "/") or "UNKNOWN", top and tostring(top) or "UNKNOWN")
        end
        table.sort(parts)
        return string.format("%s | energy %d | %s | floor hiện tại/trạng thái run: UNKNOWN (chưa có nguồn đọc)",
            where, tonumber(resp.CurrentEnergy), #parts > 0 and table.concat(parts, ", ") or "chưa có loại dungeon nào hoàn thành")
    end
    local SumRec, DetRec, SelRec, DunRec
    local function level() local ok, v = pcall(function() return tonumber(LP.Data.Level.Value) end) return ok and v or nil end
    local function simData() local ok, v = pcall(function() return tonumber(LP.Data["Simulation Data"].Value) end) return ok and v or nil end
    TI.Refresh = function()
        local mod = shared()
        local list, s = TI.Catalogue(mod, level(), simData())
        TI.Names, TI.Summary = list or {}, s
        TI.Mod = mod
        if SelRec and SelRec.SetValues then pcall(SelRec.SetValues, SelRec, TI.Names) end
        if SumRec and SumRec.SetContent then pcall(SumRec.SetContent, SumRec, s) end
    end
    TI.RefreshDungeon = function()
        local resp
        pcall(function()
            local dr = RS:FindFirstChild("DungeonShared")
            dr = dr and dr:FindFirstChild("DataRemote")
            if dr then resp = dr:InvokeServer("GetData") end
        end)
        local npc
        if type(resp) ~= "table" or not tonumber(resp.CurrentEnergy) then
            pcall(function()
                local m = RS:FindFirstChild("Modules")
                local net = m and m:FindFirstChild("Net")
                local rf = net and net:FindFirstChild("RF/DungeonNPCNetworkFunction")
                if rf then
                    local r = rf:InvokeServer("GetDungeonEnergy")
                    npc = type(r) == "table" and type(r.Text) == "table" and table.concat(r.Text, " ") or (r ~= nil and tostring(r) or nil)
                end
            end)
        end
        TI.Dungeon = TI.DungeonText(resp, game.PlaceId == DUNGEON_PLACE, npc) .. " | cập nhật " .. os.date("%H:%M:%S")
        if DunRec and DunRec.SetContent then pcall(DunRec.SetContent, DunRec, TI.Dungeon) end
    end
    UIX.Paragraph(Tabs.Raids, "Para_TIHeader", { Title = "💍 Trinket Catalogue + Dungeon Hub (chỉ đọc)", Content = "Dữ liệu thiếu hiển thị UNKNOWN. Không mua/ghép/reforge/scrap, không teleport." })
    UIX.Button(Tabs.Raids, nil, { Title = "Refresh Trinket Catalogue", Description = "Đọc AccessoriesShared 1 lần", Callback = function() task.spawn(function() local ok, e = pcall(TI.Refresh) if not ok then warn("[TrinketInfo] " .. tostring(e)) note("Lỗi đọc catalogue.") end end) end })
    SelRec = UIX.Dropdown(Tabs.Raids, "Raids_TIRing", { Title = "Trinket: xem stat theo grade", Values = {}, Multi = false,
        Callback = function(v) TI.Sel = v if v and DetRec and DetRec.SetContent then pcall(DetRec.SetContent, DetRec, TI.Detail(TI.Mod or shared(), tostring(v))) end end })
    SumRec = UIX.Paragraph(Tabs.Raids, "Para_TISummary", { Title = "Trinket Summary", Content = "chưa đọc" })
    DetRec = UIX.Paragraph(Tabs.Raids, "Para_TIDetail", { Title = "Trinket Detail", Content = "Chưa chọn trinket." })
    UIX.Button(Tabs.Raids, nil, { Title = "Refresh Dungeon Hub Status", Description = "Chỉ đọc năng lượng/độ khó/floor", Callback = function() task.spawn(function() local ok, e = pcall(TI.RefreshDungeon) if not ok then warn("[DungeonStatus] " .. tostring(e)) note("Lỗi đọc Dungeon Hub.") end end) end })
    DunRec = UIX.Paragraph(Tabs.Raids, "Para_TIDungeon", { Title = "Dungeon Hub Status", Content = "chưa đọc" })
end
