            pcall(function()
                local char = plr.Character
                if not char or not char:FindFirstChild("HumanoidRootPart") then return end
                local mode = _G.QF_TrinketMode
                local accRemote = replicated.Remotes:FindFirstChild("AccessoryInteract")
                if mode == "Buy" then
                    if accRemote then
                        pcall(function() accRemote:InvokeServer("d") end)
                    else
                        pcall(function()
                            replicated.Remotes.CommF_:InvokeServer("AccessoryInteract", "d")
                        end)
                    end
                    task.wait(1.5)
                elseif mode == "Fuse" then
                    local uids = {}
                    pcall(function()
                        local result = replicated.Modules.Net:FindFirstChild("GetAllItemValues"):InvokeServer()
                        if result then
                            for _, v in next, result, nil do
                                local isTrinket = (v.Key == "AccessoryType" and v.Value == "Trinket")
                                              or (v.Key == "Type" and v.Value == "Trinket")
                                if isTrinket and v.NetworkedUID then
                                    table.insert(uids, v.NetworkedUID)
                                end
                            end
                        end
                    end)
                    if #uids >= 3 and accRemote then
                        pcall(function() accRemote:InvokeServer("a", uids[1], uids[2], uids[3]) end)
                    end
                    task.wait(2)
                elseif mode == "Refine" then
                    local uids = {}
                    pcall(function()
                        local result = replicated.Modules.Net:FindFirstChild("GetAllItemValues"):InvokeServer()
                        if result then
                            for _, v in next, result, nil do
                                local isTrinket = (v.Key == "AccessoryType" and v.Value == "Trinket")
                                              or (v.Key == "Type" and v.Value == "Trinket")
                                if isTrinket and v.NetworkedUID then
                                    table.insert(uids, v.NetworkedUID)
                                end
                            end
                        end
                    end)
                    if #uids >= 1 and accRemote then
                        pcall(function() accRemote:InvokeServer("c", uids[1]) end)
                    end
                    task.wait(2)
                elseif mode == "Scrap" then
                    local uids = {}
                    pcall(function()
                        local result = replicated.Modules.Net:FindFirstChild("GetAllItemValues"):InvokeServer()
                        if result then
                            for _, v in next, result, nil do
                                local isTrinket = (v.Key == "AccessoryType" and v.Value == "Trinket")
                                              or (v.Key == "Type" and v.Value == "Trinket")
                                if isTrinket and v.NetworkedUID then
                                    table.insert(uids, v.NetworkedUID)
                                end
                            end
                        end
                    end)
                    if #uids > 3 and accRemote then
                        local scrap = {}
                        for i = 4, math.min(#uids, 10) do table.insert(scrap, uids[i]) end
                        if #scrap > 0 then
                            pcall(function() accRemote:InvokeServer("b", scrap) end)
                        end
                    end
                    task.wait(3)
                end
            end)
        end
    end)
end
