_G.MT_SelectRace = _G.MT_SelectRace or "All"
_G.MT_Delay = _G.MT_Delay or 3
local MT_StuckAt = 0
local MT_LastTier = -1
spawn(function()
    while wait(1) do
        pcall(function()
            if not _G.MT_Master then
                pcall(function() if MT_Status and MT_Status.SetDesc then MT_Status:SetDesc("Idle") end end)
                MT_StuckAt = 0
                MT_LastTier = -1
                return
            end
            local raceData = plr and plr:FindFirstChild("Data") and plr.Data:FindFirstChild("Race")
            if not raceData then
                pcall(function() if MT_Status and MT_Status.SetDesc then MT_Status:SetDesc("Waiting for player data...") end end)
                return
            end
            local race = tostring(raceData.Value)
            local tier = 0
            pcall(function() tier = tonumber(raceData.C.Value) or 0 end)
            local target = _G.MT_SelectRace
            if target ~= "All" and target ~= race then
                pcall(function() if MT_Status and MT_Status.SetDesc then MT_Status:SetDesc("Race mismatch: current=" .. race .. " target=" .. target) end end)
                return
            end
            _G.FARMX.FlagCoord.Set("Complete_Trials", "MT", true)
            if _G.MT_AutoPullLever then _G.FARMX.FlagCoord.Set("Lver", "MT", true) end
            if _G.MT_AutoTrainV4 then _G.FARMX.FlagCoord.Set("AcientOne", "MT", true) end
            if tier == MT_LastTier then
                MT_StuckAt = MT_StuckAt + 1
            else
                MT_StuckAt = 0
                MT_LastTier = tier
            end
            local stuckMin = math.floor(MT_StuckAt / 60)
            local statusLine = "Race=" .. race .. " | Tier=" .. tostring(tier) .. "/3 | Stuck=" .. tostring(stuckMin) .. "m"
            if MT_StuckAt >= 300 and _G.MT_HopOnStuck then
                statusLine = statusLine .. " | HOPPING"
                pcall(function() if MT_Status and MT_Status.SetDesc then MT_Status:SetDesc(statusLine) end end)
                _G.FARMX.FlagCoord.Set("Complete_Trials", "MT", false)
                _G.FARMX.FlagCoord.Set("Lver", "MT", false)
                _G.FARMX.FlagCoord.Set("AcientOne", "MT", false)
                task.wait(1)
                pcall(function() if MaruHop then MaruHop() end end)
            else
                pcall(function() if MT_Status and MT_Status.SetDesc then MT_Status:SetDesc(statusLine) end end)
            end
        end)
    end
end)

