local RD_Status = UIX.Paragraph(Tabs.Raids, "Para_RD_02", {Title = "Raid Status", Content = "Idle"})
_G.RD_SelectChip = _G.RD_SelectChip or "Flame"
_G.RD_Delay = _G.RD_Delay or 10
_G.RD_MaxRuns = _G.RD_MaxRuns or 0
local RD_RunCount = 0
local RD_Phase = "idle"
local RD_PhaseAt = 0
spawn(function()
    while wait(1) do
        pcall(function()
            if not _G.RD_Master then
                if RD_Phase ~= "idle" then
                    RD_Phase = "idle"
                    RD_PhaseAt = os.clock()
                end
                pcall(function() if RD_Status and RD_Status.SetDesc then RD_Status:SetDesc("Idle | Runs=" .. tostring(RD_RunCount)) end end)
                return
            end
            local now = os.clock()
            local phaseAge = now - RD_PhaseAt
            local inDun = false
            pcall(function() if type(inDungeonPlace) == "function" then inDun = inDungeonPlace() or false end end)
            local line = "Phase=" .. RD_Phase .. " | Age=" .. tostring(math.floor(phaseAge)) .. "s | Runs=" .. tostring(RD_RunCount) .. " | InDungeon=" .. tostring(inDun)
            if RD_Phase == "buy" then
                if phaseAge > 20 then RD_Phase = "start"; RD_PhaseAt = now end
            elseif RD_Phase == "start" then
                if inDun then
                    RD_Phase = "farming"; RD_PhaseAt = now
                    if _G.RD_AutoFarm then
                        _G.FARMX.FlagCoord.Set("AutoFarmDungeon", "RD", true)
                        _G.FARMX.FlagCoord.Set("AutoFarm_DungeonFix", "RD", true)
                    end
                    if _G.RD_AutoSelectCard then _G.FARMX.FlagCoord.Set("AutoSelectCard", "RD", true) end
                elseif phaseAge > 30 then
                    RD_Phase = "buy"; RD_PhaseAt = now
                end
            elseif RD_Phase == "farming" then
                if not inDun and phaseAge > 5 then
                    RD_Phase = "ended"; RD_PhaseAt = now
                    _G.FARMX.FlagCoord.Set("AutoFarmDungeon", "RD", false)
                    _G.FARMX.FlagCoord.Set("AutoFarm_DungeonFix", "RD", false)
                    _G.FARMX.FlagCoord.Set("AutoSelectCard", "RD", false)
                    _G.FARMX.RaidCoord.Release("RD")
                    RD_RunCount = RD_RunCount + 1
                end
            elseif RD_Phase == "ended" then
                if _G.RD_MaxRuns > 0 and RD_RunCount >= _G.RD_MaxRuns then
                    _G.RD_Master = false
                    line = "DONE | Runs=" .. tostring(RD_RunCount) .. "/" .. tostring(_G.RD_MaxRuns)
                    pcall(function() if RD_Status and RD_Status.SetDesc then RD_Status:SetDesc(line) end end)
                    return
                end
                if phaseAge > (_G.RD_Delay or 10) then
                    if _G.RD_HopOnEnd then
                        line = line .. " | HOPPING"
                        pcall(function() if RD_Status and RD_Status.SetDesc then RD_Status:SetDesc(line) end end)
                        pcall(function() if MaruHop then MaruHop() end end)
                        RD_Phase = "buy"; RD_PhaseAt = os.clock()
                    else
                        RD_Phase = "buy"; RD_PhaseAt = now
                    end
                end
            elseif RD_Phase == "idle" then
                RD_Phase = "buy"; RD_PhaseAt = now
            end
            if RD_Phase == "buy" and _G.RD_AutoBuyChip then
                pcall(function()
                    _G.SelectChip = _G.RD_SelectChip
                    if not GetBP("Special Microchip") then
                        replicated.Remotes.CommF_:InvokeServer("RaidsNpc", "Select", _G.RD_SelectChip)
                    end
                end)
            elseif RD_Phase == "start" and _G.RD_AutoStart then
                pcall(function()
                    _G.SelectChip = _G.RD_SelectChip
                    _G.FARMX.RaidCoord.Claim("RD")
                end)
            end
            pcall(function() if RD_Status and RD_Status.SetDesc then RD_Status:SetDesc(line) end end)
        end)
    end
end)

