do
    UIX.Toggle(Tabs.Main, "Main_AutoSafeChest", {
        Title = "Auto Safe Chest",
        Description = "Tat chest farming khi phat hien vat pham bao ve. Phai bat lai thu cong.",
        Default = false,
        Callback = function(v) _G.AutoSafeChest = v end
    })
end
local SC_Status = UIX.Paragraph(Tabs.Main, "Para_SC_02", {Title = "Safe Chest Status", Content = "Idle"})
local SC_ProtectedItems = {
    "God's Chalice",
    "Fist of Darkness",
    "Sweet Chalice",
    "Hallow Essence",
    "Core Brain",
    "Special Microchip",
    "Microchip",
    "Skull Guitar",
    "Dragonstorm"
}
local SC_Triggered = false
spawn(function()
    while wait(1) do
        pcall(function()
            if not _G.AutoSafeChest then
                SC_Triggered = false
                pcall(function() if SC_Status and SC_Status.SetDesc then SC_Status:SetDesc("Idle") end end)
                return
            end
            local detected = nil
            for _, itemName in ipairs(SC_ProtectedItems) do
                local has = false
                pcall(function() has = GetBP(itemName) ~= nil end)
                if has then
                    detected = itemName
                    break
                end
            end
            if detected then
                if not SC_Triggered then
                    SC_Triggered = true
                    _G.AutoFarmChest = false
                    pcall(function()
                        if _G.FARMX and _G.FARMX.ChestState then
                            _G.FARMX.ChestState.goal = nil
                        end
                    end)
                    pcall(function() if SC_Status and SC_Status.SetDesc then SC_Status:SetDesc("PROTECTED: " .. detected .. " -- chest farming OFF, bat lai thu cong") end end)
                end
            else
                if SC_Triggered then
                    pcall(function() if SC_Status and SC_Status.SetDesc then SC_Status:SetDesc("Protected item gone -- awaiting manual re-enable of Auto Farm Chest") end end)
                else
                    pcall(function() if SC_Status and SC_Status.SetDesc then SC_Status:SetDesc("Monitoring -- no protected item detected") end end)
                end
            end
        end)
    end
end)

