_G.FARMX.SafeMode = _G.FARMX.SafeMode or { state = "NORMAL", originY = nil, lastNotify = 0 }
spawn(function()
    while task.wait(Sec) do
        if not _G.SafeMode then
            if _G.FARMX.SafeMode.state ~= "NORMAL" then
                _G.FARMX.SafeMode.state = "NORMAL"
                _G.FARMX.SafeMode.originY = nil
            end
            continue
        end
        pcall(function()
            local char = game.Players.LocalPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if not hum or not hrp then return end
            if hum.MaxHealth <= 0 then return end
            local hpPct = hum.Health / hum.MaxHealth * 100
            local sm = _G.FARMX.SafeMode
            local now = os.clock()
            local fxN = _G.FARMX
            if sm.state == "NORMAL" then
                if hpPct < 40 then
                    sm.state = "PANIC_UP"
                    sm.originY = hrp.Position.Y
                    sm.own = true; pcall(_tp, hrp.CFrame * CFrame.new(0, 2000, 0)); sm.own = false
                    if fxN and fxN.FH and fxN.FH.NotifyDot and now - sm.lastNotify > 1 then
                        sm.lastNotify = now
                        pcall(fxN.FH.NotifyDot, "r", "Safe Mode: HP low, flying up", 2)
                    end
                end
            elseif sm.state == "PANIC_UP" then
                if hpPct > 65 then
                    sm.state = "PANIC_DOWN"
                    local origY = sm.originY or hrp.Position.Y
                    sm.own = true; pcall(_tp, CFrame.new(hrp.Position.X, origY, hrp.Position.Z) * (hrp.CFrame - hrp.CFrame.Position)); sm.own = false
                    if fxN and fxN.FH and fxN.FH.NotifyDot and now - sm.lastNotify > 1 then
                        sm.lastNotify = now
                        pcall(fxN.FH.NotifyDot, "g", "HP recovered, descending", 2)
                    end
                end
            elseif sm.state == "PANIC_DOWN" then
                sm.state = "NORMAL"
                sm.originY = nil
            end
        end)
    end
end)
-- [PHASE118] Auto Counter: when another player damages us while farming, fight back (race ability + skills aimed at the attacker); Safe Mode still handles the escape at low HP
do
local C = { hitAt = 0, hp = nil, engagedAt = 0, Status = "Idle" }
_G.MaruCounter = C
local PVP = _G.MaruPvP
local function attacker()
  local my = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
  if not my then return nil end
  local best, bd = nil, 200
  for _, p in ipairs(game.Players:GetPlayers()) do
    if p ~= plr and PVP.Alive(p) and not PVP.Protected(p) then
      if not (_G.NoAimTeam and p.Team == plr.Team) then
        local d = (p.Character.HumanoidRootPart.Position - my.Position).Magnitude
        if d < bd then best, bd = p, d end
      end
    end
  end
  return best, bd
end
local conn
local function watch(ch)
  if conn then conn:Disconnect() end
  local hum = ch:WaitForChild("Humanoid", 10)
  if not hum then return end
  C.hp = hum.Health
  conn = hum.HealthChanged:Connect(function(h)
    local prev = C.hp or h
    C.hp = h
    if prev - h >= math.max(40, hum.MaxHealth * 0.02) then C.hitAt = os.clock() end
  end)
end
if plr.Character then task.spawn(watch, plr.Character) end
plr.CharacterAdded:Connect(function(ch) task.spawn(watch, ch) end)
do
  UIX.Toggle(Tabs.Combat, "Combat_AutoCounter", {
    Title = "Auto Counter Attacker",
    Description = "Bi player danh luc farm thi phan don (skill + ability toc), HP thap thi Safe Mode bay len chon",
    Default = false,
    Callback = function(Value)
      _G.AutoCounter = Value
      if Value and not _G.SafeMode then
        pcall(function()
          if Library and Library.Options and Library.Options["Combat_AutoSafeMode"] then Library.Options["Combat_AutoSafeMode"]:SetValue(true) end
        end)
      end
      if not Value then MousePos = nil C.Status = "Idle" end
    end
  })
end
task.spawn(function()
  while task.wait(0.15) do
    if _G.AutoCounter then
      pcall(function()
        local now = os.clock()
        local sm = _G.FARMX and _G.FARMX.SafeMode
        if sm and sm.state ~= "NORMAL" then C.Status = "SafeMode" return end
        local hum = plr.Character and plr.Character:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return end
        -- engage only shortly after real damage, then keep going while the attacker is close
        if now - C.hitAt > 5 and now - C.engagedAt > 3 then
          if C.aimSet then MousePos = nil C.aimSet = false end
          return
        end
        local p, d = attacker()
        if not p then return end
        C.engagedAt = now
        C.Status = "Counter " .. p.Name
        PVP.Ability()
        local ap = PVP.AimPos(p)
        if ap then MousePos = ap C.aimSet = true end
        if d <= 60 then
          if d <= 12 then PVP.M1() end
          PVP.Cast(p)
        end
      end)
    elseif C.Status ~= "Idle" then
      C.Status = "Idle"
    end
  end
end)
end

UIX.Paragraph(Tabs.Combat, "Para_95", {Title = "LocalPlayer Settings", Content = ""})
local flying = false
local flySpeed = 50
local flyConnection
local bv, bg
local function toggleFly(value)
    flying = value
    local character = player.Character
    if not character then return end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local rootPart = character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("Torso") or character:FindFirstChild("UpperTorso")
    if not humanoid or not rootPart then return end
    if flying then
        bv = Instance.new("BodyVelocity")
        bv.MaxForce = Vector3.new(9e9, 9e9, 9e9)
        bv.Velocity = Vector3.new(0, 0, 0)
        bv.Parent = rootPart
        bg = Instance.new("BodyGyro")
        bg.MaxTorque = Vector3.new(9e9, 9e9, 9e9)
        bg.P = 9e5
        bg.CFrame = rootPart.CFrame
        bg.Parent = rootPart
        for _, part in ipairs(character:GetDescendants()) do
            if part:IsA("BasePart") and part.CanCollide then
                part.CanCollide = false
            end
        end
        flyConnection = RunService.Heartbeat:Connect(function()
            if not flying or not player.Character then return end
            local cam = workspace.CurrentCamera
            bg.CFrame = cam.CFrame
            local moveDir = humanoid.MoveDirection
            if moveDir.Magnitude > 0 then
                local flatLook = cam.CFrame.LookVector * Vector3.new(1, 0, 1)
                flatLook = flatLook.Magnitude > 0 and flatLook.Unit or Vector3.new(0, 0, -1)
                local flatRight = cam.CFrame.RightVector * Vector3.new(1, 0, 1)
                flatRight = flatRight.Magnitude > 0 and flatRight.Unit or Vector3.new(1, 0, 0)
                local forwardInput = flatLook:Dot(moveDir)
                local rightInput = flatRight:Dot(moveDir)
                local flyDir = (cam.CFrame.LookVector * forwardInput) + (cam.CFrame.RightVector * rightInput)
                if flyDir.Magnitude > 0 then
                    character:TranslateBy(flyDir.Unit * (flySpeed / 10))
                end
            end
        end)
    else
        if flyConnection then flyConnection:Disconnect() flyConnection = nil end
        if bv then bv:Destroy() bv = nil end
        if bg then bg:Destroy() bg = nil end
        for _, part in ipairs(character:GetDescendants()) do
            if part:IsA("BasePart") then
                part.CanCollide = true
            end
        end
    end
end
local function updateFlySpeed(value)
    flySpeed = value
end
player.CharacterAdded:Connect(function(character)
    task.wait(0.5)
    if flying then
        toggleFly(false)
        task.wait(0.1)
        toggleFly(true)
    end
end)
