local function MaruLoadPlaylist()
    if MaruLoading then return end
    MaruLoading = true
    local ok, raw = true, Library.MusicRaw
    if MARU_PLAYLIST_URL ~= "" then if _G.FARMX and _G.FARMX.NetGet then ok, raw = _G.FARMX.NetGet(MARU_PLAYLIST_URL) else ok, raw = pcall(function() return game:HttpGet(MARU_PLAYLIST_URL) end) end end
    if not ok or not raw or #raw == 0 then
        MaruLoading = false
        pcall(function() Library:Notify({Title = "Music", Content = "Lỗi tải playlist!", Duration = 7}) end)
        return
    end
    local parsed = MaruParsePlaylist(raw)
    if #parsed == 0 then
        MaruLoading = false
        pcall(function() Library:Notify({Title = "Music", Content = "Không tìm thấy bài hát!", Duration = 7}) end)
        return
    end
    MaruPlaylist = parsed
    MaruLoading = false
    MaruFiltered = {}
    for i, t in ipairs(MaruPlaylist) do
        table.insert(MaruFiltered, {index = i, track = t})
    end
    pcall(function() Library:Notify({Title = "Music", Content = "Đã tải " .. #MaruPlaylist .. " bài hát.", Duration = 5}) end)
end
