-- [QM-WIN] P75 WinFit + SideFade | nguon: yeu cau boss man (UI qua to, mo phan tren danh sach tab) | gan tai: sau WATopToggle
pcall(function()
  local fx = _G.FARMX
  local en = fx and fx.Enable
  local cam = workspace.CurrentCamera
  if not (Window and Window.UIElements and Window.UIElements.Main) then return end
  if not (en and en.WinFit == false) and cam then
    local function fit()
      if Window.IsFullscreen or Window.Destroyed or Window.Closed == true then return end
      local vp = cam.ViewportSize
      local sz = Window.Size
      local w, h = sz.X.Offset, sz.Y.Offset
      if vp.X < 50 or vp.Y < 50 or w <= 0 or h <= 0 then return end
      local cfg = fx and fx.Cfg
      local k = math.min(vp.X * ((cfg and cfg.WinFitX) or 0.9) / w, vp.Y * ((cfg and cfg.WinFitY) or 0.8) / h)
      k = math.clamp(k, 0.3, 1)
      local cur = Window:GetUIScale() or 1
      if math.abs(cur - k) > 0.02 then Window:SetUIScale(k) end
    end
    fit()
    task.delay(1, fit)
    task.delay(3, fit)
    cam:GetPropertyChangedSignal("ViewportSize"):Connect(fit)
  end
  if not (en and en.SideFade == false) then
    local U = Window.UIElements
    local sb, cont = U.SideBar, U.SideBarContainer
    local Cr0 = Library.WindUI and Library.WindUI.Creator
    if sb and cont then
      -- [QM-LG] P83 vung keo tab: lop mo mau theo mau UI (doi theme la doi mau ngay), dam hon khi keo nhanh, co ca mep duoi + xep chong tab (logic dropdown)
      local K = NumberSequenceKeypoint.new
      local bgImg
      local bg = Color3.fromRGB(14, 17, 34)
      pcall(function()
        local b = U.Main:FindFirstChild("Background")
        if b and b:IsA("ImageLabel") then bgImg, bg = b, b.ImageColor3 end
      end)
      local function mkFade(name, rot)
        local f = Instance.new("Frame")
        f.Name = name
        f.Active = false
        f.BorderSizePixel = 0
        f.BackgroundColor3 = Color3.new(1, 1, 1)
        f.BackgroundTransparency = 1
        f.ZIndex = 5000
        f.Size = UDim2.new(1, 0, 0, 30)
        local g = Instance.new("UIGradient")
        g.Name = "Tint"
        g.Rotation = rot
        g.Color = ColorSequence.new(bg)
        g.Transparency = NumberSequence.new({ K(0, 0), K(0.45, 0.35), K(1, 1) })
        g.Parent = f
        f.Parent = cont
        return f, g
      end
      local fadeT, gradT = mkFade("WASideFade", 90)
      local fadeB, gradB = mkFade("WASideFadeB", 270)
      local function tint()
        local edge = bg:Lerp(Color3.new(1, 1, 1), 0.08)
        gradT.Color = ColorSequence.new(edge, bg)
        gradB.Color = ColorSequence.new(edge, bg)
      end
      tint()
      if bgImg then
        bgImg:GetPropertyChangedSignal("ImageColor3"):Connect(function()
          bg = bgImg.ImageColor3
          tint()
        end)
      end
      local function uiScale()
        local sc = (Library.WindUI and Library.WindUI.UIScaleObj and Library.WindUI.UIScaleObj.Scale) or 1
        if sc <= 0 then sc = 1 end
        return sc
      end
      local lastY, vel, curT, curB, edgeY = sb.CanvasPosition.Y, 0, 1, 1, -1
      local function place(hT, hB)
        local sc = uiScale()
        local y0 = (sb.AbsolutePosition.Y - cont.AbsolutePosition.Y) / sc
        local y1 = (sb.AbsolutePosition.Y + sb.AbsoluteSize.Y - cont.AbsolutePosition.Y) / sc
        fadeT.Position = UDim2.fromOffset(0, y0)
        fadeT.Size = UDim2.new(1, 0, 0, hT)
        fadeB.Position = UDim2.fromOffset(0, y1 - hB)
        fadeB.Size = UDim2.new(1, 0, 0, hB)
      end
      game:GetService("RunService").Heartbeat:Connect(function(dt)
        if Window.Destroyed or Window.Closed == true then return end
        local y = sb.CanvasPosition.Y
        local v = (y - lastY) / math.max(dt, 1 / 240)
        lastY = y
        vel = vel + (v - vel) * math.min(dt * 12, 1)
        local energy = math.clamp(math.abs(vel) / 1400, 0, 1)
        local maxY = math.max(sb.AbsoluteCanvasSize.Y - sb.AbsoluteWindowSize.Y, 0)
        local a = 0.3 - 0.27 * energy
        local k = math.min(dt * 14, 1)
        curT = curT + ((y > 3 and a or 1) - curT) * k
        curB = curB + ((y < maxY - 3 and a or 1) - curB) * k
        fadeT.BackgroundTransparency = math.clamp(curT, 0, 1)
        fadeB.BackgroundTransparency = math.clamp(curB, 0, 1)
        place(30 + 18 * energy, 30 + 18 * energy)
        if Cr0 and Cr0.WAStackSideEdge and math.abs(y - edgeY) > 0.4 then
          edgeY = y
          Cr0.WAStackSideEdge(Window)
        end
      end)
      if Cr0 and Cr0.WAStackSide then
        task.delay(0.5, function() pcall(Cr0.WAStackSide, Window) end)
      end
    end
  end
end)
